(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["ya5"] = [{"id":"ya5-105-1-1","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"在相同的咬力下，口腔黏膜受力後的位移變化，下列敘述何者錯誤？","options":["(A) 年齡越大，黏膜的下沉量越大","(B) 咬力移除後，年齡越大，黏膜的恢復越快","(C) 年齡越大，取模前 2～3 天最好不要戴舊的全口活動義齒","(D) 若要使用舊的全口活動義齒，組織面最好放置組織調理材（tissue conditioner）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"下列有關評估全口無牙患者社經狀況（socioeconomic status）的敘述，何者錯誤？","options":["(A) 社經狀況與義齒製作無關","(B) 可推測該患者成為全口無牙的原因","(C) 有助於推測患者對義齒治療效果的預期","(D) 可預測患者對保持義齒清潔的成效"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-1-3","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"有關腫裂齦瘤（epulis fissuratum）之敘述，下列何者錯誤 ?","options":["(A) 為一增殖性組織（hyperplasia tissue）","(B) 多由於不合適之義齒邊緣所引致","(C) 應修除義齒邊緣可能造成壓迫之區域，並指導患者暫時不戴義齒","(D) 應立即取模置換新義齒"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"下顎全口義齒舌側齒槽溝（lingual alveolar sulcus）的深度與形狀，主要是由下列那一條肌 肉決定的？","options":["(A) 翼內肌（medial pterygoid muscle）","(B) 上咽縮肌（superior pharyngeal constrictor）","(C) 頦舌骨肌（geniohyoid muscle）","(D) 下顎舌骨肌（mylohyoid muscle）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"影響口腔黏膜支持（support）義齒能力的主要因素？ ①黏膜的厚度（thickness） ②黏膜 的稠度（consistency） ③黏膜的角化程度（keratinization）","options":["(A) 僅②","(B) 僅①②","(C) 僅①③","(D) ①②③"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-6","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"下列何者非硬腭（hard palate）處口腔黏膜（mucous membrane）的特性？","options":["(A) 為複層鱗狀上皮（stratified squamous epithelium）","(B) 為咀嚼性黏膜（masticatory mucosa）","(C) 非角質化（nonkeratinized）上皮","(D) 含脂肪與腺體（adipose and glandular tissue）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"有關臼齒後墊（retromolar pad）的敘述，下列何者錯誤？","options":["(A) 略呈三角形","(B) 具非常厚的角化上皮","(C) 含頰肌（buccinator muscle）的纖維","(D) 是下顎全口義齒後緣的參考界標（landmark）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-1-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"下列何者並非記錄基底（recording base）及咬合堤（occlusion rim）之主要功能？","options":["(A) 決定靜止垂直距離（rest vertical dimension）","(B) 建立合理之咬合間隙（interocclusal distance）","(C) 決定並記錄習慣性咬合（habitual occlusion）","(D) 轉移正確顎間關係（jaw relationships）至咬合器"],"answer":2,"clinical_level":"重點"},{"id":"ya5-105-1-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"全口義齒患者於生理性靜止位置（physiological rest position）時，上、下顎義齒間應出現以 下何者特徵？","options":["(A) 後牙輕微接觸","(B) 對咬於中心咬合（centric occlusion）位置","(C) 對咬於中心關係（centric relation）位置","(D) 上、下顎義齒第一小臼齒間約有 2～4 mm 空隙"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-10","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"製作全口義齒時，若使用定軸面弓（kinematic face-bow），下列敘述何者正確？","options":["(A) 咬合叉（bite fork）接於上顎","(B) 可藉之觀察下顎張、閉口時樞紐軸（hinge axis）之運動軌跡","(C) 耳桿（ear rod）直接置於外耳道內，方便面弓之定位","(D) 其耳桿（ear rod）與髁頭（condyle）間之距離一般定為 10 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"關於患者在開始使用新全口義齒後的說話分析（speech analysis）的敘述，下列何者錯誤？","options":["(A) 一般來說，患者需要二到四週的時間去適應新義齒，並能正確發音","(B) 年長患者往往需要較長的適應期，與年長患者的聽力回饋（auditory feedback）較差有關","(C) 對於“k”、“c” 等發音，新舊義齒咬合垂直高度的改變，較上顎義齒腭部形態的改變影響 更大","(D) 複製發音正確之舊義齒的牙弓寬窄以及上腭部型態，可縮短患者適應的時間"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"當全口義齒患者試戴及發“f ”，“v” 等唇齒音（labiodental sounds）時，若觀察到患者發音 時上顎門齒接觸的是下唇的乾燥側，且易將“v” 錯發成“f ” 音，形成此現象最有可能的理由 為何？ ①上顎門牙排列太往前 ②下顎門牙排列太往內 ③上唇的支持不足 ④上顎前牙 可能過短","options":["(A) ①③④","(B) ①②③","(C) ①②④","(D) ②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"當一位女性全口義齒患者認為前牙採用陶瓷牙（porcelain teeth）較美觀時，在何種狀況下 應告訴患者不適宜採用陶瓷牙？ ①上下顎咬合間隙（interocclusal space）太少 ②對側 為自然齒（natural teeth） ③高可見度（high visible）牙齦 ④覆蓋式義齒 （overdenture）","options":["(A) 僅①②","(B) 僅③④","(C) ①②④","(D) ②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"下列何者為平衡咬合（balanced occlusion）的優點？","options":["(A) 說話時較不會撞擊發出噪音","(B) 技術上較易達成","(C) 有助義齒非中心咬位接觸時之穩定","(D) 當口內有食糰存在時，即無平衡咬合接觸，故無優點可言"],"answer":2,"clinical_level":"重點"},{"id":"ya5-105-1-15","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"全口義齒戴入患者口內後，若是發現有明顯的過早接觸，須作調整磨修。下列何種方式為 佳？","options":["(A) 直接在病人口內以咬合紙檢查再作調整","(B) 直接在病人口內以蠟片檢查再作調整","(C) 採取口內新的咬合記錄後，置入咬合器內再作調整","(D) 使用原有咬合記錄在咬合器上重置位（remounting）來作調整"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-16","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"若全口義齒配戴者抱怨在笑時上顎義齒容易鬆動，此時通常應先採取的措施為何？","options":["(A) 將義齒換底墊（reline）","(B) 將義齒後障（post dam）加厚","(C) 將義齒頰側切迹（buccal notch）加深","(D) 將義齒遠心頰側凸緣（distobuccal flange）修薄"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-17","subject":"ya5","topic":"牙科材料學","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"有關治療椅旁使用的換底墊自聚樹脂（self-curing resin）的敘述，下列何者錯誤？","options":["(A) 可能引起口腔黏膜之化學性灼傷","(B) 常具刺激性味道","(C) 顏色之穩定性（color stability）佳","(D) 易產生氣泡"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"製作傳統即裝全口義齒（conventional immediate complete denture）時，對殘存牙齒之拔 牙順序應為何？","options":["(A) 後牙應先拔，再取模製作","(B) 前牙應先拔，再取模製作","(C) 後牙前牙應一起拔，再取模製作","(D) 先取模製作，配戴義齒時，後牙前牙應一起拔除"],"answer":0,"clinical_level":"重點"},{"id":"ya5-105-1-19","subject":"ya5","topic":"植牙贋復","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"下列何種情況的患者較適合接受上顎植體支持覆蓋式義齒（implant-supported overdenture）而非植體支持之固定義齒（implant-supported fixed prosthesis）治療？ ① 上顎前牙區有大量垂直及水平骨吸收 ②患者口腔衛生的維持能力不良 ③植體的位置在直 線上","options":["(A) 僅①","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-20","subject":"ya5","topic":"植牙贋復","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"全口缺牙患者以植體贋復，下列有關印模的敘述中，那些正確？ ①印模前要以環口 X 光攝 影檢查各印模薄蓋冠（impression coping）與植體的密合度 ②當印模薄蓋冠之間太接近 時，可把印模薄蓋冠磨小 ③可於主模上製作篩板（jig）於口中檢查印模的精確度 ④樹脂 篩板（jig）可以用作主模的修改","options":["(A) ①②③","(B) ②③④","(C) 僅①②","(D) 僅③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-21","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"有關蠟型義齒模型的包埋步驟中，下列何者錯誤？","options":["(A) 義齒模型須於包埋盒上、下半部中測試，確定義齒高度不會過高","(B) 模型最高處與包埋盒頂部之間大約有 1/8～1/4 吋空間","(C) 下顎模型遠心端和包埋盒邊緣有正確角度，避免破碎","(D) 模型置於包埋盒下半部，模型邊緣必須高出包埋盒邊緣或是呈現銳角，石膏才不易破碎"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-22","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"患者回診時一直抱怨上顎全口義齒咬東西時會晃動，下列處理方法何者最正確？","options":["(A) 要求患者適應活動義齒","(B) 請患者使用義齒黏著劑即可","(C) 告訴患者義齒用一陣子和黏膜密貼後就可改善","(D) 先改善義齒會發生晃動之原因，再請患者適應"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"有關延伸咬合面鉤靠（extended occlusal rest）之敘述，下列何者錯誤？","options":["(A) 可使用在甘迺迪第三類緊鄰缺牙區，向近心傾斜之大臼齒","(B) 鉤靠長度要超過大臼齒近遠心寬度的二分之一","(C) 鉤靠寬度為頰舌寬度三分之一","(D) 當對咬無牙時，可不用修磨支柱牙形成咬合面鉤座"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-24","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"一般舌側鉤靠（lingual rest）之近遠心寬度（mesiodistal length）最好為多少 mm？","options":["(A) 1.0","(B) 1.5～2.0","(C) 2.5～3.0","(D) 3.5～4.0"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-25","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"下列那種上顎主連接體（major connector）的設計最缺乏剛性（rigidity）？","options":["(A) 全腭覆蓋式（complete palatal coverage）","(B) 前後腭帶式（anterior-posterior palatal strap）","(C) 單腭帶式（single palatal strap）","(D) U形腭板（U-palatal plate）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"下列選項附圖所示的缺牙狀況在缺牙區支柱牙前後各製作一個環周牙鉤（circumferential clasp），假設製作牙鉤的所有條件都一樣時，那一個設計的固位力（retention force）最 佳？","options":["(A) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-003955-qo6s.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(B) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-004002-6yjs.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(C) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-004008-d9iu.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(D) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-004013-481e.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-105-1-27","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"臨床上，可撤式局部義齒的支柱牙（abutment teeth）以析量牙冠（surveyed crown）製作 的理由為何？ ①減輕支柱牙的受力負擔 ②防止牙鉤（clasp）的斷折 ③防止支柱牙的傾 斜（tilting） ④防止齲齒的發生 ⑤增加牙鉤的固位（retention）與拮抗性 （reciprocation）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ④⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-28","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"使用環鉤（ring clasp）時應該要有第二個小連接體（minor connector）於牙鉤上，主要目的 為何？","options":["(A) 增加可彎曲性（flexibility）","(B) 增加穩定性（stability）","(C) 增加剛性（rigidity）","(D) 強化支持性（support）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-29","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"下列有關間接固位體（indirect retainer）的敘述，何者錯誤？","options":["(A) 可以用來防止可撤式局部義齒的旋轉及脫離","(B) 依據槓桿作用原理，應放在遠離遠伸性基底旋轉軸線的另一側","(C) 其位置應盡可能垂直主支點線（main fulcrum line），並在許可情況下距離該線越遠效果 越佳","(D) 甘迺迪第二類的齒弓來說，最常以雙側犬齒的舌面隆凸鉤靠（cingulum rest）作為間接固 位體"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-30","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"下列有關可撤式局部義齒設計的敘述，何者錯誤？","options":["(A) 僅在臨床上不適合使用舌側桿（lingual bar）或舌側板（linguoplate）為主連接體時，方可 使用唇側桿","(B) 唇側桿因其長度較相對應的舌側桿（lingual bar）或舌側板（linguoplate）來得長，所以其 高度及厚度也要細且薄","(C) 當剩餘的前牙牙周較差時，使用舌側板（linguoplate）的方式有利於穩定剩餘前牙，以利 於之後的義齒修補","(D) 旋鎖式（swing-lock）設計可運用在缺少主要支柱牙，而由所有剩餘前牙共同分擔固位與 穩定作用"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-31","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"可撤式局部義齒設計時，下列何者應先考慮？","options":["(A) 固位（retention）方式","(B) 支持（support）方式","(C) 置入途徑（path of insertion）","(D) 連接體（connector）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"有關可撤式局部義齒製作之敘述，下列何者錯誤？","options":["(A) 患者應能容易的置入及取出義齒","(B) 牙鉤的脫離方向（path of escapement）不可與置放義齒之途徑平行","(C) 當前牙缺失時，固位牙鉤應置於近心牙齦區（mesiogingival area）","(D) 有干擾（interference）存在時，可試著改變置入及取出途徑來改善"],"answer":2,"clinical_level":"重點"},{"id":"ya5-105-1-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"在模型析量過程中，三點定位法（tripoding）是用在何情況？","options":["(A) 記錄模型在析量台（surveyor table）上的位置","(B) 記錄析量台的傾斜角度","(C) 定位咬合平面（occlusal plane）","(D) 記錄義齒的置入途徑（path of insertion）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-1-34","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"在將可撤式義齒交給病人的那一次約診中（delivery appointment），要檢查義齒的那些部 位？ ①義齒基底與黏膜密合度 ②義齒基底邊緣長度 ③人工牙的型態、色調 ④人工牙 的咬合狀態 ⑤主連接體的堅固度","options":["(A) 僅①②","(B) ①③④⑤","(C) 僅①②④","(D) 僅③④⑤"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"有關可撤式局部義齒製作的術前口腔準備（mouth preparation），下列敘述何者錯誤？","options":["(A) 析量（surveying）","(B) 殘根的拔除","(C) 咬合調整（occlusal adjustment）","(D) 牙菌斑的控制（plaque control）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-1-36","subject":"ya5","topic":"牙科材料學","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"關於橡膠基底（rubber base）與水凝膠（hydrocolloid）印模材的比較，下列敘述何者錯 誤？","options":["(A) 前者印模後倒出來的石膏模型表面，較後者倒出來的石膏模型來得光滑且堅硬","(B) 前者有較長的操作時間（working time）以及凝固時間（setting time）可進行邊緣塑形 （border molding）","(C) 一般來說，前者有令患者感覺不適的味道","(D) 兩者取模時，皆有所謂的〝突然凝固（snap set）〞的現象"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"下列何種缺牙條件應考慮採用功能性印模，來製作可撤式局部活動義齒？ ①遠心游離端的 義齒延伸區 ②甘迺迪第三類缺牙 ③剩餘支柱牙數量不多，且支持能力有限 ④連續六顆 以上的長距離缺牙","options":["(A) 僅①②","(B) 僅②③","(C) 僅①②④","(D) 僅①③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-38","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"有關可撤式局部義齒咬合的敘述，下列何者正確？","options":["(A) 局部義齒與全口義齒的咬合原則完全相同","(B) 髁頭導引（condyle guidance）在局部義齒的影響與全口義齒一樣重要","(C) 缺幾顆牙就該補幾顆牙","(D) 排牙時人工牙容許修磨改變以達到最佳咬合關係"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-39","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"有關 Kennedy Class I 可撤式局部義齒的咬合模式之敘述，下列何者正確？","options":["(A) 在離中心（eccentric）運動時，義齒應避免工作側（working side）咬合接觸","(B) 在離中心（eccentric）運動時，義齒應避免平衡側（balancing side）咬合接觸","(C) 前突（protrusion）運動時，義齒可以無咬合接觸","(D) 在中心咬位時，義齒應避免咬合接觸"],"answer":2,"clinical_level":"重點"},{"id":"ya5-105-1-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"患者在配戴新的可撤式局部義齒時，有關咬字困難的敘述，下列何者錯誤？","options":["(A) 最佳調整時間為配戴 24 小時至 48 小時之間","(B) 上顎前牙常是造成問題的原因","(C) 前腭部的形態有可能是造成問題的原因","(D) 上顎小臼齒太往頰側排列，也可能造成發音問題"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-1-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"有關可撤式局部義齒清潔之敘述，下列何者錯誤？","options":["(A) 義齒上的結石沉積，可以超音波清潔器（ultrasonic cleaner）清除","(B) 若在外用餐，飯後以清水簡單沖洗義齒及口腔","(C) 建議使用軟毛刷及無磨砂性之清潔劑","(D) 建議每天使用含氯之義齒清潔劑"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-105-1-42","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"下列有關主連接體（major connector）製作珠狀緣飾（beading）之敘述何者正確？ ①可 增加上顎主連接體與組織間的貼合 ②可減少食物嵌入主連接體與組織之間 ③珠狀緣飾的 深度約為 0.5 mm ④在隆凸（torus）處不可做 ⑤上顎及下顎在適當位置皆需製作珠狀緣 飾","options":["(A) 僅①⑤","(B) 僅②③④","(C) 僅①②③④","(D) ①②③④⑤"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"局部活動義齒金屬支架（metal framework）的製作過程中，有關裝置鑄道（spruing）之敘 述，下列何者錯誤？","options":["(A) 倒置鑄道法（inverted spruing）用於下顎的支架製作","(B) 頂端鑄道法（overjet spruing）常用於上顎的支架製作","(C) 水平鑄道法（horizontal spruing）可用於全腭板（complete palatal plate）的支架製作","(D) 使用多數鑄道法（multiple spruing method）時，鑄道的數目比鑄道的粗細還重要"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"下圖顯示在技工室製作金屬支架過程中，在支柱牙放置鑄造環周牙鉤（circumferential clasp）之部位需作適當的堵凹（blockout）或緩壓（relief），此處之堵凹屬於下列那一類？","options":["(A) 成型式堵凹（shaped blockout）","(B) 平行式堵凹（parallel blockout）","(C) 緩壓（relief）","(D) 任意式堵凹（arbitrary blockout）"],"answer":0,"image":"ya5-105-1-44.jpeg","clinical_level":"一般"},{"id":"ya5-105-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"以右下顎第二小臼齒與第二大臼齒為支柱牙（abutment）製作固定式牙橋， 兩個支柱牙之倒 錐角度（taper）及高度相同。為了加強牙橋的抗力形（resistance form），應在何處修磨 「溝」（groove）最適當？","options":["(A) 第二小臼齒的頰側與舌側","(B) 第二小臼齒的近心側與遠心側","(C) 第二大臼齒的頰側與舌側","(D) 第二大臼齒的近心側與遠心側"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"下列何者不是影響牙冠黏合後抗力性（resistance）之重要因素？","options":["(A) 支柱牙的倒錐角度（taper）","(B) 支柱牙的高度","(C) 支柱牙表面的粗糙度（roughness）","(D) 支柱牙的近遠心寬度"],"answer":2,"clinical_level":"重點"},{"id":"ya5-105-1-47","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"下列何者較易造成固定贋復物的變形？","options":["(A) 牙齒修形有足夠的咬合間隙（occlusal clearance）","(B) 使用厚弧形（heavy chamfer）邊緣設計","(C) 牙齒修形磨出功能咬頭斜面（functional cusp bevel）","(D) 選擇ADA第一型或第二型金合金製作贋復物"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-48","subject":"ya5","topic":"咬合學基礎","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"下列何種咬合方式適合採用功能軌徑生成術（functionally generated path, FGP）來製作後 牙區三單位牙橋？①相互保護性咬合（mutually protected articulation） ②單側平衡性咬合 （unilaterally balanced articulation） ③雙側平衡性咬合（bilaterally balanced articulation）","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-49","subject":"ya5","topic":"臨床基礎與倫理","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"為達到準確的印模，下列何種藥物可用來抑制口水分泌，且非膽激性對抗劑 （anticholinergics），最具安全性？","options":["(A) Atropine","(B) Pro-Banthine","(C) Antipas Bentyl","(D) Clonidine"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"根管治療後牙齒的重建有很多方式，是否使用根柱的考慮，下列因素那一項最為重要？","options":["(A) 牙齒的種類","(B) 牙齒的重要性","(C) 牙齒的剩餘牙冠齒質","(D) 牙齒的牙周狀況"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-51","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"經牙周手術處理後，若為牙齦上完成線（supragingival finish line）的支柱牙，印模的時機至 少約需在牙周手術後多久？","options":["(A) 1週","(B) 3週","(C) 5週","(D) 7週"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-52","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"下列何種情況會考慮實施牙冠增長術（crown-lengthening procedures）？","options":["(A) 牙齦發炎紅腫，而齲齒邊緣位於牙肉下1 mm","(B) 齲齒邊緣位於牙肉下3 mm，且該處牙周囊袋深度為7 mm","(C) 前牙區域牙齦高低參差不齊，差距超過5 mm","(D) 下顎第二大臼齒要做贋復物，但臨床牙冠長度過短"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"下列橋體設計，何者較容易導致牙菌斑的堆積？","options":["(A) 馬鞍型（saddle）","(B) 圓錐形（conical）","(C) 改良式嵴疊型（modified ridge-lap）","(D) 卵圓形（ovate）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-105-1-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"改良式嵴疊式橋體（modified ridge-lap pontic）與組織之接觸形狀，從牙齦面看來類似那一 個英文字母？","options":["(A) T","(B) U","(C) M","(D) L"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-1-55","subject":"ya5","topic":"牙科材料學","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"下列有關銲接的敘述，那一項錯誤？","options":["(A) 理想的銲接縫隙約0.25 mm","(B) 用火燄銲接時，應使用還原火燄","(C) 用烤爐銲接時，贋復體在烤爐內的時間要越久越好，以使銲劑能完全熔解","(D) 賤金屬贋復物較難藉銲接達到一理想的強度"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-56","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"關於瓷金屬復形物（metal-ceramic restoration）之支架設計，下列敘述何者錯誤？","options":["(A) 在瓷與金屬交界處，瓷至少要0.5 mm厚","(B) 咬合之中心止點（centric stop）可以置於瓷金屬交界處1.5 mm之處","(C) 為了美觀及方便清潔，鄰接面接觸可置瓷上","(D) 瓷與金屬之間應做成120°夾角之接合"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-57","subject":"ya5","topic":"牙科材料學","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"全瓷牙冠系統中，何者之成分以白榴石（leucite）為主？","options":["(A) IPS-Empress","(B) In-Ceram","(C) Procera","(D) Cercon"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-1-58","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"關於纖維強化樹脂（fiber-reinforced composites）用於贋復物的優點，下列何者錯誤？","options":["(A) 有很好透光性","(B) 可減少對咬的磨耗","(C) 很高的彎曲強度（flexural strength），可用於二顆橋體（pontic）的固定義齒","(D) 可以減少支柱牙的修磨量"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"瓷牙外染（external color modification）時，如果要製造出牙齒切端（incisal edge）的透明 感（translucency），可染上何種顏色？","options":["(A) 紅色","(B) 紫色","(C) 灰色","(D) 白色"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-60","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"25歲女子，主訴為微笑時上顎前牙區露出太多牙齦。臨床發現臉部上、中、下比例均等，微 笑時露出上顎牙齦約3 mm，上顎中門齒的長度為6 mm，寬度為8 mm。下列何種治療方式 最適宜？","options":["(A) 矯正治療將上顎前牙下壓內縮（intrusion）","(B) 進行正顎手術將上顎骨向上移位","(C) 進行牙冠增長術","(D) 進行上唇整形手術"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-61","subject":"ya5","topic":"植牙贋復","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"人工植體治療時，骨頭高度的喪失，每年以不超過多少距離較佳？","options":["(A) 0.2 mm","(B) 0.5 mm","(C) 1.0 mm","(D) 2.0 mm"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-1-62","subject":"ya5","topic":"植牙贋復","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"相鄰兩植體間的距離會影響到周邊骨頭生長及日後清潔的問題，試問相鄰兩植體間可允許的 最小距離約為多少？","options":["(A) 1 mm","(B) 3 mm","(C) 5 mm","(D) 7 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-63","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"下列何種狀況可以製作較長咬頭（longer cusps）的後牙？","options":["(A) 前牙有較短的前牙水平重疊（horizontal overlap）","(B) 前牙有較少的前牙垂直重疊（vertical overlap）","(C) 關節髁（condyle）有明顯的立即性側方位移","(D) 髁窩（condyle fossa）有較淺的髁導引（condylar guidance）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-1-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"如下圖，患者缺失上顎14，15，18，25，26，27，28，若要為患者製作上顎2顆中門齒的全 瓷牙冠時，要如何將上下顎的模型置位（mounting）到咬合器上？","options":["(A) 上顎模型做面弓轉移後，直接用手將上下顎模型卡在一個最穩定的位置後，固定在咬合器 上","(B) 利用患者的參考模型製作一個紀錄基底（record base），在最終印模當天同時做好面弓轉 移，以及用紀錄基底，取上下顎間的中心咬合（centric occlusion）","(C) 11，21最終印模需倒出兩次模型，第一個做成工作模型，第二個則用來製作紀錄基底 （record base），患者需在最終印模後再次約診，以取得面弓轉移以及用紀錄基底來做紀 錄中心咬合（centric occlusion）","(D) 最終印模當天做面弓轉移，並以石蠟質蠟片（paraffin wax）折疊成兩層後，取患者的中心 關係咬合（centric relation）"],"answer":2,"image":"ya5-105-1-64.jpeg","clinical_level":"重點"},{"id":"ya5-105-1-65","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"下列何者會增加鑄造金屬牙冠的黏著劑空間（cement space）？①印模材硬化時產生收縮 ②石膏模型硬化時產生膨脹 ③包埋蠟型時，在鑄造環內面多墊一層liner ④鑄造時使用較 高熔點的金屬","options":["(A) ①②④","(B) ①②③","(C) ①③④","(D) 僅②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-66","subject":"ya5","topic":"牙科材料學","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"若採用同一種印模材取模，並由以下材料①ADA type IV stone ②ADA type V stone ③環 氧樹脂（epoxy resin）灌製單齒模，則單齒模的尺寸從大到小排列依序為何？","options":["(A) ①②③","(B) ③②①","(C) ①③②","(D) ②①③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-67","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"有關顳顎關節（temporomandibular joint）髁頭（condyle）的敘述，下列何者錯誤？","options":["(A) 於同一個人身上，左右兩側髁頭之型態與角度不對稱之情況並不少見","(B) 髁頭之外側極（lateral pole）多落於髁頭中軸連線（intercondylar transverse axis）之前 方","(C) 於下顎開口運動時，相對於髁頭之外側極（lateral pole），髁頭之內側極（medial pole） 會往下、往後移動","(D) 於中心咬合（centric occlusion）時，髁頭並不會與關節窩（fossa）的頂部接觸"],"answer":2,"clinical_level":"重點"},{"id":"ya5-105-1-68","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"下列關於肌梭（muscle spindles）的敘述，何者錯誤？","options":["(A) 對肌肉長度改變的感受器","(B) 由 nuclear bag 與 nuclear chain 兩種梭內肌纖維（intrafusal muscle fibers）組成","(C) 在咬肌、顳肌及翼內肌中均可發現其存在","(D) 梭內纖維的運動神經支配是由 Ia 羣神經細胞構成"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-69","subject":"ya5","topic":"咬合學基礎","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"有關本奈氏角（Bennett angle）的敘述，下列何者正確？ ①出現在非工作側 ②出現在工 作側 ③側方運動時，髁頭向前向內移動路徑水平投影與矢狀面所形成的角度 ④側方運動 時，髁頭向前向下移動與水平面所成之角度","options":["(A) ①②","(B) ①③","(C) ③④","(D) ②④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-70","subject":"ya5","topic":"臨床基礎與倫理","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"除 C 纖維外，以下神經纖維中，何者與傷害受器（nociceptor）有關？","options":["(A) Aα","(B) Aβ","(C) Aγ","(D) Aδ"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-71","subject":"ya5","topic":"咬合學基礎","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"當下顎向左側進行側突運動（laterotrusive movement）時，對於非工作側（non-working side）可能的觸碰，下列何者正確？","options":["(A) 下顎頰側咬頭的舌側斜面（lingual incline of mandibular buccal cusps）碰觸上顎 側咬 頭的 側斜面（palatal incline of maxillary palatal cusps）","(B) 下顎頰側咬頭的舌側斜面（lingual incline of mandibular buccal cusps）碰觸上顎 側咬 頭的頰側斜面（buccal incline of maxillary palatal cusps）","(C) 下顎頰側咬頭的頰側斜面（buccal incline of mandibular buccal cusps）碰觸上顎頰側咬頭 的 側斜面（palatal incline of maxillary buccal cusps）","(D) 下顎頰側咬頭的頰側斜面（buccal incline of mandibular buccal cusps）碰觸上顎頰側咬頭 的頰側斜面（buccal incline of maxillary buccal cusps）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-72","subject":"ya5","topic":"咬合學基礎","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"關於前突運動時，咬合干擾的移除與調整，下列何者錯誤？","options":["(A) 上顎小臼齒的遠心斜面（distal slope）以及下顎小臼齒的近心斜面（mesial slope）接觸 所造成的干擾需完全去除","(B) 上顎牙齒前突運動干擾的修磨，位於遠心斜面（distal slope）","(C) 下顎牙齒前突運動干擾的修磨，位於近心斜面（mesial slope）","(D) 當干擾點位於咬頭時，修磨時應遵循 BULL 規則"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-73","subject":"ya5","topic":"咬合學基礎","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"有關下顎側方運動的敘述，下列何者錯誤？","options":["(A) 平衡側髁頭會向前、向下及向內側滑動","(B) 平衡側髁頭路徑於水平面上之投影與矢狀面（sagittal plane）形成本奈氏角（Bennett angle）","(C) 工作側髁頭可能包含向後或向前的側向移動","(D) 泛得繪（pantograph）所得到的軌跡代表顎關節與肌肉造成的運動軌跡，還可以藉此觀察 到功能性運動"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-74","subject":"ya5","topic":"咬合學基礎","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"左側咀嚼食物時，下顎會偏向何方？","options":["(A) 右上方","(B) 左上方","(C) 左下方","(D) 右下方"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"咀嚼功能障礙之病因，可能是： ①肌源性（myogenic type） ②關節源性（arthrogenic type） ③神經性（neurogenic） ④精神性（psychogenic）","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"當顳顎關節出現交替彈響（reciprocal click）時，下列何者為最有可能的原因？","options":["(A) 可復位關節盤異位（disc displacement with reduction）","(B) 不可復位關節盤異位（disc displacement without reduction）","(C) 退化性關節病變（degenerative joint disease）","(D) 咀嚼肌群夾護（muscle splinting）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"關於使用咬合板治療顳顎障礙症的敘述，下列何者錯誤？","options":["(A) 早期咬合板治療的理論發展，部分是根據 Ramfjord 與 Ash 等人認為咬合干擾會造成顳顎 關節問題的基礎而來","(B) 目前臨床醫師大多同意，使用咬合板的治療約有 70％以上的廣義成功療效或是初期療效","(C) 使用咬合板治療顳顎關節障礙症，是屬於一種可逆（reversible）且非侵入性（non- invasive）的治療","(D) 治療關節盤前移易位，應使用重置位咬合板（repositioning splint）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"有關史偉德咬合板（Sved splint）之製作及使用，下列何者錯誤？","options":["(A) 製作容易","(B) 適合長期使用","(C) 咬合板只覆蓋上顎前牙切緣","(D) 對顳顎關節及咀嚼肌肉疼痛的減輕常有明顯療效"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"下圖為患者張、閉口之情形，對此患者之顳顎關節最可能之診斷為何？","options":["(A) 右側關節盤可復位性移位（disc displacement with reduction）","(B) 右側關節盤不可復位性移位（disc displacement without reduction）","(C) 左側關節盤可復位性移位（disc displacement with reduction）","(D) 左側關節盤不可復位性移位（disc displacement without reduction）"],"answer":3,"image":"ya5-105-1-79.jpeg","clinical_level":"一般"},{"id":"ya5-105-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"下圖是一個戴在下顎之咬合板的咬合面示意圖，何者是表示可能被夜間磨牙（bruxism）磨 出的痕跡？","options":["(A) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-004724-7bgj.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(B) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-004734-kc5v.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(C) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-004739-kj28.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(D) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-004744-lyek.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">"],"image":"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-004654-4bcq.png","answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-1","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"有關牙周膜承載區（bearing area of periodontal membrane）與全口無牙義齒承載區（ridge supporting area）的敘述，下列何 者正確？","options":["(A) 下顎牙周膜承載區約為下顎無牙義齒承載區的兩倍","(B) 下顎牙周膜承載區約為上顎牙周膜承載區的兩倍","(C) 上顎無牙義齒承載區約為下顎無牙義齒承載區的兩倍","(D) 上顎牙周膜承載區約為下顎無牙義齒承載區的兩倍"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-2","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"下列何種狀況最適合使用義齒黏著劑（denture adhesive）？","options":["(A) 當口腔衛生不佳的患者抱怨新製作不久的義齒缺乏固位性","(B) 患有乾口症（xerostomia）導致義齒缺乏固位性時","(C) 斷裂的下顎義齒先以義齒黏著劑固定，再尋求牙醫師協助","(D) 因舊義齒組織面已經與黏膜非常不密貼，而導致舊義齒缺乏固位性時"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"下顎全口義齒前牙若過度向唇側排列，張口時其固位性（retention）主要會受下列何種肌肉的影響？","options":["(A) 咬肌（masseter muscle）","(B) 下顎舌骨肌（mylohyoid muscle）","(C) 頦肌（mentalis muscle）","(D) 口輪匝肌（orbicularis oris muscle）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-4","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"全口義齒配戴者因念珠菌感染而造成的義齒性口炎（Candida-associated denture stomatitis），下列何者最不可能是前置因素 （predisposing factors）？","options":["(A) 高齡","(B) 女性","(C) 糖尿病","(D) 口乾症"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-2-5","subject":"ya5","topic":"臨床基礎與倫理","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"根據臨床統計，存在人類口腔中最久的牙齒為何？","options":["(A) 下顎犬齒","(B) 下顎門齒","(C) 上顎犬齒","(D) 上顎門齒"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"全口義齒邊緣成形（border molding）時，如何決定下顎唇側凸緣（labial flange）的厚度？ ①張大嘴巴 ②閉口 ③做吸吮 動作 ④下顎左右側移","options":["(A) ①②","(B) ②③","(C) ①③","(D) ③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"有關全口無牙口腔中之頰棚（buccal shelf）的敘述，下列何者正確？","options":["(A) 位於頰繫帶之前方","(B) 印模時需要緩壓（relief）","(C) 頦肌（mentalis muscle）之附著點","(D) 可以作為全口義齒之壓力承受區"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"全口義齒製作時，有關基底板及咬合堤（baseplate and occlusal rim）的功用，下列敘述何者錯誤？","options":["(A) 可建立垂直距離（vertical dimension）","(B) 可取得中心咬合位（centric occlusion）","(C) 轉移顎間關係（jaw relationship）至咬合器","(D) 可排上人工牙，以利義齒試戴工作"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"何謂發聲時的最小說話空間（closest speaking space），藉此可以作為全口無牙患者正確垂直高度的參考？","options":["(A) 靜止位置時，上、下顎間的距離","(B) 下顎前突時，後牙區呈現的顎間距離","(C) 發“s” 音時，上下門齒間平均距離","(D) 發音時，牙齒與舌頭之間的距離"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-10","subject":"ya5","topic":"咬合學基礎","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"將上顎模型置位於咬合器上時，使用面弓（face-bow）之目的為下列何者？","options":["(A) 決定中心關係（centric relation）","(B) 決定髁導引（condylar guidance）","(C) 確定咬合器上之開閉軸可符合病人下顎之開閉軸","(D) 決定垂直高度"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"選擇全口義齒之後牙時，其頰舌側寬度（buccolingual width）與患者原有自然齒之關係最好應為如何？","options":["(A) 較小","(B) 較大","(C) 相等","(D) 寬度應與患者之舌頭寬度成正比"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-2-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"有關義齒人工牙材料選擇的原則，下列何者正確？","options":["(A) 上顎之抗磨耗度應高於下顎","(B) 下顎之抗磨耗度應高於上顎","(C) 前牙區之抗磨耗度應高於後牙區","(D) 後牙區之抗磨耗度應高於前牙區"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"全口義齒後牙，若選用平面人工牙（monoplane teeth）時，下列敘述何者錯誤？","options":["(A) 適用於下顎牙嵴過度萎縮之患者","(B) 排列時仍應具雙側平衡性咬合（bilateral balanced occlusion）","(C) 由於是使用平面義齒牙，故無裂溝（fissure）或窩洞（fossa）之型態","(D) 若製作良好，其咀嚼功能與非使用平面人工牙後牙之全口義齒無明顯差異"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"為達到全口義齒的平衡咬合，有關門齒導引（incisal guidance）的敘述，下列何者錯誤？","options":["(A) 決定全口義齒門齒導引的角度，應考慮患者之美觀及發音","(B) 若前牙垂直重疊（vertical overlap）固定時，減少前牙水平重疊（horizontal overlap）可以增加門齒導引角度","(C) 門齒導引角度較大時，有助於全口義齒的穩定","(D) 門齒切斷食物屬於意識行為，可由學習及經驗控制施力的大小與方向，因此對於全口義齒來說，側移平衡（lateral balance） 比前突平衡（protrusive balance）來得更重要"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"在全口義齒的製作中，若患者有較大的髁頭導引（condylar guidance）時，為了較容易達到平衡性咬合（balanced occlusion），下列何種選擇是正確的？","options":["(A) 選擇角度較小的解剖形態牙齒","(B) 減少前後牙齒的補償曲線（compensating curve）","(C) 減少咬合平面（occlusal plane）的傾斜角度","(D) 若患者可以接受，則減少前牙之垂直覆蓋（overbite）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"有關全口義齒長期配戴後之顎骨吸收，下列敘述何者錯誤？","options":["(A) 上顎骨之吸收，會使上顎義齒之位置朝向上方及後方移動","(B) 患者可能抱怨鼻子下方之前庭處疼痛","(C) 咬合時之咬合力可能驅使上顎義齒向前移","(D) 下顎骨對應上顎骨之位置因而較往後移"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"若上顎義齒基底（denture base）於腭皺摺（rugae）處過厚時，最可能會影響下列何者？","options":["(A) 義齒的穩定性（stability）","(B) 義齒的固位性（retention）","(C) 患者的呼吸","(D) 患者的發音"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"有關全口義齒治療中，於拔牙後立即裝戴的即裝義齒（immediate denture）之優、缺點，下列何者正確？","options":["(A) 優點：容易重現原來自然牙之大小、型態與軸向","(B) 優點：立即裝戴時通常不需換底墊（relining），即可與口腔組織非常密貼","(C) 缺點：通常上顎前牙區會太薄，容易斷裂","(D) 缺點：對美觀性要求較高的病人，並不適用"],"answer":0,"clinical_level":"重點"},{"id":"ya5-105-2-19","subject":"ya5","topic":"植牙贋復","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"天生缺牙或無牙病患，接受口腔植體治療的考慮，下列敘述何者錯誤？","options":["(A) 盡量減少青春期（puberty growth）前的口腔植體治療","(B) 6 歲以前絕對禁止植體治療","(C) 青春期前的口腔植體治療以後牙為主，幫助咀嚼","(D) 青春期前以活動義齒贋復為主"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-20","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"下列何者不是覆蓋式義齒（overdenture）的優點？","options":["(A) 改善義齒的穩定性（stability）及固位性（retention）","(B) 患者的主觀感覺較佳","(C) 較全口義齒美觀","(D) 可以藉由改善咬合力量的分散來維持齒槽骨的高度"],"answer":2,"clinical_level":"重點"},{"id":"ya5-105-2-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"下列何者是造成全口義齒咬合誤差的原因？ ①填塞（packing）時施予包埋盒太大壓力 ②樹脂聚合時的收縮 ③義齒磨光 （polishing）時過熱 ④樹脂於口內之吸水膨脹","options":["(A) 僅①②③","(B) 僅③④","(C) 僅①②④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-22","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"一位 78 歲老年男性病患因日間無法控制的咬牙及磨牙前來就診，下列那一種診斷與治療比較恰當？","options":["(A) 顳顎關節障礙，以咬合板治療","(B) 肌肉痙攣，以肌肉鬆弛劑治療","(C) 咬合干擾，以咬合調整治療","(D) 會診神經內科醫師再做處置"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"鉤靠與鉤座（rests and rest seats）不具下列何種功能？","options":["(A) 提供垂直支持（vertical support）","(B) 將咬合負荷分布至支柱牙（abutment teeth）","(C) 防止可撤式局部義齒支架刺壓（impinge）軟組織","(D) 阻止垂直脫離力量（dislodging force）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-24","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"下列有關環周牙鉤（circumferential clasp）之敘述，何者錯誤？","options":["(A) 穩定性佳","(B) 彈性差","(C) 固持性佳","(D) 抱持（bracing）性質佳"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-2-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"下列那一種直接固位體（direct retainer）最具抗衡作用（reciprocation）？","options":["(A) 迴力牙鉤（back action clasp）","(B) 反作用牙鉤（reverse action clasp）","(C) 洛奇牙鉤（Roach clasp）","(D) 阿克斯牙鉤（Akers clasp）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-2-26","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"上顎遠伸性（distal extension）義齒有異物感及對發音有影響的因素為何？","options":["(A) 人工齒的材質","(B) 主連接體（major connector）的形態","(C) 中心咬合位的關係","(D) 前牙的排列位置"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-27","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"考慮生物力學之狀況，下列何者為使用平面人工牙（monoplane teeth）的適應症？ ①剩餘牙齒過度磨耗 ②剩餘牙齒形成 之史比曲線（curve of Spee）較大 ③缺牙區域較大且殘嵴（residual ridge）較平 ④前牙垂直重疊（overbite）較大","options":["(A) ①③④","(B) ①②④","(C) 僅①③","(D) 僅②④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"有關遠端延伸可撤式局部義齒（distal extension removable partial denture）在基底以及相接的支柱牙間使用剛硬式連接 （rigid connection）時，以下那些設計可以減小壓力，以避免支柱牙或殘嵴組織的傷害？ ①印取遠端缺牙嵴的功能性形態 （functional form） ②容許範圍內較寬大的基底覆蓋面積 ③具和諧咬合的較小咬合面人工牙 ④可選用較具 stress breaking 效果的鍛製金屬線牙鉤（wrought wire clasp）","options":["(A) 僅①②③","(B) 僅②③","(C) 僅①④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-29","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"相較於傳統使用牙鉤（clasp）的活動義齒，下列有關使用附連體（attachments）之敘述，何者錯誤？","options":["(A) 前牙區域使用附連體可達到較好的美觀要求，進而影響患者對義齒的接受度","(B) 冠內附連體（intracoronal attachment）較易對於支柱牙產生非軸向力（non-axial loading）的傷害","(C) 使用剛性（rigid）的精密附連體，可改善跨弓負荷轉移（cross-arch load transfer）以及增進活動義齒的穩定 （stabilization）","(D) 使用附連體在義齒製作的複雜度會高於傳統假牙，而患者也需要更好的口腔清潔指導與較多的回診配合"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"在使用析量器標記固持鉤所需的倒凹（undercut），並設計局部活動義齒支柱牙的牙鉤時，以下敘述何者正確？ ①鑄造牙鉤 （cast clasp）之固位端通常需置於 0.01 inch 的倒凹處 ②錐型鍛製金屬線牙鉤置於 0.02 inch 的倒凹處，仍可避免側向力矩 作用 ③一般來說很少使用到 0.03 inch 的倒凹 ④當支柱牙只限於牙弓單側時，應先考慮加大牙鉤固位力，而非增加支柱牙 的數目","options":["(A) 僅①②③","(B) 僅②③④","(C) 僅①③④","(D) 僅①②④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-2-31","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"下列何者並非甘迺迪氏分類法（Kennedy classification）的特點？","options":["(A) 是一種以缺牙區為主的分類法","(B) 可以知道是屬於牙齒支持或牙齒－組織支持型義齒","(C) 對義齒設計的執行有幫助","(D) 可以知道上下殘留齒列的咬合關係"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-2-32","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"關於析量主模型（master cast）的目的，下列敘述何者錯誤？","options":["(A) 決定最適當的置放途徑（path of placement）","(B) 指出須作口腔處理（mouth preparation）之部位","(C) 測量倒凹（undercut）大小及決定置放牙鉤臂之位置","(D) 整修封凹（trim blockout），以利製作耐火模型（refractory cast）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-2-33","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"有關決定可撤式局部義齒置入途徑（path of insertion）之因素，下列何者錯誤？","options":["(A) 引導面（guiding plane）","(B) 美觀（esthetics）","(C) 咀嚼方向（chewing direction）","(D) 干擾因素（interference）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-34","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"製作可撤式局部義齒時，有關上下顎間關係 （jaw relationship）之敘述，下列何者錯誤？","options":["(A) 若大部分健康的後牙存在，且無顳顎關節障礙，則可以剩餘牙齒的最大咬頭嵌合（maximum intercuspation）的狀況下製作 義齒","(B) 若大部分自然中心止點（natural centric stop）不存在時，義齒之製作應使中心關係（centric relation）與最大咬頭嵌合 （maximum intercuspation）有合諧的關係","(C) 若剩餘的後牙有傾斜（drifting）、傾移（tipping） 或突出（extrusion），須先做咬合調整，使中心關係（centric relation） 與最大咬頭嵌合（maximum intercuspation）一致","(D) 診斷模型（diagnostic cast）應以最大咬頭嵌合（maximum intercuspation）之上下顎間關係來置位 （mounting），以重現 口內情況"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-35","subject":"ya5","topic":"臨床基礎與倫理","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"一位 65 歲女性患者，要求製作可撤式局部義齒，經血液檢查發現，飯前血糖高過正常值兩倍。有關此患者之敘述，下列何者 錯誤？","options":["(A) 在贋復治療前應請患者找內科醫師，先控制糖尿病情","(B) 唾液分泌量經常會減少","(C) 不易取得咬合記錄","(D) 口腔黏膜較易受傷"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"有關可撤式局部義齒印模時，採用修正模型印模（altered cast impression）之敘述，下列何者正確？ ①可得到支柱牙倒凹 （undercut）正確的分布位置 ②於金屬支架（metal framework）上添加樹脂基底，應於金屬支架試戴前進行 ③可在殘嵴 主要承壓區記錄其功能形態（functional form） ④記錄殘嵴非承壓區的解剖形態（anatomic form）","options":["(A) 僅①②","(B) 僅②③④","(C) 僅③④","(D) 僅②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"下列有關遠心游離端可撤式局部義齒，利用選擇性加壓印模（selective pressure impression）之敘述，何者錯誤？","options":["(A) 選擇性加壓印模的目的，是讓有支持能力的組織多負擔支持，以保護較不能負擔的組織","(B) 最常使用的印模材是流動性最好的 agar 印模材","(C) 以下顎而言，主承壓區（primary stress-bearing area）是頰棚區（buccal shelf）","(D) 可以在模托用 spacer 或鑽洞來控制印模時對組織的壓力"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-38","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"有關 Kennedy Class III 可撤式局部義齒咬合模式之敘述，下列何者錯誤？","options":["(A) 在中心咬位時，所有咬合接觸必須均勻","(B) 在離中心（eccentric）運動時，工作側（working side）應避免接觸","(C) 在離中心（eccentric）運動時，平衡側（balancing side）應避免接觸","(D) 前突運動（protrusion）時，義齒應避免咬合接觸"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-2-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"在可撤式局部義齒贋復時，下列那一項不是選擇零度後牙的適應症？","options":["(A) 巴金森氏症（Parkinsonism）病人","(B) 殘嵴較平","(C) 對咬牙有明顯磨耗（attrition）現象","(D) 殘餘前牙呈安格氏二級異常咬合第二分類（Angle's Class II, Div. 2）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"關於可撤式局部義齒換底墊（relining）之敘述，下列何者錯誤？","options":["(A) 如果以手指加壓遠端缺牙區義齒之咬合面會導致義齒鉤靠（rest）離開鉤座（rest seat）超過 2 mm 或更多時，則需考慮換底 墊","(B) 盡量以技工室換底墊法（laboratory reline）來完成","(C) 應根據覆蓋於殘嵴（residual ridge）上軟組織的條件來選擇印模材","(D) 須注意於換底墊印模時，維持咬合狀態"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-2-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"有關可撤式局部義齒清潔維護之敘述，下列何者錯誤？","options":["(A) 上顎為全口活動義齒下顎為可撤式局部義齒時，晚上應該戴著義齒睡覺","(B) 正常狀況下，宜每六個月做追蹤檢查","(C) 清洗義齒可用小頭軟毛牙刷刷洗","(D) 晚上不佩戴義齒時，應浸泡在清水中"],"answer":0,"clinical_level":"重點(深度)"},{"id":"ya5-105-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"下列有關可撤式局部義齒之主模型封凹（blockout）的敘述，何者錯誤？","options":["(A) 封凹步驟應在主模型複製成耐火模型前完成","(B) 封凹蠟應置於外廓高隆線（height of contour）上方","(C) 封凹的目的在消除多餘的組織倒凹（undercut）","(D) 牙齒支持（tooth-support）的局部活動義齒，一般使用平行式的金屬器械移除多餘的蠟"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"下列有關義齒支架（framework）鑄造步驟的敘述，何者錯誤？","options":["(A) 鑄道成形器（sprue former）的位置和幾何形態與使用的金屬有關","(B) 鑄道連接處要圓滑","(C) 輔助鑄道成形器（auxiliary sprue former）的直徑約為主要鑄道的 1/3 到 1/4","(D) 去蠟所需的時間和溫度與使用的金屬無關"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-44","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"一般而言，下列何種可撤式局部義齒的設計，適合用單一鑄道（single sprue）來製作？","options":["(A) 單一腭槓（single palatal bar）","(B) 前後腭槓（anterior-posterior palatal bar）","(C) 腭板（palatal plate）","(D) U型腭連接體（U-shaped palatal connector）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"下列何者可以有效降低修磨牙齒時的髓腔溫度（pulpal temperature）？①以高速手機（high speed handpiece）用力修磨牙齒 ②採用新的鑽石磨針 ③修磨時大量噴水 ④使用高速手機噴氣在牙齒上","options":["(A) ①②④","(B) ①②③","(C) ③④","(D) ②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-46","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"固定牙冠內面的粗糙程度會影響與黏合劑的結合能力，試問下列何種大小的噴砂顆粒，可用來增加牙冠內面之粗糙度？","options":["(A) 5 µm","(B) 50 µm","(C) 0.5 mm","(D) 1.0 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-47","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"下列何者支柱牙的邊緣設計，會導致義齒邊緣與支柱牙完成線（finish line）有最大的間隙？","options":["(A) 5°斜切肩台型（beveled shoulder）","(B) 15°斜切肩台型（beveled shoulder）","(C) 30°斜切肩台型（beveled shoulder）","(D) 45°斜切肩台型（beveled shoulder）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-105-2-48","subject":"ya5","topic":"咬合學基礎","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"下列何者為泛得繪（Pantograph）裝置之用途？","options":["(A) 用於以全調節咬合器進行咬合調整","(B) 用於定軸面弓（kinematic facebow）轉移，以記錄真正樞鈕軸","(C) 用於記錄下顎運動","(D) 用於數位全口X光照射之裝置"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-49","subject":"ya5","topic":"牙科材料學","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"不完全的印模材聚合反應會影響到印模的精確性，試問某些乳膠手套會影響下列何種印模材料的聚合反應？","options":["(A) 不可逆性水凝膠（irreversible hydrocolloid）","(B) 多硫化物（polysulfide）","(C) 加成式矽膠（addition silicone）","(D) 聚乙醚（polyether）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"有關牙根根管與根柱之敘述，下列何者錯誤？","options":["(A) 細的根柱比粗的根柱對牙根有較低的應力","(B) 大部分牙根都有凹陷（concavity），是因為頰舌側比近遠心側窄的緣故","(C) 根柱的直徑不可超過牙根直徑的1/3，且根管壁的牙本質至少有1 mm厚","(D) 預製型根柱（prefabricated post）之橫切面通常呈圓形，能適用的根管不多"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-2-51","subject":"ya5","topic":"咬合學基礎","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"製作固定式義齒時，最常使用的咬合觀念為何？","options":["(A) 犬齒導引（canine guidance）的咬合關係","(B) 平衡性咬合關係（balanced occlusion）","(C) 增加垂直重疊（vertical overlap）","(D) 平坦的後牙咬頭（flattened posterior cusps）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-2-52","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"牙冠增長術（crown-lengthening procedures）手術前的考量因素，不包括下列何者？","options":["(A) 美觀","(B) 是否會有根叉暴露（root furcation exposure）","(C) 術後的牙齒動搖度","(D) 牙髓的活性"],"answer":3,"clinical_level":"重點"},{"id":"ya5-105-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"當患者的左上第一小臼齒及第一大臼齒缺失，其他牙齒皆有適當的牙周支持時，下列何者是一種較簡單的修復方式？","options":["(A) 以左上犬齒、第二小臼齒和第二大臼齒當支柱牙的五個單位牙橋","(B) 在左上第二小臼齒的近心加上一非剛性連接體（nonrigid connector）的五個單位牙橋","(C) 在左上第二小臼齒的遠心加上一非剛性連接體（nonrigid connector）的五個單位牙橋","(D) 以左上第一小臼齒當懸臂式橋體，第二小臼齒和第二大臼齒當支柱牙的四個單位牙橋"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"當固定牙橋的橋體長度增加時，下列那些措施能夠減少失敗率？ ①採用彈性係數較高的金屬 ②增加橋體金屬支架（metal framework）的截面積 ③在支柱牙的近心與遠心側修磨溝槽 ④在支柱牙的頰側與舌側修磨溝槽 ⑤增加燒瓷的厚度","options":["(A) 僅①③④⑤","(B) 僅①②③","(C) 僅①②④","(D) 僅②④⑤"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"下列何者不是樹脂黏著式固定牙橋（resin-bonded fixed bridge）的禁忌症（contraindication）？","options":["(A) 深咬（deep vertical overlap）","(B) 第二小臼齒缺失","(C) 牙冠高度不足","(D) 對鎳金屬過敏"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-2-56","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"下列何者並非全瓷牙冠的優點？","options":["(A) 腭舌側面較少的牙齒修磨量","(B) 美觀","(C) 良好的生物相容性","(D) 良好的透明性"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-2-57","subject":"ya5","topic":"牙科材料學","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"全瓷補綴之製作技術，何者不是以CAD/CAM技術完成？","options":["(A) Procera","(B) In-Ceram","(C) Cerec","(D) Lava"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-58","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"已在工作模型上完成各種調整、修磨及磨光等步驟之牙冠，於口內試戴時，發現有咬合太高的情形。請問下列何者是發生此現 象的最可能原因？","options":["(A) 未作暫時牙冠","(B) 牙冠與鄰牙之接觸區太鬆","(C) 支柱牙咬合面切削不足","(D) 製作蠟型時，單齒模（die）底部與基底之間有蠟碎屑黏連"],"answer":0,"clinical_level":"重點"},{"id":"ya5-105-2-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"比色時，室內擺設或牆壁的顏色明度（Munsell value）至少在多少以上為佳？","options":["(A) 1","(B) 4","(C) 7","(D) 10"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-60","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"要決定兩個中門齒的長度時，可以請患者發下列那一個聲音，來測試長度是否適當？","options":["(A) F","(B) T","(C) S","(D) H"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-2-61","subject":"ya5","topic":"植牙贋復","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"下列那些因素可能造成人工植體支柱體的螺絲（abutment screw）鬆脫？①承受過度非平行於人工植體軸向的咬合力 ②過度 的側方接觸（excessive lateral contacts） ③螺絲本身沒有適度鎖緊 ④骨整合尚未完全時，過早製作贋復體 ⑤過度的懸 臂接觸（excessive cantilever contact）","options":["(A) 僅①③","(B) ②③④","(C) ①②③⑤","(D) ①②④⑤"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-62","subject":"ya5","topic":"植牙贋復","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"贋復體設計時，若將自然牙與人工植體相連，容易造成下列那些問題？①破壞人工植體周邊的骨整合 ②贋復物之黏合劑受到 破壞，導致贋復物鬆動 ③增加自然牙周邊牙周囊袋的深度","options":["(A) 僅①③","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-63","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"支柱牙間的平行度是製作固定式牙橋必須考量的因素之一，若以傳統方式製作牙橋，建議支柱牙間的長軸聚攏 （convergence）角度至多不超過多少度？","options":["(A) 40","(B) 30","(C) 20","(D) 10"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"製作黏著式牙橋（resin-bonded bridge）時，支柱牙的近遠心傾斜度（mesiodistal inclination）最多不應超過多少度？","options":["(A) 3度","(B) 6度","(C) 10度","(D) 15度"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-65","subject":"ya5","topic":"牙科材料學","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"下列關於蠟型包埋之敘述，何者正確？","options":["(A) 將包埋材倒入鑄造環中時，震盪越久越好，以避免氣泡出現在包埋材內","(B) 鑄造環襯裡（ring liner）應盡量壓扁，以提供蠟型的膨脹空間","(C) 鑄造環襯裡若沒有先弄濕，會吸走混合後包埋材的水分，而導致包埋材整體膨脹量之增加","(D) 包埋蠟型時為了避免氣泡生成，應該調稀包埋材"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-66","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"燒瓷完成（瓷燒結溫度為 982℃）的牙橋要銲接時，若手邊有兩種銲劑，其熔點分別為：①710~743℃ ②1110~1127℃。請 問要選擇那一種銲劑進行銲接，而這種焊接技巧名稱為何？","options":["(A) 銲劑選①，技巧稱為前銲（pre-ceramic soldering）","(B) 銲劑選②，技巧稱為前銲（pre-ceramic soldering）","(C) 銲劑選①，技巧稱為後銲（post-ceramic soldering）","(D) 銲劑選②，技巧稱為後銲（post-ceramic soldering）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-67","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"下列關於顳顎關節韌帶組織，何者錯誤？","options":["(A) 韌帶組織的長度大致固定不變","(B) 固定關節盤的韌帶（discal ligament）並非真正的韌帶","(C) 關節囊韌帶（capsular ligament）可限制顳顎關節髁頭的側向運動","(D) 顳顎韌帶（temporomandibular ligament）能限制開口量"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-68","subject":"ya5","topic":"咬合學基礎","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"最大咬力發生在上下顎牙齒分開約多少距離時？","options":["(A) 3～5 mm","(B) 5～7 mm","(C) 9～10 mm","(D) 15～17 mm"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-69","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"關於某個體咬力之敘述，何者錯誤？","options":["(A) 臼齒功能性咬力介於 150～250 牛頓之間，最大緊咬可達 1000 牛頓","(B) 咬力與肌梭（muscle spindle）之長度無關","(C) 下顎前突時咬力變強","(D) 疼痛的牙齒在牙周被麻醉時咬力會增強"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-70","subject":"ya5","topic":"咬合學基礎","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"在咀嚼系統中，游離神經末端（free nerve ending）主要在偵測下列那一項？","options":["(A) 肌肉張力（muscle tension）","(B) 肌肉長度（muscle length）","(C) 本體感受（proprioception）","(D) 傷害感受（nociception）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-71","subject":"ya5","topic":"咬合學基礎","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"下列何者會影響義齒咬頭高度（cusp height）？ ①前方導引（anterior guidance） ②咬合平面（plane of occlusion） ③ 史比氏曲線（curve of Spee） ④下顎側方運動（mandibular lateral movement）","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-105-2-72","subject":"ya5","topic":"咬合學基礎","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"下列何者不是自然牙齒離心咬合調整（eccentric occlusal adjustment）的目標？","options":["(A) 提供咬合時各種方向不受限的滑動","(B) 提供相似的左右側的門齒及犬齒導引（incisal, cuspid guidance）","(C) 除去工作側的干擾，並維持平衡側之接觸","(D) 可採 BULL 法則來修磨"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-73","subject":"ya5","topic":"咬合學基礎","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"當作側方運動時，下顎的瞬間側移量（immediate side shift）越大時，下列敘述何者正確？ ①下顎牙齒的齒溝會越偏近心側 ②上顎牙齒的齒溝則越偏遠心側 ③咬頭高度需更高 ④上顎前牙舌側凹陷越小","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-2-74","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"下列何者不影響下顎的邊緣運動（border movement）？","options":["(A) 牙齒","(B) 舌頭","(C) 咀嚼肌肉","(D) 顳顎關節之韌帶"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-2-75","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"顳顎關節內部紊亂症（internal derangement）當中，最常見的關節盤移位為何？","options":["(A) 關節盤向前方移位","(B) 關節盤向後方移位","(C) 關節盤向左方移位","(D) 關節盤向右方移位"],"answer":0,"clinical_level":"重點"},{"id":"ya5-105-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"下列關於關節產生交替彈響（reciprocal click）的敘述，何者錯誤？","options":["(A) 可能是可回復性關節盤移位（displacement with reduction）造成","(B) 可能是不可回復性關節盤移位（displacement without reduction）造成","(C) 關節盤沒有移位亦可能產生","(D) 可做為關節內紊亂（internal derangement）的診斷依據"],"answer":1,"clinical_level":"一般"},{"id":"ya5-105-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"當患者使用上顎密西根式咬合板，並作前突運動至門牙切端對咬時（edge-to-edge），下顎門牙與上顎咬合板間的距離，下列 何者最為適當？","options":["(A) 距離 1～2 mm","(B) 距離 3～5 mm","(C) 距離 5 mm 以上","(D) 應輕微接觸"],"answer":0,"clinical_level":"一般"},{"id":"ya5-105-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"以密西根咬合板治療的適用情形，不包括以下何者？","options":["(A) 夜間磨牙","(B) 三叉神經痛（trigeminal neuralgia）","(C) 穩定動搖牙齒","(D) 有助獲得中心關係"],"answer":1,"clinical_level":"重點"},{"id":"ya5-105-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"患者之主動最大張口距（active range of mandibular opening）為 52 mm，被動最大張口距（passive range of mandibular opening）為 58 mm，下列敘述何者正確？","options":["(A) 患者之拮抗試驗（Widerstand test）結果為 6 mm","(B) 患者可能有顳顎關節盤（disc）前置位（anterior displacement）","(C) 患者可能有關節鬆弛（joint hypermobility）","(D) 患者可能有第二類型顳顎關節內部紊亂"],"answer":2,"clinical_level":"一般"},{"id":"ya5-105-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"以下關於夜間磨牙症（bruxism）病因的敘述，何者錯誤？","options":["(A) 夜間磨牙僅發生在淺層睡眠過程中","(B) 夜間磨牙者多無主要精神疾病（major psychopathology）","(C) 夜間磨牙似與某些人格特質有關","(D) 某些藥物會引發夜間磨牙"],"answer":0,"clinical_level":"重點"},{"id":"ya5-106-1-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"口腔黏膜具有黏彈的物理性質（viscoelastic property），當全口活動義齒使用時，有關下方黏膜的敘述，下列何者錯誤？","options":["(A) 咀嚼食物時，義齒下方黏膜及殘嵴組織單位面積之受力，上顎比下顎要小","(B) 口腔黏膜越厚時，受力後的沉降絕對值越大，百分比也越高","(C) 咀嚼食物較快時，其口腔黏膜受力後的變化較接近彈性性質（elastic property）","(D) 咀嚼食物比牙關緊咬更易觸發口腔黏膜的潛變行為（creeping behavior）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"下列何者不是導致無牙口腔殘嵴吸收的誘發因素（predisposing factors）？","options":["(A) 維生素D攝取不足","(B) 性別","(C) 平衡且協調的咬合關係","(D) 接受過齒槽骨成形術（alveoloplasty）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"有關唾液與義齒製作之關係，下列敘述何者錯誤？","options":["(A) 唾液之流量及黏度（viscosity）會對全口義齒成功與否造成影響","(B) 正常人休息狀態之唾液流量每分鐘約 1 毫升","(C) 服用多種藥物可能會造成唾液流量減少","(D) 高年齡是影響唾液流量減少的主要原因之一"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"下列有關振動線（vibrating line）的敘述，何者錯誤？ ①是硬腭（hard palate）與軟腭（soft palate）的界線 ②平均約在腭 小窩（fovea palatinae）前方 2 mm ③上顎全口義齒的後緣絕對不可超過振動線 ④是一個區域（area）而非一條線（line）","options":["(A) ①②","(B) ①③","(C) ②③","(D) ①④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"有關顎舌骨肌後窩（retromylohyoid fossa）的敘述，下列何者錯誤？","options":["(A) 下顎全口義齒之舌側凸緣（lingual flange）可以延伸至顎舌骨肌後窩","(B) 受下顎舌骨肌（mylohyoid muscle）活動的影響","(C) 前緣為下顎舌骨肌（mylohyoid muscle）","(D) 後緣為顎舌骨肌後幕（retromylohyoid curtain）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-1-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"全口活動義齒邊緣成形（border molding）時，要求患者慢慢閉口至緊咬，可表現下列何種肌肉的影響？","options":["(A) 翼外肌（external pterygoid muscle）","(B) 咬肌（masseter muscle）","(C) 口輪匝肌（orbicularis oris）","(D) 下顎舌骨肌（mylohyoid muscle）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-7","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"有關隆凸（torus）的敘述，下列何者正確？","options":["(A) 上顎位於腭部的中線處，發生的機率很低，只有 5％","(B) 下顎通常位於兩邊的第一小臼齒和第二小臼齒舌側","(C) 隆凸上方覆蓋厚的黏膜","(D) 下顎隆凸在緩壓（relief）時通常可以不破壞義齒的邊封（border seal）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-8","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"全口義齒由咬合面觀，上顎正中門齒之切緣（incisal edge）平均約在門齒乳頭（incisive papilla）中點之前方約幾 mm 處？","options":["(A) 3","(B) 5","(C) 8","(D) 11"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-1-9","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"當患者難以建立可重複性的水平顎間關係時，可以利用下列何種咬合學方法來幫助義齒的穩定？","options":["(A) 建立長中心（long centric）","(B) 努力達成三點接觸（tripod contact）","(C) 選擇頰舌向徑較寬的人工牙","(D) 盡量選擇陶瓷人工牙"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-1-10","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"下列有關最小說話空間（closest speaking space）的敘述，何者錯誤？","options":["(A) 一般上下顎前牙間隙平均值大約為 3 mm","(B) 可以由發“s” 音時上下前牙之間的距離來決定","(C) 可藉以檢查咬合垂直距離（occlusal vertical dimension）是否正確","(D) 可幫助決定上顎前牙排牙位置"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-1-11","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"當全口義齒依照平面咬合（monoplane occlusion）觀念，並選用零度牙製作時，下列敘述何者錯誤？","options":["(A) 只需要上下顎的中心關係（centric relation）咬合紀錄","(B) 可以僅使用簡單型咬合器（simple articulator）","(C) 上下前牙排列沒有水平及垂直重疊（overjet and overbite）","(D) 當患者有異功能咬合習慣（parafunctional habits）時，依此方式完成的全口義齒對基底下的黏膜較無側方壓力"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"有關全口義齒人工牙的選擇以及咬合觀念，下列敘述何者錯誤？","options":["(A) 犬齒導引（canine guidance）的咬合模式並不適合運用於全口義齒的咬合","(B) 依照平面咬合（monoplane articulation）觀念製作全口義齒，不能使用簡單型咬合器","(C) 使用零度牙配合補償曲線（compensating curves）來排列牙齒，仍可以達成平衡咬合（balanced occlusion）的要求","(D) 製作帕金森氏症（Parkinson's disease）患者的全口義齒應使用零度牙及平面咬合（monoplane articulation）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"牙齒排列位置會影響患者的發音，下列敘述何者最正確？","options":["(A) 在安格氏 Class I 咬合分類的患者，發“s” 音時，上下顎門牙是位在同一垂直平面上","(B) 當上顎門牙位置太低時，“v” 音會變成“f ” 音","(C) “th” 音與牙齒位置無關","(D) 發“t” 音時，無法判斷前牙的位置是否正確"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"全口義齒患者若具有較大角度的髁頭導引（condylar guidance）時，下列何種設定的改變，有助於達到平衡咬合？","options":["(A) 將原先的 33 度牙換成 20 度人工牙","(B) 在美觀條件可接受的情況下，減少前牙的垂直重疊（vertical overlap）","(C) 減小前後方向的補償曲線（compensating curve）","(D) 減小咬合平面的傾斜度"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-1-15","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"製作全口義齒時，下列何種情況需要重置位（remounting）下顎模型？ ①中心關係（centric relation）記錄錯誤時 ②將下 顎咬合蠟堤往唇側移 2 毫米時 ③欲改變咬合垂直距離時","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"下列對於全口義齒患者之指示何者錯誤？","options":["(A) 用新義齒咀嚼之學習適應期至少需 6 至 8 週","(B) 如能同時用兩側咀嚼將可減少義齒傾移","(C) 應試圖向下推動食物，以助義齒穩定於殘嵴上","(D) 咀嚼時食物應放在嘴角附近之牙齒間，而非放在前牙之間"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"患者配戴新的全口義齒一般需要多久的時間適應，說話時才能較為自然？","options":["(A) 1～2 星期","(B) 2～4 星期","(C) 1～2 個月","(D) 2～4 個月"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"當病人拔牙後立即戴用即裝全口義齒時，下列何種因應方式錯誤？","options":["(A) 前 24 小時需持續戴用","(B) 24 到 72 小時之內應逐漸增加不戴的時間，以免異物干擾傷口復原","(C) 避免硬食","(D) 24 小時內可進行冰敷"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-19","subject":"ya5","topic":"植牙贋復","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"有關骨整合植體治療的敘述中，下列何者正確？ ①年幼病患，因骨質密度較低，所以不適合植體贋復 ②曾接受頭頸部放射 線治療的病患，最少一年後才能進行種植手術 ③已骨整合植體會加強放射線的效果，破壞骨質，所以放射線治療前，應先去 除植體 ④吸煙會影響骨整合植體治療的成功率","options":["(A) ①②③","(B) ②③④","(C) 僅①③","(D) 僅②④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-20","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"與全口義齒相較，何者不是覆蓋式義齒（overdenture）之優點？","options":["(A) 可經由改善牙冠牙根比（crown-root ratio），保留支柱牙","(B) 支柱牙的邊緣牙齦（marginal gingiva）較易清潔","(C) 支柱牙與無牙嵴黏膜可共同支撐咬合壓力","(D) 保留牙齒，可減低殘嵴吸收"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-1-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"如圖所示，A 處為全口義齒後緣，B 處的珠狀緣飾（bead）與振動線（vibrating line）之間距離應為多少 mm？","options":["(A) 0.5","(B) 1","(C) 2","(D) 3"],"answer":2,"image":"ya5-106-1-21.jpeg","clinical_level":"重點"},{"id":"ya5-106-1-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"患者至牙科門診抱怨新製作的義齒穩定性不佳，且義齒完成後，開始出現顳顎關節痠痛等臨床症狀。下列何者為最正確的臨床 處置？","options":["(A) 告知患者上一位牙醫師技術不佳和經驗不足導致義齒穩定性不佳","(B) 告知患者應該早來找你，就不會有這些問題","(C) 了解患者牙科治療的病史和進行臨床口腔檢查，向患者說明可能的原因和處置方式。在患者同意的狀況下，調整目前的義齒 以減緩患者的問題與不適","(D) 告訴患者先去看精神科"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"某患者下顎左及右側全部大臼齒缺失，兩顆門齒經牙周病治療後狀況不佳，將來可能拔除，則最適合採用之可撤式局部義齒主 連接體為何？","options":["(A) 舌側槓（lingual bar）","(B) 舌下槓（sublingual bar）","(C) 唇側槓（labial bar）","(D) 舌側板（lingual plate）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"當某患者下顎多顆前牙之間有間隙（space）存在，最優先考慮採用之主連接體為何？","options":["(A) 舌側板（lingual plate）","(B) 舌側槓（lingual bar）","(C) 舌面隆凸槓（cingulum bar）","(D) 旋鎖式裝置（swing-lock device）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"可撤式局部義齒的直接固位體（direct retainer）的敘述何者正確？ ①抑制義齒的移位（displacement） ②抑制義齒基底床 的下沈 ③主要的固位力放在黏膜上 ④以鉤座（rest seat）的型態設置 ⑤拮抗鉤臂放於析量線（survey line）上面","options":["(A) ①②③","(B) ②③④","(C) ③④⑤","(D) ①②⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-26","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"關於局部義齒，義齒床基底（denture base）連結樹脂床的小連接體（minor connector），有開放大格子（open lattice）及網 狀（mesh）兩種設計，下列敘述何者錯誤？","options":["(A) 開放大格子的在做樹脂填充（resin packing）時比較容易","(B) 網狀的強度較開放大格子的好","(C) 開放大格子的其縱支柱（longitudinal strut）不應干擾排牙（tooth arrangement）","(D) 網狀的厚度較薄，適用於垂直空間（vertical space）受限的情形"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"遠伸性可撤式局部義齒（distal extension removable partial denture）於咀嚼時會有不同方向的轉動，請問下列何種轉動對義 齒支柱牙（abutment）的牙周組織傷害最大？","options":["(A) 於矢狀面（sagittal plane）上繞著遠心鉤靠（rest）往組織方向的下沈運動","(B) 於額狀面（frontal plane）上繞著殘嵴（residual ridge）所做頰舌側（buccolingual）方向的運動","(C) 於矢狀面（sagittal plane）上因食物黏性將義齒帶離組織的運動","(D) 於水平面（horizontal plane）上繞著牙弓（dental arch）中心垂直軸（vertical axis）所做的水平方向運動"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-106-1-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"有關甘迺迪第一類型（Kennedy Class I）可撤式局部義齒的設計，下列敘述何者正確？ ①應具備有彈性的直接固位 （flexible direct retention）設計 ②直接固位體（direct retainer）在義齒受力時，應往支柱牙較小倒凹（undercut）處移動 ③義齒基底涵蓋面積應盡可能大且貼密 ④需適當放置間接固位體（indirect retainer）","options":["(A) 僅①③","(B) 僅①③④","(C) 僅②④","(D) ①②③④"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-106-1-29","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"如圖所示，活動義齒支架上的小圓圈，所指部位名稱為何？","options":["(A) 模型止位（cast stop）","(B) 內終接線（internal finish line）","(C) 外終接線（external finish line）","(D) 輔助性鉤靠（auxiliary rest）"],"answer":1,"image":"ya5-106-1-29.jpeg","clinical_level":"一般"},{"id":"ya5-106-1-30","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"製作可撤式局部義齒時，模型上那些區域不需要作平行式封凹（parallel blockouts）？","options":["(A) 需被剛性連接體跨越的組織倒凹（tissue undercuts to be crossed by rigid connectors）","(B) 槓狀牙鉤之下的組織倒凹（tissue undercuts beneath bar-clasps）","(C) 作為導引面的牙齒臨接面（proximal tooth surfaces to be used as guiding planes）","(D) 在金屬支架遠心端之後的組織倒凹（tissue undercuts distal to cast framework）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-1-31","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"可撤式局部義齒支柱牙修形（abutment preparation）時，鉤靠（rest）和小連接體（minor connector）之間的角度應為多 少？","options":["(A) 等於 90 度","(B) 小於 90 度","(C) 大於 90 度","(D) 任何角度皆可"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-32","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"有關可撤式局部義齒（removable partial denture）的支柱牙（abutment）用全鑄牙冠（full cast crown）修復的設計，下列敘 述何者錯誤？","options":["(A) 可以減輕支柱牙的負擔","(B) 可以減少齲齒（caries）的發生","(C) 可以提供理想的支柱牙外形（contour），以配合設計","(D) 可以預留鉤靠座（rest seat）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-106-1-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"遠心游離端可撤式局部義齒，利用 functional reline method 來印模時，下列敘述何者正確？","options":["(A) 以義齒基底置入印模材，放入口中，請病人輕咬咬合蠟堤","(B) 以義齒基底置入印模材，放入口中，請病人重咬咬合蠟堤","(C) 以義齒基底置入印模材，放入口中，用手指壓住遠心游離端蠟堤","(D) 以義齒基底置入印模材，放入口中，用手指壓住鉤靠及間接固位體"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-34","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"造成可撤式局部義齒金屬支架在齒模上很合適，但在口內試戴卻不合適，其最可能的原因為何？","options":["(A) 金屬的熱脹冷縮","(B) 印模時支柱牙（abutment）的位移","(C) 口腔內牙菌斑（plaque）的蓄積","(D) 金屬支架的電鍍及打光"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-35","subject":"ya5","topic":"牙科材料學","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"強化複合樹脂的人工牙（improved acrylic resin teeth），和下列何種材料對咬，所產生的磨耗最小？","options":["(A) 自然牙（natural tooth）","(B) 金合金（gold alloy）","(C) 強化複合樹脂的人工牙","(D) 陶瓷牙（porcelain teeth）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-36","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"在製作上顎可撤式局部義齒時，下列何者情況不需要使用記錄基底（record base）及咬合堤（occlusion rim）就可以得到正確 的面弓轉移（face-bow transfer）？","options":["(A) 甘迺迪第一類（Kennedy Class I）缺牙","(B) 甘迺迪第二類（Kennedy Class II）缺牙","(C) 甘迺迪第三類第一型（Kennedy Class III, modification 1）缺牙","(D) 甘迺迪第一類第一型（Kennedy Class I, modification 1）缺牙"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-37","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"裝戴新的可撤式局部義齒數星期後，鉤靠（rest）斷裂，下列何者是最可能的原因？ ①鉤靠厚度不足 ②鉤靠鑄造金屬有空 泡（bubble） ③鉤靠上有咬合干擾 ④牙鉤臂（clasp arm）有裂痕 ⑤主連接體剛性（rigidity）大","options":["(A) ①②③","(B) ②③④","(C) ①②⑤","(D) ③④⑤"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-1-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"可撤式局部義齒支柱牙（abutment teeth）的那一個面最容易形成牙菌斑（dental plaque）？","options":["(A) 支柱牙與義齒基底之鄰接面","(B) 咬合面","(C) 頰側面","(D) 遠離義齒基底之鄰接面"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-1-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"處理局部活動義齒的主模型（master cast）時，下列敘述何者正確？","options":["(A) 修整主模型時，至少須留 2 mm 的邊緣","(B) 主模型最薄位置如上顎腭部中心處，應該有 5 mm 的厚度","(C) 主模型上不必保留完整的舌繫帶形態","(D) 修磨前，不宜將主模型浸泡於清水中"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-1-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"以下為可撤式局部義齒金屬支架（metal framework）的製作步驟。下列何者為正確的製作程序？ ①蠟型製作（waxing） ②磨光與完成（polishing and finishing） ③複製（duplication）及以蜂蠟（beeswax）浸泡 ④封凹及緩壓（blockout and relief） ⑤裝鑄道與包埋（spruing and investing） ⑥燒除及鑄造（burnout and casting）","options":["(A) ①③④②⑤⑥","(B) ③①⑤②④⑥","(C) ④③①⑤⑥②","(D) ④⑤⑥①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-41","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"有關後牙人工樹脂（resin）牙齒的選擇，下列敘述何者錯誤？","options":["(A) 易修正（modify）及再塑形（reshaping）","(B) 易加溢流道（spillway）及溝（groove）來增加咀嚼效益","(C) 可減少頰舌寬（buccolingual width）來減少咬合面積而不致影響強度及美觀","(D) 咬合面中心咬合（centric occlusion）咬點不需因磨耗而做經常性的咬合追踪"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-42","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"上顎存留牙齒為 43︱34時，是屬於可撤式局部義齒分類中的那一類？","options":["(A) Kennedy Class IV modification 2","(B) Kennedy Class II modification 2","(C) Kennedy Class I modification 1","(D) Kennedy Class V modification 2"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-43","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"承上題，下顎為自然牙無缺牙情況，上顎義齒之設計，下列何者較不理想？","options":["(A) 做43︱34八顆固定牙橋，再做可撤式義齒","(B) 所有存留齒都固定在一起的懸臂式固定義齒","(C) 43︱與︱34分別作兩顆固定局部義齒連接精密附連體（cantilever bridge），再做可撤式義齒","(D) 將43︱34做修整再製作可撤式義齒即可"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-44","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"承上題，下顎為無牙嵴單顎全口義齒（single complete denture）情況，上顎義齒之設計，下列何者較理想？ ①做43︱34八 顆固定牙橋，再做可撤式義齒 ②所有存留齒都固定在一起的懸臂式固定義齒 ③43︱與︱34分別作兩顆固定局部義齒，連接 精密附連體，再做可撤式義齒 ④將43︱34做修整再製作可撤式義齒即可","options":["(A) 僅①②③","(B) 僅②③④","(C) 僅③④","(D) 僅①③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"關於支柱牙修形時長凹槽（fluting）的敘述，下列何者正確？①適用於牙周被破壞後的大臼齒 ②位於根叉處的牙齒修形 ③ 需注意方向與牙冠置入途徑一致 ④此處的修形邊緣特別厚，以保持贋復物的強度 ⑤此設計的目的為增加支柱牙的固位 （retention）","options":["(A) 僅②④⑤","(B) 僅③④⑤","(C) 僅①②③","(D) 僅①③⑤"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"全牙冠支柱牙在修磨完成後應與鄰牙分開，試問邊緣外側面與鄰牙應有的間隙至少須為多少mm？","options":["(A) 0.2","(B) 0.6","(C) 1.2","(D) 2.0"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-47","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"下圖為口內臼齒牙冠修形後由咬合面觀看，其最明顯的缺點為何？","options":["(A) 近心端與遠心端兩側的錐狀夾角太大","(B) 邊緣（margin）寬窄不一","(C) 固位性不足，為達到更好的固位性，應在頰、舌兩側牆加平行溝（groove）","(D) 咬合面的外形沒有順著牙齒的外形修形"],"answer":1,"image":"ya5-106-1-47.jpeg","clinical_level":"一般"},{"id":"ya5-106-1-48","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"下列何種情況在印完最終模型後可以不需要做咬合紀錄（bite registration）？①安格式一級咬合，全口牙齒都健在，但需要製 作平面咬合板 ②前牙開咬而要製作上顎右側中門齒的全瓷冠 ③安格式一級咬合，智齒已被拔除，要製作下顎左側36,37的 兩顆金屬牙冠 ④製作下顎右側兩顆小臼齒外加一顆大臼齒橋體的懸臂式接合牙冠（44-45-X cantilever splinted crowns） ⑤製作上顎右側第一大臼齒的金合金嵌體（gold inlay）","options":["(A) 僅①③⑤","(B) 僅②⑤","(C) 僅②③⑤","(D) 僅①②④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-49","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"有關印模前可用電刀（electrosurgery）修整牙齦之敘述，下列何者錯誤？","options":["(A) 裝置經皮神經電刺激器（TENS,transcutaneous electrical nerve stimulation unit）的病人，不可使用電刀","(B) 可用於切除較薄的附連牙齦（attached gingiva）","(C) 須設定在未調整（unmodulated）的交流電下使用","(D) 使用時不可接觸至金屬復形物"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-50","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"齒質完整的下顎大臼齒，根管治療後較保守而安全的復形方式為何？","options":["(A) 以銀粉充填即可","(B) 裝置嵌體（Inlay）","(C) 冠蓋體（Onlay）","(D) 全金屬冠"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-51","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"關於牙根切除術（root resection）後的牙齒的處置，下列何者錯誤？","options":["(A) 不一定要做牙冠修復（crown restoration）","(B) 一定要有根柱冠心（dowel-core）","(C) 可使用鑄造式的根柱冠心（dowel-core）","(D) 根柱（dowel）無法強化牙根"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-1-52","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"當牙周病已經進行至根叉侵犯（furcation involvement）的程度，欲製作補綴物時，下列敘述何者錯誤？","options":["(A) 牙齒修形時，儘可能在牙骨質牙釉質交界（CEJ）之上以保留較多齒質","(B) 若修形時邊緣根據牙根形狀修形為長凹槽（flute），易造成牙菌斑堆積","(C) 若修形邊緣在牙骨質牙釉質交界（CEJ）之下，且形態為肩台邊緣（shoulder type），易造成過多齒質修磨，及牙髓侵犯","(D) 先了解牙根形態，確認牙根分叉處的位置，再修磨牙齒為佳"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-1-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"下列橋體設計，何者較適合用於上顎前牙區？","options":["(A) 衛生型（sanitary）","(B) 馬鞍型（saddle）","(C) 圓錐狀（conical）","(D) 卵圓形（ovate）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-1-54","subject":"ya5","topic":"牙科材料學","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"銲接用熔媒（soldering flux）的主要成分為何？","options":["(A) 石墨（graphite）","(B) 氧化鐵（rouge）","(C) 硼砂玻璃（borax glass）","(D) 矽（silicone）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"當患者上顎有單顆側門齒缺失時，下列何種牙橋設計有較佳的預後？","options":["(A) 單顆犬齒和側門齒的懸臂式牙橋（cantilever bridge）","(B) 兩顆中門齒和側門齒的懸臂式牙橋（cantilever bridge）","(C) 以中門齒、犬齒為支柱牙的傳統牙橋（conventional bridge）","(D) 以中門齒、犬齒為支柱牙的馬利蘭牙橋（Maryland bridge）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-56","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"全瓷冠不宜使用在下列那些情況？①對切緣咬合（edge-to-edge occlusion） ②深咬（deep bite） ③根管治療過的牙齒 （endodontically treated tooth） ④短牙冠（short clinical crown）","options":["(A) 僅①②","(B) 僅③④","(C) ②③④","(D) ①②④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-57","subject":"ya5","topic":"牙科材料學","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"製作瓷融合金屬牙冠（porcelain-fused-to-metal crown）時，金屬與陶瓷的鍵結機制可能為何？①mechanical bond ②chemical bond ③Van der Waal’s force","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-58","subject":"ya5","topic":"牙科材料學","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"下列那一項不能使暫時牙冠所使用的樹脂有較好的物理特性（physical properties）？","options":["(A) 適度增加充填劑（filler）的量","(B) 增加單體（monomer）的分子大小（molecule size）","(C) 傳播（propagation）過程中不要被打斷","(D) 引發劑（initiator）被啟動時，開始由化學（chemical）起動，然後再由熱（thermal）加速進行"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"為正確獲得牙齒之比色，醫師的眼睛與患者之距離約為多少最好？","options":["(A) 1公尺","(B) 2公尺","(C) 50公分","(D) 25公分"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-60","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"關於前牙排列方式的美觀考量，下列敘述何者錯誤？","options":["(A) 牙齒中線與臉部中線若相差在 2 mm以內，較可被接受","(B) 正中門齒的軸向若稍向遠心側傾斜（牙根向近心側），比向近心側傾斜（牙根向遠心側）美觀","(C) 以牙齒的鄰間接觸點來看，由前牙向後牙，接觸點逐漸朝牙齦方向接近，較為美觀","(D) 切緣楔隙（incisal embrasure）較大時，看起來較年輕"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-61","subject":"ya5","topic":"植牙贋復","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"下列有關人工植體置放的敘述，何者錯誤？","options":["(A) 人工植體底部應位於下齒槽神經管（inferior alveolar nerve）上方至少2 mm","(B) 下顎人工植體之置位應遠離頦孔（mental foramen）之出口","(C) 人工植體與自然牙間至少距離1 mm","(D) 相鄰兩人工植體至少應間隔2 mm"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-62","subject":"ya5","topic":"植牙贋復","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"人工植體支柱體（implant abutment）的選擇必須考量以下那些因素：①人工植體與對側齒列的距離 ②植體上的牙齦厚度 ③美觀 ④人工植體植入的角度？","options":["(A) 僅①④","(B) 僅①②③","(C) 僅②③","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-63","subject":"ya5","topic":"臨床基礎與倫理","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"下列上顎牙齒的牙根表面積，由大至小的排序為何？①大臼齒 ②小臼齒 ③犬齒 ④中門齒","options":["(A) ①②③④","(B) ①③②④","(C) ①③④②","(D) ①④③②"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"牙橋之橋體長度延長一倍時，在其他條件不變的情況下，其彎曲之程度會增至幾倍？","options":["(A) 2倍","(B) 4倍","(C) 6倍","(D) 8倍"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-65","subject":"ya5","topic":"牙科材料學","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"下列關於無環式包埋法（ringless investment technique）的敘述，何者錯誤？","options":["(A) 必須採用高強度的包埋材","(B) 包埋材多為磷酸鹽結合包埋材（phosphate-bonded investment）","(C) 膨脹量比採用鑄造環包埋法小","(D) 適用於高熔點的鑄造金屬"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-1-66","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"單齒模空間層（die spacer）可提供日後黏合劑所需的空間。試問單齒模空間層在塗佈時，最好應距離單齒模邊緣線多遠，以 確保鑄造體的邊緣密貼度？","options":["(A) 0.2 mm","(B) 1.0 mm","(C) 2.0 mm","(D) 4.0 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-67","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"由於下顎運動時，力量承受的關係，顳顎關節髁頭（condyle）的退化性病變多發生在何處？","options":["(A) 髁頭內側","(B) 髁頭外側","(C) 髁頭前側","(D) 髁頭後側"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-68","subject":"ya5","topic":"咬合學基礎","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"關於顎反射，下列敘述何者正確？","options":["(A) 閉顎反射為多突觸反射","(B) 開顎反射為多突觸反射","(C) 開顎反射只有受到傷害性刺激時才發生","(D) 閉顎反射與二腹肌（digastric muscle）有關"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-69","subject":"ya5","topic":"咬合學基礎","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"影響咬頭高度的因素，不包括以下何者？","options":["(A) 史比曲線（curve of Spee）","(B) 關節隆突的角度","(C) 咬合平面","(D) 咬合力大小"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-1-70","subject":"ya5","topic":"咬合學基礎","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"在橋腦之網狀構造（reticular formation）中之特定部位施予電刺激，會產生週期性之開閉口運動。該部位稱為什麼？","options":["(A) pattern generator","(B) chewing generator","(C) rhythm generator","(D) action generator"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-1-71","subject":"ya5","topic":"咬合學基礎","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"有關中心關係（centric relation）與中心咬合（centric occlusion）之敘述，何者錯誤？","options":["(A) 大多數人中心關係與中心咬合位置並不一致","(B) 大多數人中心關係位於中心咬合位置之後 1 至 2 mm","(C) 中心關係之重要定義之一為其具可重覆性","(D) 二者之位置均由咀嚼肌群決定"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-1-72","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"關於選擇性修磨（selective grinding）之敘述，下列何者錯誤？","options":["(A) 屬於不可回復性（irreversible）的治療，應謹慎選擇使用時機及適用性","(B) 需可確認預後（predictable outcome），即施行此術式確實可解除咬合干擾","(C) 非顳顎關節患者，在進行大範圍咬合重建時，可考慮先進行選擇性修磨，以提供較穩定的功能性咬合","(D) 當對單一顆牙齒進行局部選擇性修磨時，應同時針對咬頭嵌合位置（intercuspal position，ICP）及所有離心運動的接觸應一 併去除，以形成保護性咬合"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-1-73","subject":"ya5","topic":"咬合學基礎","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"有關下顎功能性運動的敘述，下列何者錯誤？","options":["(A) 不同咬合面形態其咀嚼的軌跡也因此而不同","(B) 除了咬合面的形態影響咀嚼效率，咀嚼行為也可以經由學習來改善其效率","(C) 軟的食物比硬的食物容易判斷咀嚼效率好壞","(D) 口香糖等膠狀物質常用來測定個體處理軟的食物之嚼食能力"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-1-74","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"有關下顎邊緣運動（border movement）的敘述，下列何者錯誤？","options":["(A) 是指下顎沿著其最極限的可能運動範圍所形成的一個範圍","(B) 最大咬頭嵌合位（maximum intercuspation）不屬於下顎邊緣運動","(C) 下顎邊緣運動的範圍多半會受頭部或身體姿勢所影響","(D) 決定下顎最後退（most retruded）位置者為顳顎關節之顳顎韌帶（TMJ ligament）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"顳顎關節組織中，下列何種部位沒有痛覺感受器？","options":["(A) 盤韌帶（discal ligaments）","(B) 囊韌帶（capsular ligaments）","(C) 關節面（articular surfaces）","(D) 盤後組織（retrodiscal tissues）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"下列有關下顎運動的敍述，何者錯誤？","options":["(A) 從中心咬合（centric occlusion）至最大左右側偏移，約為 10 mm","(B) 從中心咬合（centric occlusion）一般大約能前突（protrusion）約 10 mm","(C) 從中心咬合（centric occlusion）開口，一般人約為 40 mm 以上","(D) 泛得繪（pantograph）顎運動描繪器所描繪出之軌跡因人而異，不可做為顳顎關節功能障礙診斷之參考"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"咬合板之厚度不受下列何者影響？","options":["(A) 史比曲線（curve of Spee）","(B) 前牙開咬（anterior open bite）","(C) 垂直覆蓋（overbite）","(D) 威爾森曲線（Wilson's curve）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"下列有關咬合的敘述，何者錯誤？","options":["(A) 從統計學的角度而言，理想咬合（ideal occlusion）並不是一個標準值（norm）","(B) 理想咬合是牙科治療的參考依據，牙齒調整應以達到三點接觸（tripodization）為目標","(C) 雖然型態上是咬合不良，但只要是處於健康狀態（a state of health），就可以歸類為生理咬合（physiological occlusion）","(D) 雖然有咬牙或夜間磨牙，但是咀嚼系統的每一個構造都適應得很好，沒有疼痛或功能障礙的症狀表現時，也應該視為生理咬 合（physiological occlusion）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"經皮神經電刺激（TENS）治療的最主要目的為下列何者？","options":["(A) 止痛","(B) 肌肉訓練","(C) 止血","(D) 改善關節盤異位"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-1-80","subject":"ya5","topic":"咬合學基礎","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"以下的動作何者不是下顎的異功能運動（parafunctional movement）？","options":["(A) 緊咬","(B) 吼叫","(C) 下顎邊緣運動","(D) 臉部表情"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-1","subject":"ya5","topic":"咬合學基礎","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"口腔黏膜與牙周膜物理性質的比較，下列敘述何者錯誤？","options":["(A) 兩者皆是黏彈性質（viscoelastic property）","(B) 接受咬力後牙周膜位移較小，恢復較快","(C) 口腔黏膜下和牙周膜周圍的骨組織，在咀嚼時主要都是承受抗張力（tensile load）","(D) 接受咬力後口腔黏膜位移較大，恢復較慢"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"從有牙變成無牙，人的臉型會有下列何種變化？ ①鼻唇角（nasolabial angle）變大 ②唇變薄 ③唇變厚 ④上顎前方後縮 ⑤下顎前凸","options":["(A) 僅①②⑤","(B) ①③④","(C) ③⑤","(D) ①②④⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-3","subject":"ya5","topic":"咬合學基礎","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"存在於牙周韌帶、下顎肌肉、下顎關節中，可以提供下顎在空間位置感覺的感受器（receptors）稱為何者？","options":["(A) 外感受器（exteroceptor）","(B) 遠距感受器（teleceptor）","(C) 內感受器（interoceptor）","(D) 本體感受器（proprioceptors）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"製作全口義齒前，口內何種組織最好需要手術移除？","options":["(A) 會影響上顎後腭封閉（posterior palatal seal）的上顎隆突（maxillary torus）","(B) 外生骨贅（exostoses）","(C) 下顎前牙區齒槽骨嵴之唇側倒凹","(D) 不尖銳的下顎舌骨嵴（mylohyoid ridge）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-2-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"戴全口義齒者，擬製作新的全口義齒，於印模前，解決口腔黏膜發炎現象最有效方法為何？","options":["(A) 義齒內襯一層組織調理材（tissue conditioner）","(B) 開消炎藥劑服用","(C) 舊義齒停止裝戴至少 24 小時以上","(D) 口服抗黴菌藥劑"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"全口義齒在印模時，要求患者做何種動作，可記錄咬肌（masseter musle）對印模的影響？","options":["(A) 吞嚥口水","(B) 吸吮動作","(C) 張大嘴巴","(D) 閉口"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"下顎全口義齒遠心頰側凸緣（buccal flange）邊緣所參考之解剖位置為何？","options":["(A) 下顎頰棚（buccal shelf）距牙嵴最高點 8 mm 處","(B) 外斜線（external oblique line）上","(C) 內斜線（internal oblique line）上","(D) 下顎舌骨肌（mylohyoid muscle）上"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"在全口義齒的製作中，有關咬合堤（occlusion rim）的用途，下列何者正確？ ①協助建立咬合平面 ②協助 設計牙弓排牙形態 ③協助取得上下顎中心關係（centric relation）位置 ④協助取得髁導引（condylar guidance） ⑤協助建立平衡咬合（balanced occlusion）","options":["(A) 僅①④","(B) 僅②③⑤","(C) 僅①②③④","(D) ①②③④⑤"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-2-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"全口義齒贋復時，在高度之決定上，要求病人發“m” 聲後放鬆肌肉時，上下顎之間的關係是什麼？","options":["(A) 咬合垂直距離（occlusal vertical dimension）","(B) 中心關係（centric relation）","(C) 中心自由（freedom in centric）","(D) 生理性靜止位置（physiological rest position）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-10","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"有關取得垂直距離（vertical dimension）的敘述，下列何者錯誤？","options":["(A) 口腔內存在記錄基底及咬合堤與否，不會影響垂直高度的判斷","(B) 發音法，當發“s” 音時，若上下咬合堤接觸，表示垂直高度太高","(C) 休憩間隙法：靜止垂直距離和咬合垂直距離有 2～4 mm 的差距","(D) 若病患有長期使用之舊假牙，可優先參考其垂直距離"],"answer":0,"clinical_level":"重點"},{"id":"ya5-106-2-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"關於全口義齒人工牙的選擇，下列何種情況選用瓷牙較樹脂牙來得適當？","options":["(A) 當上下顎間咬合距離（interocclusal space）不足時","(B) 若為單顎全口義齒（single denture）對咬自然牙時","(C) 若為單顎全口義齒（single denture）對咬牙咬合表面為高金含量的補綴物時","(D) 當其他條件允許，且美觀及耐用的要求極為重要時"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"下列關於全口義齒咬合模式（occlusal scheme）的敘述何者錯誤？ ①具咬頭的人工牙（cusped teeth）有 較好的咀嚼效率（chewing efficiency） ②咬頭之解剖型態（cuspal anatomy）對義齒的支持組織 （supporting tissues）有明顯的影響 ③非解剖型態之義齒牙（nonanatomical teeth）無法排出平衡咬合 （balanced occlusion） ④舌側化咬合（lingualized occlusion）之下顎義齒常用非解剖型態之人工牙 ⑤舌 側化咬合無法排出平衡咬合","options":["(A) ①③④","(B) ②④⑤","(C) ①②③","(D) ②③⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"關於義齒人工牙之選擇，下列何種組合需要避免？","options":["(A) 前牙與後牙全用瓷牙","(B) 後牙用瓷牙，前牙用樹脂牙","(C) 後牙用樹脂牙，前牙用瓷牙","(D) 後牙用瓷牙，上顎前牙用瓷牙，下顎前牙用樹脂牙"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"在調整全口義齒的咬合時，若側方運動時平衡側並沒有提供平衡接觸，下列何種調整是正確的？","options":["(A) 調整工作側上顎的腭側咬頭","(B) 調整工作側下顎的頰側咬頭","(C) 調整平衡側上顎的腭側咬頭","(D) 調整工作側上顎的頰側咬頭"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"有關全口義齒咬合模式（occlusal scheme）與人工牙的敘述，下列何者正確？","options":["(A) 若選擇陶瓷牙則無法達成平衡咬合（balanced occlusion）","(B) 單一平面咬合（monoplane occlusion）型式，特別適用於單顎義齒","(C) 舌側咬合（lingualized occlusion）型式，特別適用於單顎義齒","(D) 選擇有角度人工牙較易達成平衡咬合（balanced occlusion）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"有關全口義齒之保養，下列敘述何者錯誤？","options":["(A) 患者晚上睡覺時應將義齒取下泡水，或將義齒浸泡於清潔液殺菌","(B) 睡前取下義齒可讓口腔組織休息","(C) 睡覺時不戴義齒可避免夜間磨牙對組織造成傷害","(D) 清潔義齒之正確方式在泡水前應以牙刷搭配牙膏刷洗"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-2-17","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"有關念珠菌性義齒口炎（Candida-associated denture stomatitis）之症狀，下列何者最少出現？","options":["(A) 口乾","(B) 灼熱感","(C) 味覺異常","(D) 疼痛"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"製作傳統即裝全口義齒（conventional immediate complete denture）時，下列敘述何者錯誤？","options":["(A) 與全口義齒印模相似，須作個別模托（individual trays）","(B) 與全口義齒印模相似，須作邊緣成形（border molding）","(C) 與全口義齒相似，須作記錄基底與咬合堤（record base and occlusion rim）","(D) 須先拔除前牙後，才印模"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-2-19","subject":"ya5","topic":"植牙贋復","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"下列有關植體支持的覆蓋式義齒（implant-supported overdenture）之敘述中，那些正確？ ①因植體的數量 較少，所以咬合面要較自然牙縮小 ②因有植體能增加義齒的固位性，所以組織面不會有食物碎屑堆積 ③ 義齒的穩定性及固位性均能改善 ④日後維護不會太困難","options":["(A) ①②③④","(B) 僅②③④","(C) 僅①②","(D) 僅①③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-20","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"下列有關覆蓋式全口義齒（overdenture）之敍述，何者錯誤？","options":["(A) 可改善全口義齒咬合力之感覺（occlusal stress awareness）","(B) 可增加下顎義齒之固持性（retention）","(C) 可減少支柱牙（abutment teeth）區域之殘嵴（residual ridge）吸收（resorption）","(D) 支柱牙（abutment teeth）區可接受較大之咬合負擔"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-2-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"全口義齒放進包埋盒（flask）時，義齒的咬合面與包埋盒上緣最適當的距離為多少 mm？","options":["(A) 1.5","(B) 4.5","(C) 8.5","(D) 11.5"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"若有患者戴著一副剛做好的全口義齒來找你，並抱怨無法使用時，你認為最合適的處理方式應該為何？","options":["(A) 向患者說明前一位牙醫師那裡沒做好，並保證你可以做得更好","(B) 檢查患者之義齒與口腔，分析可能的治療計畫後，由患者決定後續處理方式","(C) 請患者回去找原來的牙醫師處理","(D) 直接轉診給其他專科醫師"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"被可撤式局部義齒之主連接體（major connector）覆蓋時，下列部位需作緩壓（relief）處理？ ①皺摺 （rugae） ②昇高之正中腭縫（elevated median palatal suture） ③無法手術去除之隆凸（torus）","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-24","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"下列有關可撤式義齒膨下位牙鉤（infrabulge clasp）之敘述，何者正確？","options":["(A) 可彎曲性（flexibility）差","(B) 抱持性（bracing）佳","(C) 固持性（retention）差","(D) 較難以脫卸"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-25","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"可撤式局部義齒金屬支架的設計中，下列何者最適用於甘迺迪分類 Ⅲ 之缺牙狀況？","options":["(A) 單一腭帶（single palatal strap）","(B) 前後腭帶（anterior-posterior palatal strap）","(C) 單一寬型腭主連接體（single broad palatal major connector）","(D) U型腭主連接體（U-shaped palatal major connector）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-2-26","subject":"ya5","topic":"牙科材料學","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"使用鈷-鉻合金（cobalt-chromium alloy）來製作可撤式局部義齒支架（removable partial denture framework），下列敘述何者為其特徵？ ①比重（density）約為金合金（gold alloy）的二分之一 ②與金 合金一樣有很好的組織相容性（tissue compatibility） ③其適合性（fit）比金合金還好 ④楊氏係數 （Young’s modulus）和金合金相近 ⑤與金合金一樣有很好的抗腐蝕性（corrosion resistance）","options":["(A) ①②③","(B) ①②⑤","(C) ①④⑤","(D) ②③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"可撤式局部義齒的遠伸性基底（distal extension denture base）常用功能性印模（functional impression）， 以平衡牙齒與軟組織的支持或壓力分佈。下列何者不是所須之必要條件？","options":["(A) 要有能發揮功能的咬合鉤靠（positive occlusal rest）","(B) 要有彈性且可以隨咬合力彎曲的義齒支架（flexible framework）","(C) 要有可增加穩定度的間接固位體（indirect retainer）","(D) 要有覆蓋範圍廣泛且貼合的義齒基底（denture base）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"有關各種局部缺牙齒弓所做的甘迺迪分類（Kennedy Classification），下列敘述何者錯誤？","options":["(A) 下顎只剩左下第二大臼齒，左下犬齒，右下犬齒及第一小臼齒的缺牙齒弓，屬於 Class II，modification 2","(B) 上顎除了智齒皆已拔除外，尚缺右上第一及第二小臼齒，左側則缺少第一小臼齒及第一大臼齒時，屬於 Class III，modification 2","(C) 下顎只剩左右雙側的犬齒及第一小臼齒時，屬於 Class I，modification 1","(D) 上顎只剩兩側犬齒及兩側的第一、第二大臼齒時，屬於 Class III，modification 1"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-106-2-29","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"牙鉤（clasp）的可彎曲性（flexibility）與鉤臂的那個度量成正比？ ①長度 ②寬度 ③厚度 ④截面積 ⑤彈性係數","options":["(A) 僅①","(B) ①⑤","(C) ④⑤","(D) ②③④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-2-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"當一個牙鉤組合（clasp assembly）於口腔中完全裝戴到定位時，必須符合那些要求？ ①鉤靠（rest）必須 與鉤座（rest seat）吻合 ②固位臂（retentive arm）必須位於預定的倒凹中 ③抗衡臂（reciprocal arm） 必須與支柱牙密合 ④固位臂（retentive arm）必須施予支柱牙適當的側向力","options":["(A) ①③④","(B) ②③④","(C) ①②④","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-31","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"上顎缺牙的症例如下圖，其缺牙的分類與義齒支持模式之組合，下列何者正確？","options":["(A) Kennedy I 級 2 類（Kennedy Class I modification 2）──組織支持（tissue supported）模式","(B) Kennedy I 級 2 類（Kennedy Class I modification 2）──牙齒－組織支持（tooth-tissue supported）模式","(C) Kennedy II 級 2 類（Kennedy Class II modification 2）──組織支持（tissue supported）模式","(D) Kennedy II 級 2 類（Kennedy Class II modification 2）──牙齒－組織支持（tooth-tissue supported）模式"],"answer":3,"image":"ya5-106-2-31.jpeg","clinical_level":"一般"},{"id":"ya5-106-2-32","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"關於可撤式局部義齒在做模型析量分析時，決定模型最適當傾斜角度的因素為何？ ①合宜的倒凹 ②消除 軟硬組織的干擾 ③患者美觀的考量 ④適當的導引面","options":["(A) 僅②④","(B) 僅①②③","(C) 僅①④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"析量器（surveyor）具有下列功能，但何者除外？","options":["(A) 析量診斷模型及主模型","(B) 修塑蠟模型（wax pattern）","(C) 修磨模型倒凹封填蠟（blockout wax）","(D) 修磨金屬義齒支架（framework）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-34","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"有關製作可撤式局部義齒時，使用舌側槓（lingual bar）或舌側板（lingual plate）之決定，下列敘述何者錯 誤？","options":["(A) 可由診斷模型決定","(B) 二者之下緣都在相同的位置","(C) 須測量抬升的口底 （elevated floor of mouth）至牙齦邊緣之距離","(D) 不須考慮患者的年齡"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-2-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"製作可撤式局部義齒時，有關 esthetic try-in 診次之敘述，下列何者正確？ ①可與支架試戴（framework try- in）同一診次完成，以節省時間 ②確認人工牙排列與唇部支撐（lip support） ③請患者緊咬以找出壓痛點 ④有助於再次確認顎間關係 ⑤完成導引面修磨","options":["(A) 僅①⑤","(B) 僅②③④","(C) 僅②④","(D) 僅③④⑤"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-36","subject":"ya5","topic":"牙科材料學","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"關於可撤式局部義齒印模材的敘述，下列何者錯誤？","options":["(A) 縮合式矽化物（condensation silicone）印模材的工作時間約為 5 到 7 分鐘","(B) 縮合式矽化物（condensation silicone）的精確度為彈性印模材（elastic materials）中之最佳","(C) 加成式矽化物（addition silicone）會受排齦線中的硫酸鋁（aluminum sulfate）影響而抑制凝固","(D) 加成式矽化物（addition silicone）印模材的永久變形量（permanent deformation）較聚乙醚（polyether） 小"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-2-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"可撤式局部義齒製作使用修正模型印模技術（altered cast impression technique），其主要目的為何？","options":["(A) 要得到支柱牙（abutment）的解剖外型（anatomic form）","(B) 要得到上、下顎間正確關係（interjaw relationship）","(C) 要得到黏膜與支柱牙（abutment）之間，平衡的支持關係","(D) 要得到各支柱牙（abutment）之間的正確關係位置"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-2-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"進行可撤式局部義齒治療時，當患者具有下列何種問題，較不適合使用零度牙？","options":["(A) 前牙為 Angle's Class II，division 1 者","(B) 需建立平衡咬合（balanced occlusion）關係時","(C) 有磨牙癖者","(D) 帕金森氏症患者"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-39","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"有關 Kennedy Class II 可撤式局部義齒咬合模式之敘述，下列何者錯誤？","options":["(A) 在中心咬位時所有咬合接觸必須均勻","(B) 在離中心（eccentric）運動時，工作側（working side）應避免接觸","(C) 在離中心（eccentric）運動時，平衡側（balancing side）應避免接觸","(D) 前突運動（protrusion）時，義齒應避免接觸"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-2-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"下列何者不適用於可撤式局部義齒的清潔？","options":["(A) 鹽水","(B) 沸水","(C) 重碳酸鈉（sodium bicarbonate）","(D) 鹼性過氧化物清潔劑（alkaline peroxide cleaner）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"在病人口腔內直接將遠伸性（distal extension）可撤式局部義齒基底（denture base）換底墊（reline）時， 把自聚樹脂（self-curing resin）加到義齒基底組織側並將義齒置回口中後，接下來的步驟為何？","options":["(A) 醫師應用手指輕壓義齒使所有鉤靠（rest）及間接固位體（indirect retainer）定位","(B) 醫師應用手指輕壓義齒基底上方的牙齒","(C) 應讓病人輕輕咬住","(D) 應讓病人以咬食物的力量咬住"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"有關可撤式局部義齒放置緩壓蠟（relief wax）的敘述，下列何者正確？ ①應於主模型複製成耐火模型後放 置緩壓蠟於某些區域 ②緩壓蠟應與鄰近支柱牙保持約 1.5 毫米的距離 ③缺牙區應放置緩壓蠟 ④未手術移 除之小隆凸（torus）上應放置緩壓蠟","options":["(A) 僅①④","(B) 僅①②③","(C) 僅②③④","(D) ①②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"下列有關局部義齒前牙排列的敘述，何者錯誤？","options":["(A) 當唇部放鬆時，應能看見上顎正中門齒的切緣","(B) 前牙的位置將影響上唇的支持和發音","(C) 患者檢視排牙的結果時，應避免以手持小鏡子近距離檢視","(D) 減少牙齒的數量並不會影響外觀"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"下列那種可撤式義齒金屬支架在鑄造時可採用單一鑄道（single sprue）設計？","options":["(A) 下顎甘迺迪第一類缺牙以舌側槓（lingual bar）為主連接體（major connector）的金屬支架","(B) 下顎甘迺迪第一類缺牙以舌側板（lingual plate）為主連接體（major connector）的金屬支架","(C) 上顎以腭板（palatal plate）為主連接體（major connector）的金屬支架","(D) 上顎以前後腭帶（anterior-posterior palatal strap）為主連接體（major connector）的金屬支架"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"若右上顎第一大臼齒牙冠高度不足，應該如何加強此支柱牙的抗力形（resistance form）？","options":["(A) 在頰側與舌側修磨平行的溝槽","(B) 在遠心側與近心側修磨平行的溝槽","(C) 在頰側與舌側修磨互不平行的溝槽","(D) 在牙齒的四個軸向面上修磨互不平行的溝槽"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-2-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"下列那些情形，牙冠之抗力形（resistance form）比較好？①牙齒高度與寬度的比例較大 ②牙齒寬度與高度 的比例較大 ③牙齒軸壁聚攏角度（convergence angle）較大 ④牙齒軸壁聚攏角度較小 ⑤做齒齦上牙冠 邊緣 ⑥做固位溝（retention groove）","options":["(A) ①③⑤","(B) ②④⑥","(C) ①④⑥","(D) ②③⑤"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-47","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"下列那一項與牙齒修形的固位型（retention form）之機械性考量無關？","options":["(A) 牙齒修形的幾何外形（geometry of tooth preparation）","(B) 脫落力量的大小（magnitude of dislodging force）","(C) 黏合劑的厚度（film thickness of the luting agent）","(D) 牙齒的活性（vitality）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-48","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"採用功能軌徑生成術（functionally generated path, FGP）來製作單牙冠時，宜採用下列何種裝置？","options":["(A) 全調節式咬合器（fully adjustable articulator）與顎運動立體描軌器（Pantograph）","(B) 半調節式咬合器（semiadjustable articulator）與面弓（face bow）","(C) 雙階咬合儀（Twin-stage Occluder）與單齒負模（counter die）","(D) 髁關節型咬合器（ARCON type articulator）與哥德式弧形描軌器（Gothic arch tracer）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-2-49","subject":"ya5","topic":"牙科材料學","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"將硬化後的多硫化物印模（polysulfide impression）浸泡於2% 麩醛（glutaraldehyde）當中消毒，浸泡時間 下列何者最適宜？","options":["(A) 60分鐘","(B) 30分鐘","(C) 10分鐘","(D) 5分鐘"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"有關根管治療後的牙齒，使用根柱（post）的敘述，下列何者正確？","options":["(A) 在前牙區，當牙齒受力時，牙根的唇與舌側皆有很大的應力（stress）出現，根柱可以減低一些應力，並預 防牙根斷裂","(B) 當牙齒的牙冠部分有缺損，或須用為一固定牙橋或可撤式活動義齒的支柱牙（abutment）時，為達到足夠的 固位（retention）或支撐（support），需要有根柱的支持較為理想","(C) 在後牙區，牙齒承受較大的力量，容易引起咬頭斷裂（cusp fracture），建議下顎的小臼齒與大臼齒應以根 柱與冠心（post and core）及牙冠來加強牙齒的結構","(D) 根柱與冠心（post and core）的裝戴方向應與牙冠的裝戴方向相同較為理想"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-51","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"非美觀區支柱牙修形時，完成線（finish line）應儘量放置在何處？","options":["(A) 牙齦上的牙釉質","(B) 牙齦下的牙釉質","(C) 牙齦下的牙骨質","(D) 牙齦等高位置的牙骨質"],"answer":0,"clinical_level":"重點"},{"id":"ya5-106-2-52","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"當牙齒需要一深入牙齦溝的修復體時，此牙齒至少必須具有多寬的附連牙齦（attached gingiva）？","options":["(A) 5 mm","(B) 3 mm","(C) 2 mm","(D) 1 mm"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"下顎後牙缺失且口腔衛生清潔較差的患者， 下列何種橋體設計最合適？","options":["(A) 衛生形（sanitary）","(B) 圓錐形（conical）","(C) 卵圓形（ovate）","(D) 嵴曡形（ridge lap）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-106-2-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"連接體（connector）的位置會影響到牙周組織的健康，試問理想的連接體應至少位於齒間軟組織尖端以上多 少毫米？","options":["(A) 0.2","(B) 0.5","(C) 1.0","(D) 2.0"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-2-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"有關鑲瓷牙橋的橋體製作之敘述，下列何者錯誤？","options":["(A) 鑲瓷牙橋的支架設計上，需提供約1.2 mm的厚度給瓷的空間","(B) 橋體上正中咬點（centric contact）於金屬與瓷交界處","(C) 為了得到均勻的燒瓷空間，最好在刻蠟時，先刻出整個牙冠解剖上的外形，再除去厚度均勻的蠟","(D) 橋體上金屬需很平滑，且不能有氣泡；尖銳處也需去除，否則容易引起機械性的失敗"],"answer":1,"clinical_level":"重點"},{"id":"ya5-106-2-56","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"選用不同全瓷冠系統時，下列何者並非主要考量因素？","options":["(A) 強度","(B) 美觀","(C) 磨耗對咬牙的機會","(D) 牙齒修磨的量"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-57","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"有關金屬瓷修復體（metal-ceramic restoration），下列敘述何者正確？","options":["(A) 瓷粉在燒成（firing）過程中，其體積收縮（volumetric shrinkage）通常大於20%","(B) 金屬的熱膨脹係數（coefficient of thermal expansion）最好小於瓷","(C) 瓷內部最好維持於抗張應力（tensile stress）的狀態","(D) 金屬與瓷之間的氧化層（oxide layer）厚度愈厚愈好"],"answer":0,"clinical_level":"重點(深度)"},{"id":"ya5-106-2-58","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"下列何者不是一個良好的暫時牙冠在生物學上的要求？","options":["(A) 保護牙髓組織（pulpal protection）","(B) 提供咬合適應性（provide occlusal compatibility）","(C) 維持牙齒位置（maintain tooth position）","(D) 色澤穩定（color stability）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"關於前牙牙齦頂點（zenith）的位置，以下何者最為自然而美觀？","options":["(A) 在牙齒正中線上","(B) 在牙齒正中線旁，略偏遠心側（distal side）","(C) 在牙齒正中線旁，略偏近心側（mesial side）","(D) 不管位於何處，都不影響牙齒的自然美觀"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-60","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"臨床上在比色前，牙醫師應讓眼睛休息並先注視下列何種顏色為佳？","options":["(A) 黃色","(B) 藍灰色","(C) 深綠色","(D) 灰白色"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-61","subject":"ya5","topic":"植牙贋復","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"人工牙根植入時，理想的齒槽骨寬度與高度，至少須各為多少mm？","options":["(A) 3 mm與5 mm","(B) 5 mm與7 mm","(C) 5 mm與8 mm","(D) 6 mm與10 mm"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-62","subject":"ya5","topic":"植牙贋復","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"植體間骨頭至齒間接觸點（interproximal contact point）的距離，如不大於幾個毫米時，人工植牙術後齒間乳 頭（interdental papilla）通常都會完全存在？","options":["(A) 5毫米","(B) 6毫米","(C) 7毫米","(D) 8毫米"],"answer":0,"clinical_level":"重點"},{"id":"ya5-106-2-63","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"評估修形後的支柱牙（abutment）邊緣是否有足夠的健康齒質，主要是考量下列何者？","options":["(A) 贋復物之圍箍效應（ferrule effect）","(B) 贋復物之耐用性（structure durability）","(C) 贋復物之楔入作用（wedging effect）","(D) 齒質保存性（structure preservation）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-106-2-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"如果要製作45 x x 48的牙橋，且支柱牙較短，下列有那些是你必須要考慮的？①必須先進行咬合分析 ②保 留拆下來的牙橋並測量橋體與連接體的尺寸 ③確保暫時牙橋的形狀能做好橋體下的清潔工作 ④牙橋底部 以金屬面接觸牙嵴黏膜部分 ⑤儘量採用含金量較高的貴金屬製作牙橋以保持美觀","options":["(A) ①②③④⑤","(B) 僅①②③④","(C) 僅②⑤","(D) 僅①③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-65","subject":"ya5","topic":"牙科材料學","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"下列何者最不易增加金屬牙冠鑄造時包埋材的膨脹？","options":["(A) 將鑄造環襯裡（ring liner）先弄濕再倒入包埋材","(B) 將鑄造環襯裡盡量密貼鑄造環內面且壓扁","(C) 將乾的鑄造環襯裡輕貼在鑄造環內面","(D) 將倒入包埋材的鑄造環浸在水中等待完全硬化"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-66","subject":"ya5","topic":"牙科材料學","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"鑄造溫度是選擇包埋材料種類的重要決定因素，試問為維持石膏結合鑄造用包埋材料（gypsum-bonded investment）的穩定，鑄造溫度不可高於多少？","options":["(A) 450℃","(B) 550℃","(C) 650℃","(D) 750℃"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-2-67","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"有關顳顎關節之敍述，下列何者正確？","options":["(A) 顳顎關節充滿關節囊液（synovial fluid），為黏液關節（synovial joint）","(B) 關節盤表面為透明軟骨（hyaline cartilage）所包覆","(C) 關節盤之功能主要為承擔應力（stress bearing）","(D) 關節盤內之膠原纖維走向在前後緣為橫向"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-68","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"有關咀嚼肌之神經生理，下列敘述何者正確？","options":["(A) 所謂的 motor unit 指的是一個運動神經元（motor neuron）支配一條肌肉纖維","(B) 翼外肌下腹（inferior lateral pterygoid muscle）的運動神經元支配的肌肉纖維數比咬肌（masseter muscle）高","(C) 造成肌肉纖維收縮的神經傳導物質是乙醯膽素（acetylcholine）","(D) 一個運動神經元（motor neuron）支配的肌肉纖維數目越多，肌肉的動作越細膩"],"answer":2,"clinical_level":"一般"},{"id":"ya5-106-2-69","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"以下何者不屬於閉口肌（jaw-closing muscles）？","options":["(A) 咬肌（masseter muscle ）","(B) 顳肌（temporalis muscle ）","(C) 二腹肌（digastric muscle）","(D) 翼內肌（medial pterygoid muscle）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-106-2-70","subject":"ya5","topic":"咬合學基礎","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"下列有關史比曲線（curve of Spee）之敘述，何者錯誤？","options":["(A) 為由矢狀面（sagittal plane）觀察之曲線","(B) 由矢狀面（sagittal plane）觀之，史比曲線半徑較小者，咬合平面較平","(C) 由犬齒咬頭，沿著後牙咬頭連結之曲線稱之","(D) 史比曲線亦會影響咬頭高度"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-71","subject":"ya5","topic":"咬合學基礎","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"下顎在中心咬合位置時，前牙接觸的情況為何？","options":["(A) 與後牙的接觸一樣緊密","(B) 比後牙的接觸輕","(C) 沒有接觸，只有前突運動時有接觸","(D) 沒有接觸，前突運動時也不應有接觸"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-72","subject":"ya5","topic":"咬合學基礎","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"側方運動時，下顎牙齒需修磨調整的干擾位置，下列何者正確？","options":["(A) 在工作側（working side）為舌側咬頭舌側斜嵴（lingual incline）","(B) 在工作側（working side）為舌側咬頭頰側斜嵴（buccal incline）","(C) 在非工作側（non-working side）為中央溝（central groove）","(D) 在非工作側（non-working side）為近心頰側溝（mesio-buccal groove）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-73","subject":"ya5","topic":"咬合學基礎","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"記錄自然齒列之下顎邊緣運動（border movement），描繪出波氏圖（Posselt's diagram），由矢狀面觀 （sagittal view），中心咬合（centric occlusion, CO）與中心關係（centric relation, CR）之相關位置通常為 何？","options":["(A) CO 在 CR 之水平後方","(B) CO 在 CR 之水平前方","(C) CO 在 CR 之後下方","(D) CO 在 CR 之前上方"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-74","subject":"ya5","topic":"咬合學基礎","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"咬合器上髁頭間的距離（intercondylar distance）較應有之距離短時，下顎在進行側向運動時運動之軌跡會變 得如何？","options":["(A) 較偏前","(B) 較偏後","(C) 較偏上","(D) 較偏下"],"answer":1,"clinical_level":"一般"},{"id":"ya5-106-2-75","subject":"ya5","topic":"咬合學基礎","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"下顎髁頭在進行下列何種運動時，旋轉（rotation）量最少？","options":["(A) 開口","(B) 閉口","(C) 側向運動","(D) 前突運動"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"關於顳顎關節骨性關節炎（osteoarthritis）的敘述，下列何者有誤？","options":["(A) 屬於一種關節的退化性疾病（degenerative joint disease）","(B) 致病因尚未完全被明瞭，但咸信與關節內承受過大負荷（overloading）有關","(C) 一般來說其症狀會自我限制（self-limiting）","(D) 初期症狀為疼痛，此時就應以 X 光檢查來確診"],"answer":3,"clinical_level":"一般"},{"id":"ya5-106-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"以下何種治療不屬於顳顎障礙症的可逆性療法？","options":["(A) 咬合板治療","(B) 脈衝電磁治療","(C) 使用 NSAID 藥物","(D) 去除牙齒的咬合干擾"],"answer":3,"clinical_level":"重點"},{"id":"ya5-106-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"下列關於慢性疼痛以及治療原則的敘述，何者錯誤？","options":["(A) 疼痛持續 6 星期以上叫做慢性疼痛","(B) 持續疼痛會改變病人的行為與心理狀況","(C) 若病人接受一般顳顎關節障礙之治療，數週後仍無改善，應重新考慮其診斷是否正確","(D) 牙醫師在轉介上述病人至其他醫學專科之前，應確定考量過顳顎關節障礙"],"answer":0,"clinical_level":"重點"},{"id":"ya5-106-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"關於顳顎關節造影術（temporomandibular joint arthrography）的敘述，下列何者錯誤？","options":["(A) 是將顯影劑注入上或下關節腔內，間接地將關節盤以及關節髁頭運動時的關係位置顯示出來","(B) 在可復位關節盤前移的下關節腔打入顯影劑時，下顎由閉口至最大開口過程中，顯影劑會自後方往前移動","(C) 若顯影劑只打入下關節腔，但是在影像中，上下關節腔都出現顯影劑時，則可能代表關節盤出現穿孔","(D) 由於手術較具侵入性且不適用於對碘過敏的人，是此術式的缺點"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-106-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"下列有關「咬合與夜間磨牙」的敘述，何者正確？","options":["(A) 咬合干擾是造成夜間磨牙的主要原因","(B) 實驗結果顯示：以人為方式在牙齒上製造的咬合干擾通常會導致夜間磨牙","(C) 牙齒咬合面上的咬合型態可以用來研判夜間磨牙的力量及方向","(D) 實驗結果顯示：用咬合調整將咬合干擾去除可以有效改善夜間磨牙"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-1","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"有關唾液腺的敘述，下列何者正確？","options":["(A) 唾液腺功能是否正常，對贋復治療的預後沒有影響","(B) 下顎義齒的舌側凸緣過度延伸時，會造成顎下腺（submandibular gland）阻塞","(C) 舌下腺（sublingual gland）的大小不會對患者配戴下顎義齒的滿意度造成干擾","(D) 健康的高齡者，唾液腺的流量仍和年齡有關"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"下列關於老化與口乾之間的敘述，何者錯誤？","options":["(A) 唾液分泌的量會隨著年齡增加而減少","(B) 抗憂鬱藥物常會引起口乾","(C) 停經是造成口乾的原因之一","(D) 酒精的攝取有可能影響唾液分泌"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-1-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"唾液會影響全口義齒的使用狀況，下列敘述何者最正確？","options":["(A) 老化（aging）仍然被認為是唾液流量減少的主要因素","(B) 正常休息時的唾液流量大約 1 mL/min","(C) 只有唾液流量（flow rate）會影響全口義齒的成功與否","(D) 只有唾液黏度（viscosity）會影響全口義齒的成功與否"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"下列有關全口義齒患者之診斷及治療計劃，何者錯誤？","options":["(A) V 形腭穹窿（palatal vault）及大角度下彎之軟腭不利於上顎義齒之固位（retention）","(B) 上顎粗隆（maxillary tuberosity）外側之骨倒凹，通常較不需做手術去除","(C) 腭隆凸（torus palatinus）通常需做手術去除","(D) 上顎頰繫帶（buccal frenum）通常不需做手術修正"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"下列何種情況與全口義齒印模時不正確放置印模托無關？","options":["(A) 兩側印模材一厚一薄","(B) 印模托內側露出印模材","(C) 模型有氣泡","(D) 印模托內印模材過厚"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"下列何者是全口義齒在初步印模（preliminary impression）時，最適當印模材？","options":["(A) 不可逆性水凝膠印模材（irreversible hydrocolloid）","(B) 聚乙醚印模材（polyether impression material）","(C) 氧化鋅丁香油酚印模材（zinc oxide-eugenol impression paste）","(D) 矽化合物精取印模材（silicone wash impression material）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-1-7","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"下列關於下顎的解剖組織的敘述，何者正確？","options":["(A) 當齒槽骨吸收嚴重時，全口義齒會壓迫很接近齒槽骨嵴的頦孔（mental foramen）上的神經和血管，造成疼 痛或麻木感","(B) 下顎隆凸（torus mandibularis）通常出現在單側","(C) 頰棚（buccal shelf）是指頰側繫帶和咬肌前緣間的區域，當齒槽骨持續吸收時，此區域骨地基的寬度會變 的較小","(D) 下顎舌骨肌（mylohyoid muscle）附著在下顎舌骨嵴，後方比前方接近舌底"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-1-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"下列何者是咬合堤（occlusion rim）之功能？ ①決定上唇之支撐度（lip support） ②決定義齒邊緣封閉區 （peripheral seal） ③建立中立區（neutral zone） ④排牙以利義齒之試戴","options":["(A) 僅①④","(B) 僅③④","(C) ①③④","(D) ①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"下࠻有關生理靜止位置（physiological rest position）的敘述，何者正確？","options":["(A) 製作全口義齒時，最常用來決定水平的顎間關係（horizontal jaw relation）","(B) 此位置容易受到頭、頸部姿勢的影響","(C) 應請患者仰臥，頭部以枕頭支撐，測量該位置才準確","(D) 與測量上、下齒列之間的休憩間隙（freeway space）無關"],"answer":1,"clinical_level":"重點"},{"id":"ya5-107-1-10","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"在建立全口義齒的上、下顎咬合關係時的臨床步驟，下列順序何者最為合理？ ①決定咬合垂直高ล （occlusal vertical dimension） ②決定上、下顎水平關係 ③以咬合堤（occlusal rim）紀錄咬合平面的位 置 ④決定髁頭導引（condylar guidance） ⑤建立咬合模式（occlusal scheme）","options":["(A) ①②③④⑤","(B) ③①②④⑤","(C) ③②①⑤④","(D) ④③①②⑤"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"全口義齒常使用瓷牙（porcelain teeth）和壓克力樹脂牙齒（acrylic resin teeth）來排牙，下列敘述何者錯 誤？","options":["(A) 壓克力樹脂牙齒最大的優點是容易進行咬合調整","(B) 和義齒基底的樹脂具有化學鍵結能力是壓克力樹脂牙齒","(C) 當顎間距離（interarch distance）較小時，使用瓷牙比樹脂牙適合","(D) 瓷牙較不會磨耗"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-12","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"全口義齒患者在試戴及檢測發音時，下列敘述何者錯誤？","options":["(A) 若患者易將“d ” 發成“t ”，表示上顎前牙排列太過舌側","(B) 若患者易將“v” 發成“f ”，表示上顎前牙可能過短","(C) 若上顎義齒基底於皺摺區（rugae area）過厚時，患者易將“s” 發成“z”","(D) 若發“p”，“b”，“m” 等子音有困難，可能是咬合垂直高度不正確"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-1-13","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"下列何者是覆蓋義齒（overdenture）選用樹脂牙時應注意事項？ ①因應牙根或植體位置來排列牙齒，常需 磨出一個很大的空洞（hollow-ground）會使得義齒結構變弱 ②當使用多層牙（laminated teeth）時，可能 因為牙齒內部修磨過多而會出現剝離 ③建議應選擇較為錐形（tapered）或是彎曲（curved）的樹脂牙","options":["(A) 僅①③","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"當全口義齒進行最大咬頭嵌合（maximum intercuspation）的咬合調整時，下列敘述何者錯誤？","options":["(A) 先達成中心咬合的最大咬頭嵌合（maximum intercuspation）才進行側方運動以及前突運動的咬合調整","(B) 調整最大咬頭嵌合（maximum intercuspation）時，咬合器應鎖定在中心位置（centric position）","(C) 此時過早接觸最常出現在下顎牙齒的咬窩或邊緣嵴以及上顎舌側咬頭的舌側面","(D) 最大咬頭嵌合（maximum intercuspation）是要建立上顎後牙的舌側咬頭為主要的支持咬頭（supporting cusp）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"全口義齒試戴時，患者抱怨看不到上顎的前牙，下列何者為可能的原因？ ①咬合平面設定太低 ②咬合垂 直高度太低 ③前牙垂直重疊過大 ④上顎前牙排列太近舌側","options":["(A) ①②","(B) ②③","(C) ③④","(D) ②④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"全口義齒配戴者若覺得上顎之前部有燒灼或麻木感，最可能的原因為下列何者？","options":["(A) 維他命缺乏","(B) 義齒聚合不完全","(C) 門齒乳頭（incisive papilla）受到壓迫","(D) 有側向咬合干擾（lateral occlusal interference）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"下列那些病患，配戴全口義齒，比較有適應不良的問題？ ①超過60歲 ②肌肉協調能力不良 ③易有噁心 反應 ④具Angle's Class III上下顎間關係","options":["(A) ①②③","(B) ②③④","(C) 僅①④","(D) 僅②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"即裝義齒（immediate dentures）戴入後的第一次回診應在拔牙手術後幾天？","options":["(A) 一","(B) 三","(C) 五","(D) 七"],"answer":0,"clinical_level":"重點(深度)"},{"id":"ya5-107-1-19","subject":"ya5","topic":"臨床基礎與倫理","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"有關咽腭帆關閉（velopharyngeal closure）功能的敘述，下列何者錯誤？","options":["(A) 咽腭帆關閉主要分離口咽部（oropharynx）與喉咽部（laryngopharynx）","(B) 咽腭帆關閉在吞嚥時最明顯","(C) 咽腭帆關閉在吹口哨時較不明顯","(D) 咽腭帆關閉在說英文時較不明顯"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-1-20","subject":"ya5","topic":"植牙贋復","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"有關植體贋復時，病患的選擇與診斷之敘述，下列何者正確？ ①只要全口缺牙病患，願接受手術治療，便 可種植植體 ②病患的診斷，要包括診斷模型及現有贋復體的分析 ③X 光片的解讀，包括手術區齒槽骨的 質與量 ④要了解病患抽煙、喝酒的習慣","options":["(A) ①②③","(B) ②③④","(C) ①②④","(D) ①③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"因為下列那個因素所造成的義齒咬合錯誤，可透過單純的咬合調整來解決？","options":["(A) 顎間記錄錯誤","(B) 印模錯誤","(C) 樹脂於聚合後收縮","(D) 義齒盒埋（flasking）時義齒牙移位"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"醫療人員治療病人的醫學倫理，是基於下列四個倫理法則。尊重自主原則（the principle of respect for autonomy）、不傷害原則（the principle of non-maleficence）、行善原則（the principle of beneficence） 及公平正義原則（the principle of justice）。一患者的上顎正中門齒斷裂，已無足夠圍箍效應（ferrule effect），為保留此牙齒，而將此牙齒復形，除了做牙套之外，還必須施與牙冠增長術。當醫師在考量治療計 畫時，符合上述那兩個原則？","options":["(A) 尊重自主和公平正義","(B) 行善和不傷害","(C) 不傷害和尊重自主","(D) 公平正義和行善"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-23","subject":"ya5","topic":"牙科材料學","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"與金合金（gold alloy）比較，鈷鉻合金（chromium-cobalt alloy）義齒支架之性質不包括下列何者？","options":["(A) 彈性係數較高（high modulus of elasticity）","(B) 比例限度較低（proportional limit）","(C) 屈伏強度較高（yield strength）","(D) 生物相容性較差（biocompatibility）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-1-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"有關舌側板（lingual plate）之敘述，下列何者正確？①不需加鈎靠（rest）就具有間接固位體（indirect retainer）的功能 ②下緣須做成半梨狀以增加硬度 ③牙齦溝處須做平行封凹（parallel blockout）","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"下列何者為阿克斯牙鈎（Akers clasp）的構成要素？ ①固位部（retention part） ②抱持部（bracing part）③關節部（joint part） ④緩壓部（stress-breaking part） ⑤支持部（support part）","options":["(A) ①②③","(B) ②③④","(C) ③④⑤","(D) ①②⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"下列何者不是可撤式義齒牙鈎臂（clasp arm）之功能？","options":["(A) 穩定化（stabilization）","(B) 支持（support）","(C) 固位（retention）","(D) 抗衡作用（reciprocation）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-27","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"可撤式局部義齒設計時常用的鍛製金屬線（wrought wire），其粗細為何？","options":["(A) 9～12 gauge","(B) 17～20 gauge","(C) 25～28 gauge","(D) 30 gauge 以上"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-28","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"下列對於可撤式局部義齒固位力的敘述，何者正確？ ①其固位力只需達到最基本可抵抗一般合理的義齒鬆 脫力（dislodging forces）即可 ②支柱牙的固位力往往無法左右側相同，但應具備跨弓的正向拮抗力 （positive cross-arch reciprocation） ③牙鈎所提供的固位力與義齒置入途徑（path of insertion）無關 ④選擇不同粗細、長度或材質的牙鈎可以改變其所提供的固位力","options":["(A) 僅①③","(B) ①②④","(C) ①③④","(D) 僅②④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-29","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"甘迺迪第一類（Kennedy Class I）之可撤式局部義齒採用下列何種牙鈎（clasp）時，其義齒基底鞍 （denture base saddle）可能會有最大的垂直向移動？","options":["(A) 鍛製金屬線牙鈎（wrought wire clasp）","(B) I型牙鈎（I-clasp）","(C) T型牙鈎（T-clasp）","(D) 環鈎（ring clasp）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-1-30","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"遠伸性可撤式局部義齒（distal extension removable partial denture）於咀嚼功能中會有不同方向的轉動， 下列何種義齒運動對支柱牙（abutment）的傷害最大？","options":["(A) 於矢狀面（sagittal plane）上繞著遠心鈎靠（rest）往組織方向的下沈運動","(B) 於矢狀面（sagittal plane）上因食物的黏性而將義齒帶離組織方向的運動","(C) 於額狀面（frontal plane）上繞著殘嵴（residual ridge）所做頰舌側方向的運動","(D) 於軸面（axial plane）上繞著牙弓（dental arch）中心垂直軸（vertical axis）所做的水平方向運動"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-107-1-31","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"設計甘迺迪第一類（Kennedy Class I）之可撤式局部義齒時，若是支柱牙的牙周支持不佳而須特別保護時， 最好使用下列何種牙鈎（clasp）？","options":["(A) 鍛製金屬線牙鈎（wrought wire clasp）","(B) T型牙鈎（T-clasp）","(C) 環鈎（ring clasp）","(D) 阿克斯牙鈎（Akers clasp）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-1-32","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"使用析量器（surveyor）來分析可撤式局部義齒的模型時，第一步驟為何？","options":["(A) 在模型上使用三點定位法（tripoding）","(B) 劃出析量線（survey line）","(C) 確認最佳的模型傾斜度","(D) 找出牙鈎（clasp）需要的倒凹區（undercut）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-33","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"當患者抱怨可撤式局部義齒於咀嚼食物時容易脫落，主要原因是在下列何者之設計出現問題？","options":["(A) 主連接體（major connector）","(B) 小連接體（minor connector）","(C) 鈎靠（rest）","(D) 置放途徑（path of placement）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-34","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"設計上顎可撤式局部義齒時，若有明顯腭隆凸（palatal torus）存在，又要顧及義齒的穩定性，下列何種主連 接體的設計最適當？","options":["(A) 前後腭槓（anterior-posterior palatal bar）","(B) 馬蹄形主連接體（horseshoe major connector）","(C) 腭板（palatal plate）","(D) 腭帶（palatal strap）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-1-35","subject":"ya5","topic":"牙科材料學","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"下列那種可撤式局部義齒的金屬材質有最高的彈性係數（modulus of elasticity）？","options":["(A) 第四類金合金（Type IV gold alloy）","(B) 鈷鉻（Co-Cr）合金","(C) 純鈦（titanium）金屬","(D) 鈦六鋁四釩（TiAl6V4）合金"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-36","subject":"ya5","topic":"牙科材料學","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"藻膠印模材（alginate impression material）完成口內印模後，以自來水沖洗完畢，可以噴灑何種溶液來做感 染控制？","options":["(A) 氯化鈉溶液","(B) 氯化鈣溶液","(C) 次氯酸鉀溶液","(D) 次氯酸鈉溶液"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-37","subject":"ya5","topic":"牙科材料學","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"關於橡膠（rubber base）印模材，下列敘述何者錯誤？","options":["(A) 取模時印模材料厚度應儘量一致，且不宜超過 3 mm","(B) 有較長的操作時間（working time）以及凝固時間（setting time）（約 8～10 分鐘）","(C) 有較高的抗撕裂強度（tear strength），適用於有較大組織倒凹區域的印模","(D) 印模完成後應先等 7～15 分鐘才倒模"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-1-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"製作下顎遠端缺牙之可撤式局部義齒時，決定人工牙之顆數最不需考慮的因素為何？","options":["(A) 齒槽骨殘嵴（residual ridge）的走向","(B) 臼齒後墊（retromolar pad）的位置","(C) 人工牙顆數應與缺牙顆數一致","(D) 對咬牙的位置"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-39","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"在部分缺牙患者口中，如果存在嚴重突出（extrusion）的牙齒，且該牙齒對可撤式局部義齒的支撐 （support）、固持（retention）與抱持（bracing）均無關，則對該顆牙齒的最佳處置策略為何？","options":["(A) 不處理，使用到非拔牙不可","(B) 拔除","(C) 根管治療後，作為覆蓋式義齒（overdenture）之支柱牙（abutment）","(D) 以矯正方法將該牙齒拉至理想位置"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"有關可撤式局部義齒基底延伸（denture base extension）之敘述，下列何者錯誤？","options":["(A) 義齒基底過度延伸可能造成黏膜潰瘍","(B) 義齒基底是否過度延伸只可用肉眼察覺到","(C) 壓力指示膏（pressure indicator paste）可偵測義齒基底是否過度延伸","(D) 不可磨滅墨水（indelible ink）可用來標記過度延伸之義齒基底"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"有關可撤式局部義齒金屬支架之修補（repair），下列敘述何者錯誤？","options":["(A) 鑄造式固位牙鈎（retentive clasp）斷裂，可使用鍛製金屬線（wrought wire）取代","(B) 電銲（electric soldering）可預防鍛製金屬線產生再結晶（recrystallization）","(C) 咬合鈎靠斷裂，須先確認是否因鈎座（rest seat）修磨不夠","(D) 主連接體因太薄造成斷裂，可直接用銲接方式修補"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-42","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"有關可撤式局部義齒金屬義齒支架的設計，下列何者是放置珠狀緣飾（beading）的主要目的？ ①提供明 顯可見的邊緣 ②將主連接體（major connector）的設計轉移至耐火模型（refractory cast） ③可使義齒 支架與組織更密貼 ④減少食物在主連接體下的積存","options":["(A) 僅①②","(B) 僅①③④","(C) 僅②③④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-43","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"有關可撤式局部義齒的設計，下列敘述何者正確？","options":["(A) 材質與設計相同時，牙鈎（clasp）的長度越長，彈性越好","(B) 牙鈎（clasp）數量的多寡比放置的位置重要","(C) 甘迺迪第一類患者，其最末端支柱牙上的鈎靠（rest）最常放置處是咬合面的遠心處","(D) 相同條件下，鍛製金屬線牙鈎（wrought wire clasp）的彈性比鑄造式牙鈎（cast clasp）差"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-1-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"在鑄造局部義齒金屬支架（framework）的步驟中，緩壓（relief）須在那個模型上進行？","options":["(A) 研究模型（study cast）","(B) 主模型（master cast）","(C) 耐火模型（refractory cast）","(D) 主模型和耐火模型（master cast and refractory cast）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"下列關於支柱牙修形時的名詞「長凹槽」（flute）之敘述，何者錯誤？","options":["(A) 適用在根叉侵犯的大臼齒","(B) 作用是為了容易維持牙周的清潔與健康","(C) 適用於上顎大臼齒之近心牙根分叉","(D) 若在下顎大臼齒作此修形，則從咬合面上方看到此支柱牙的外形呈「8」字型"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"製作金屬全牙冠修復體時，下列那一種邊緣修形最適用？","options":["(A) 肩台邊緣（shoulder margin）","(B) 弧形邊緣（chamfer margin）","(C) 斜面邊緣（bevel margin）","(D) 鑿子邊緣（chisel margin）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-47","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"在牙齒修形中，邊緣的設計有很多種，下列敘述何者錯誤？","options":["(A) 弧形緣（chamfer）用於金屬牙冠","(B) 肩緣（shoulder）用於全瓷牙冠","(C) 斜坡肩緣（sloped shoulder）用於金屬瓷牙冠（metal-ceramic-crown）的顏面側邊緣（facial margin）","(D) 淺弧形緣（light chamfer）用於金屬瓷牙冠（metal-ceramic-crown）的顏面側邊緣（facial margin）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-48","subject":"ya5","topic":"咬合學基礎","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"下列何種安格氏（Angle's）上下顎關係，較易以相互保護性咬合（mutually protected occlusion）模式進行 全口固定義齒重建？","options":["(A) 第一類（class I）","(B) 第二類（class II）","(C) 第三類（class III）","(D) 錯咬（cross bite）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-1-49","subject":"ya5","topic":"牙科材料學","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"下列何種彈性印模材硬化後會產生乙醇（ethyl alcohol）？","options":["(A) 多硫化合物（polysulfide）","(B) 聚乙醚（polyether）","(C) 縮合式矽膠（condensation silicone）","(D) 加成式矽膠（addition silicone）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"下列有關根柱（post）周圍牙根應力之敘述，何者正確？","options":["(A) 當根柱的長度增加時，牙根的應力反而降低","(B) 一般而言，牙根的應力常集中在根柱的中心點","(C) 錐形根柱（tapered post）的牙根應力分布比平行根柱（parallel-sided post）平均","(D) 錐形根柱（tapered post）比螺紋根柱（threaded post）容易產生牙根應力集中現象"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-1-51","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"為維持牙周組織的健康，理想的牙橋連接體（connector）應至少離開齒間牙齦尖端多少距離？","options":["(A) 0.5 mm","(B) 1.0 mm","(C) 1.5 mm","(D) 2.0 mm"],"answer":1,"clinical_level":"重點"},{"id":"ya5-107-1-52","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"做過牙根切斷術（root amputation）後的牙齒要進行贋復時，下列敘述何者正確？","options":["(A) 切斷牙根的牙齒無法當作任何補綴物的支柱牙","(B) 為保留較多齒質結構修形邊緣，不應超過切斷牙根之牙髓腔開口程度","(C) 為美觀因素，須將牙根切斷處之贋復物做成隆凸狀（convex）","(D) 咬頭應避免咬合過重接觸"],"answer":3,"clinical_level":"重點"},{"id":"ya5-107-1-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"在其他條件不變下，橋體的跨距（pontic span length）增為3倍時，牙橋的彎曲變形（deflection）將提高為 幾倍？","options":["(A) 3","(B) 6","(C) 9","(D) 27"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"下列有關橋體設計的美觀考量，何者錯誤？","options":["(A) 橋體的唇側面，可往橋體與組織交界面的唇側稍加延伸，以達到較佳外觀","(B) 齒槽骨萎縮的病人，可在橋體上做出牙骨質牙釉質交界線（CEJ），再把牙根部分染色","(C) 嚴重齒槽骨萎縮的病人，用固定義齒復形比可撤式義齒美觀","(D) 用粉紅色瓷（pink porcelain）模擬牙齦組織，可遮掩齒槽骨凹陷處"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-1-55","subject":"ya5","topic":"牙科材料學","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"下列何者為常用之銲接抗熔劑（soldering antiflux）？","options":["(A) 硼酸（boric acid）","(B) 硫化物（sulfide）","(C) 石墨（graphite）","(D) 氧化鎂（magnesium oxide）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-56","subject":"ya5","topic":"牙科材料學","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"下列何者是金屬燒附瓷時，顏色變綠的主要原因？","options":["(A) 鉀","(B) 鈉","(C) 銀","(D) 鎂"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-1-57","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"下列何種全瓷冠系統應該採用氫氟酸酸蝕以及樹脂黏著劑黏著？","options":["(A) Procera Alumina","(B) In-Ceram Zircornia","(C) IPS Empress 2","(D) Captek"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-58","subject":"ya5","topic":"牙科材料學","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"下列何種黏合劑（cement）最適合用於暫用修復體（provisional restoration）？","options":["(A) 氧化鋅丁香油酚（zinc oxide-eugenol）","(B) 磷酸鋅（zinc phosphate）","(C) 聚羧酸鹽（polycarboxylate）","(D) 玻璃離子體（glass-ionomer）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-1-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"牙齒比色時，將眼睛瞇起來，是為了正確判斷 CIELab color system中的何項參數？","options":["(A) a值","(B) b值","(C) L值","(D) V值"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-1-60","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"依據Rosenstiel的建議，人的上顎門牙之寬／長比應為多少最美？","options":["(A) 70～73%","(B) 75～78%","(C) 82～85%","(D) 86～90%"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-61","subject":"ya5","topic":"植牙贋復","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"下列何者並非使人工植體支持的補綴物得到長期成功（long-term success）的因素？","options":["(A) 避免人工植體補綴物受到側方力（lateral force）","(B) 跟自然牙連接在一起","(C) 製作與人工植體密合的補綴物","(D) 維持口腔衛生"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-62","subject":"ya5","topic":"植牙贋復","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"下列有關人工植牙的敘述，何者正確？①人工植牙贋復物咬合平面設計，應設計較平之咬頭傾斜面及較小之 咬合面積 ②植體周圍之骨頭因不良應力導致吸收後，當不良應力移除後，周圍之骨頭會再形成 ③當植體 周圍之骨頭每年平均減少0.2毫米以上時，就應特別注意其可能造成的因素 ④人工植牙之患者完成治療後的 第一年，至少應每6個月回診檢查一次","options":["(A) ②③","(B) ①③④","(C) 僅①③","(D) 僅①④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-63","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"使用根柱時，依下列圖示之牙根面修形設計，最主要是為了要獲得什麼效果？","options":["(A) 抵抗根柱下沉","(B) 抵抗根柱旋轉","(C) 增加根柱強度","(D) 增加根柱彈性"],"answer":1,"image":"ya5-107-1-63.jpeg","clinical_level":"一般"},{"id":"ya5-107-1-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"病患陳先生求診時，主訴是下顎前牙短且小，並且對冷熱有不舒服感，口內檢查如下圖所示。陳先生的口內 狀況，根據American College of Prosthodontists（ACP）所訂定的PDI（Prosthodontic Diagnostic Index），是屬於那一個Class？","options":["(A) Class I","(B) Class II","(C) Class III","(D) Class IV"],"answer":3,"image":"ya5-107-1-64.jpeg","clinical_level":"一般"},{"id":"ya5-107-1-65","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"下列材料：①母金屬 ②後銲用子金屬 ③前銲用子金屬 ④瓷，依熔點高低排列，何者正確？","options":["(A) ①＞②＞③＞④","(B) ④＞①＞③＞②","(C) ①＞③＞④＞②","(D) ④＞②＞③＞①"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-66","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"最適當的銲接縫隙（soldering gap）應為多少mm，才能達到最理想的強度與準確性？","options":["(A) 0.1","(B) 0.2～0.25","(C) 0.4～0.5","(D) 0.6～0.7"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-67","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"有關顳顎關節的敘述，下列何者錯誤？","options":["(A) 顳顎關節髁頭（condyle）離開關節窩（glenoid fossa）的動作不可視為脫臼（dislocation）","(B) 軟骨在關節髁頭（condyle）覆蓋的部位代表髁頭於運動中主要的受力位置","(C) 覆蓋在關節窩（glenoid fossa）與關節隆突（articular eminence）上的軟骨，其厚度較覆蓋在髁頭上之軟 骨為均勻","(D) 覆蓋在顳顎關節之軟骨均為纖維軟骨（fibro-cartilage）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-1-68","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"三叉反射（trigeminal reflex）和脊椎反射（spinal reflex）的比較，以下敘述何者正確？ ①三叉反射的向心 輸入神經元有部分位於第五腦神經中腦神經核（trigeminal mesencephalic nucleus）中 ②脊椎反射的向心 輸入神經元位於背根神經節（dorsal root ganglion）中 ③除了肌梭，皮膚或顳顎關節內的感受器也可引起 三叉反射","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"重點"},{"id":"ya5-107-1-69","subject":"ya5","topic":"咬合學基礎","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"下列關於咀嚼動作的敘述，何者錯誤？","options":["(A) 刺激咀嚼中樞型發生器（central pattern generator）會引發週期性開閉口動作","(B) 咀嚼動作之發動者為中樞型發生器（central pattern generator）","(C) 一些反射動作可調控咀嚼運動","(D) 在麻醉牙周組織後，個體控制咬力的能力會降低"],"answer":1,"clinical_level":"重點"},{"id":"ya5-107-1-70","subject":"ya5","topic":"咬合學基礎","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"吃東西不小心咬到舌頭或嘴唇的瞬間會引起那一種反射（reflex）反應？","options":["(A) jaw-closing reflex","(B) jaw-opening reflex","(C) jaw-unloading reflex","(D) horizontal jaw reflex"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-1-71","subject":"ya5","topic":"咬合學基礎","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"下列有關「中心關係（centric relation）」的敘述，何者有誤？","options":["(A) 是用來分析及重建咀嚼系統的一個關鍵參考位置","(B) 是一個咀嚼功能最適合的最終點","(C) 須在病人的肌肉不主動參與的狀態下由操作者來實現","(D) 是評估所有咬合接觸的關鍵參考位置"],"answer":1,"clinical_level":"重點"},{"id":"ya5-107-1-72","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"有關咬合干擾（occlusal interference）的敘述，下列何者錯誤？","options":["(A) 牙齒咬合急速的改變（acute change）可促使肌肉出現協同收縮 （co-contraction）並升高肌肉的緊張度 （muscle tonus）","(B) 緩慢的咬合改變（chronic change）可影響肌肉結構產生一定程度的調適反應（adaptive response）","(C) 牙齒的咬合干擾是引起夜間磨牙的最主要因素之一","(D) 當下顎前突時，若有後牙的過早接觸（premature contact）使得前牙開咬，可謂之前突干擾（protrusive interference）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-1-73","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"除牙齒形態與排列外，下列那些為限制下顎邊緣運動（border movement）的因素？ ①顳顎關節的韌帶 （ligaments of the TMJ） ②顳顎關節的關節面（articular surfaces of the TMJ） ③咬合肌群 （masticatory muscles）","options":["(A) 僅①②","(B) 僅③","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-74","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"顳顎關節隆突（temporomandibular joint articular eminence）與關節盤（disc）上表面之間的主要運動行為 為何？","options":["(A) 滯動（trapping）","(B) 轉動（rotation）","(C) 滑動（sliding）","(D) 滾動（rolling）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"咀嚼功能障礙之主要症狀有那些？ ①咀嚼肌群疼痛 ②顳顎關節疼痛 ③下顎運動受限 ④下顎運動時顳 顎關節發出聲音","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-76","subject":"ya5","topic":"咬合學基礎","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"下列何者是咬合傷害（occlusal trauma）在牙根尖 X 光影像的特徵？","options":["(A) 齒槽骨的高度保持不變","(B) 齒槽骨內骨小樑（trabeculae）數目減少","(C) 齒槽骨水平吸收","(D) 牙周韌帶（periodontal ligament）之空間變寬"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"有關肌炎（myositis）之敘述，下列何者正確？","options":["(A) 在休息時有明顯疼痛","(B) 運動時疼痛減輕","(C) 按壓可緩解肌肉疼痛","(D) 感覺肌肉鬆軟"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"下列關於顳顎關節不可復位性關節盤易位（disc displacement without reduction）的治療，何者錯誤？","options":["(A) 在急性期可使用前置位咬合板（anterior positioning splint）治療","(B) 若此現象剛發生不久，有較高的機會經由推拿（manipulation）回復病患完整的開口量","(C) 有時可給予非類固醇消炎藥物（NSAIDs）減輕症狀","(D) 關節內部之組織會調適，而使症狀逐漸減緩"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"在牙醫診所以環口顎攝影機之顳顎關節模式拍攝顳顎關節，在判讀髁頭（condyle）之內極（medial pole） 與外極（lateral pole）影像時須注意：","options":["(A) 髁頭之外極落在近心側","(B) 髁頭之外極落在遠心側","(C) 髁頭之外極落在上方","(D) 髁頭之內極與外極落在同一位置"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"關於夜間磨牙，下列敘述何者較不恰當？","options":["(A) 有可能造成顳顎關節功能障礙","(B) 咬合干擾是磨牙的主要原因","(C) 也常見於小孩","(D) 情緒壓力可能會使夜間磨牙變嚴重"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-2-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"根據 Stefan's law，為了增加全口義齒的固位性，義齒基底與其組織之間的關係為何？","options":["(A) 最大的間隙，最大覆蓋面積","(B) 最小的間隙，最小覆蓋面積","(C) 最大的間隙，最小覆蓋面積","(D) 最小的間隙，最大覆蓋面積"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-2","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"下列有關高齡患者咀嚼時顎運動（jaw movement）的敘述，何者正確？","options":["(A) 咀嚼速度加快","(B) 咀嚼時下顎之垂直位移（vertical displacement）變大","(C) 閉口肌張力（muscle tone）增加","(D) 咀嚼運動週期較雜亂"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"治療前，發現不利於製作全口義齒之因素可以藉由手術方式來改善，下列敘述何者錯誤？","options":["(A) 前庭成形術（vestibuloplasty）可以改善義齒承戴區域（denture-bearing area）之不足","(B) 宜修整上顎前牙唇側的外生骨疣（exostosis）以減少義齒裝載之倒凹","(C) 上顎腭部的隆凸（torus）一定要移除","(D) 全口無牙齒槽嵴的倒凹區可以提供全口義齒的穩定性"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-4","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"手術後，若影響咽腭帆關閉（velopharyngeal closure）的功能，下列敘述何者錯誤？","options":["(A) 無法正常吞嚥動作","(B) 會造成鼻音過重（hypernasality）","(C) 無法關閉鼻咽（nasopharynx）","(D) 臨床上無法以閉孔器（obturator）來矯正"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-5","subject":"ya5","topic":"臨床基礎與倫理","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"下顎舌骨肌（mylohyoid muscle）附著於下顎舌骨嵴（mylohyoid ridge）的那個部位？","options":["(A) 近心部三分之二","(B) 遠心部四分之三","(C) 中段二分之一","(D) 全部範圍"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"上顎全口義齒所謂的振動線（vibrating line）應位於何處？","options":["(A) 軟腭（soft palate）上","(B) 硬腭（hard palate）上","(C) 硬軟腭交界線上","(D) 腭小窩（fovea palatinae）之後"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"有關全口無牙口腔中之頦結節（genial tubercle）之敘述，下列何者正確？","options":["(A) 於下顎齒槽骨極度萎縮的病人口腔中，容易觀察到","(B) 是上顎全口義齒之主要壓力承受區","(C) 是下顎全口義齒之主要壓力承受區","(D) 頰肌（buccinator muscle）之附著點"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"以下關於以門齒乳頭（incisive papilla）與下顎門齒來估計全口義齒垂直距離（vertical dimension）的敘述， 何者錯誤？","options":["(A) 此方法屬於機械性方法（mechanical methods）的一種","(B) 在自然齒列中，下顎門齒切緣與門齒乳頭間之垂直距離約為 4 mm","(C) 門齒乳頭與上顎門齒切緣間之垂直距離約為 6 mm","(D) 齒槽骨嚴重吸收的病人，由於記錄基底（recording base）的穩定性差，故本方法特別可靠"],"answer":3,"clinical_level":"重點"},{"id":"ya5-107-2-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"利用中立區（neutral zone）的觀念，最有助於決定全口義齒的那一部分？","options":["(A) 咬合平面的傾斜度（inclination）","(B) 印模面（impression surface）的範圍","(C) 咬合型式（occlusal scheme）","(D) 咬合堤的頰、舌側位置"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"在製作全口義齒時，下列那一個因素是病人特有，而牙醫師不能改的？","options":["(A) 門齒導引（incisal guidance）","(B) 髁傾斜度（condylar inclination）","(C) 補償曲線（compensating curve）","(D) 咬合平面（occlusal plane）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-2-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"關於全口義齒製作時，選擇前牙的敘述，下列何者錯誤？","options":["(A) 首先要聆聽患者的需求","(B) 前牙的選擇應單純評估患者的口腔顏面生理條件，而不宜將心理因素列入考量","(C) 牙醫師的工作是在於協助患者做出最後的決定","(D) 患者仍應對最後美觀結果具有首要的責任"],"answer":1,"clinical_level":"重點"},{"id":"ya5-107-2-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"關於“s” 發音時，舌頭前背部與上顎義齒的腭部之間形成的溝隙，下列敘述何者錯誤？","options":["(A) 舌尖不會觸及上顎門牙之舌側","(B) 溝隙空間的大小及形狀會影響“s” 的發音","(C) 溝隙空間斷面（cross-section）的大小約為 10 mm2","(D) 若溝隙太大時，會發成類似口哨音（whistles）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"為避免影響咀嚼效率，採取以下何種後牙咬合時，前牙所能容許的垂直覆蓋最小？","options":["(A) 0° 牙","(B) 20° 牙","(C) 30° 牙","(D) 舌側化咬合（lingualized occlusion）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"全口義齒製作時，決定咬合平面的參考標記中，下列敘述何者錯誤？","options":["(A) 甘伯氏平面（Camper's plane）大致平行於咬合平面","(B) 由額面觀（frontal view）看時，咬合平面應平行於兩眼瞳孔間之連線","(C) 由矢面觀（sagittal view）看時，咬合平面應大致平行於眼眶下緣與耳珠之連線","(D) 下顎咬合平面大致等高於靜止時舌背的高度，可參考嘴角的渦輪（modiolus）與臼齒後墊（retromolar pad）三分之二高度的連線"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"在全口義齒的舌側化咬合觀念（lingualized occlusion concept）中，下列何者是真正的工作側咬觸（working side contact）？","options":["(A) 上顎頰側咬頭的舌側面","(B) 下顎頰側咬頭的頰側面","(C) 上顎舌側咬頭的舌側面","(D) 下顎舌側咬頭的舌側面"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"患者最近有感冒症狀，戴上新做的全口義齒後，覺得右側喉嚨痛，針對此情況，下列敘述何者錯誤？","options":["(A) 可能是下顎義齒右方遠心舌側凸緣（lingual flange）過長，修短此區義齒舌側凸緣","(B) 可能是義齒過度壓迫臼齒後墊（retromolar pad）區，調整義齒使其不覆蓋臼齒後墊區","(C) 口腔內若有多處潰瘍，應先建議給予感冒症狀處理","(D) 口腔內潰瘍若位於義齒覆蓋區，須調整義齒"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"在裝戴新完成的全口義齒前，理想上應指示患者至少多久不要戴舊的義齒，以保牙床組織不受影響？","options":["(A) 12 小時","(B) 6小時","(C) 2小時","(D) 可直接裝戴，因主模型印模前已進行組織調理"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"有關下顎單顎義齒（single denture）的敘述，下列何者正確？","options":["(A) 一般而言下顎會比上顎更早變成完全無牙狀態","(B) 下顎單顎義齒比上顎單顎義齒製作簡易","(C) 上顎齒列的咬合平面會影響下顎單顎義齒的穩定性（stability）","(D) 不適宜以植體（implant）增加下顎單顎義齒的固持性（retention）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-19","subject":"ya5","topic":"植牙贋復","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"有關以兩支植體固位之下顎全口覆蓋式義齒（implant-retained mandibular overdenture）的敘述，下列何者 正確？","options":["(A) 植體是在活動義齒下方支持，並不影響美觀，所以種在無牙區的任何位置都可以","(B) 若前牙殘嵴（anterior residual ridge）弧度很大時，較適合使用鑄造槓（cast bar）來固位活動義齒","(C) 比起用單一附連體（attachment）來固位活動義齒，鑄造槓（cast bar）的製作需要更多的上下顎間空間 （interarch space）","(D) 兩支植體愈靠近愈可達到固位效果"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-20","subject":"ya5","topic":"植牙贋復","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"目前最常用的口腔植體材料為何？","options":["(A) 氧化鋯（Zirconium）","(B) 商業用純鈦（commercially pure titanium）","(C) 鈦六鋁四釩（Ti-6Al-4V）","(D) 氫氧磷灰石（hydroxyapatite）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-2-21","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"當我們在修整全口義齒之磨光面（polished surface）的前牙牙齦蠟型時，蠟刀與水平面的夾角為：","options":["(A) 20°","(B) 30°","(C) 45°","(D) 60°"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-2-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"在贋復治療時，為了符合醫學倫理中之「不傷害病人原則（the principle of non-maleficence）」，病患口腔 中若存在化膿搖晃的殘根時，病人要求不拔牙原則下製作活動義齒，下列何者是牙醫師的最合理作為？","options":["(A) 與病患溝通，告知拔牙的必要性","(B) 牙醫師必須堅持拔牙治療方針","(C) 將病人轉診給專科醫師做治療","(D) 僅依據病人的要求做為治療方針"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"對於牙鈎金屬線可彎曲性（flexibility of clasp）的描述，下列敘述何者正確？① 鍛製金屬線牙鈎（wrought wire clasp）的可彎曲性較鑄造牙鈎（cast clasp）佳 ② I型槓（I-bar）長度較長，故其可彎曲性較環周牙 鈎（circumferential clasp）佳 ③ 半圓形（half-rounded）牙鈎較圓形（rounded）牙鈎的可彎曲性好 ④ 抗衡臂（reciprocal arm）必須較固位臂（retentive arm）剛硬（rigid）","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"下列何者不是可撤式局部義齒下顎主連接體（major connector）舌側板（lingual plate）使用的適應狀況？","options":["(A) 用於舌繫帶位置很高或牙齦至口底間距離不到8 mm","(B) 用於甘迺迪第一類（Kennedy Class I），且殘嵴發生過量骨吸收","(C) 用於甘迺迪第三類（Kennedy Class III），且殘嵴未發生過量骨吸收","(D) 可用於穩定有牙周問題的剩餘牙齒"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-2-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"有關可撤式局部義齒間接固位體（indirect retainer）的敘述，下列何者錯誤？","options":["(A) 常見於甘迺迪第一、二、四類（Kennedy Class I, II, IV）缺牙的義齒設計","(B) 位置必須在遠心游離端（distal free-end）缺牙區的水平相對側","(C) 鈎靠放置應該距離旋轉支點線（fulcrum line）愈遠愈好","(D) 只能放置在上顎小臼齒咬合面與下顎犬齒舌側隆凸上"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-107-2-26","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"牙齒-組織支持（tooth-tissue borne）的可撤式局部義齒，最主要是屬於甘迺迪分類（Kennedy classification）的那幾類？①第一類（Class I） ②第二類（Class II） ③第三類（Class III） ④第四類 （Class IV）","options":["(A) ①②","(B) ①③","(C) ②③","(D) ③④"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-2-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"關於可撤式局部義齒的設計原理，下列敘述何者最正確？","options":["(A) 不必考慮功能，美觀與舒適性兼顧即可","(B) 製作可撤式局部義齒之前，患者口腔衛生教育至為重要","(C) 設計時牙鈎（clasp）愈多愈好","(D) 對剩餘牙齒的壓力作用須保持主動（active）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-2-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"可撤式局部義齒的固位作用除了主要的固位牙鈎外，還另有其他固位作用來源，但下列何者不是？","options":["(A) 義齒基底（denture base）的長度與外形設計，對義齒的固位與穩定性影響不大","(B) 可撤式局部義齒在支柱牙引導面（guiding plane）的設計與數量會影響義齒的固位與穩定性","(C) 引導面設計的數量與平行度會影響義齒戴入與取出的方向與固位性","(D) 唾液的黏著力與內聚力"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-29","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"在製作可撤式局部義齒時，下列何者不須提供緩壓（relief）設計？","options":["(A) 引導面（guiding plane）","(B) 隆凸（torus）","(C) 鞍部（saddle area）","(D) 舌側槓（lingual bar）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-30","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"有關引導面（guiding plane）的敘述，下列何者正確？①引導面可以提供可撤式局部義齒額外的固位 （retention） ②不同的引導面之間需要相互平行 ③引導面的修形一般約為牙冠咬合-齒頸（occusion- cervical）方向長度的1/3 ④引導面的修形一般約為牙冠頰-舌（buccal-lingual）寬度的2/3","options":["(A) ①②","(B) ①③","(C) ②④","(D) ③④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"可撤式局部義齒印模製作主模型時，有關口內印模材料的選擇與操作，下列敘述何者錯誤？","options":["(A) 藻膠印模材因為便宜、簡便，是最廣泛被使用的牙科印模材料之一","(B) 可撤式局部義齒進行最終取模時，應儘量避免用手在牙齒表面塗抹印模材，以減少氣泡產生","(C) 可撤式局部義齒進行最終取模時，應由牙醫師主導，但須病人之配合","(D) 印模材硬化完成後，應以快速動作將印模自病人口中取出，並以清水沖洗後噴灑消毒劑"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-2-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"可撤式局部義齒在修形牙齒引導面（guiding plane）時需注意的事項，下列敘述何者錯誤？","options":["(A) 引導面是引導可撤式局部義齒戴入與取出的路徑，不論數量多少應儘量修成互為平行的表面","(B) 緊鄰牙齒支持式義齒之缺牙區支柱牙引導面修形，咬合齒齦垂直高度為2～4 mm，應呈直線切割平面而非 弧面，以利平行","(C) 鄰近甘迺迪第一類（Kennedy Class I）遠心端游離缺牙空間的支柱牙，應修形引導面，高度為1.5～2.0 mm","(D) 為強化支柱牙的拮抗作用，會在舌側表面作引導面修形，垂直高度為2～4 mm，且位於臨床牙冠中央1/3處"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-107-2-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"製作可撤式局部義齒時的口腔檢查，下列何者最正確？","options":["(A) 只需注意要建構的牙齒數目即可","(B) 不需將模型置位在咬合器上","(C) 需注意口腔的清潔維護狀況","(D) 不必特別評估牙周組織的狀況"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-34","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"請依序排列模型定位在咬合器上的正確步驟？①上顎模型放置在面弓記錄上 ②以石膏固定上顎模型在咬合 器上 ③將面弓記錄正確置放在咬合器上 ④下顎模型正確對放在中心關係記錄上 ⑤將中心關係記錄放置 在上顎模型咬合面上 ⑥將上、下顎模型相對位置固定 ⑦以石膏固定下顎模型在咬合器上","options":["(A) ①②③④⑤⑥⑦","(B) ③①②④⑤⑥⑦","(C) ③①②⑤④⑥⑦","(D) ③②①④⑤⑥⑦"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-35","subject":"ya5","topic":"牙科材料學","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"下列印模材料中，何者最經濟且適合用於局部義齒的初次印模（primary impression）？","options":["(A) 不可逆性水凝膠（irreversible hydrocolloid）","(B) 巴黎石膏（plaster of Paris）","(C) 氧化鋅丁香酚（zinc oxide eugenol）","(D) 多硫化橡膠（polysulfide rubber）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-36","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"下列何種作法無法減少遠伸性可撤式局部義齒之整體咬合力負擔（total occlusal load）？","options":["(A) 調整過度萌長自然牙之咬合平面","(B) 減少咬合平面的面積","(C) 遠心端殘嵴植入植體以增進延伸基底之穩定性","(D) 將咬合面具解剖形態之人工牙換成零度牙"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-37","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"下列有關甘迺迪第一類（Kennedy Class I）缺牙狀況之殘嵴承受力量的敘述，何者錯誤？","options":["(A) 下顎臼齒後墊（retromolar pad）處須加以緩壓","(B) 下顎頰棚（buccal shelf）處是主要承受咬力區","(C) 上顎殘嵴（residual ridge）處須加以緩壓","(D) 上顎之頰腭側斜坡（buccal and palatal slope）可抗水平旋轉，但只能提供有限的垂直支撐"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-2-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"下列何者不是丙烯酸樹脂牙（acrylic resin teeth）用於可撤性局部義齒之特質？","options":["(A) 易於修整及調整咬合面之細微處","(B) 使用率最高","(C) 易於配合金屬支架之固位元素（retentive elements）作調整","(D) 抗磨耗能力佳，咬合面不須定期檢視"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"關於建立正確的可撤式局部義齒咬合關係之敘述，下列何者錯誤？","options":["(A) 缺後牙時，在中心關係位置排牙","(B) 若可直接對合上下顎齒模，可維持住現有咬合垂直高度，且可呈現側向運動時的咬合干擾","(C) 以剩餘後牙直接取得咬合間咬蠟記錄，並將流到倒凹之多餘材料修除","(D) 在剩餘後牙上，以金屬強化過的蠟片直接作咬合記錄，仍可能造成軟組織移動而無法精確放到石膏模型上"],"answer":1,"clinical_level":"重點"},{"id":"ya5-107-2-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"下列何種狀況換底墊（reline）時不需緊咬？","options":["(A) 缺牙區前後均有牙齒","(B) 有附連體（attachment）提供支持","(C) 遠伸性（distal extension）可撤式局部義齒基底與殘嵴間有間隙","(D) 壓克力樹脂基底下有植體當支柱牙"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-2-41","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"有關甘迺迪第一類（Kennedy Class I）可撤式局部義齒（removable partial denture）在遠心端缺牙牙嵴 （distal edentulous ridge）區，若須植入植體（implants）時，下列敘述何者正確？①可撤式局部義齒以植 體輔助的最主要好處之一是增加義齒固持性（retention） ②植體置於無牙區越後方區域，義齒越可得到較 大的固持性（retention） ③若義齒對咬不規則咬合面（irregular occlusal plane）之自然牙，植體最好使用 非彈性（non-resilient）的支柱組成（abutment components） ④若義齒對咬不規則咬合面（irregular occlusal plane）之自然牙，植體最好使用非固持性（non-retentive）的支柱組成（abutment components）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"配戴下顎甘迺迪第一類（Kennedy Class I）可撤式局部義齒之病人例行回診時，下列何種情況可能需要換底 墊（reline）？①對咬時，義齒基底下方軟組織疼痛且有潰瘍（ulceration）發生 ②對咬時，義齒與對咬自 然牙（opposing natural teeth）失去原有之咬合接觸 ③咀嚼時，義齒間接固位體（indirect retainer）離開 其鈎座","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-43","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"下列何者可做為可撤式局部義齒的間接固位體（indirect retainer）？ ①門齒鈎靠（incisal rest） ②舌面 隆凸鈎靠（cingulum rest） ③咬合鈎靠（occlusal rest） ④舌側槓（lingual bar）","options":["(A) 僅①②③","(B) 僅①②④","(C) 僅②③④","(D) ①②③④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"下列何者是可撤式局部義齒（removable partial denture）理想的義齒基底材料（denture base material）之 條件？①能夠精確地貼合組織 ②表面緻密無刺激性 ③有足夠的強度以抵抗斷裂或變形","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"上顎犬齒3/4 牙冠（three quarter crown）之修磨，其V-形補強（V-shaped offset）應置於何處？","options":["(A) 切緣（incisal）","(B) 近心軸壁（mesial axial wall）","(C) 舌面隆突（cingulum）","(D) 遠心軸壁（distal axial wall）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"有關瓷鑲面（porcelain laminate veneers）的設計與臨床操作，下列敘述何者正確？①最常使用自聚樹脂黏 著劑（self-curing resin cement）黏合瓷鑲面的理由是為了美觀考量 ②變色且有大範圍樹脂填補的前牙， 是選用瓷鑲面的適應症之一 ③長圓弧邊緣（long chamfer margin）是瓷鑲面邊緣設計的最佳選擇 ④瓷鑲 面需要0.5 mm唇側修磨量（labial reduction）","options":["(A) ①③","(B) ②④","(C) ①②","(D) ③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-47","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"下列關於相互保護性咬合（mutually protected occlusion）的敘述，何者正確？①又稱為前方保護性咬合 （anterior-protected occlusion） ②下顎離中心（eccentric）運動時，後方牙齒完全不接觸 ③咀嚼時，力 量分配到所有牙齒以保護前後的牙齒 ④可避免後方牙齒磨耗 ⑤在安格氏二級咬合（Angle's Class II）病 例最適用","options":["(A) 僅②④","(B) ①③","(C) 僅①②⑤","(D) ①②④⑤"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-2-48","subject":"ya5","topic":"牙科材料學","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"有關聚乙醚（polyether）印模材使用的敘述，下列何者錯誤？","options":["(A) 不適用於動搖牙齒之印模","(B) 可延遲灌模達一週，不會影響精確度","(C) 其抗撕裂強度（tear strength）優於多硫聚合物（polysulfide）","(D) 親水性佳，不適合浸泡太久的消毒劑"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-2-49","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"關於放置根柱（post）前根管內修形，建議可比根管治療時的銼針（file）的號數大，但最多不可超過幾號？","options":["(A) 2號","(B) 3號","(C) 4號","(D) 5號"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-50","subject":"ya5","topic":"植牙贋復","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"上顎前牙拔牙之後，其殘嵴平均吸收量大約多少？","options":["(A) 3.5～5.0 mm垂直齒槽骨及牙齦組織，1.0～2.0 mm頰舌側齒槽骨及牙齦","(B) 2.0～3.5 mm垂直齒槽骨及牙齦組織，2.0～3.0 mm頰舌側齒槽骨及牙齦","(C) 2.0～3.5 mm垂直齒槽骨及牙齦組織，1.0～2.0 mm頰舌側齒槽骨及牙齦","(D) 3.5～5.0 mm垂直齒槽骨及牙齦組織，2.0～3.0 mm頰舌側齒槽骨及牙齦"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-51","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"覆蓋式可撤式義齒（overdentures）之下，在自然牙根或植體上放置距突附連體（stud attachment）或桿狀 附連體（bar attachment）時，最少需有多少垂直空間（vertical space）？","options":["(A) 1～3 mm","(B) 4～6 mm","(C) 7～9 mm","(D) 10～12 mm"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-52","subject":"ya5","topic":"牙科材料學","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"依美國牙醫學會（ADA）標準，牙科用高貴金屬合金（high-noble alloys）所含之貴金屬比重與黃金比重各 為多少？","options":["(A) ≧60%，≧20%","(B) ≧60%，≧40%","(C) ≧85%，≧60%","(D) ≧85%，≧40%"],"answer":1,"clinical_level":"重點"},{"id":"ya5-107-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"全瓷修復體（all-ceramic restorations）邊緣貼合度的好壞，取決於下列何項因素？①牙醫師取模的精準度 ②技工操作的技術 ③瓷材的種類","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"金屬瓷修復體（metal-ceramic restorations）外觀不良的原因，可能為下列何者？①金屬層厚度不足 ②牙 齒修形量不足 ③不透光層太厚 ④過度燒烤","options":["(A) 僅①③","(B) 僅①②④","(C) 僅②③④","(D) ①②③④"],"answer":2,"clinical_level":"重點"},{"id":"ya5-107-2-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"有關樹脂黏合固定義齒（resin-bonded fixed dental prostheses）的敘述，下列何者錯誤？","options":["(A) 一般不需要使用暫時義齒（interim restoration）","(B) 後牙區會有美觀（esthetics compromised）問題","(C) 可用在小孩前牙缺失（missing anterior teeth）的義齒贋復","(D) 可用於已殘缺或修復過的支柱牙（damaged or restored abutment）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-56","subject":"ya5","topic":"牙科材料學","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"在蒙塞氏色系（Munsell color order system）描述顏色的三個向度中，由物體表面所反射或發射出來的光波 波長所決定的是那一個向度？","options":["(A) 色相（hue）","(B) 色度（chroma）","(C) 明度（value）","(D) 色溫（color temperature）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-57","subject":"ya5","topic":"植牙贋復","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"當多個植體角度顯著不平行時，一般而言使用何種印模方式較為準確？","options":["(A) pickup impression technique","(B) transfer impression technique","(C) snap-on impression technique","(D) indirect impression technique"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-58","subject":"ya5","topic":"植牙贋復","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"為避免傷及下齒槽神經及鄰牙，人工植體置入時與解剖構造之距離，下列敘述何者正確？","options":["(A) 位於下齒槽神經管上至少2.0 mm，頦孔前3.0 mm，離鄰牙牙周韌帶1.5 mm以上","(B) 位於下齒槽神經管上至少1.0 mm，頦孔前5.0 mm，離鄰牙牙周韌帶1.5 mm以上","(C) 位於下齒槽神經管上至少2.0 mm，頦孔前5.0 mm，離鄰牙牙周韌帶1.0 mm以上","(D) 位於下齒槽神經管上至少1.0 mm，頦孔前3.0 mm，離鄰牙牙周韌帶1.0 mm以上"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"齒列完整但缺少下列那顆牙齒時，最不適合使用懸臂式牙橋（cantilever bridge）的設計？","options":["(A) 左側上顎側門齒","(B) 左側上顎第一小臼齒","(C) 左側下顎正中門齒","(D) 左側下顎第一小臼齒及第一大臼齒"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-60","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"下列有關印製固定義齒診斷模型的敘述，何者錯誤？","options":["(A) 印模托必須夠堅固以提供印模材料的支撐","(B) 使用藻膠類不可逆性水凝膠（alginate irreversible hydrocolloids）時，牙弓與印模托間隙愈小愈好","(C) 客製的印模托配合矽膠印模材可得到最準確的診斷模型","(D) 診斷模型不一定要印到前庭（vestibule）的底部"],"answer":1,"clinical_level":"一般"},{"id":"ya5-107-2-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"一般而言，固定義齒重建包含前、後牙時，下列何種治療順序最恰當？","options":["(A) 前、後牙一起製作","(B) 製作順序不重要","(C) 先製作前牙","(D) 先製作後牙"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-62","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"下列關於客製前方導引台（custom anterior guide table）的敘述，何者錯誤？","options":["(A) 無法由診斷蠟型取得","(B) 可藉由患者口內已調整理想之暫時修復物（interim restoration）印模後製作","(C) 可從診斷模型製作取得","(D) 製作多顆前牙贋復物時尤其重要"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-63","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"關於硬石膏單齒模（die）製備過程，下列敘述何者正確？","options":["(A) 單齒模之各部位須塗佈空間劑（spacer），以便提供均勻之黏合劑空間","(B) 單齒模空間劑（spacer）不會因蒸發變濃稠","(C) 單齒模整修（trimming）完成後，應以一般鉛筆標劃出完成線（finish line）","(D) 可以塗一薄層氰丙烯酸酯（cyanoacrylate）於標記後的完成線（finish line）上"],"answer":3,"clinical_level":"重點"},{"id":"ya5-107-2-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"關於固定義齒試戴的順序，下列何者為第一個步驟？","options":["(A) 確認鄰接面接觸","(B) 確認牙冠邊緣密合度","(C) 確認咬合關係","(D) 確認美觀"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-65","subject":"ya5","topic":"牙科材料學","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"在鑄造過程中，當金鈀合金（gold-palladium alloy）加熱到何種顏色時，才可以把鑄造環從烤爐拿出來放到 鑄造機器上？","options":["(A) 紅色","(B) 黃色","(C) 橘色","(D) 白色"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-66","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"固定義齒最終黏著後，下列何者最不可能是牙橋固位體（retainer）鬆動之原因？","options":["(A) 黏著技術有問題","(B) 牙齒修磨量不足","(C) 齲齒產生","(D) 固位體之材質"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-67","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"下列關於閉口肌肌纖維的敘述，何者正確？","options":["(A) 顳肌（temporalis muscle）前部（anterior portion）的肌纖維為水平走向","(B) 顳肌（temporalis muscle）中部（middle portion）的肌纖維為上下走向","(C) 顳肌（temporalis muscle）後部（posterior portion）的肌纖維為上下走向","(D) 咬肌深部（deep portion of masseter muscle）的肌纖維為上下走向"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-68","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"關於咀嚼，下列敘述何者錯誤？","options":["(A) 由位於中樞神經內的模式發生器（pattern generator）所控制","(B) 咀嚼活動會受到來自周邊與中樞神經的影響與調節","(C) 咀嚼效率受牙齒和咬點的數目影響","(D) 全口無牙的人會因為缺乏牙周組織的感覺輸入而無法咀嚼"],"answer":3,"clinical_level":"重點"},{"id":"ya5-107-2-69","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"依據 Lund 及 Olsson 1983 年的研究，施麻醉於牙齒的牙周韌帶，會造成何種最大咬力的變化？","options":["(A) 減少","(B) 不變","(C) 增加","(D) 不一定"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-70","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"在下述腦幹（brainstem）的三叉神經核綜合體（trigeminal nucleus complex）中，何者為運動神經核 （motor nucleus）？ ①第五對腦神經之運動神經核（motor nucleus of the 5th cranial nerve） ②三叉神 經之主要感覺神經核（main sensory trigeminal nucleus） ③口次核（subnucleus oralis） ④極間次核 （subnucleus interpolaris） ⑤尾次核（subnucleus caudalis）","options":["(A) 僅①","(B) 僅②③","(C) 僅①③④","(D) ①③④⑤"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-71","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"有關中心關係（centric relation）與最大咬頭嵌合位置（maximum intercuspation）之敘述，何者正確？ ① 中心關係能提供重建咬合的參考 ②大多數的人，中心關係與最大咬頭嵌合位置不重疊 ③兩者位置均需牙 齒咬合決定 ④兩者位置均由咀嚼肌決定","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-72","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"針對不可回復性的咬合治療（irreversible occlusal therapy），下列敘述何者錯誤？","options":["(A) 牙齒選擇性修磨（selective grinding）以及牙齒矯正治療（orthodontic treatment）皆屬不可回復性的咬合 治療","(B) 針對顳顎障礙的患者，初期的治療應以可回復性治療（reversible therapy）為主，並以該治療的結果來評估 是否再進行侵入性（invasive treatment）的治療","(C) 若可回復性治療，例如穩定型咬合板（stabilization splint），可成功治療患者時，則可確保不可回復性咬合 調整也將同樣有效","(D) 對於明顯異常咬合（malocclusion）的自然齒列，不應該進行預防性的牙齒修磨，來降低未來罹患顳顎功能 障症的風險"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-73","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"有關本奈氏運動（Bennett movement）之敘述，下列何者正確？ ①本奈氏運動出現於下顎之側方運動 （lateral movement） ②本奈氏運動之方向（direction）與後牙咬頭高度相關 ③本奈氏運動之量 （amount）與後牙咬頭高度相關 ④本奈氏運動之時機（timing）與後牙咬頭高度相關","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-74","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"從額面觀（frontal view）看下顎咀嚼運動，下列敘述何者錯誤？","options":["(A) 工作側上顎後牙頰側咬頭對到下顎後牙舌側咬頭","(B) 平衡側上顎後牙舌側咬頭對到下顎後牙頰側咬頭","(C) 咀嚼週期張口和閉口路徑平滑不交叉，且閉合接觸幾乎都在中心咬合位置","(D) 開口初期有可能會發生牙齒接觸"],"answer":0,"clinical_level":"一般"},{"id":"ya5-107-2-75","subject":"ya5","topic":"咬合學基礎","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"Miller 於 1982 年提出可能增加肌肉緊張度（muscle tonicity）的因素，包含下列何者？ ①荷爾蒙 ②體內 器官疾病 ③冷熱 ④濕度","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-107-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"下列何者與引起退化性的顳顎關節疾病（degenerative TMJ disease）較無因果關係？","options":["(A) 磨牙","(B) 下顎撞傷","(C) 齒列不整","(D) 喪失後牙支持（loss of posterior support）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"下列有關前置位咬合板（anterior positioning splint）的描述，何者錯誤？","options":["(A) 主要使用在可復位性關節盤易位（disc displacement with reduction）","(B) 主要目的在使易位之關節盤永久回復到正常位置","(C) 不建議長期持續配戴","(D) 臨床上戴此咬合板時，關節盤與髁頭應是處在正常關係"],"answer":1,"clinical_level":"重點"},{"id":"ya5-107-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"下列那一種檢查被認為是診斷顳顎關節盤（TMJ disc）是否移位的判斷標準（gold standard）？","options":["(A) 全口環景攝影（panoramic x-ray）","(B) 測顱攝影（cephalometric x-ray）","(C) 顳顎關節核磁共振（MRI）","(D) 顳顎關節斷層掃描（CT scan）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-107-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"下列顳顎關節影像檢查中，何者最不適宜用來判斷顳顎關節髁頭（condyle）的型態學變化？","options":["(A) 環口顎攝影（panoramic projection）","(B) 直線斷層攝影（linear tomography）","(C) 電腦斷層攝影（computed tomography）","(D) 磁振攝影（MRI）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-107-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"以下關於夜間磨牙的敘述，何者正確？ ①去除咬合干擾點能減輕夜間磨牙 ②絕大部分的病人戴上咬合板 後能抑制夜間磨牙 ③可能與情緒壓力有關 ④有可能伴隨阻塞型睡眠呼吸中止症發生 ⑤發生在兒童身上 的夜間磨牙有可能隨著年齡增加而減緩","options":["(A) 僅①②④⑤","(B) 僅③⑤","(C) 僅②③④","(D) 僅③④⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"裝戴全⼝義齒時，下列何者為其殘嵴所承受的咬⼒型式與主要⽅向？①張⼒（tensile） ②壓⼒ （compressive） ③垂直⽅向 ④垂直及⽔平⽅向","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"全⼝無牙患者的顏⾯特徵常出現下列何種變化？","options":["(A) 唇齒⾓（labiodental angle）喪失","(B) 紅唇露出程度變多","(C) ⿐唇溝（nasolabial groove）的深度不變","(D) 下顎變得較為後縮"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"下列何者不是全⼝義齒患者容易罹患⼝⾓炎（angular cheilitis）的原因？","options":["(A) 義齒垂直⾼度過⾼","(B) 患有缺鐵性貧⾎","(C) 維⽣素B攝取不⾜","(D) 念珠菌感染"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"關於振動線（vibrating line）的敘述，下列何者錯誤？","options":["(A) 病患發 ah⾳時，振動線前後 1～2 mm 區域之軟組織會動","(B) 振動線側⽅延伸到鈎狀切跡（hamular notch）","(C) 張腭帆肌（m. tensor veli palatine）是組成振動線的結構之⼀","(D) 上顎全⼝義齒後緣需延伸到振動線"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"全⼝義齒在最終印模（final impression）做齒槽舌側溝（alveololingual sulcus）的邊緣成形（border molding）時，需要患者做何種動作？","options":["(A) 吞嚥⼝⽔","(B) 張⼤嘴巴","(C) 吸吮動作","(D) 舌頭往前伸出⼝外"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"有關⾅齒後墊（retromolar pad）的敘述，下列何者正確？","options":["(A) 黏膜為⾓化上⽪所構成","(B) 不含腺體組織","(C) 義齒基底後緣應延伸覆蓋","(D) 不含顳腱纖維（temporal tendon）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-1-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"全⼝義齒上顎咬合堤之前後位置，可透過患者發出何⾳來觀察及調整？","options":["(A) S⾳","(B) F⾳","(C) M⾳","(D) B⾳"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"下列何者會影響全⼝義齒正確垂直⾼度（vertical dimension）的建立？","options":["(A) 咬合堤的牙⼸形態錯誤","(B) 咬合平⾯太低","(C) 中⼼關係記錄錯誤","(D) 咬合平⾯未與⿐翼⽿珠線（ala-tragus line）平⾏"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-1-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"在全⼝義齒贋復中，決定⽣理性靜⽌位置（physiological rest position）之重要因素為何？①肌⾁ ②重⼒ （gravity） ③牙齒","options":["(A) 僅①③","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-1-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"關於全⼝義齒的咬合功能，下列敘述何者正確？","options":["(A) 咬合⼒量是健康⾃然齒列的50%","(B) 不同形式的咬合平台（occlusal table）會具有相同的吞嚥前咀嚼次數","(C) 當牙齒接觸後，咬合⼒會隨著滑動時明顯增加","(D) 吞嚥時期的總咬合⼒⼩於咀嚼時期"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"關於義齒⼈⼯牙（artificial teeth）的敘述，下列何者最正確？","options":["(A) 牙齒的形狀比⼤⼩重要","(B) 參考臉型主要是⽤來選擇下顎正中⾨牙","(C) 牙齒的⼤⼩可能會因為光線和陰影⽽改變","(D) 超過50歲的患者才需要模擬⾨牙切端的磨耗（attrition）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"製作全⼝義齒時，如何選擇⼈⼯前牙（anterior tooth selection）的敘述，下列何者最不適當？","options":["(A) 仔細聽病⼈的需求","(B) 請病⼈參與牙齒比⾊（color selection）的步驟","(C) ⼈⼯牙⼤⼩由牙醫師全權決定","(D) 病⼈年輕時的照片有助於決定⼈⼯牙⼤⼩"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"全⼝義齒的製作時，若病⼈的髁頭導引（condylar guidance）較陡，排牙時可藉由下列何種⽅法來達到平衡 性咬合（balanced occlusion）？","options":["(A) 選擇咬頭傾斜度（cusp inclination）較⼩的⼈⼯牙","(B) 減少前牙導引（anterior guidance）的⾓度","(C) 減少咬合平⾯（occlusal plane）的傾斜度","(D) 減少前後⽅向的補償曲線（compensating curve）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"製作完成的全⼝義齒若做側向運動時，平衡側沒有接觸。為維持中⼼咬點並達到平衡咬合，下列何種調整 （adjustment）是正確的？①調整⼯作側下顎的頰側咬頭 ②調整⼯作側下顎的舌側咬頭 ③調整⼯作側 上顎的腭側咬頭 ④調整⼯作側上顎的頰側咬頭","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"當全⼝義齒患者回診，抱怨其張⼤嘴巴吃三明治時，上顎義齒會有鬆動的現象，此時對患者的義齒應該採取 的措施為下列何者？","options":["(A) 將上顎義齒的最後⾯邊緣修短","(B) 將上顎義齒的後障（post-dam）修薄","(C) 將上顎義齒的遠⼼頰側緣修薄","(D) 將上顎義齒的頰側邊緣修短"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"關於全⼝義齒修復的敘述，下列何者錯誤？","options":["(A) 義齒基底的斷裂與殘嵴的吸收無關","(B) 義齒牙齒的斷裂常因撞擊所造成，置換新的牙齒最好在技⼯所完成","(C) 上顎義齒的硬腭部分太薄時與下顎義齒中線部分切⾯部分設計不適當","(D) 義齒⾦屬基底板的斷裂，常因基底樹脂與⾦屬的接合不佳"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"製作上顎單顎全⼝義齒（single complete denture）時，有關前牙之排列，下列敘述何者錯誤？","options":["(A) ⾨齒導引（incisal guidance）的⾓度愈⼩愈好","(B) 必要時下顎前牙必須做咬合調整","(C) 上下顎前牙於中⼼關係咬合（centric relation occlusion）時，維持輕接觸","(D) 若因美觀需求⾨齒導引⾓度較⼤時，則後牙區必須使⽤咬頭⾓度較⼤的⼈⼯牙齒來排列"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-1-18","subject":"ya5","topic":"植牙贋復","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"關於下顎植體⽀持式全⼝義齒之遠⼼懸臂延伸的理想⻑度，下列何者為最適當的考量？","options":["(A) 不得超過患者⼤⾅齒近遠⼼距離的2.0倍","(B) 不得超過患者⼩⾅齒近遠⼼距離的2.5倍","(C) 不得超過最前⽅植體⾄最後⽅植體連線⻑度之1.5倍","(D) 不得超過第⼀⼤⾅齒最近⼼端⾄第⼆⼤⾅齒最遠⼼端的2.0倍"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-19","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"關於覆蓋式義齒⽀柱牙之敘述，下列何者正確？①牙位之分布以梯形分布為佳 ②義齒受⼒時，⽀柱牙扮演 主要承擔壓⼒的⾓⾊ ③覆蓋式義齒常於⽀柱牙處斷裂 ④義齒斷裂處為牙根受⼒太⼤處","options":["(A) ①②③","(B) 僅①③","(C) 僅①②","(D) 僅②④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-20","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"下列何者並非於上顎全⼝義齒在咬合蠟堤（occlusion wax rim）的技⼯製作或臨床評估時之參考點？","options":["(A) ⾨齒乳頭（incisive papilla）","(B) ⽢伯⽒線（Camper's line）","(C) 法蘭克福⽔平⾯（Frankfort horizontal plane）","(D) ⿐翼⽿珠線（ala-tragal line）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"全⼝義齒基底（denture base）若使⽤熱聚合式壓克⼒樹脂，熱⽔浴煮聚（processing）之溫度與時間控 制，下列那⼀種⽅式較能達到良好的樹脂聚合？①於 74℃下 8 ⼩時，再於100℃中 1 ⼩時 ②維持於 74℃ 下超過 8 ⼩時 ③於 74℃下 2 ⼩時，之後於 100℃下超過 1 ⼩時","options":["(A) 僅①","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-22","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"若病患之經濟狀況不是很好，需製作下顎全⼝義齒時，最適合的製作⽅式為下列何者？","options":["(A) 植體⽀持的全⼝義齒","(B) 傳統式的全⼝義齒","(C) ⾦屬床為基底的全⼝義齒","(D) 彈性床全⼝義齒"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"可撤式局部義齒之RPI固位系統的組成，除有I型槓之外，還包含下列何者？①近⼼鄰接板 ②近⼼鈎靠 ③遠⼼鄰接板 ④遠⼼鈎靠","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"關於可撤式局部義齒（removable partial denture）主連接體（major connector）舌側板（lingual plate）使 ⽤的適應狀況，下列敘述何者正確？①齒槽舌溝（alveolar lingual sulcus）與舌側牙齦緣（lingual gingival margin）之間距離不⾜的情況 ②⽢迺迪第三類（Kennedy Class III），且為垂直⽅向吸收嚴重的殘存牙嵴 ③牙周健康狀況不佳（periodontal weaken）的情況 ④可以提供抵抗遠⼼延伸（distal extension）義齒垂 直旋轉（vertical rotation）的功效","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"關於可撤式局部義齒抗衡臂（reciprocal arm）功能之敘述，下列何者錯誤？","options":["(A) 抵消固位臂（retentive arm）傳來的⼒量","(B) 抵抗側向運動，穩定可撤式局部義齒","(C) 當作直接固位體（direct retainer）","(D) 對可撤式局部義齒的穩定性（stability）非常重要"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-26","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"有關可撤式局部義齒主連接體的設計，下列敘述何者錯誤？","options":["(A) 主連接體設計時需有⾜夠剛性，以適度傳遞咬合受⼒","(B) 舌側板對牙周狀況不佳的下顎前牙，可提供穩定作⽤","(C) 下顎舌側板對於有牙周問題的⽀柱牙，可提供垂直⽀持作⽤","(D) 上顎主連接體，可提供垂直⽀持作⽤"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-1-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"下列何者為可撤式局部義齒固位⼒（retention）之來源？①來⾃於牙鈎的固位⼒ ②嘴唇與頰側肌⾁的控制 ⼒ ③⼤氣壓⼒ ④唾液之聚合⼒","options":["(A) 僅①②③","(B) 僅①②④","(C) 僅①③④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"有關可撤式局部義齒的咬合設計，下列敘述何者錯誤？","options":["(A) 偏斜的咬合接觸，產⽣的⽔平分⼒容易傷害到⽀柱牙與牙嵴軟組織","(B) 可撤式局部義齒與對側⾃然齒列咬合，會比對側為全⼝義齒者產⽣較⼤咬⼒","(C) 遠⼼端游離可撤式局部義齒基底承受咬合⼒時，離⽀柱牙愈遠則義齒基底移動的現象愈不明顯","(D) 義齒最合適的咬合作⽤⼒區域應置於第⼆⼩⾅齒與第⼀⼤⾅齒"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-1-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"有關遠伸性局部義齒（distal extension partial denture）的設計，下列何者錯誤？","options":["(A) 為防⽌義齒遠⼼端因食物沾黏⽽脫離，通常需要設計間接固位裝置（indirect retainer）","(B) 使⽤較⻑的鄰接板（proximal plate）可讓⽀柱牙在咀嚼時承擔較少的⽔平分⼒","(C) 常將鈎靠（rest）置於終端（terminal）⽀柱牙的近⼼舌側","(D) 終端（terminal）⽀柱牙若使⽤I型槓（I-bar）作為固位裝置時，其I型槓的尖端應置於該牙頰側的中⼼偏近 ⼼側"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-108-1-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"有關可撤式局部義齒⽀柱牙外廓⾼隆線（height of contour）修形的敘述，下列何者錯誤？","options":["(A) 可藉由改變外廓⾼隆線以提供製作牙鈎與舌側板（lingual plating）最佳設計位置","(B) 上顎後牙常⾒往頰側⽅向傾斜，⽽下顎牙齒則以舌側⽅向傾斜較為常⾒","(C) ⽀柱牙發⽣前移位或傾斜時都有實施修形的必要，但應局限在牙釉質內進⾏","(D) 理想的外廓⾼隆線在近咬合⾯⽅向以不超過咬合⾯與牙齒中間三分之⼀交界為原則"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"有關可撤式局部義齒析量處理的順序為何？①固定析量台 ②模型三點定位處理 ③以分析桿確立置入路 徑 ④劃出析量線 ⑤封凹處理 ⑥以倒凹測量器確立適當倒凹位置","options":["(A) ③①②④⑤⑥","(B) ①③④②⑥⑤","(C) ③①②④⑥⑤","(D) ①③④②⑤⑥"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"有關⽢迺迪第⼆類（Kennedy Class II）可撤式局部義齒的設計考量，下列敘述何者錯誤？","options":["(A) 設計考量基本上與⽢迺迪第⼀類（Kennedy Class I）相似","(B) 間接固位體常設在遠⼼端游離之缺牙區同側的⽝齒或⼩⾅齒上","(C) 牙齒的選擇與排列應能將施⼒於義齒的壓⼒減⾄最低","(D) 缺牙區建議使⽤功能性印模"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-1-33","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"下列因素何者最不影響可撤式局部義齒的預後？","options":["(A) 飲食狀況","(B) 磨牙習慣","(C) 性別","(D) 舌頭推⼒"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-34","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"關於牙齒缺失順序和齒槽骨變化的敘述，下列何者錯誤？","options":["(A) 上顎牙缺失早於下顎","(B) 後牙缺失早於前牙","(C) 上顎⾨牙比下顎⾨牙具有較⾼的蛀牙風險","(D) ⼀般⽽⾔上顎的齒槽骨喪失較下顎嚴重"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"修磨可撤式局部義齒之⽯膏模型時，由前庭往外的邊緣（land area）⾄少為多少mm？","options":["(A) 1","(B) 3","(C) 5","(D) 7"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-36","subject":"ya5","topic":"牙科材料學","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"下列何種印模材料印模後，不適合使⽤浸泡⽅式進⾏消毒？","options":["(A) 多硫化橡膠（polysulfide rubber）","(B) 加成式矽化物（addition silicone）","(C) 縮合式矽化物（condensation silicone）","(D) 聚⼄醚（polyether）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-37","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"有關可撤式局部義齒之理想咬合接觸狀態，下列敘述何者錯誤？①當對側為全⼝義齒或上顎兩側遠伸性可撤 式局部義齒，下顎做前突運動時，上下顎後牙需有接觸 ②側向運動時，上或下顎單側遠伸性可撤式局部義 齒只需有⼯作側的牙齒接觸 ③後⽅⼈⼯牙為求達到平衡咬合及增加咀嚼效率，儘可能排⾄下顎骨嵴開始向 上延伸⾄⾅齒後墊處（retromolar pad） ④⽢迺迪第四類可撤式局部義齒之上下顎前牙在中⼼咬合時，不 需要接觸，以避免過⼤咬合⼒量傳遞⾄殘嵴","options":["(A) 僅②③④","(B) 僅②③","(C) 僅①④","(D) 僅③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"製作上顎前牙可撤式局部義齒時，下列敘述何者錯誤？","options":["(A) 邀請病⼈家屬共同參與前牙的排列，決定美觀是否滿意","(B) 上顎⼈⼯牙的中線需與顏⾯參考中線⼀致","(C) ⼈⼯牙不要修磨以免影響美觀及強度","(D) 在病⼈同意下可適度修磨鄰接之⾃然牙外形"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"可撤式局部義齒完成後，初次置入患者⼝內做咬合調整時，下列敘述何者錯誤？","options":["(A) 牙齒⽀持（tooth-supported）類可撤式局部義齒，⼤多可以⼝內直接調整⽅式達到適當的精確度","(B) 牙齒⽀持（tooth-supported）類可撤式局部義齒的咬合調整，可依循⾃然齒列的咬合調整原則","(C) 遠伸性可撤式局部義齒（distal extension removable partial denture）應以新的咬合記錄固定於咬合器上再 進⾏咬合調整，此法較⼝內直接調整準確","(D) 當上下顎都是牙齒⽀持（tooth-supported）類可撤式局部義齒時，應⼀律先進⾏下顎可撤式局部義齒的調 整，可保持上顎咬合平⾯的⼀致性並減少下顎齒嵴的吸收"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"有關缺牙區牙嵴黏膜容易移動的⽢迺迪第⼀類（Kennedy Class I）可撤式局部義齒，換底墊（reline）時印 模技術的敘述，下列何者正確？①選⽤閉⼝取模技術（closed mouth impression method） ②選⽤張⼝取 模技術（open mouth impression method） ③適⽤選擇性壓⼒印模技術（selective pressure impression technique） ④必須使⽤功能性印模技術（functional impression technique）","options":["(A) 僅①③","(B) 僅②④","(C) 僅②③","(D) 僅①④"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-1-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"可撤式局部義齒換底墊（reline）時，下列何者可作為義齒基底之印模材？①橡膠（rubber base） ②⼝溫 蠟（mouth temperature wax） ③組織調理材料（tissue conditioning material） ④⾦屬氧化物印模膏 （metallic oxide impression paste）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-42","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"可撤式局部義齒鍛製⾦屬線牙鈎（wrought wire clasp）的尖端，⾄少須距離牙齦多少mm？","options":["(A) 0.2","(B) 1.0","(C) 1.8","(D) 2.4"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-43","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"有關可撤式局部義齒⾦屬⽀架設計，上顎左側第⼆⼩⾅齒的遠⼼端缺牙，設計間接固位體（indirect retainer）最適當的位置為下列何者？","options":["(A) 右側第⼀⼤⾅齒近⼼","(B) 左側第⼆⼩⾅齒近⼼","(C) 右側⽝齒舌側","(D) 左側第⼀⼩⾅齒近⼼"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya5-108-1-44","subject":"ya5","topic":"牙科材料學","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"以瓊膠（agar）翻製耐火模型（refractory cast）時，下列敘述何者錯誤？","options":["(A) 將模型放置於複製包埋盒（duplicating flask）中間，並⽤黏⼟類（clay-like）材料將模型邊緣和盒底貼合固 定","(B) 包埋盒拆開時可利⽤兩把⼑刃插入模型兩側，⼩⼼地將主模型移出","(C) 瓊膠材料操作溫度為53°C","(D) 只有包埋盒的基底部分需浸在冷卻⽔槽中"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"當⼤⾅齒⽀柱牙的牙周已經變差，導致根叉侵犯（furcation involvement），下列何者不是製作此⽀柱牙牙冠 時應注意事項？","options":["(A) 在⽀柱牙靠近根叉處應修磨固位溝（retentive groove）以利於清潔","(B) 因為⽀柱牙的⾼度較⼤，因此倒錐⾓度可稍⼤，以避免牙冠不易置入到底","(C) 若牙根⽀持⾯積已經變少，則牙冠頰舌⾯的寬度應略⼩，以減少咬合⼒","(D) 應避免修磨過寬的邊緣（margin），以免齒質喪失更多"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-1-46","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"下列何者對牙冠之固位⼒（retention）幫助較少？","options":["(A) 將牙冠內⾯弄粗糙","(B) 牙齒軸壁聚攏⾓度保持在6度之內","(C) 將牙齒表⾯弄粗糙","(D) ⽤樹脂黏合劑黏著"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-1-47","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"當全牙冠（complete crown）遇到⼀個頰側的側⽅⼒量時，其抗⼒形區域（resistance area）會在何處？","options":["(A) 近⼼⾯（mesial surface）","(B) 遠⼼⾯（distal surface）","(C) 頰側⾯（buccal surface）","(D) 舌側⾯（lingual surface）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-48","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"下列何者為顳顎關節之特點？①可做樞紐（hinge）運動及滑動 ②為雙關節（diarthric） ③有⼆關節腔 ④有關節盤","options":["(A) 僅①②④","(B) 僅①③④","(C) 僅①②③","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-49","subject":"ya5","topic":"牙科材料學","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"為了增加⽯膏抵抗磨損的能⼒，可加入⼀些添加物，但下列何者不合適？","options":["(A) colloidal silica","(B) calcium hydroxide","(C) gum arabic","(D) silver or copper"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"有關根柱（post）之敘述，下列何者錯誤？","options":["(A) 根柱⻑度增加，固位性（retention）亦隨之增加且兩者成線性關係","(B) 兩側平⾏的根柱（parallel-sided post）固位性優於錐形根柱（tapered post）","(C) 根柱之⻑度若較臨床牙冠為短，則其預後不佳","(D) 根柱之直徑不應超過牙根橫切⾯直徑之1/3"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-1-51","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"牙齦萎縮的牙齒製作固定義齒時，下列何項處置可以讓圖中箭頭所⽰的⾅齒頰側牙根分叉區域有較佳的清潔 性？","options":["(A) 牙根切除（root amputation）","(B) ⼩⾅齒化（bicuspidization）","(C) 半切斷術（hemisection）","(D) ⻑凹槽（flute）"],"answer":3,"image":"ya5-108-1-51.jpeg","clinical_level":"一般"},{"id":"ya5-108-1-52","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"下列對於橋體設計的考量，何者錯誤？","options":["(A) 橋體與橋體下的軟組織，應保持被動（passive）接觸","(B) 橋體⾦屬與瓷的交界處，可放置在橋體與殘嵴接觸的部位","(C) 咬合寬度較⼩的橋體，可能較不易清潔，也不能⽀撐臉頰軟組織（cheek support）","(D) 橋體在強咬合⼒下會產⽣彎曲形變，其形變量為徑距（span length）變化量的立⽅倍"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-1-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"下列何種橋體（pontic）設計，適⽤於下顎非美觀區且頰舌徑很窄的殘嵴？","options":["(A) 鞍形（saddle）","(B) 改良式嵴疊形（modified ridge lap）","(C) 圓錐形（conical）","(D) 卵圓形（ovate）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-1-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"下列那⼀項不屬於⾦屬瓷牙橋（metal-ceramic bridge）失敗的主要原因？","options":["(A) 不好的⽀架設計","(B) 不適合的咬合","(C) 不適合的殘嵴外形","(D) 不好的牙齒修形"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-1-55","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"關於Procera全瓷冠系統，下列敘述何者錯誤？","options":["(A) 牙齒修磨後的形狀不可以有尖銳的線⾓（line angle）","(B) 在齒模上要塗上單齒模空間劑（die spacer）以提供⽇後黏著劑的空間","(C) ⽀柱牙的邊緣必須⾄少是heavy chamfer或rounded shoulder","(D) 可以⽤樹脂黏著劑黏著牙冠"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-1-56","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"⼀患者因為左上中⾨齒的瓷牙⾦屬邊緣露出⽽要求重新製作，同時發現右上中⾨齒切端有破損⽽決定以瓷貼 ⾯（ceramic laminate）修復。若希望兩個牙齒的顏⾊能夠⼀致，理想的補綴物製作步驟應為如何？","options":["(A) 同時修磨兩顆⾨齒並印模，同時製作瓷貼⾯與瓷牙","(B) 同⼀個模型上先製作瓷牙後再製作瓷貼⾯","(C) 先做好瓷牙，黏上牙齒後再製作瓷貼⾯","(D) 先做好瓷貼⾯，黏著好後再製作瓷牙"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-57","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"下列何者並非臨時固定義齒的主要功能？","options":["(A) 保護牙髓","(B) 維持牙周組織健康","(C) 保持咬合穩定","(D) 避免牙齦萎縮"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-58","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"考量上顎前牙重建時的切緣位置與美觀，下列敘述何者正確？①嘴唇放鬆時前牙切緣約在上嘴唇緣以下1～2 mm ②發F⾳時，前牙切緣接觸下嘴唇乾濕表⾯的交界線 ③前牙切緣的連線應該與微笑時上嘴唇唇緣弧 度相同 ④前牙切緣連線應該與顏⾯中線垂直","options":["(A) ②③④","(B) ①②④","(C) ①②③","(D) ①③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"關於比⾊的技巧，下列何者錯誤？","options":["(A) 為了避免同⾊異構（metamerism）的現象，比⾊時應該在不同照明環境下進⾏","(B) 比⾊時觀察時間越久，比出來的顏⾊越正確","(C) 選擇牙齒的明度（value）時，可以將眼睛瞇起以減少光線進入眼中","(D) 比⾊時應請患者穿著顏⾊較淡的服裝，同時避免濃妝"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-60","subject":"ya5","topic":"植牙贋復","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"下圖中植牙的印模套件是⽤在何種印模⽅式？","options":["(A) 轉移印模（transfer impression）","(B) 提取印模（pickup impression）","(C) 閉合牙托印模（closed tray impression）","(D) ⼀體型印模（one-piece impression）"],"answer":1,"image":"ya5-108-1-60.jpeg","clinical_level":"一般"},{"id":"ya5-108-1-61","subject":"ya5","topic":"植牙贋復","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"⼈⼯植體使⽤⼀年後，周邊齒槽骨每年吸收量在多少mm以內，為臨床可接受之範圍？","options":["(A) 0.2","(B) 1","(C) 1.5","(D) 2"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-62","subject":"ya5","topic":"植牙贋復","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"前牙⼈⼯植牙前，對植體近遠⼼之齒間乳頭（interdental papilla）於術後是否能存在，術前評估的主要依據 為何？","options":["(A) 鄰接牙的牙骨質牙釉質交接處（cementoenamel junction）⾄鄰間接觸點（interproximal contact point）的 距離","(B) 齒間骨頭（interdental bone）⾄預定的鄰間接觸點（interproximal contact point）的距離","(C) 鄰接牙的牙齦線⾄預定的鄰間接觸點（interproximal contact point）的距離","(D) ⼈⼯植牙植體之平台（platform）⾄預定的鄰間接觸點（interproximal contact point）的距離"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-63","subject":"ya5","topic":"臨床基礎與倫理","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"下列評估病⼈贋復治療預後的考量何者最不重要？","options":["(A) 年齡","(B) 系統性疾病","(C) ⼝內牙齒的蛀牙率","(D) 性別"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-64","subject":"ya5","topic":"牙科材料學","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"以噴燈（torch）進⾏銲接（soldering）操作時，銲劑（solder）之流動⽅向應為下列何種⽅式？","options":["(A) 流向熱源⽅向","(B) 遠離熱源⽅向","(C) 與熱源⽅向無關，流向⽯墨","(D) 與熱源⽅向無關，遠離⽯墨"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-65","subject":"ya5","topic":"牙科材料學","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"關於嵌體蠟（inlay wax）的敘述，下列何者錯誤？","options":["(A) 第⼀類嵌體蠟在⼝腔溫度下不具顯著的流動性","(B) 第⼆類嵌體蠟適合以間接法製作蠟型","(C) 嵌體蠟的主要成分是含40～60%的蜂蠟（beeswax）","(D) 嵌體蠟燃燒後容許0.1%的殘餘物"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-66","subject":"ya5","topic":"臨床基礎與倫理","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"下列何種處置最能有效降低青少年鄰接⾯之蛀牙？","options":["(A) 每隔兩週做⼝腔衛教","(B) 每隔兩週塗氟","(C) 每隔兩週由牙醫師作⼝腔清潔","(D) 每隔兩週使⽤漱⼝⽔"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-67","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"關於咀嚼肌神經感覺受器（neurosensory receptors），下列敘述何者正確？","options":["(A) 肌梭（muscle spindles）主要傳遞肌⾁壓⼒（pressure）的訊號","(B) ⾼爾基腱器官（Golgi tendon organ）主要傳遞肌⾁速度的訊號","(C) 游離神經末梢（free nerve endings）傳遞訊號比肌梭和⾼爾基腱器官還要快","(D) 閉⼝肌群比開⼝肌群含有比較多的肌梭"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-1-68","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"關於⼝腔顏⾯疼痛經驗的基本概念，下列何者正確？①痛處（site of pain）是病患主觀上描述感到疼痛的位 置，痛源（source of pain）是實際上導致疼痛經驗的位置 ②在異位痛（heterotopic pain）中，痛源與痛 處並非同⼀個位置 ③即使是異位痛，痛處與痛源依然位於同⼀條神經⽀配的範圍內 ④轉移痛（referred pain）可被視為是⼀種異位痛","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-69","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"三叉反射（trigeminal reflex）和脊椎反射（spinal reflex）的比較，下列敘述何者正確？①都為simple reflex ②兩者的向⼼輸入的神經元都位於中樞神經系統外 ③除了肌梭（muscle spindle），⽪膚或顳顎關節內的 感受器也可引起三叉反射 ④兩者的運動神經傳導速度相同","options":["(A) ①③","(B) ②③","(C) ①④","(D) ②④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-70","subject":"ya5","topic":"咬合學基礎","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"以下關於中⼼⾃由（freedom in centric）咬合之敘述，何者正確？","options":["(A) 較常⾒於年⻑者的⾃然齒列中","(B) 因咬合接觸不穩定，易造成咀嚼肌⾁過度使⽤","(C) 若⾃由度超過 0.5 mm，病⼈易有不知該咬在那裡的困擾","(D) ⻑中⼼（long centric）較寬中⼼（wide centric）對病⼈來得好"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-71","subject":"ya5","topic":"咬合學基礎","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"下列何種情況不適合建立相互保護性咬合（mutually protected occlusion）？","options":["(A) 安格式 class I 咬合","(B) 安格式 class III 咬合","(C) 前牙完整且牙周狀況良好","(D) 安格式 class II division 2 咬合"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-1-72","subject":"ya5","topic":"咬合學基礎","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"當下顎從中⼼關係（centric relation）滑到咬頭嵌合位置（intercuspal position）產⽣前上滑動 （anterosuperior slide）時，下列何者為導致此滑動的牙齒斜⾯？","options":["(A) 上顎的近⼼斜⾯（mesial incline）對到下顎遠⼼斜⾯（distal inlcine）","(B) 上顎的遠⼼斜⾯（distal incline）對到下顎近⼼斜⾯（mesial incline）","(C) 上顎的近⼼斜⾯（mesial incline）對到下顎近⼼斜⾯（mesial incline）","(D) 上顎的遠⼼斜⾯（distal incline）對到下顎遠⼼斜⾯（distal incline）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-1-73","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"關於下顎前突運動的敘述，下列何者錯誤？","options":["(A) 兩側外翼肌拉著髁頭沿關節前隆突向前向下斜移，此時的關節盤則往後往上旋轉","(B) 下顎前突運動時，閉⼝肌也會同時作⽤","(C) 在第⼀類咬合型態中，從上下牙齒嵌合處到上下⾨齒切端相對處的平均⾓度，稱之前⽅導引（anterior guidance）","(D) 前突運動時，可藉由前⽅導引（anterior guidance）使後牙分開不接觸"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-1-74","subject":"ya5","topic":"咬合學基礎","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"將模型置位（mounting）於咬合器時，有關第三參考點與平⾯設定的敘述，下列何者錯誤？","options":["(A) ⼀般常選⽤眼框下緣（lower border of orbital rim）或⿐根點（nasion）為第三參考點","(B) 是為了配合髁頭樞紐軸線（condylar hinge axis）與⽔平⾯（horizontal plane）上可能的位置，適當地設定 在咬合平⾯","(C) 咬合器上⽀架（upper member）常被設定平⾏於眼框平⾯向（orbital axis plane）","(D) ⿐根點（nasion）常被⽤來執⾏置位模型時之垂直調整，使模型與咬合器上⽀架位置更適當"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"下列何者不屬於顳顎障礙症的症狀？","options":["(A) 出現異感痛（allodynia）","(B) 磨牙","(C) 牙關緊咬","(D) 下顎運動於開閉⼝不規則"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"醫師做終極試驗（endfeel test）時，患者的最⼤張⼝距仍維持不變，下列何者比較不是可能的原因？","options":["(A) 腫瘤","(B) 骨折","(C) 關節盤可復位前移（disc anterior displacement with reduction）","(D) 關節囊內黏連（adhesion）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"關於咬合板的治療⽬的，下列敘述何者錯誤？","options":["(A) 可以提供穩定的顎間關係","(B) 對於疼痛控制的療效，有許多看法不⼀的報告","(C) 對於顎關節噪⾳的處理，被認為⼀定有療效","(D) 阻斷部分牙齒的過早接觸，可以保護牙齒並排除可能性的咬合⼲擾"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"下列有關顳顎障礙症藥物治療的敘述，何者錯誤？","options":["(A) 非類固醇消炎藥（NSAID）對治療關節炎有效","(B) 僅使⽤肌⾁鬆弛劑即可明顯減輕關節炎性疼痛","(C) 若需使⽤類固醇消炎，建議採⽤關節注射以減少全⾝性副作⽤","(D) 若有睡眠困擾的肌源性疼痛，建議使⽤低劑量三環抗憂鬱劑（tricyclic anti-depressants）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"關於退化性顳顎關節炎（osteoarthritis）的敘述，下列何者正確？①成因為滑膜（synovial membrane）發 炎並擴及articular surface造成 ②通常合併有不可復位性關節盤移位（disc displacement without reduction） ③通常關節有捻髮聲（crepitus） ④診斷需要有TMJ 放射片（radiograph）之骨破壞來確定","options":["(A) 僅①③","(B) 僅③④","(C) 僅②③④","(D) ①②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"以貫顱投影法（transcranial projection）拍攝顳顎關節，呈像中看到的顳顎關節髁頭的上緣，實際上是接近 下列那⼀個部位的影像？","options":["(A) 內極（medial pole）","(B) 上緣（superior border）","(C) 外極（lateral pole）","(D) 前緣（anterior border）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-1","subject":"ya5","topic":"臨床基礎與倫理","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"全口無牙患者全身性健康狀況會影響到口腔黏膜組織，而造成全口義齒的預後不佳，下列敘述何者錯誤？","options":["(A) 口腔扁平苔藓（oral lichen planus）的患者，其口腔黏膜組織容易遭受刺激而疼痛，因而造成全口義齒適應 的困難","(B) 多形性紅斑（erythema multiforme）或黏膜類天皰瘡（mucous membrane pemphigoid）與口腔扁平苔藓（oral lichen planus）的狀況相似","(C) 全身性紅斑狼瘡（systemic lupus erythematosis）會造成口腔黏膜上皮細胞下發炎（subepithelial inflammation），容易產生口腔潰瘍，因而不易承受全口義齒的壓力","(D) 全身性紅斑狼瘡（systemic lupus erythematosis）屬於自體免疫第三類的過敏反應，且男女發生機率相似"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"下列何者不是口腔灼感症候群（burning mouth syndrome）的可能原因？","options":["(A) 感染（infection）","(B) 肌筋膜疼痛（myofascial pain）","(C) 缺鐵性貧血（iron deficiency anemia）","(D) 老化（aging）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"一位年長的男性全口義齒患者，配戴義齒多年未定時回診，上顎義齒已鬆動不貼合。若在上顎義齒覆蓋之前硬 腭部出現花椰菜狀增生組織（cauliflower-like hyperplastic tissues），下列診斷何者錯誤？","options":["(A) 此增殖性組織亦稱為腫裂齦瘤（epulis fissuratum）","(B) 此為創傷發炎性組織","(C) 易合併念珠菌感染","(D) 屬於type III 義齒性口腔炎（denture stomatitis）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"關於鈎狀切迹（hamular notch）的敘述，下列何者錯誤？","options":["(A) 位於上顎粗隆（tuberosity）與內翼板（medial pterygoid plate）之間","(B) 此處黏膜主要由疏鬆的蜂窩組織（areolar tissue）構成","(C) 張腭帆肌（m. tensor veli palatini）以水平走向通過此處","(D) 上顎全口義齒後邊緣需將此處之軟組織排開（displace）"],"answer":[0,1,2,3],"clinical_level":"一般","explanation_pending":false},{"id":"ya5-108-2-5","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"有關全口無牙病人舌（tongue）之位置與協調的敘述，下列何者正確？","options":["(A) 由於舌外在肌（extrinsic muscle）重新定位，故舌頭變大","(B) 舌的習慣性運動變多（habitually active）","(C) 後縮型（retrude）舌位置有利義齒的穩定","(D) 前置型（protrude）舌位置有利義齒的穩定"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"下列那項組合最適合實施上顎全口義齒的同時全邊緣成形法（simultaneous molding of all borders）？","options":["(A) 常備模托（stock tray），藻膠印模材（alginate）","(B) 客製化模托（custom tray），藻膠印模材（alginate）","(C) 客製化模托（custom tray），聚乙醚印模材（polyether）","(D) 客製化模托（custom tray），棒狀印模化合材（stick impression compound）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"有關咬合平面之決定方式，下列何者錯誤？","options":["(A) 上顎咬合堤在前方應與瞳孔連線（interpupillary line）平行","(B) 上顎咬合堤在後方應與鼻翼耳珠連線（ala-tragus line）平行","(C) 以嘴角的位置作為決定咬合平面高度之參考時，往往相對應於下顎犬齒之高度","(D) 下顎第一大臼齒約與臼齒後墊（retromolar pad）之上 2/3 處等高"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"欲獲得正確的全口義齒垂直距離（vertical dimension），下列敘述何者正確？","options":["(A) 是否戴咬合堤，不影響靜止時垂直距離（vertical dimension of rest）的測量","(B) 影響靜止垂直距離（vertical dimension of rest）的因素只有肌肉","(C) 咬合垂直距離（vertical dimension of occlusion）不同時，中心關係（centric relation）記錄會隨之改變","(D) 靜止時的垂直距離（vertical dimension of rest）閉口肌肌電圖電位為零"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-2-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"為獲得全口無牙病患可靠的口內中心關係（centric relation）紀錄，下列敘述何者錯誤？","options":["(A) 指示病患將下顎往後縮，閉合咬合蠟堤後部","(B) 指示病患將舌捲向上顎義齒後側緣，閉合咬合蠟堤後部","(C) 指示病患重覆輕敲前牙咬合蠟堤","(D) 按摩顳肌與咬肌使其放鬆"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"製作全口義齒，有必要縮小前牙區的牙齒寬度且要具有吸引力（attractive）時，最合適作法為何？","options":["(A) 使用較窄的中門牙","(B) 使用較窄的側門牙","(C) 使用較窄的犬齒","(D) 使用較窄的全部前牙"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"全口義齒排牙時，上顎正中門齒切緣位置應距離門齒乳頭（incisive papilla）中心之前方多少 mm？","options":["(A) 2～4","(B) 5～7","(C) 8～10","(D) 11～13"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-2-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"於全口義齒選擇人工牙材質時，下列何種組合是最不利的組合？","options":["(A) 前牙為瓷牙，後牙為樹脂牙","(B) 前牙為樹脂牙，後牙為瓷牙","(C) 上顎牙為瓷牙，下顎牙為樹脂牙","(D) 下顎牙為瓷牙，上顎牙為樹脂牙"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-13","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"依循平衡咬合（balanced occlusion）觀念並選用零度牙製作全口義齒時，下列敘述何者錯誤？","options":["(A) 需要中心關係（centric relation）的咬合紀錄","(B) 宜使用半調節式咬合器（semiadjustable articulator）","(C) 相對於平面咬合（monoplane occlusion）模式，有較美觀的前牙覆蓋（overlap）","(D) 相對於平面咬合（monoplane occlusion）模式，可大幅減少排牙時間"],"answer":3,"clinical_level":"重點"},{"id":"ya5-108-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"製作全口義齒時，有五大咬合法則可以調整以達到平衡性咬合（balanced occlusion），牙醫師無法決定的因 素為何？","options":["(A) 髁導引（condylar guidance）","(B) 補償曲線（compensating curve）","(C) 門齒導引（incisal guidance）","(D) 咬合平面（occlusal plane）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-2-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"義齒製作與完成過程中，下列何者是產生咬合誤差的因素？①顳顎關節的狀態改變 ②上下顎關係紀錄未轉 移至咬合器 ③後牙不正確的排列 ④義齒基底樹脂吸收水與唾液 ⑤使用過大的壓力緊閉包埋盒","options":["(A) 僅①②③⑤","(B) 僅①②③④","(C) 僅②③④⑤","(D) ①②③④⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"全口義齒患者因偏移性（deflective）咬合接觸所導致之疼痛，常出現於下列何處？","options":["(A) 殘嵴嵴頂（crest of the residual ridge）","(B) 殘嵴斜坡（slope of the residual ridge）","(C) 頰側前庭（buccal vestibule）","(D) 舌繫帶（lingual frenum）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"下列何者不是即裝義齒（immediate denture）的缺點？","options":["(A) 不能試戴蠟型義齒","(B) 較不易取得正確的上下顎間紀錄","(C) 拔牙傷口較易有疼痛的情形","(D) 較不易取得正確的印模"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya5-108-2-18","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"閉孔器製作完成後，有關口腔與鼻腔之間密合度的測試方法，下列何者正確？","options":["(A) 觀察患者是否可以完成擤鼻涕的動作","(B) 觀察患者於低頭喝水時，水是否倒流至鼻腔中","(C) 可以使用吸管喝水來測試閉孔器的密合狀態","(D) 患者如果將b音發成m音，通常意味著閉孔器密合度不夠理想"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-19","subject":"ya5","topic":"植牙贋復","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"下列那些植體與槓狀附連體（bar）的組合，會形成由植體與齒槽骨嵴共同支持（implant/ridge supported）的 下顎義齒？ ①二支植體以一根容許旋轉的槓狀附連體相連 ②二支植體以一根不容許旋轉的槓狀附連體相 連 ③三支不共線植體以二根容許旋轉的槓狀附連體相連 ④三支不共線植體以二根不容許旋轉的槓狀附連 體相連","options":["(A) 僅①","(B) ①②","(C) ①③","(D) ②④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-20","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"下列何者不是下顎全口義齒主模型（master cast）排牙參考的界標（landmark）？","options":["(A) 臼齒後墊（retromolar pad）之高度與寬度","(B) 甘伯氏線（Camper's line）之走向","(C) 下顎小臼齒區齒槽嵴（residual ridge）之位置","(D) 下顎大臼齒區齒槽嵴最凹陷處"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"全口義齒製作過程中，在蠟型義齒（wax denture）試戴後，下列何種情形不必重置（remount）下顎模型？","options":["(A) 患者下半臉部過短，而必須提高垂直高度（vertical dimension）","(B) 上顎前牙排得太長且太突，而必須重新排列","(C) 咬合平面（occlusal plane）明顯傾斜時必須重新進行面弓轉移（facebow transfer）","(D) 兩側後牙區之咬合接觸明顯左右不均勻"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"新設計之牙科植體（dental implant）需進行臨床人體試驗。依據相關法規之規範，下列敘述何者錯誤？","options":["(A) 研究計畫主持人必須接受過人類研究倫理審查委員會（簡稱IRB）之訓練課程","(B) 研究計畫必須經IRB審查，並送衛生福利部主管單位核准才可執行","(C) 必須取得受測者合法的同意書","(D) 受測者的病歷保存至研究計畫結束後十年"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"有關RPI的敘述，下列何者正確？①I型槓最上緣位於支柱牙（abutment）的倒凹處（undercut） ②使用0.01 inch的倒凹，且倒凹位於支柱牙頰側齒頸1/3（cervical third）位置 ③遠伸性（distal extension）局部義齒為 適應症之一 ④組成應有鄰接板（proximal plate）、鈎靠（rest）、舌側抗衡臂（lingual reciprocal arm）及I 型槓","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"病患上顎剩下6顆前牙且有輕度牙周問題，已經完成治療，兩側遠心端缺牙區之殘嵴呈現中、重度萎縮。若希 望以可撤式局部義齒重建口腔功能，則應選擇下列那一種主連接體最適當？","options":["(A) 馬蹄型（horseshoe）","(B) 全腭型（complete palatal plate）","(C) 前後腭槓（anteroposterior palatal bar）","(D) 前後腭帶（anteroposterior palatal strap）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-25","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"有關可撤式局部義齒支柱牙固定（splinting of abutment teeth）方法的敘述，下列何者錯誤？","options":["(A) 適用於牙周支持作用比較不理想的支柱牙，可經由固定處理達到增強效果","(B) 將兩顆或多顆牙以固定式或可撤式局部義齒方式固定，可提供支柱牙穩定性的改善","(C) 兩顆牙以固定方式連結就如同一顆多根的支柱牙，可以將咬合受力充分達到分散效果","(D) 多顆牙周狀況不佳的牙齒，可利用多個鈎靠及固位性牙鈎分散咬合力與提升義齒整體固位作用"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-26","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"可撤式局部義齒上顎主連接體（major connector）的側面部分，至少應距離腭側牙齦緣多少mm？","options":["(A) 6","(B) 10","(C) 14","(D) 18"],"answer":0,"clinical_level":"重點(深度)"},{"id":"ya5-108-2-27","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"可撤式局部義齒的直接固位體（direct retainer），下列何者最不影響美觀？","options":["(A) 槓鈎（bar clasp）","(B) 冠內附連體（intra-coronal attachment）","(C) 鍛製金屬線牙鈎（wrought wire clasp）","(D) 環周牙鈎（circumferential clasp）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-2-28","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"可撤式局部義齒印模時，使用修正模型印模技術（altered cast impression technique）的主要目的為何？","options":["(A) 取得上下顎顎間咬合關係","(B) 取得軟組織的倒凹（undercut）與理想的解剖形態（anatomic form）","(C) 取得支柱牙的倒凹（undercut）及分布位置","(D) 取得殘嵴軟組織與支柱牙之間平衡的受力關係"],"answer":3,"clinical_level":"重點"},{"id":"ya5-108-2-29","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"可撤式局部義齒的設計中，有關間接固位體（indirect retainer）的敘述，下列何者錯誤？","options":["(A) 可由一或多個鈎靠（rest）與支持的小連接體（minor connectors）共同組成","(B) 為了獲得良好的力矩，間接固位體的放置，應距離支點線（fulcrum line）越近越好","(C) 鄰近無牙區的鄰接板（proximal plates）也具有間接固位（indirect retention）的功能","(D) 可減少遠伸性（distal extension）局部義齒的基底（denture base），因食物沾黏而旋轉脫離牙嵴組織面的機 會"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-108-2-30","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"製作可撤式局部金屬義齒支架（metal framework）時，下列何者不需平行封凹 （parallel blockout）？","options":["(A) 當作引導面（guiding plane）用之鄰接牙面","(B) 小連接體（minor connector）所覆蓋的鄰接面","(C) 固位鈎臂（retentive clasp arm）的倒凹（undercut）","(D) 槓鈎（bar clasp）所經過的組織倒凹（undercut）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-2-31","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"有關甘迺迪第四類（Kennedy Class IV）缺牙製作可撤式局部義齒的設計考量，下列敘述何者最正確？","options":["(A) 義齒的運動和傳遞至支柱牙的壓力，與甘迺迪其他三類大同小異","(B) 為滿足美觀與發音需求，牙齒的排列置放須偏向殘嵴頂的後側","(C) 不同於甘迺迪第一、第二類，此類可撤式局部義齒不需設計間接固位體","(D) 假如缺牙數量多，且面積延伸較廣泛時，應考慮進行功能性印模處理"],"answer":3,"clinical_level":"重點"},{"id":"ya5-108-2-32","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"有關鄰接咬合鈎座（interproximal occlusal rest seat）修磨的敘述，下列何者正確？①在牙齒的邊緣嵴 （marginal ridge）處必須有1.5 mm厚度 ②修磨主要是將接觸點（contact point）打開 ③修磨時需要延伸到 腭／舌（palatal/lingual）側 ④磨出舌側垂直溝（lingual vertical groove）","options":["(A) 僅①③","(B) 僅③④","(C) 僅②③","(D) ①②③④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"有關製作可撤式局部義齒前詳細的口腔檢查與評估，下列敘述何者錯誤？","options":["(A) 必須充分瞭解患者的需求，並且做詳細的口腔檢查和評估","(B) 發生義齒性口炎（denture stomatitis）時，病患常會感到燒灼與搔癢感","(C) 腭隆凸（torus palatinus）較常於男性口腔內發現","(D) 口乾的患者配戴可撤式局部義齒時，軟組織容易受到義齒磨擦的刺激或形成潰瘍"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-34","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"關於部分牙齒缺失後的變化，下列敘述何者錯誤？","options":["(A) 前牙缺失會影響唇齒音","(B) 剩餘牙齒會出現移位的情況","(C) 剩餘牙齒不會過度受力","(D) 可能會喪失垂直高度"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-2-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"修正模型印模技術（altered cast impression technique）最常用在下顎何種類型的部分缺牙狀況？①甘迺迪第一 類（Kennedy Class I） ②甘迺迪第二類（Kennedy Class II） ③甘迺迪第三類（Kennedy Class III） ④甘 迺迪第四類（Kennedy Class VI）","options":["(A) ①②","(B) ①③","(C) ②④","(D) ③④"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-2-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"關於常備模托（stock tray）的敘述，下列何者錯誤？","options":["(A) 必須要足夠剛硬（rigid）","(B) 必須提供給印模材均勻的4～7 mm空間","(C) 在甘迺迪第三類（Kennedy Class III）的病例，可以用常備模托來印取主模型","(D) 常備模托延伸的長度不是影響變形的主要原因"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-37","subject":"ya5","topic":"牙科材料學","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"有關多硫化橡膠印模材（polysulfide rubber impression material）的敘述，下列何者錯誤？","options":["(A) 具有高度的彈性與良好的抗撕裂性","(B) 屬於加成式反應（addition reaction）印模材，凝固後會有水分子的副產物釋出造成收縮變形","(C) 凝固時間較長，操作時間充裕","(D) 印模後不應立即灌模，但需在一小時內進行石膏灌模處理為佳"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-2-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"在獲取可撤式局部義齒之咬合記錄時，何項不是金屬氧化物膏（metallic oxide paste）優於蠟製材料之好處？","options":["(A) 流動性較佳","(B) 經濟、便宜","(C) 體積穩定","(D) 對合時容易被推擠移位"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"下列關於可撤式局部義齒咬合調整的敘述，何者錯誤？","options":["(A) 當下顎可撤式局部義齒對咬上顎全口活動義齒時，應考慮以雙側平衡性咬合（bilateral balanced occlusion）","(B) 下顎遠伸性義齒（distal extension denture）的人工牙齒與同側的自然齒，應同時具有工作側的咬合接觸 （working side contacts）","(C) 單側遠伸性可撤式局部義齒，除了該側工作時的咬合接觸外，另側同時有平衡咬合接觸也是必要的","(D) 下顎遠伸性義齒的後牙不應排在陡升（sharp upward incline）的齒嵴或臼齒後墊（retromolar pad）之上"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-2-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"有關可撤式局部義齒換底（rebase）之敘述，下列何者錯誤？","options":["(A) 是一種以新的材料置換義齒基底的作法","(B) 通常不須置換新的人工牙","(C) 施作的機會比換底墊（reline）還高","(D) 以開口（open mouth）或閉口（closed mouth）之方式取模均可"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"有關缺牙牙嵴黏膜堅實（firm）的甘迺迪第二類（Kennedy Class II）可撤式局部義齒置換底墊（reline）的敘 述，下列何者正確？①適用選擇性壓力印模技術（selective pressure impression technique） ②適用功能性印 模技術（functional impression technique） ③印模前，舊義齒基底（denture base）頰棚（buccal shelf）處修 磨比牙嵴頂（ridge crest）修磨多","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"可撤式局部義齒的金屬義齒支架和人工齒之間至少要距離幾mm？","options":["(A) 0.5","(B) 1.5","(C) 2.5","(D) 3.5"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"有關可撤式局部義齒主模型進行珠緣（beading）處理的敘述，下列何者錯誤？①上下顎模型都要珠緣 ②建 立樹脂與金屬義齒支架（metal framework）的終接線（finishing line） ③使金屬義齒支架與組織能有密貼 （intimate contact）的效果 ④珠緣由縱切面觀之，為半圓形","options":["(A) 僅①②","(B) 僅②③","(C) 僅③④","(D) 僅②④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-44","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"關於可撤式局部金屬義齒支架（metal framework）與樹脂基底連結所形成的終接線（finishing line），下列敘 述何者錯誤？","options":["(A) 內終接線（internal finishing line）在主模型的缺牙區，以緩壓蠟（relief wax）貼製而成","(B) 外終接線（external finishing line）在金屬義齒支架製作過程中置放，並於雕刻蠟型時形成","(C) 壓克力樹脂義齒基底與金屬的結合界面，理想是以方形接合（butt joint）","(D) 外終接線的內緣角（internal angle），亦即主連接體和小連接體在交接處所形成的角度，應大於90度"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"有關鑄造式全金屬牙冠支柱牙修磨的敘述，下列何者正確？①邊緣（margin）為弧形（chamfer） ②功能性 咬頭至少要有1 mm 的修磨量 ③儘可能做牙齦上（supraginginval）邊緣修形 ④邊緣修磨至少要有0.8 mm 的厚度","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-46","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"下列何者不是前牙部分鑲面牙冠（partial veneer crown）的禁忌症（contraindications）？①活性齒（vital teeth） ②球狀齒（bulbous teeth） ③齒頸部齲齒（cervical caries） ④較長的牙冠（longer crown）","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-47","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"重建下顎大臼齒及小臼齒的咬合面時，下列敘述何者錯誤？","options":["(A) 平坦的前伸髁徑（protrusive condylar path）必有較低的咬頭高度","(B) 較大的立即性側方位移（immediate lateral translation）產生較寬的中心窩（central fossa）","(C) 牙脊（ridge）與牙溝（groove）的方向及位置主要受前伸髁徑（protrusive condylar path）的影響","(D) 較小的立即性側方位移（immediate lateral translation）可能有較高的咬頭高度"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-48","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"使用電刀排齦時，那一種電流切除能力佳且具止血效果？","options":["(A) unrectified電流","(B) partial rectified電流","(C) full rectified電流","(D) full rectified with filter電流"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-49","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"有關黏著鑄造式柱心的敘述，下列何者正確？","options":["(A) 因為黏合劑流動度關係，必須快速將柱心置入","(B) 放到定位後，立即讓患者咬住為宜","(C) 使用螺旋渦針（lentulo spiral）可幫助將黏合劑置入根管內","(D) 為了增加柱心的固位力，黏合劑越多越好"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-2-50","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"為支撐齒間乳突（interdental papilla），在拔牙時，卵圓形橋體（ovate pontic）應放入拔牙後齒槽中約多少 mm ？","options":["(A) 1.5","(B) 2.5","(C) 3.5","(D) 5.0"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-51","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"有關使用於金屬瓷冠合金的敘述，下列何者錯誤？","options":["(A) 鈀－銀（Pd-Ag）合金較金－鈀－銀（Au-Pd-Ag）合金有較高的彈性係數（elastic modulus）與降伏強度 （yield strength）","(B) 鈀－銀（Pd-Ag）合金中的銀含量約30～35%，易造成瓷綠變色","(C) 鈀－鎵（Pd-Ga）合金較鈀－銅－鎵（Pd-Cu-Ga）合金表面硬度低","(D) 鈀－鎵－鈷（Pd-Ga-Co）合金較難以瓷粉遮色"],"answer":0,"clinical_level":"重點"},{"id":"ya5-108-2-52","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"局部可撤式義齒的牙冠固位體（retainer）上，若欲放置冠內附連體（intracoronal attachment），此附連體之齒 頸－咬合（cervical-occlusal）高度至少應為多少mm ？","options":["(A) 2","(B) 3","(C) 4","(D) 6"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"衛生型橋體（sanitary pontic）有利於清潔，下列何種臨床狀況較適合使用衛生型橋體？①缺牙區高度僅3 mm 時 ②上顎臼齒區 ③下顎臼齒區","options":["(A) 僅①","(B) 僅②","(C) 僅③","(D) ②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-54","subject":"ya5","topic":"牙科材料學","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"高溫融合牙科瓷（high-fusing dental ceramics）的融合溫度範圍為下列何者？","options":["(A) 攝氏1290～1370度","(B) 攝氏1600～1950度","(C) 攝氏2050～2300度","(D) 攝氏2350～2500度"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"製作金屬瓷修復體（metal-ceramic restorations）時，下列何者會影響修復體的外觀？①顏色（color） ②形 狀（shape） ③表面結構與特徵（surface texture and characteristics）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-56","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"關於前牙黏著牙橋（adhesion bridge）及其支柱牙修磨的敘述，下列何者正確？①由於高貴金屬生物相容性 佳，常用於黏著牙橋義齒支架（framework）製作 ②支柱牙舌溝（lingual grooves）修磨必須約1 mm深， 0.75 mm寬，5 mm長 ③支柱牙舌溝修磨必須要相互平行 ④鄰接於缺牙區的鄰接面溝（interproximal groove），用以抵抗頰舌方向的位移","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-57","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"下列有關比色（shade matching）的敘述，何者錯誤？","options":["(A) 比色時，牙醫師的眼睛應該與病人等高，這樣牙醫師才能應用到視網膜上對顏色最為敏銳的區域來比色","(B) 比色應該在不同的燈光下進行","(C) 要進行比色的牙齒需要保持乾淨","(D) 長時間持續觀察比較容易獲得正確的比色"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-58","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"上顎正中門齒缺牙區應採用何種橋體設計（pontic design），最能滿足患者的美觀要求？","options":["(A) 嵴疊（ridge-lap）橋體","(B) 改良式嵴疊（modified ridge-lap）橋體","(C) 錐形（conical）橋體","(D) 卵形（ovate）橋體"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-59","subject":"ya5","topic":"植牙贋復","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"相對於screw-retained implant crown，下列那一項並非cement-retained implant crown之優點？","options":["(A) 容易達成 passive fit","(B) 比較少出現screw loosening","(C) 調整植體與義齒之間的角度差異相對容易","(D) 製作費用比較便宜"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-60","subject":"ya5","topic":"植牙贋復","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"植體長軸與其受力方向間之角度增加時，可能出現的狀況不包含下列何者？","options":["(A) 支柱螺絲較易鬆脫","(B) 植體邊緣之骨吸收增加","(C) 較易發生美觀及形態問題","(D) 在bone-implant interface之咬合應力向根部擴散，而不再集中於crestal bone"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-61","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"下列何者不是選擇性咬合修形（selective occlusal reshaping）的主要目的？","options":["(A) 治療顳顎關節障礙","(B) 建立牙尖對咬窩的咬合接觸（cusp-fossa occlusion）","(C) 去除偏移性咬合接觸（deflective occlusal contacts）","(D) 移除邊緣脊差異（marginal ridge discrepancies）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-62","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"使用玻璃瓷（glass ceramic）全牙冠重建上顎第一小臼齒，下列何種情況的預後最差？","options":["(A) 近、遠心面齲齒，但不須根管治療","(B) 近心面齲齒，已根管治療","(C) 近心面齲齒合併頰側咬頭斷裂至牙齦處，已根管治療","(D) 近心面齲齒合併腭側咬頭斷裂至牙齦處，已根管治療"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-63","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"下列何種方法可以增加牙冠黏合劑之空間？","options":["(A) 增加包埋材之膨脹","(B) 使用環氧樹脂單齒模系統（epoxy resin die system）","(C) 使用具有高熔點範圍之合金","(D) 使用電鍍單齒模系統（electroplated die system）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-108-2-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"固定義齒最理想的銲接縫隙是多少mm？","options":["(A) 0.1","(B) 0.25","(C) 0.4","(D) 0.55"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-65","subject":"ya5","topic":"牙科材料學","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"使用前銲（preceramic soldering）技術時，其銲劑（solders）的特點，下列何者錯誤？","options":["(A) 必須使用熔點高於烤瓷溫度的合金","(B) 銲劑的熔點範圍很寬","(C) 銲劑不可以含有銀和銅","(D) 陶瓷無法與銲劑具有良好的鍵結"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-66","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"考慮製作固定義齒時，下列有關牙根齲齒之敘述，何者錯誤？","options":["(A) 隨年齡增長有增加之趨勢","(B) 與病患之經濟狀況、種族背景及口腔衛生有關","(C) 與緩徵鏈球菌（Streptococcus mitis）有關","(D) 50歲以上之族群發生率較高"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-67","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"關於顳顎關節周邊之韌帶（ligament）的敘述，下列何者錯誤？","options":["(A) 囊韌帶（capsular ligment）包覆整個顳顎關節","(B) 顳顎（temporomandibular）韌帶斜部（oblique portion）的作用是限制旋轉張口（rotational opening）運動","(C) 顳顎（temporomandibular）韌帶水平部（horizontal portion）的作用是限制顎髁與關節盤向後運動","(D) 莖突下顎（stylomandibular）韌帶的作用是限制下顎過度向後移動"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-68","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"關於中樞模式產生器（central pattern generator）與咀嚼運動的關聯，下列何項敘述正確？①對於控制運動的 節律性（rhythmic）扮演重要角色 ②由眾多神經核組成，主要分布於小腦與基底核（basal ganglia） ③協 調拮抗肌（antagonist muscle）的收縮 ④會接收來自舌唇齒與牙周韌帶的感官回饋訊息","options":["(A) 僅②④","(B) 僅①②③","(C) 僅①③④","(D) ①②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-69","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"關於咀嚼系統肌肉過動（muscle hyperactivity），下列何者明顯錯誤？","options":["(A) 肌肉過動意指肌肉活動程度（muscular activity）超出執行正常功能所需的程度","(B) 若觀察到肌肉過動，即表示口顎系統有異常功能（parafunction）","(C) 肌肉過動可能與肌肉緊張度（muscle tonus）升高有關","(D) 即使下顎並未運動，也可能有肌肉過動現象"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-70","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"在安格氏第一類咬合關係中，當下顎進行側向運動（lateral movement）時，在工作側與非工作側若有接觸， 其接觸的可能位置，下列何者錯誤？","options":["(A) 工作側上顎後牙頰側咬頭內（inner）斜面接觸下顎後牙頰側咬頭外（outer）斜面","(B) 工作側上顎後牙舌側咬頭外（outer）斜面接觸下顎後牙舌側咬頭內（inner）斜面","(C) 非工作側上顎後牙舌側咬頭外（outer）斜面接觸下顎後牙頰側咬頭外（outer）斜面","(D) 非工作側上顎後牙舌側咬頭內（inner）斜面接觸下顎後牙頰側咬頭內（inner）斜面"],"answer":2,"clinical_level":"一般"},{"id":"ya5-108-2-71","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"導致下顎向左側側移（left side shift）的中心關係干擾（CR interferences）的相對位置，下列何者錯誤？","options":["(A) 左側上顎舌側咬頭頰側斜面接觸左下顎頰側咬頭的舌側斜面","(B) 左側上顎舌側咬頭舌側斜面接觸左下顎舌側咬頭的舌側斜面","(C) 右側上顎舌側咬頭舌側斜面接觸右側下顎舌側咬頭頰側斜面","(D) 右側上顎頰側咬頭舌側斜面接觸右側下顎頰側咬頭頰側斜面"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-72","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"關於咬合中心關係（centric relation）的敘述，下列何者錯誤？","options":["(A) 這個位置是可重複取得的，它位於下顎最終後退旋轉弧線（terminal retruded arc）上，牙齒後退接觸的位置","(B) 它位於下顎邊界運動上緣與後緣的交點，此時髁頭位於最終樞紐軸線（terminal hinge axis）上","(C) 多數人的中心關係與最大咬頭嵌合MICP（maximum intercuspation）的位置會重疊","(D) 以此為起點導引下顎沿邊界運動後緣旋轉至門齒距離約20mm時，髁頭應有較明顯的轉動，也尚未越過關節 隆突"],"answer":2,"clinical_level":"重點"},{"id":"ya5-108-2-73","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"關於髁頭導引（condylar guidance）的敘述，下列何者正確？","options":["(A) 髁頭導引的取得不會因為不同操作者與不同咬合器而造成差異","(B) 如果咬合器上之髁頭導引設定較患者實際值陡，贋復物將容易產生後牙的咬合干擾","(C) 使用放射影像也可以定出髁頭導引值，且影像上很容易判斷，不易受其它解剖構造影像的影響","(D) 髁頭導引的斜度，常受顎間關係的影響。class I 患者量測得的數值比class II患者的大，但比 class III患者的 小"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-74","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"老李嚼食花生時，右側為其咀嚼時之慣用側（habitual side），此時其左右側髁頭（condyle）之運動情形為 何？","options":["(A) 右側髁頭往前下位移之量大於左側髁頭","(B) 右側髁頭往右側位移之量小於左側髁頭","(C) 左側髁頭往前下位移之量等於右側髁頭","(D) 左側髁頭往左側位移之量大於右側髁頭"],"answer":1,"clinical_level":"一般"},{"id":"ya5-108-2-75","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"下列敘述，何者較不常出現在左側不可復位型關節盤前移（disc anterior displacement without reduction）的患 者？","options":["(A) 最大開口距離（maximum mouth opening）常會受限","(B) 終極測試（endfeel test）呈現較硬的觸感，且不太容易再被動增加其開口距離","(C) 下顎進行側方運動時，向右側側移的幅度常小於向左側側移的幅度","(D) 無法保持直線開口，常有向右側偏斜（deflection）的軌跡"],"answer":3,"clinical_level":"重點"},{"id":"ya5-108-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"關於顳顎障礙症的敘述，何者正確？","options":["(A) 人口中有近 2/3 的人具有一或多個顳顎關節或肌障礙症的癥兆","(B) 最常見的症狀為開口障礙","(C) 大多數的患者為年齡介於 40 至 60 歲之女性","(D) 約半數出現症狀的人會尋求治療"],"answer":0,"clinical_level":"重點(深度)"},{"id":"ya5-108-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"關於顳顎障礙症的病因與治療目標，下列何者錯誤？","options":["(A) 它被認為是肌肉骨骼障礙症的變體，多與下顎運動相關聯","(B) 藉由可逆性、保守謹慎的方法可以有效處理，但較難治癒","(C) 治療的原則應基於效力與實證，藉由廣泛性壓力處理與諮商進行行為修正，也可改善疼痛並促進關節運動恢 復","(D) 顳顎障礙症若合併咬合問題，則治療應優先處理咬合問題"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-108-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"關於重置位咬合板（repositioning splint）的製作與臨床使用，下列何者正確？","options":["(A) 其目的是提供新的髁中心位置，對關節盤異位的患者皆有好的療效","(B) 睡眠時使用重置位咬合板，較白天時使用更可能維持關節盤的復位","(C) 製作重置位咬合板時，設定下顎的位置應盡可能的前突，以促使確保關節盤的復位來使用","(D) 重置位咬合板的使用更需患者的配合，與有計劃的回診，以避免後牙開咬的不可逆咬合變化"],"answer":3,"clinical_level":"一般"},{"id":"ya5-108-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"造成顳顎關節（temporomandibular joint）髁盤複合體（condyle-disc complex）盤韌帶（discal ligament）延長 （elongation）的相關致病因素，下列何者可能性較低？","options":["(A) 上下牙齒分開時下顎承受外傷（open mouth trauma）","(B) 上下牙齒咬緊時下顎承受外傷（closed mouth trauma）","(C) 持久性張大開口（extended wide mouth opening）","(D) 全身麻醉下插管（intubation）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-108-2-80","subject":"ya5","topic":"咬合學基礎","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"關於單側下外翼肌（inferior lateral pterygoid muscle）肌肉痙攣（muscle spasm）的敘述，下列何者正確？① 造成同側後牙無接觸 ②造成對側後牙無接觸 ③造成對側前牙過重接觸 ④造成同側前牙過重接觸","options":["(A) 僅①③","(B) ②④","(C) ①②③","(D) ①③④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-1","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"關於口腔黏膜組織的生物機械性質，下列敘述何者正確？①口腔黏膜的物理性質是純屬於彈性（elastic property） ②當口腔黏膜組織承受壓力時，短時間內即會變形與變薄 ③當口腔黏膜組織承受壓力（11 g/mm2, 10分鐘）時，在壓力移除8分鐘後，組織厚度即可以恢復90% ④當口腔黏膜組織承受壓力（11 g/mm2, 10分鐘）時，在壓力移除2小時後，組織厚度可以恢復100%","options":["(A) ①②","(B) ①③","(C) ②③","(D) ②④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"關於唾液的敘述，下列何者錯誤？","options":["(A) 唾液之流量及黏度（viscosity）與全口義齒的固位性（retention）有關","(B) 正常人於休憩狀態之唾液流量每分鐘約 1 ml","(C) 口腔黏膜是否容易受傷及對發音的影響與唾液量無關","(D) 唾液量不足時，會造成食物有金屬味"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"關於全口無牙患者初診時的臨床檢查，常見的顏面特徵變化，下列敘述何者錯誤？","options":["(A) 唇紅緣邊緣（vermilion border）內縮","(B) 鼻唇角（nasolabial angle）變大","(C) 鼻唇溝（nasolabial groove）加深","(D) 下顎後縮（retrognathic appearance）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-4","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"上下顎較常發生外生贅骨（exostoses）的位置為下列何者？","options":["(A) 上顎頰側後方（buccal sides of the posterior maxillary segments）","(B) 上顎頰側前方（buccal sides of the anterior maxillary segments）","(C) 下顎舌側後方（lingual sides of the posterior mandibular segments）","(D) 下顎舌側前方（lingual sides of the anterior mandibular segments）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"下列何者為全口義齒最終印模（final impression）需緩壓（relief）的區域？","options":["(A) 下顎齒槽骨嵴（mandibular alveolar ridge）","(B) 上顎粗隆（maxillary tuberosity）","(C) 下顎臼齒後墊（mandibular retromolar pad）","(D) 上顎硬腭（maxillary hard palate）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-109-1-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"上顎全口義齒牙床何處最適合做為主要咬合壓力承載區？","options":["(A) 無牙嵴（edentulous ridge）","(B) 中線外側水平硬腭（horizontal palate）","(C) 皺摺（rugae）","(D) 粗隆（tuberosity）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"關於全口義齒咬合堤（occlusion rim）的敘述，下列何者錯誤？","options":["(A) 以下顎咬合堤建立咬合平面與高度","(B) 以上顎咬合堤決定上下顎牙弓形態","(C) 記錄初步的中心顎間關係（centric relation）","(D) 以咬合堤決定垂直高度（vertical dimension）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-8","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"關於全口義齒前牙的重疊（overlap）關係，下列敘述何者錯誤？","options":["(A) 由美觀決定","(B) 可以利用由發音確定上下前牙位置的正確性","(C) 門齒導引（incisal guide）設定成完全水平時，前牙排列成只有切緣互相接觸或完全不接觸","(D) 當前牙沒有垂直覆蓋時，門齒導引（incisal guide）的角度設定應加大"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-9","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"全口義齒排牙後，於試戴時檢查顎間咬合關係的敘述，下列何者錯誤？","options":["(A) 義齒基底與黏膜之貼合與否，不影響義齒的咬合穩定性","(B) 上顎義齒基底若穩固性佳，只須用手固定下顎義齒基底","(C) 義齒基底在牙齒閉合過程中有滑動，表示顎間關係有誤","(D) 需清楚觀察牙齒最初至最大咬合接觸的過程"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-10","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"全口義齒的後緣封閉（posterior palatal seal）至少應位於義齒後緣之前方多少 mm？","options":["(A) 0.5","(B) 1.0","(C) 1.5","(D) 2.0"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-1-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"關於排列全口義齒後牙的注意事項，下列何者錯誤？","options":["(A) 當患者上下牙嵴頂的連線與咬合平面所形成之舌側角度小於 80 度，應考慮將後牙排成錯咬（crossbite）","(B) 第二小臼齒的咬頭尖端應低於臼齒後墊（retromolar pad）1 至 2 mm","(C) 大臼齒的咬頭頰側略高於舌側，與水平面的夾角應小於 10 度","(D) 以舌側化咬合（lingualized occlusion）觀念排牙時，下顎牙齒的功能性咬頭要接觸上顎牙齒"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"配戴全口義齒的患者要有正確的發音，舌頭前腹與上顎中線區空間的橫截面（cross section）面積是多少 mm2？","options":["(A) 6","(B) 10","(C) 14","(D) 18"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"依循舌側咬合（lingualized occlusion）觀念製作全口義齒時，下列敘述何者錯誤？","options":["(A) 需做適當的調整以獲得多個工作側接觸及至少一個平衡側接觸來維持側方運動時的義齒穩定","(B) 舌側咬合型式，特別適用於單顎義齒","(C) 相對於平面咬合（monoplane occlusion）模式，可大幅提高咀嚼效率（chewing efficiency）","(D) 相對於平面咬合（monoplane occlusion）模式，患者後牙外觀較不自然"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"有關全口義齒的排牙，若依照舌側化咬合（lingualized occlusion）模式，下列敘述何者錯誤？","options":["(A) 在中心位置（centric position）時，上顎後牙的頰側咬頭並未與對咬牙直接接觸","(B) 側向運動時，工作側以及平衡側皆有牙齒接觸","(C) 下顎後牙可以選擇使用零度牙","(D) 不適用於下顎後縮顎間關係的患者"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-1-15","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"關於全口義齒換底墊（relining）與換基底（rebasing）的敘述，下列何者錯誤？","options":["(A) 換底墊指的是加入新材料重新讓義齒基底更加密合口內組織","(B) 換底墊可以在臨床診間直接完成","(C) 換基底指的是將整個義齒基底置換成新的材料","(D) 換基底只要在臨床診間直接完成，不需要送去技工所完成"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"有關下顎全口義齒穩定性較上顎差之原因，下列敘述何者正確？①下顎全口義齒之基底面積約僅有上顎之 1/2～1/3 ②下顎全口義齒頰側及舌側之肌肉均可能影響其穩定性 ③舌頭位置較會影響下顎全口義齒之穩 定","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"關於即裝義齒（immediate denture）的敘述，下列何者錯誤？","options":["(A) 裝著後的第一個 24 小時，患者不可以將義齒取下","(B) 即裝義齒只是過渡性的義齒，因此印模和製作前不需要進行咬合分析和咬合平面的修整","(C) 印模時，印模牙托的把手必須避免過長，以免干擾前方邊緣成形（border molding）的進行","(D) 軟底墊（soft liner）更換的頻率主要以齒槽嵴吸收狀況和患者維持軟底墊清潔的能力為考量的因素"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-109-1-18","subject":"ya5","topic":"植牙贋復","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"植體覆蓋式義齒使用桿狀附連體之設計考量，下列何者最不適當？","options":["(A) 連結桿外型應順應殘嵴形態","(B) 保留人工齒排列空間","(C) 患者可方便進行口腔清潔","(D) 儘量使用較長的遠心端懸臂延伸"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-19","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"腭部豐隆贋復物（palatal augmantation prosthesis）不使用於下列何種顎顏面缺陷？","options":["(A) 患者因舌癌切除部分舌頭","(B) 舌下神經（hypoglossal nerve）受損","(C) 因下顎骨局部切除而致下顎偏斜","(D) 軟腭切除"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-20","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"門齒乳頭（incisive papilla）之位置是上顎全口義齒前牙排列的重要參考點。關於此位置的敘述，下列何者錯 誤？","options":["(A) 在一般中等程度吸收的牙床上，門齒乳頭之位置穩定","(B) 上顎中門齒切端位於門齒乳頭前緣水平向前 8-10 mm","(C) 上顎犬齒間連線會經過門齒乳頭後緣，但會因牙弓形態而稍有變異","(D) 若上顎前牙區牙床嚴重吸收，其位置會改變，前牙排列之參考需做修正"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-1-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"有關全口義齒製作過程中，臨床重置位（clinic remount）與技工室重置位（laboratory remount）之比較，下列 敘述何者錯誤？","options":["(A) 技工室重置位在先，臨床重置位於後","(B) 技工室重置位只能修正樹脂包埋聚合形成之誤差，臨床重置位可同時修正臨床過程與技工製作中形成之誤差","(C) 上顎的定位，技工室重置位以裂模法。臨床重置位只能使用面弓轉移","(D) 下顎之定位，技工室重置位以裂模法。而臨床重置位必須使用中心關係咬合記錄"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-1-22","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"患者就診時的主訴是全口義齒容易脫落，於臨床檢查發現全口義齒咬合關係和垂直高度正確，但是義齒與黏 膜密合度不足，下列的處置何者最正確？","options":["(A) 告訴患者義齒一定要重新製作","(B) 利用現有全口義齒換底墊（reline）","(C) 告訴患者一定要進行人工植牙治療","(D) 告訴患者全口義齒原本就是這樣"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"影響可撤式局部義齒固位牙鈎臂（retentive clasp arm）可彎曲性大小的因素，下列敘述何者錯誤？","options":["(A) 隨長度增加而增加","(B) 隨橫切面大小減少而增加","(C) 外型不影響可彎曲性","(D) 合金的機械性質會影響牙鈎的可彎曲性"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"可撤式局部義齒之下顎主連接體（major connector）舌側槓（lingual bar）的橫切面形狀為何？","options":["(A) 圓形（round shape）","(B) 三角形（triangular shape）","(C) 半梨形（half-pear shape）","(D) 方形（square shape）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-1-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"對於可撤式局部義齒組合牙鈎（combination clasp）的敘述，下列何者正確？①常用於鄰接遠心游離端的支柱 牙具有適當遠心（distal）倒凹的病例 ②組合牙鈎較環周牙鈎（circumferential clasp）美觀 ③固位牙鈎臂 （retentive clasp arm）應為半圓形（half rounded） ④抗衡性牙鈎臂（reciprocal arm）應為鑄造（cast）式","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-26","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"在可撤式局部義齒的設計上，於甘迺迪分類（Kennedy classification）中同時兼具牙齒支持（tooth-borne）與 牙齒-組織支持（tooth-tissue-borne）的特點是屬於第幾類？","options":["(A) Class I","(B) Class II","(C) Class III","(D) Class IV"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"在可撤式局部義齒中，下列何者較不適用長引導面（long guiding plane）？","options":["(A) 以牙齒支持（tooth-borne）為主的可撤式局部義齒","(B) 下顎前牙區缺牙的可撤式局部義齒","(C) 上顎前牙區缺牙的可撤式局部義齒","(D) 以組織支持（tissue-borne）為主的可撤式局部義齒"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-109-1-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"遠伸性可撤式局部義齒（distal extension removable partial denture）的無牙嵴區可提供的支持，受以下那些因 素影響？①義齒基底（denture base）與遠伸區組織的密合度 ②牙嵴的形態與質地 ③可撤式局部義齒金 屬支架的設計 ④間接固位體（indirect retainer）的位置","options":["(A) 僅①②③","(B) 僅①③④","(C) 僅②④","(D) ①②③④"],"answer":0,"clinical_level":"重點(深度)"},{"id":"ya5-109-1-29","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"製作可撤式局部義齒時，義齒與支柱牙之鄰接面沿牙齒的縱軸與鈎座（rest seat）底部所呈的夾角應如何才最 正確？","options":["(A) 大於90度","(B) 等於90度","(C) 小於90度","(D) 大於180度"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-30","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"有關可撤式局部義齒最終主模型灌注需要注意事項，下列敘述何者最正確？","options":["(A) 口內取出的聚乙醚印模材（polyether impression material）經過噴灑消毒劑後，應該立即灌注石膏防止變形","(B) 混合硬石膏時，應依據正確水粉比灌注模型，且避免氣泡產生","(C) 第一層石膏初步硬化後取出，以水濕潤表面後，加上第二層石膏材料後手持做基底造型","(D) 主模型在上顎硬腭中心點與下顎舌側口底最深處的模型基底至少要保有15 mm以上厚度"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-1-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"局部義齒製作時，下列何者無法藉由析量（survey）診斷模型而獲得？","options":["(A) 支柱牙引導面（guiding plane）修形的參考","(B) 齒槽嵴與支柱牙倒凹（undercut）的測量","(C) 支柱牙外廓高隆線（height of contour）","(D) 主連接體（major connector）的種類"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-32","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"有關可撤式局部義齒前牙鈎座（rest seat）修形理念，下列敘述何者錯誤？","options":["(A) 前牙舌面隆凸（cingulum）與切緣鈎座常呈現傾斜表面，容易產生偏離軸心的荷重","(B) 切緣鈎座位置選擇常須考慮咬合狀況與美觀，故通常選擇放在犬齒的機會多於正中門齒","(C) 切緣鈎座一般只能製作在牙釉質層，大部分案例都放置在靠鄰接面的遠心切緣表面上","(D) 切緣鈎座常使用6號圓型鑽石磨針修形，位置離鄰接角約2.0～3.0 mm，且深度約2.0～3.0 mm"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"關於製作可撤式局部義齒患者，其口內評估的相關敘述，下列何者最不恰當？","options":["(A) 記錄口內需要調整的區域","(B) 是否維持適當的口腔健康","(C) 以牙醫師主觀的想法來進行評估","(D) 患者對於現有假牙的使用經驗"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-34","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"製作可撤式局部義齒時，用來定位上顎模型於咬合器上的設備，下列何者可以提供最多資訊？","options":["(A) 咬合記錄（occlusal record）與模型支撐（cast support）","(B) 咬合記錄（occlusal record）與咬合叉（bite fork）","(C) 面弓（facebow）與咬合叉（bite fork）","(D) 面弓（facebow）與模型支撐（cast support）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"製作可撤式局部義齒時，印模的牙托與牙齒之間最適當的距離為多少mm？","options":["(A) 2～4","(B) 5～7","(C) 8～10","(D) 11～13"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"遠伸性可撤式局部義齒（distal extension removable partial denture）需進行換底墊（reline）或換底（rebase） 時，若使用原來的義齒戴入口中取模，則下列何者為最正確的操作方法？","options":["(A) 請患者閉口緊咬","(B) 請患者輕輕閉口吞口水","(C) 醫師以手指施予平均壓力於遠伸區的人工牙齒咬合面上","(D) 醫師手指壓於鈎靠（rest）以及間接固位體（indirect retainer）上"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-109-1-37","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"堆疊何種材料於記錄基底（record base）上所取得的中心關係（centric relation）最不精確？","options":["(A) 軟化的蠟咬合堤（softened wax occlusal rim）","(B) 製模塑膠咬合堤（modeling plastic occlusal rim）","(C) 快凝取模用石膏（quick-setting impression plaster）","(D) 自聚式樹脂（autopolymerizing resin）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-109-1-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"下列關於可撤式局部義齒的咬合建立與調整何者錯誤？","options":["(A) 大多數情況的咬合是依循當下剩餘自然牙所呈現的咬合型式（occlusal pattern）來建立","(B) 當剩餘的前牙會造成義齒的鬆脫或是不穩定，則應依循全口義齒的咬合方式來調整咬合","(C) 當下顎可撤式局部義齒對咬上顎全口義齒時，則應考慮依循全口義齒的咬合方式來調整咬合","(D) 口內直接調整的咬合往往比固定於咬合器上調整來得容易且準確"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-1-39","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"下列何者為可撤式局部義齒建立和諧咬合之原則？①下顎遠伸性可撤式局部義齒，須併同自然牙建立工作側 之咬合接觸（working side contact） ②若對咬為上顎全口義齒，下顎為遠伸性可撤式局部義齒時，離中心位 置（eccentric position），須達到雙側平衡性咬合（bilateral balanced occlusion）之要求 ③在甘迺迪第四類之 可撤性局部義齒，在中心咬合（centric occlusion）時須與對咬之前牙有接觸，以避免對咬自然牙之延長生長 （elongation）","options":["(A) 僅②③","(B) 僅①②","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-40","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"下列何者不是可撤式局部義齒牙鈎臂（clasp arm）斷掉之可能原因？","options":["(A) 牙鈎臂反覆彎曲","(B) 進入過深的倒凹區","(C) 放置牙鈎處的支柱牙鬆動","(D) 牙鈎臂鑄造時的缺陷"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-1-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"有關可撤式局部義齒之追蹤與維護，下列何者最正確？","options":["(A) 安排病人於初次試戴48小時後回診","(B) 若病人有夜間磨牙的問題，牙醫師可建議戴著義齒睡覺","(C) 如果上顎是全口義齒，下顎仍保有幾顆前牙，睡覺時應配戴上顎全口義齒","(D) 漂白水可用來取代假牙清潔液"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-1-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"可撤式局部義齒蠟型試戴完成後，關於進行樹脂基底充填包埋處理過程，下列敘述何者錯誤？","options":["(A) 選擇緊密貼合的包埋盒","(B) 模型置放在包埋盒底部，牙齒咬合面距離包埋盒上緣至少15 mm","(C) 包埋時，上下層之間的石膏均需塗抹凡士林分離劑，而且包埋盒間隙邊緣不得有石膏殘留","(D) 以四層包埋法包埋，在除蠟處理後，將上、下包埋盒分開，可以看見樹脂牙留在第三層"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"製作可撤式局部義齒時，關於義齒基底樹脂充填煮聚過程，下列敘述何者錯誤？","options":["(A) 樹脂粉／液以1:1的比率均勻混合後，待其呈現麵團狀不黏手時即可填壓處理","(B) 樹脂填壓應少量多次重複操作，直到溢出量達最少時再緊閉包埋盒以螺絲固定","(C) 若欲快速煮聚樹脂，可將水溫在1小時內升至74℃維持90分鐘後，再加熱至沸騰並維持30分鐘","(D) 主模型與義齒從包埋盒取出後，重置放回咬合器做咬合調整，是修正煮聚過程樹脂聚合產生的誤差"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"有關可撤式局部義齒金屬支架（metal framework）之鑄道設計，下列敘述何者錯誤？","options":["(A) 鑄道附著點應向外張開避免局部收縮（constriction）","(B) 鑄道成型器（sprue former）的位置和幾何形狀按鑄造用合金供應商建議而定","(C) 前後帶（anterior-posterior strap）適合用單一鑄道（single sprue）來製作","(D) 避免急轉彎鑄道及T形接頭"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-1-45","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"修磨上顎小臼齒四分之三牙冠（three-quarter crown）時，需注意的事項為何？①近遠心的鄰接面（proximal surface）需修磨開來以便製作單齒模（die） ②顏面邊緣（facial margin）不宜延伸到頰面 ③顏面邊緣的 設計與下顎小臼齒四分之三牙冠相同 ④顏面邊緣宜採用短斜面（short bevel）以保護牙釉質與美觀","options":["(A) ①③④","(B) ①②④","(C) ②③","(D) 僅①②"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"樹脂黏著牙橋（adhesion bridge）之支柱牙修形設計，會影響到抵抗脫落的能力，其理想的修形應環抱多少角 度以上？","options":["(A) 90°","(B) 120°","(C) 150°","(D) 180°"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-47","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"當支柱牙過短時，下列那種方法對增加固位力（retention）最沒有幫助？","options":["(A) 做出溝（groove）或箱（box）","(B) 減少牙齒修磨的厚度","(C) 減小錐形角度（taper）","(D) 完成線（finish line）延伸至牙齦溝內"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-1-48","subject":"ya5","topic":"咬合學基礎","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"有關髁關節型（ARCON type）咬合器之性質，下列敘述何者正確？","options":["(A) 屬於半調節型咬合器","(B) 其相對於機械之關節窩（glenoid fossa）位置，在咬合器之上顎構件上","(C) 在記錄前突記錄（protrusive record）時，正確度不足","(D) 髁軌徑（condylar path）之記錄較正確"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-49","subject":"ya5","topic":"牙科材料學","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"以polyvinyl siloxane印製牙冠模型時，下列敘述何者錯誤？","options":["(A) 材料成分本身會釋出氫氣，常導致石膏模型表面有小氣泡產生","(B) 材料成分常添加palladium可吸收氫氣，但最好仍需等15～30分鐘後才灌模","(C) 不可以戴著vinyl材質的手套混合putty，以免影響putty的聚合","(D) 材料成分常添加表面作用劑（surfactant），倒模時可減少氣泡的產生"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"關於圍箍效應（ferrule effect）的敘述，下列何者錯誤？","options":["(A) 可避免牙冠齒質嚴重受損的牙齒產生垂直斷裂（vertical fracture）","(B) 需要補綴物包圍牙冠邊緣（crown margin）1～2 mm高度的牙本質","(C) 以鑄造金屬根柱與冠心來圍箍牙根，有助牙周健康之維持","(D) 為了達到圍箍效應可能會侵犯到生物性寬度（biologic width），必須以強逼萌出（forced eruption）或是牙冠 增長術（crown lengthening）來解決問題"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-51","subject":"ya5","topic":"臨床基礎與倫理","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"下列何者不是牙根切除術（root resection）的適應症？","options":["(A) 增加根叉侵犯（furcation involvement）區域的清潔便利性","(B) 無法復形的牙根蛀牙","(C) 鄰近牙齒的牙根太接近","(D) 根叉（furcation）太接近根尖部"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-52","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"臨床上進行牙冠增長術（surgical crown lengthening）時，下列何項不是應考慮的因素？","options":["(A) 骨修整手術儘量在腭側或是舌側區域進行對美觀較不造成影響","(B) 牙齦的厚度越厚可能會導致手術後牙齦再度生長（regrowth），必要時在手術中要增加修磨的量","(C) 若需修磨骨質的量太多，會考慮合併矯正將牙齒拉出的治療","(D) 前牙區為避免手術後牙齦增生影響美觀，術後應儘快將贋復物完成"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"金屬瓷冠（metal-ceramic crown）的金屬支架設計應避免應力集中而導致瓷斷裂，其理想的金屬與瓷接合處 （interface）應呈幾度夾角？","options":["(A) 30°","(B) 60°","(C) 90°","(D) 120°"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"對於上顎前牙固定牙橋而言，何種橋體（pontic）的設計最合乎美觀的要求？","options":["(A) sanitary pontic","(B) modified ridge lap pontic","(C) saddle pontic","(D) ovate pontic"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"若固定牙橋45×47的金屬支架無法裝置到底時，以內部密合顯示劑（internal fitting agent）檢查金屬支架內 部，下列何種情況不適合將金屬支架切開重新銲接？","options":["(A) 內部密合顯示劑約有0.5～1 mm不均勻的厚度，但沒有顯示劑破掉的情形","(B) 內部密合顯示劑在45有破洞，但在47有約0.5 mm的厚度","(C) 45與47內部都有顯示劑破掉的情形","(D) 分別用手壓45或47有不同的顯示劑破掉情形"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-56","subject":"ya5","topic":"牙科材料學","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"下列何種牙科黏合劑，於硬化後最容易清除？","options":["(A) 玻璃離子體黏合劑（glass ionomer cement）","(B) 複合樹脂黏合劑（composite resin cement）","(C) 聚羧酸鋅黏合劑（zinc polycarboxylate cement）","(D) 磷酸鋅黏合劑（zinc phosphate cement）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-57","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"臨床上試戴牙冠時，下列敘述何者錯誤？","options":["(A) 臨床上常使用上蠟的牙線（waxed floss）來檢查proximal contact","(B) 試戴gold crown時，可使用burnisher或green polishing stone來改善60μm以下的margin opening","(C) 建議使用0.0005 inch shim stock來做咬合調整","(D) 金屬瓷牙冠之咬合點應距離金屬瓷界面1.0～1.5 mm以上"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-1-58","subject":"ya5","topic":"牙科材料學","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"暫時牙冠常因支柱牙需其他治療而僅以暫時黏合劑黏著，下列何者較適合做為暫時黏合劑使用？","options":["(A) 氧化鋅丁香油酚黏合劑（zinc oxide-eugenol cement）","(B) 磷酸鋅黏合劑（zinc phosphate cement）","(C) 玻璃離子體黏合劑（glass ionomer cement）","(D) 樹脂黏合劑（resin cement）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"為製作適當的上顎前牙補綴物，下列敘述何者錯誤？","options":["(A) 請病人發音，可以評估前牙的長度是否恰當","(B) Color Rendering Index 分為1～10十個等級，比色時用的光源最好是在scale 8以上","(C) 兩個物件在某一光源下看起來顏色相同，但在其他光源下看來顏色又不一樣，則此現象稱為metamerism","(D) 在比色時所採用的光線色溫最好在5000°K～6000°K"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-60","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"為了使牙齒比色的正確性更高，四周的牆壁最好是何種顏色？","options":["(A) 草綠色","(B) 灰白","(C) 淺藍灰","(D) 粉紅色"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-61","subject":"ya5","topic":"植牙贋復","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"下顎無牙患者，欲將人工植體種植於頦孔（mental foramen）之前，人工植體與頦孔之間的距離，至少應為多 少？","options":["(A) 1 mm","(B) 3 mm","(C) 5 mm","(D) 10 mm"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-62","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"在製作人工植體支持的固定牙橋時，何種印模材最為理想？","options":["(A) 藻膠（alginate）","(B) 縮合式矽膠（condensation silicone）","(C) 多硫體（polysulfide）","(D) 加成式矽膠（addition silicone）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-1-63","subject":"ya5","topic":"牙科材料學","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"下列關於無環式包埋法（ringless investment technique）的敘述，何者錯誤？","options":["(A) 需採用高強度的包埋材","(B) 包埋材多為磷酸鹽結合包埋材（phosphate-bonded investment）","(C) 膨脹量比採用鑄造環包埋法還大","(D) 適用於含金量高的貴金屬"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-1-64","subject":"ya5","topic":"牙科材料學","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"下列關於銲接（soldering）的敘述，何者錯誤？","options":["(A) 牙科使用的銲劑（solder）其熔點應低於將要進行銲接的合金約攝氏30°","(B) 最適當的銲接縫隙（soldering gap）應為0.2～0.25 mm，才能達到最理想的強度與準確性","(C) 依熔點大小排列，應為母金屬＞前銲用子金屬＞陶瓷＞後銲用子金屬","(D) 為防止銲接時銲劑不當的流動，可在表面塗上石墨（graphite）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-65","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"85歲吳奶奶前來求診，主訴為上顎多處缺牙，咀嚼功能不佳，有中風和糖尿病病史，並且行動不便。口內檢 查發現上顎剩餘牙齒為雙側側門牙及犬齒，下顎齒列完整，下列敘述何者錯誤？","options":["(A) 此為立即式植牙贋復（immediate placement and immediate loading）的適應症","(B) 可藉由咬合蠟堤的製作來評估咬合高度和咬合平面","(C) 可製作前牙六單位牙橋並搭配遠伸性可撤式局部活動義齒贋復","(D) 贋復物製作完成後應定期回診追蹤"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-66","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"承上題，要如何將病人上下顎的模型置位（mounting）到咬合器上，以進行診斷蠟型（diagnostic wax up）的 製作?","options":["(A) 可以用手依照任意的位置將模型置位到咬合器上，以進行診斷蠟型製作","(B) 上顎取面弓紀錄轉移（facebow transfer）後，使用參考模型製作紀錄基底（record base）並製作咬合蠟堤 （occlusal rim）以記錄病人的顎中心咬合（centric occlusion）","(C) 可以改變病人的髁導引角度（condylar guidance）","(D) 使用簡單型咬合器和半調節式咬合器進行診斷蠟型製作，並無差別"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-1-67","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"關於內翼肌（medial pterygoid muscle）與外翼肌（lateral pterygoid muscle）構造與功能的敘述，下列何者正 確？ ①內翼肌收縮造成下顎向上與向前移動 ②開顎運動與下（inferior）外翼肌收縮的關係較密切 ③上 （superior）外翼肌收縮與上下顎用力緊咬（power stroke）有關 ④只有上外翼肌，而非下外翼肌，附著於 髁（condyle）","options":["(A) 僅①④","(B) 僅②③④","(C) 僅①②③","(D) ①②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-1-68","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"以下何種感受器受到刺激，會引起閉顎反射（jaw-closing reflex）？","options":["(A) 肌梭（muscle spindles）","(B) 高爾基腱器（Golgi tendon organs）","(C) 巴氏小體（Pacinian corpuscles）","(D) 梅克氏小體（Meckel's corpuscles）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-109-1-69","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"下列有關咬力之敘述，何者正確？","options":["(A) 咬力大小不受磨牙（bruxism）因素之影響","(B) 咬力大小與面部形態無關","(C) 單顆牙之牙周被麻醉時，咬力會增大","(D) 咬力大小和嚼食食物之硬度無關"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-1-70","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"咬合面看下顎第一大臼齒的非中心咬頭尖（noncentric cusp tip）到其舌側外緣，佔總頰舌（buccolingual width）寬度比例為下列何者？","options":["(A) 1/6","(B) 1/5","(C) 1/4","(D) 1/3"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-71","subject":"ya5","topic":"咬合學基礎","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"理想情況下在作下顎之側向運動時，咬合導引應在何處？","options":["(A) 在功能側，而無平衡側的接觸","(B) 在功能側，而有平衡側的接觸","(C) 在門齒","(D) 在臼齒"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-72","subject":"ya5","topic":"咬合學基礎","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"對於上下牙齒間前後方向滑動的差異（anteroposterior direction of the slide）進行選擇性磨修（selective grinding）時，下列敘述何者正確？","options":["(A) 2到4 毫米（mm）滑動差異，可用選擇性磨修去除此差異","(B) 牙齒咬頭較高陡（tall and sharp）時，其前後滑動的差異以水平（horizontal）方向為主","(C) 牙齒咬頭較平（flat）的滑動差異，較容易利用選擇性磨修去除","(D) 垂直（vertical）方向的滑動差異越大，較容易利用選擇性磨修去除"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-1-73","subject":"ya5","topic":"咬合學基礎","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"根據Pösselt 1952年在波氏圖（Pösselt's diagram）的敘述，下列何者錯誤？","options":["(A) 正常人下顎運動中的側向與前突運動能執行的範圍大致接近約10mm","(B) 一般而言最大開口的程度約可達側向運動的5倍之多","(C) 下顎邊界運動（border movement）通常容易受頭部或身體位置變動的影響而改變","(D) 下顎邊界運動的軌跡可分別在額面觀（frontal view）、矢狀面觀（sagittal view）與水平面觀（horizontal view）重複取得"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-1-74","subject":"ya5","topic":"咬合學基礎","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"有關下顎運動咀嚼與吞嚥的敘述，下列何者正確？","options":["(A) 下顎的功能性運動如咀嚼，僅由反射動作為其調節機制","(B) 應幫病人將因咀嚼而造成的牙齒磨耗，回復到未磨耗之前的形態","(C) 處理較軟的食物時，咬頭高度和形態對咀嚼運動軌跡的影響不大","(D) 嬰兒式吞嚥（infantile swallowing）所使用的肌群主要是由三叉神經來支配"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"磨牙症會造成許多症狀，但以下何者不是磨牙症（bruxism）形成的後果？","options":["(A) 牙齒磨耗","(B) 牙周病","(C) 顏面肌僵硬","(D) 臉頰內側表面有壓痕"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"關於顳顎關節內部紊亂（internal derangement）的描述，下列何者正確？","options":["(A) 不會產生交互性關節彈響（reciprocal joint clicking）","(B) 夜間磨牙病患不會惡化關節內部紊亂","(C) 關節盤相對於髁頭可能產生前方或是前內方的移位（displaced）","(D) 關節盤的內側破壞會比外側為嚴重"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"關於上顎穩定型咬合板（stabilization splint）的敘述，下列何者正確？①在咬合板上中心關係（centric relation）的接觸點通常位於習慣性閉合（habitual closure）接觸點的前方0.5~1.0 mm 處 ②對於有嚴重水平 覆蓋（overjet）者，上顎覆蓋較易製作 ③咬合板的固位力（retention）來自於頰側 ④當下顎做側方移動 （laterotrusive movement）時，前後牙多均勻接觸","options":["(A) 僅①③","(B) 僅②③","(C) ②④","(D) ①②③"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"當髁頭－關節盤錯位症（condyle-disc derangement disorders）必須進行較侵略性的治療時，下列何種處置應首 先考慮，以減少手術傷害？","options":["(A) 關節穿刺術（arthrocentesis）","(B) 關節鏡（arthroscopy）","(C) 關節盤褶疊術（discal plication）","(D) 關節盤修補（discal repair）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"進行顳顎關節攝影時，如果射線與關節髁頭（condyle）之夾角如下，最可能獲得以下何種影像？","options":["(A)","(B)","(C)","(D)"],"answer":1,"image":"ya5-109-1-79.jpeg","clinical_level":"一般"},{"id":"ya5-109-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"承上題，此種攝影術的名稱？又再考慮與顱骨的可能重疊效應後，它最能清楚呈現的部位為何？","options":["(A) 側穿顱攝影（lateral transcranial projection）；顳顎關節髁頭（TMJ condyle）之外極（lateral pole）","(B) 側穿顱攝影（lateral transcranial projection）；顳顎關節髁頭（TMJ condyle）之內極（medial pole）","(C) 環口顎攝影（panoramic projection）；顳顎關節髁頭（TMJ condyle）之外極（lateral pole）","(D) 環口顎攝影（panoramic projection）；顳顎關節髁頭（TMJ condyle）之內極（medial pole）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-1","subject":"ya5","topic":"臨床基礎與倫理","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"關於造成唾液分泌功能不佳的敘述，下列何者錯誤？","options":["(A) 年紀大的患者，唾液分泌量會減少","(B) 造成乾口症（xerostomia）的最主要原因是頭頸部放射線治療與自體免疫","(C) 副交感神經藥物（parasympathetic drugs）並不會影響唾液分泌","(D) 謝格連氏症候群（Sjögren’s syndrome）的患者，其唾液腺會被淋巴細胞侵犯而減少唾液分泌"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"下列何者最不會造成乾口症（xerostomia）？","options":["(A) 糖尿病（diabetes）","(B) 停經（menopause）","(C) 維他命A缺乏（vitamin A deficiency）","(D) B型肝炎感染（hepatitis B infection）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-3","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"有關全口無牙患者診斷用模型（diagnostic cast）的敘述，下列何者正確？","options":["(A) 有助於決定全口義齒基底的覆蓋範圍","(B) 由於沒有牙齒存在，診斷用模型的應用價值不高","(C) 不須上咬合器，即可藉以判斷上下顎間關係","(D) 在診斷用模型的階段，不須呈現義齒的主要壓力承受區"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-4","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"下顎全口義齒邊緣若過度延伸（overextension），下列何者最有可能造成病患吞嚥時的疼痛？①腭舌肌 （palatoglossus muscle） ②下顎舌骨肌（mylohyoid muscle） ③莖突咽頭肌（stylopharyngeal muscle） ④ 上縮肌（superior constrictor muscle）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"會影響下顎義齒顎舌骨肌後窩（retromylohyoid fossa）邊界的肌肉，下列何者正確？①下顎舌骨肌（mylohyoid muscle） ②腭舌肌（palatoglossus muscle） ③上縮肌（superior constrictor muscle）","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"下列何者為全口義齒最終印模（final impression）不須緩壓（relief）的區域？","options":["(A) 正中腭縫線（median palatal raphe）","(B) 下顎臼齒後墊（mandibular retromolar pad）","(C) 舌骨肌後嵴（retromylohyoid ridge）","(D) 上顎隆凸（maxillary torus）"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"關於全口義齒之製作，口輪匝肌（orbicularis oris muscle）與下列何者無直接關係？","options":["(A) 上下顎義齒唇側緣的厚薄","(B) 前牙排列位置","(C) 垂直高度高低","(D) 中心關係正確與否"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"配戴全口義齒的病人，下顎於坐姿休憩位置時，上下顎義齒間距若大於 4 mm 時，最可能導致下列何種結果？","options":["(A) 咬合垂直高度太低","(B) 吞嚥困難","(C) 臉部皺紋減少","(D) 影響發音"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-9","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"全口無牙患者在試戴義齒測試發音時，下列敘述何者錯誤？","options":["(A) 觀察患者發舌齒音（linguodental sounds）例如th時，舌尖露出上下前牙間隙的量，可檢查前牙位置","(B) 觀察患者發舌嵴音（linguoalveolar sounds）例如t，d時，由舌頭碰觸前牙舌側的情況，可檢查前牙位置","(C) 觀察患者發唇齒音（labiodental sounds）例如f，v時，上顎門齒與下唇的接觸位置，可檢查上顎門齒的長短","(D) 觀察患者發雙唇音（bilabial sounds）例如p，b時，由雙唇緊閉時的口內負壓，可檢查義齒腭部基底的形態"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"下列何種排牙方式，會降低全口義齒的穩定性？","options":["(A) 選用近遠心距離較小的牙齒","(B) 下顎選用頰舌側寬度較窄的牙齒","(C) 不能超過下顎舌骨嵴（mylohyoid ridge）垂直線","(D) 下顎第一小臼齒的排列應該比自然牙偏舌側"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-11","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"全口義齒製作第二大臼齒斜坡（second molar ramp）的目的為何？","options":["(A) 穩定垂直高度（vertical dimension）","(B) 形成克里斯坦森現象（Christensen phenomenon）","(C) 提高咀嚼效能（mastication efficiency）","(D) 提供平衡咬合（balanced occlusion）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"全口義齒前牙位置最主要為影響下列何者的支撐？","options":["(A) 咬肌（masseter muscle）","(B) 笑肌（risorius muscle）","(C) 頦肌（mentalis muscle）","(D) 口輪匝肌（orbicularis oris muscle）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"若考慮患者之美觀及發音，形成的門齒導引（incisal guidance）較陡時，為達到全口義齒的平衡咬合，下列何 者錯誤？","options":["(A) 門齒導引（incisal guidance）角度較大時，不利於全口義齒的穩定","(B) 選擇咬頭傾斜度（cusp inclination）較大的解剖形態牙齒","(C) 減少矢狀面咬合平面（sagittal occlusal plane）的傾斜度","(D) 增加前後方向的補償曲線（compensating curve）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"上顎全口義齒對咬下顎的植體固持覆蓋式義齒（implant-retained overdenture）時，最好的咬合模式應為下列 何種？","options":["(A) 雙側平衡咬合（bilaterally balanced occlusion）","(B) 單側平衡咬合（unilaterally balanced occlusion）","(C) 相互保護咬合（mutually protected occlusion）","(D) 群體功能咬合（group function occlusion）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-15","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"全口義齒完成後的臨床裝置程序中，需要調整製作過程中所產生的咬合誤差，下列敘述何者錯誤？","options":["(A) 在中心關係（centric relation）位置時，須調整到所有牙齒都均勻一致的接觸","(B) 側方移動時，牙齒的工作側接觸，必須調整上顎牙齒的頰側咬頭與下顎牙齒的舌側咬頭，使之均勻接觸","(C) 側方移動時，牙齒的平衡側接觸，必須調整下顎牙齒的頰側咬頭的舌側斜面，使之均勻接觸","(D) 可以調整上顎牙齒的近心面，以及下顎牙齒的遠心面，以達到直線前突運動時的均勻接觸"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-16","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"關於使用組織調理材（tissue-conditioning materials）進行功能性印模的敘述，下列何者錯誤？","options":["(A) 此材料會先經過塑化期（plastic stage）再到彈性期（elastic stage）","(B) 在塑化期（plastic stage）時，此材料可以配合咬合壓力，使義齒基底更密貼組織","(C) 在彈性期（elastic stage）時，此材料已經硬化成類似聚合樹脂的表面，此階段約需要10～14天","(D) 為了使組織調理材料如軟底墊（soft liner）維持在良好的狀態，每2～5星期更換新材料是必要的"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"關於即裝全口義齒（immediate complete denture）的製作，因過程中有難以控制的因素，術前必須對患者詳細 解釋。下列敘述何者錯誤？","options":["(A) 無法前牙試戴（anterior try-in），故前牙之美觀較無法預測","(B) 拔牙後立即裝戴義齒，因傷口尚未癒合，不可長時間使用義齒，以免干擾齒槽骨之重塑（remodeling）","(C) 義齒因齒槽骨漸吸收而穩定性會漸差，故可能幾個月後義齒便需要換底（relining）","(D) 比起傳統全口義齒之製作，即裝全口義齒之治療次數較多，且整體費用也會較高"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-109-2-18","subject":"ya5","topic":"植牙贋復","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"患者於完成植體支持式固定義齒治療後，抱怨發音問題，下列敘述何者錯誤？","options":["(A) 此現象常見於上顎齒列的重建","(B) 較困難之發音為s、f、v","(C) 發音的適應較植體覆蓋式義齒需時較久","(D) 一般來說，三到六個月後，大部分患者可達成發音適應"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-19","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"下列何者是在進行邊緣成型（border molding）時，達成咽腭帆關閉（velopharyngeal sealing）最重要的運動？","options":["(A) 吞嚥","(B) 頭部後仰","(C) 深呼吸","(D) 下顎左右來回動"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-20","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"有關上顎全口義齒製作中後腭封（posterior palatal seal）之敘述，下列何者正確？","options":["(A) 位於振動線（vibrating line）之前，在上顎軟組織上形成壓跡，以提供上顎義齒完整之邊緣封閉","(B) 金屬義齒床（metal denture base）可不用刻意形成後腭封","(C) 只能於臨床上取得後腭封位置，之後於主模型（master cast）上刻出凹陷，而無法於主模型（master cast）印 模時取得","(D) 因上顎義齒後緣加厚，致舌頭有較明顯之異物感"],"answer":0,"clinical_level":"重點"},{"id":"ya5-109-2-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"全口義齒包埋時塗佈分離劑的原則，下列敘述何者錯誤？","options":["(A) 人工牙的底部不能塗分離劑","(B) 塗佈分離劑時機為包埋盒（flask）乾燥並降至室溫時","(C) 義齒的組織面只須塗一層分離劑","(D) 義齒的磨光面可塗 2 至 3 層分離劑"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-22","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"對於全口無牙狀況的敘述，下列何者正確？①為一種社會經濟（socioeconomic）現象 ②為疾病後的生物 （biological）結果 ③聚乙醚印模（polyether impression）應浸泡於戊二醛（glutaraldehyde）消毒溶液中至少 10分鐘以控制感染 ④植體覆蓋式義齒（implant overdenture）無法改善下顎義齒的穩定性","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"有關下顎可撤式局部義齒主連接體（major connector）的敘述，下列何者錯誤？","options":["(A) 舌側槓（lingual bar）是臨床上比較常用的設計，橫切面呈現半梨形（half-pear shaped）","(B) 舌側板（lingual plate）適用於舌側牙齦邊緣與口底距離8 mm以下的患者","(C) 舌側板與雙舌側槓（double lingual bar）常延伸至兩側最遠心牙齒之遠心咬窩放置鈎靠，提供遠心端缺牙之 可撤式局部義齒間接固位作用","(D) 唇側槓（labial bar）常用於下顎前牙往舌側嚴重傾斜或舌側有骨性隆凸（torus）的患者"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya5-109-2-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"有關可撤式局部義齒主連接體（major connector）單腭帶（single palatal strap）的敘述，下列何者正確？①厚 度至少須有4 mm ②前、後緣與正中腭縫（median palatine suture）之交角須接近90度 ③適用於牙齒支持的 義齒（tooth-supported restoration） ④約需有兩顆大臼齒近-遠心距的寬度","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"關於可撤式局部義齒鈎靠（rest）的敘述，下列何者錯誤？","options":["(A) 提供支持（support）是最主要的功能","(B) 使可撤式局部義齒受力沿牙齒長軸方向","(C) 作為間接固位體（indirect retainer）","(D) 鈎座（rest seat）應放在汞齊充填（amalgam filling）上"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-26","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"對於牙齒支持（tooth-supported）型可撤式局部義齒的敘述，下列何者錯誤？","options":["(A) 固位裝置經常使用鍛製金屬線牙鈎（wrought wire clasp）","(B) 殘嵴的印模通常不需要使用功能性印模方式（functional impression）","(C) 金屬支架設計通常不須間接固位裝置（indirect retainer）","(D) 大部分可用現有牙齒的對咬來決定上下顎間的咬合關係"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-27","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"可撤式局部義齒製作時，對於垂直上下顎空間（intermaxillary distance）較不足的病例，其義齒床的小連結體 （minor connector）選擇為何？","options":["(A) 格子狀（open lattice）","(B) 網狀（mesh）","(C) Ｖ字形","(D) 圓形"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-28","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"在設計可撤式局部義齒牙鈎時，需要考量固位牙鈎臂之可彎曲性，下列敘述何者錯誤？","options":["(A) 愈具可彎曲性的固位牙鈎臂傳遞至支柱牙的力量愈低","(B) 較具可彎曲性的固位牙鈎臂對殘嵴產生較小的傷害","(C) 牙周狀況較好的支柱牙可以選擇可彎曲性較小的固位牙鈎臂","(D) 牙周狀況較差的支柱牙可以選擇鍛製金屬線固位牙鈎臂"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"影響可撤式局部義齒作用力傳遞到支柱牙（abutment）的情況，下列敘述何者錯誤？","options":["(A) 遠伸性義齒基底（denture base）愈長，傳遞到支柱牙的作用力愈小","(B) 牙嵴黏膜（mucosa of ridge）厚度與健康狀態","(C) 義齒戴入與取出時，鈷鉻合金牙鈎較金合金牙鈎，會對支柱牙產生較大的作用力","(D) 固位性牙鈎（retentive clasp）愈長愈具可彎曲性，其支柱牙承受的作用力愈低"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"對於RPI的敘述，下列何者正確？①I型槓（I-bar）接觸支柱牙（abutment）上下距離至少為3 mm ②鈎靠 （rest）必須放置於支柱牙近心咬合面（mesial occlusal） ③遠端引導面（distal guiding plane）修磨從支柱牙 中段1/3與咬合1/3交界（junction of middle third and occlusal third）向下延伸到中段1/3與齒頸1/3交界（junction of middle third and cervical third） ④連結近心咬合鈎靠（mesial occlusal rest） 的小連接體（minor connector）向咬合面延伸通過支柱牙與其臨接牙隙縫，但是小連接體不可接觸到臨接牙","options":["(A) ①②","(B) ②③","(C) ②④","(D) ③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-31","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"有關可撤式局部義齒的設計，下列敘述何者錯誤？","options":["(A) 不應施加超過支柱牙生理上所能容忍的壓力","(B) 缺前牙的贋復，其固位牙鈎應置於近心牙齦區","(C) 可以抵抗義齒脫出之力量","(D) 使病人容易置入及取出義齒"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-109-2-32","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"有關可撤式局部義齒咬合鈎座（occlusal rest seat）的修磨，下列敘述何者正確？①頂端為圓三角形（rounded triangle），指向支柱牙咬合中心 ②在邊緣嵴（marginal ridge）上頰-舌方向至少3.5 mm長 ③在邊緣嵴 （marginal ridge）上咬合-齒頸方向至少2.0 mm深 ④咬合鈎靠與垂直小連接體（minor connector）形成的夾 角必須小於90度","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-2-33","subject":"ya5","topic":"臨床基礎與倫理","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"關於印模時避免患者嘔吐的方法，下列何者錯誤？","options":["(A) 取模時讓患者採坐姿","(B) 印模前先用冷水漱口","(C) 使用麻醉噴劑","(D) 放置牙托時，由後方先置入"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-34","subject":"ya5","topic":"咬合學基礎","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"有關以面弓轉移（facebow transfer）將石膏模型定位到咬合器上的原理，下列敘述何者錯誤？","options":["(A) 面弓是用來轉移上顎牙弓位置至咬合器","(B) 常見面弓轉移若以眼眶下緣為第三參考點，則建立的平面與法蘭克福平面（Frankfort plane）平行","(C) 最準確的面弓轉移方法是先決定患者的真樞紐軸（true hinge axis），超過90%的患者可使用這種方法","(D) 如Hanau等的半調節咬合器，放置面弓前，髁導引（condyle guidance）應先設定為30度，而側方導引設為15 度"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"下列4項修正模型技術（Altered cast technique）的操作步驟，其操作的先後順序為何？①試戴金屬架 ②製作 無牙嵴的牙托 ③邊緣塑型和印模 ④重新灌模","options":["(A) ②①③④","(B) ①②③④","(C) ②③④①","(D) ③④②①"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-2-36","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"下列何者是可撤式局部義齒之頰側基底延伸不足的缺點？①容易卡入食物 ②臉頰支撐度不足（inadequate facial contour） ③固位性不良，易鬆脫","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-37","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"下列何者不會影響遠伸性可撤式局部義齒之支持（support）？","options":["(A) 義齒基底之密合度","(B) 殘嵴之外形及品質","(C) 無牙區齒嵴印模的精確度","(D) 支柱牙之牙齦健康狀況"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"下列何者並非可撤式局部義齒咬合無法正確建立，並維持穩定的原因？","options":["(A) 義齒基底下的支持不足","(B) 只考慮了上下顎靜態的關係","(C) 不正確的咬合平面","(D) 使用咬頭角度過小的人工牙齒"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"若要進行記錄咬合軌跡（occlusal pathways）之方式，記錄可撤式局部義齒上下對咬關係，患者至少須配戴以 嵌體蠟（inlay wax）製作蠟堤之義齒基底多少小時？","options":["(A) 4","(B) 8","(C) 12","(D) 24"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"甘迺迪第三類（Kennedy Class III）可撤式局部義齒置換底墊（reline）的敘述，下列何者正確？①可重新建立 缺牙牙嵴組織對義齒基底的支持（support） ②印模時可選用閉口取模技術（closed-mouth impression method） ③印模時可選用張口取模技術（open-mouth impression method）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"遠伸性可撤式局部義齒換底墊（reline）時，有閉口換底法（closed-mouth reline）和開口換底法（open-mouth reline）兩種方式。選用方式之取決主要考量為何？","options":["(A) 殘嵴軟組織的黏膜回彈性","(B) 張口度的大小","(C) 殘嵴之長度","(D) 殘嵴之吸收程度"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"製作可撤式局部義齒過程中，有關蠟形的包埋與鑄造，下列敘述何者錯誤？","options":["(A) 包埋第一層先以毛刷塗3～4 mm厚的包埋材於蠟型上，以減少氣泡產生","(B) 去蠟處理時一定要遵循廠商指示進行，以得到熱脹冷縮的互補效果","(C) 製作局部義齒用的合金鑄造一般使用敏感度較高的感應式鑄造儀器","(D) 去除金屬牙架大部分包埋材後，組織面之殘留包埋材可使用氧化鋁噴砂處理"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"下列何者不是可撤式局部義齒主模型需要緩壓（relief）處理的區域？","options":["(A) 舌側槓（lingual bar）連接體下面","(B) 下顎隆凸（torus）","(C) 突起的上顎正中腭縫線（palatal raphes）","(D) 大而明顯的上顎粗隆（maxillary tuberosity）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"製作可撤式局部義齒時，完成耐火模型上義齒支架蠟型後，有關鑄道（sprue）成型處理時須注意的事項，下 列敘述何者錯誤？","options":["(A) 鑄道的方向與支架蠟形應避免垂直的接觸關係","(B) 第四類金合金和鈷鉻合金使用單一主鑄道連接蠟型","(C) 鑄道成型須均勻，由大至小不可有中間變窄現象","(D) 輔助性鑄道是為確保金屬能快速達到遠端部位的設計"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-45","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"有關部分鑲面牙冠（partial veneer crown）適應症的敘述，下列何者正確？①可用為後牙固定義齒的固位體 （retainer） ②可用為前牙固定裝置（splint）的固位體 ③適合根管治療後的前牙贋復 ④適合根管治療後 頰側咬頭缺損的後牙贋復","options":["(A) ①②","(B) ③④","(C) ②③","(D) ①④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"有關上顎前牙固定贋復體（fixed prosthesis）邊緣設計（margin design）適用情況的敘述，下列何者最正確？","options":["(A) 弧形緣（chamfer margin）用於金屬瓷冠（metal-ceramic crown）的頰側邊緣（buccal margin）","(B) 斜邊緣 （beveled margin）用於金屬瓷冠（metal-ceramic crown）的頰側邊緣（buccal margin）","(C) 斜面肩台緣（beveled shoulder margin）用於全瓷冠（complete ceramic crown）的舌側邊緣（lingual margin）","(D) 傾斜肩台緣（sloped shoulder margin）用於金屬瓷冠（metal ceramic crown）的頰側邊緣（buccal margin）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-47","subject":"ya5","topic":"咬合學基礎","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"下列關於離中心咬合紀錄（eccentric checkbite）的敘述，那些正確？①屬於動態紀錄的一種 ②僅用於設定 全調節咬合器 ③包括一個前伸（protrusive）咬合及兩個側方（lateral）咬合紀錄 ④前伸咬合紀錄用於調整 咬合器的門齒導引板（incisor guide table） ⑤側方咬合紀錄用於調整咬合器的側移（side shift）","options":["(A) ①②③④","(B) ①②⑤","(C) ④⑤","(D) ③⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-48","subject":"ya5","topic":"牙科材料學","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"下列那一種消毒液適用於聚乙醚（polyether）印模材之消毒？","options":["(A) iodophors","(B) phenolics","(C) chlorine compound","(D) 2% glutaraldehyde"],"answer":[0,2],"clinical_level":"重點","explanation_pending":false},{"id":"ya5-109-2-49","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"關於根管治療後根柱（post）的製作，從根尖起算，根管內剩餘的封填材料至少需要多少mm？","options":["(A) 1～2","(B) 3～4","(C) 5～6","(D) 7～8"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"修復根管治療後的牙齒時，下列何者是影響預後最重要的因素？","options":["(A) 牙根長短","(B) 牙根直徑","(C) 牙冠齒質的剩餘量","(D) 牙齒的牙位"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-51","subject":"ya5","topic":"臨床基礎與倫理","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"有學者（Spear & Clooney）指出，齒間楔隙（interproximal embrasure）的形態受到相鄰牙齒距離的影響，下 列敘述何者錯誤？","options":["(A) 當楔隙過寬時，乳突會變平坦，形成較淺的牙齦溝","(B) 當楔隙在理想寬度下，會形成3.5～4.0 mm牙齦溝，但牙間峽（col）仍然維持健康狀態","(C) 當楔隙過窄時，乳突會向頰側和舌側突出，並出現發炎狀態","(D) 利用矯正治療使相鄰牙根平行，可以改善鄰接關係及乳突形態"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-52","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"製作局部可撤式義齒之固位體（retainer）時，其咬合面鈎靠（occlusal rest）部位，金屬厚度至少須多少mm ？","options":["(A) 0.5","(B) 1.0","(C) 1.5","(D) 2.0"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"有關金屬瓷冠在金屬瓷交界處（metal-ceramic junction）的設計，下列何者錯誤？","options":["(A) 需距離中心咬合點1～1.5 mm以上","(B) 不可置放於鄰接面接觸點（proximal contact）處","(C) 由斷面型態上來看，金屬與瓷相接處最好是方形接合（butt joint）","(D) 在上顎前牙舌側若使對咬牙與瓷接觸，咬合調整較為容易"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-2-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"一般而言，全瓷牙冠（all ceramic crowns）相較於金屬瓷牙冠（metal-ceramic crowns）的缺點有下列那些項 目？①全瓷牙冠的強度較差 ②全瓷牙冠需要較精細的技工技術來達到適當的邊緣密合度 ③全瓷牙冠較不 美觀","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"前牙金屬瓷修復體（metal-ceramic restorations）在烤瓷過程中，於切緣處通常會收縮多少mm？","options":["(A) 0.2","(B) 0.6","(C) 1.0","(D) 1.4"],"answer":1,"clinical_level":"重點(深度)"},{"id":"ya5-109-2-56","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"使用醋酸纖維素（cellulose acetate）的預製牙冠外殼（preformed crown form）製作暫用性牙冠（interim crown）的敘述，下列何者正確？","options":["(A) 醋酸纖維素材質會影響完成後暫用牙冠的色調（shade）","(B) 使用的自聚樹脂與醋酸纖維素形成化學鍵結（chemical bond）","(C) 使用的自聚樹脂與醋酸纖維素形成機械式鍵結（mechanical bond）","(D) 需要加樹脂來重建暫用牙冠之鄰間接觸（proximal contact）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-57","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"有關金屬瓷冠設計瓷厚度之敘述，下列何者錯誤？","options":["(A) 若瓷厚度大於2 mm ，則瓷容易破裂","(B) 應先將完整解剖構造的蠟型堆出來，再做回削（cutback）以避免瓷的厚度不均","(C) 在瓷金屬界面的瓷厚度最少要0.5 mm","(D) 在講究美觀的區域瓷厚度最少要0.7 mm"],"answer":[2,3],"clinical_level":"重點","explanation_pending":false},{"id":"ya5-109-2-58","subject":"ya5","topic":"植牙贋復","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"當患者的牙弓遠心端（distal extension）有多顆缺牙，欲使用植體做贋復時，下列何種情況應考慮增加植體之 數量？","options":["(A) 對咬為全口義齒","(B) crown-to-implant ratio較大時","(C) 對咬同為遠心端的局部可撤式義齒","(D) 植牙區垂直贋復空間小"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-59","subject":"ya5","topic":"植牙贋復","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"後牙區implant-supported固定牙橋出現瓷破裂之最可能原因為何？","options":["(A) metal framework支撐不足","(B) 植體角度過大","(C) 過大的screw preload","(D) 植體長度不足"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-60","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"關於三單位固定牙橋使用鄰接面半冠（proximal half crown）設計的說明，下列何者錯誤？","options":["(A) 用於向舌側嚴重傾斜的遠心端支柱牙","(B) 保留遠心端支柱牙的遠心鄰接面","(C) 不建議用於遠心端支柱牙與遠心鄰牙間邊緣脊（marginal ridge）有落差的情況","(D) 咬合面需有溝槽（channel）連接頰側與舌側溝（groove），避免遠心咬合面邊緣變形"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"在支柱牙牙周狀況良好且齒質結構完整的情況下，下列那顆牙齒缺失，使用三單位牙橋重建有最大風險？","options":["(A) 上顎犬齒","(B) 上顎第一小臼齒","(C) 上顎側門牙","(D) 下顎第一小臼齒"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-62","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"鑄造牙冠於口內試戴時，若未能完全戴入，下列何者非其原因？","options":["(A) 製作過程形成鑄造牙冠之收縮","(B) 與鄰牙之接觸過緊","(C) 牙冠內部有小結（nodules）","(D) 工作模型置位（mounting）於咬合器時，咬合關係有誤"],"answer":3,"clinical_level":"重點"},{"id":"ya5-109-2-63","subject":"ya5","topic":"牙科材料學","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"石膏結合包埋粉（gypsum-bonded investment）加熱時，最高不可超過攝氏幾度？","options":["(A) 400","(B) 650","(C) 900","(D) 1150"],"answer":1,"clinical_level":"重點"},{"id":"ya5-109-2-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"裝戴牙冠時，尖銳的探針尖端可以插進牙冠和牙齒之間時，通常表示兩者之間的縫隙大於多少µm？","options":["(A) 15","(B) 25","(C) 35","(D) 50"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-65","subject":"ya5","topic":"牙科材料學","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"聚羧酸鹽黏合劑（polycarboxylate cement）對牙髓的刺激性較低，下列何者是最主要的原因？","options":["(A) pH值小於4","(B) 聚丙烯酸（polyacrylic acid）分子較大","(C) 抗壓強度（compressive strength）較高","(D) pH值接近7"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-66","subject":"ya5","topic":"牙科材料學","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"下列何種成分可幫助樹脂黏合劑（resin luting cement）與牙齒之鍵結（bonding）？","options":["(A) EBA（ethoxybenzoic acid）","(B) HEMA（hydroxyethyl methacrylate）","(C) ZOE（zinc oxide-eugenol）","(D) 5-META（5-methacryloxyethyl trimellitic anhydride）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-67","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"關於正常顳顎關節於開閉口時的敘述，下列何者正確？","options":["(A) 下顎開口由下方部分的旋轉絞鏈運動（rotation），及上方部分的髁位移（translation）組成","(B) 閉口時，關節盤的中間帶位於關節髁頭的正上方","(C) 下顎閉合時，髁旋轉且移向後方及下方","(D) 緊咬時，內翼肌的上頭有活動，故其和TMJ的穩定有關"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-68","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"關於異常功能（parafunction）的敘述，下列何者正確？①相較於正常功能（如咀嚼）以下顎垂直方向運動為 主，異常功能（如磨牙）常見下顎水平方向移動 ②下顎較常往離中心位置移動 ③白天牙齒緊咬時，咀嚼 肌較常見等長（isometric）運動","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-109-2-69","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"肌肉收縮時，偵測肌肉張力的主要感受器為下列何者？","options":["(A) 肌梭（muscle spindles）","(B) 高爾基腱器（Golgi tendon organs）","(C) 巴氏小體（Pacinian corpuscles）","(D) 梅克氏小體（ Meckel's corpuscles）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-70","subject":"ya5","topic":"咬合學基礎","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"安格式第一類臼齒關係（Angle's class I molar relationship）牙齒相對位置，下列何者正確？","options":["(A) 下顎第一大臼齒遠心頰側咬頭對咬於上顎第一大臼齒與第二小臼齒之間的楔隙（embrasure）","(B) 上顎第一大臼齒遠心頰側咬頭對齊下顎第一大臼齒的頰溝（buccal groove）","(C) 上顎第一大臼齒近心舌側咬頭對咬於下顎第一大臼齒中心窩（central fossa）","(D) 下顎第一大臼齒近心頰側咬頭對齊上顎第一大臼齒的頰溝（buccal groove）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-71","subject":"ya5","topic":"咬合學基礎","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"當引導病人下顎進入中心關係（centric relation）位置後，再使其緊咬時，下顎會滑入中心咬合（centric occlusion）位置，所以在二者之間可記錄到一段很短的距離，這個短距離的滑動稱為中心內滑動（slide in centric），這個滑動通常包含下列何者？","options":["(A) 向前、側方及上下的運動","(B) 向後、側方及上下的運動","(C) 僅向後及側方的運動","(D) 僅向前及向後的運動"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-72","subject":"ya5","topic":"咬合學基礎","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"在自然齒列中，製作後牙補綴物時應有的正確觀念為何？①下顎做前突運動時，下顎的後牙補綴物不應接 觸 ②下顎做前突運動時，若咬合平面與關節隆突所形成的夾角越小時，後牙補綴物的咬頭高度應越低 ③ 關節隆突角度越大時，後牙補綴物的咬頭高度應越低，而上顎前牙的舌側隆突可越大","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-73","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"關於「哥德弓描軌記錄（Gothic arch tracing）」的敘述，下列何者錯誤？","options":["(A) 可分為口內與口外兩種描繪裝置","(B) 描軌記錄的尖端位置為中心關係（centric relation）","(C) 重複取得性與方便性皆比下巴點導引（chin point）或雙手導引法（bimanual manipulation）更好","(D) 口內描繪裝置可以將導引針設在下顎，導引板固定在上顎"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-2-74","subject":"ya5","topic":"咬合學基礎","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"當本奈氏運動（Bennett movement）發生時，平衡側髁頭之運動方向為何？","options":["(A) 向前、向下、向內","(B) 向外、向上","(C) 向前、向外","(D) 向外側移"],"answer":0,"clinical_level":"一般"},{"id":"ya5-109-2-75","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"當顳顎關節有彈響（click）聲，可能病因為何？①關節盤移位（disc displacement） ②重塑 （remodeling） ③肌源性（myogenic type） ④關節表面不平滑","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-109-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"下列關於肌源性疼痛的敘述，何者錯誤？","options":["(A) 肌肉夾護（muscle splinting）的發生，在行保護性的反射以限制疼痛部位的運動","(B) 受傷組織局部釋出的發炎物質（pain mediator），可能造成肌壓痛（muscle tenderness）現象","(C) 疼痛的肌肉於咀嚼時的肌電圖（EMG）活性會提高","(D) 咀嚼肌肉疼痛也會使下顎運動受限"],"answer":2,"clinical_level":"重點"},{"id":"ya5-109-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"顳顎障礙症與義齒贋復治療的關係，下列敘述何者錯誤？","options":["(A) 短牙弓（short dental arch）已被接受為贋復治療的模式之一，多重後牙的缺失可能只是危險因子，而非病因","(B) 顳顎障礙症雖因處理不穩定的咬合型態而獲得改善，因此延續穩定咬合的贋復治療可避免顳顎障礙之復發","(C) 義齒贋復治療屬於第二階段、非可逆的治療，通常是非優先採取的考量","(D) 全口齒列在適當的垂直高度下，兩側、同時穩定的接觸在最大嵌合處（MI），是型態穩定的必須條件"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"下列何者不是顳顎關節障礙症（temporomandibular joint disorders）之症狀療法（symptomatic treatment）？","options":["(A) 咬合板","(B) 齒顎矯正治療","(C) 藥物治療","(D) 冷、熱敷"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"對顳顎障礙症施行之物理治療的敘述，下列何者正確？①熱療（thermotherapy）有減輕疼痛的效果 ②冷卻 劑治療（coolant therapy）可使痙攣（spasm）的肌肉放鬆 ③冰敷至少持續15分鐘才會出現療效 ④關節鬆 動術（joint mobilization）可用於急性不可復性關節盤移位（disc displacement without reduction）","options":["(A) 僅②③","(B) 僅①②④","(C) 僅①③④","(D) ①②③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-109-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"以貫顱投影法（transcranial projection）拍攝顳顎關節，關於髁頭位置的敘述，下列何者正確？①看到的關節 間隙（joint space）為髁頭上緣處的關節間隙 ②後關節間隙（posterior joint space）較小，可能與肌肉障礙 （muscle disorders）有關 ③髁頭外極（lateral pole）的型態影響關節間隙大小 ④放射線投射（projection） 角度影響關節間隙大小","options":["(A) ①②","(B) 僅③④","(C) 僅①④","(D) ①③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-1","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"上顎頰繫帶（buccal frenum）於功能時，其移動方向為何？","options":["(A) 向前","(B) 向後","(C) 向上","(D) 向下"],"answer":[0,1],"clinical_level":"一般","explanation_pending":false},{"id":"ya5-110-1-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"可能造成口腔灼感症候群（burning mouth syndrome）的系統性病因，下列何者正確？①維他命缺乏 （vitamin deficiency） ②缺鐵性貧血（iron deficiency anemia） ③黴菌感染（candidiasis） ④糖尿病 （diabetes）","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"以下關於臼齒後墊（retromolar pad）的敘述，何者錯誤？","options":["(A) 下顎全口義齒需將其完全包覆","(B) 其黏膜下層（submucosa）包含部分肌肉纖維","(C) 為決定下顎全口義齒咬合平面（occlusal plane）的參考點之一","(D) 一般下顎第一大臼齒的咬合高度約在臼齒後墊的三分之二處"],"answer":0,"clinical_level":"重點"},{"id":"ya5-110-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"舌之功能性運動（functional movement of tongue）可輔助下顎全口義齒最終印模之邊界界定，下列敘述何者正 確？","options":["(A) 舌前突時，舌尖應該舔到下嘴唇","(B) 舌前突時，舌尖應該越過下嘴唇約0.5 cm","(C) 舌前突時，舌尖應該越過下嘴唇約1.5 cm","(D) 印模時，舌應儘量往前突"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"進行上顎全口義齒後頰側邊緣成形（posterior lateral border molding）時，應引導病人做何種動作？","options":["(A) 嘟嘴（pucker）","(B) 張大嘴（open wide）","(C) 吞嚥（swallowing）","(D) 下顎左右運動（move the mandible right and left）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-6","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"下顎全口義齒於靜止位置（rest position）時，可平穩地留置於下顎牙嵴上。但患者一張口，義齒即浮動於牙嵴 上，下列何者為最不可能之原因？","options":["(A) 下顎義齒遠心頰側凸緣（buccal flange）過長","(B) 下顎義齒遠心舌側凸緣（lingual flange）過短","(C) 下顎義齒後牙排列太靠近頰側","(D) 下顎義齒前牙齒頸部排列太近唇側"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"製作全口義齒時，可於下顎咬合堤上記錄患者口角的位置，以作為排列下列那個牙齒位置的參考？①側門齒 ②犬齒 ③第一小臼齒 ④第二小臼齒","options":["(A) ①②","(B) ②③","(C) ③④","(D) 僅②"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"全口義齒製作時，關於取得上下顎咬合紀錄（interocclusal record）的敘述，下列何者錯誤？","options":["(A) 咬合紀錄可分為靜態的（static）、圖形的（graphic）或功能性的（functional）","(B) 優先使用的方法是圖形（graphic）紀錄法，因為操作簡單容易重作和記錄重現度高","(C) 靜態（static）紀錄是使用軟性材料放入上下顎蠟堤間取得","(D) 圖形（graphic）紀錄可使用口內描繪器取得"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"全口義齒製作時，若發現咬合器上的髁傾斜度（condylar inclination）設定有問題，應重新取何項記錄來設定？","options":["(A) 側方顎關係紀錄（lateral jaw relation record）","(B) 前突紀錄（protrusive record）","(C) 中心咬合紀錄（centric occlusion record）","(D) 中心關係紀錄（centric relation record）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"上顎門牙排列若太往上（high up）時，發唇齒音（labiodental sounds）時，容易出現何種錯誤？","options":["(A) 將v錯發成f音","(B) 將f錯發成v音","(C) 將t錯發成d音","(D) 將d錯發成t音"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-1-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"下列何者為全口義齒排牙前，不必於石膏模型上標示的解剖構造？","options":["(A) 外斜嵴（external oblique ridge）","(B) 門齒乳突（incisive papilla）","(C) 臼齒後墊（retromolar pad）","(D) 下顎舌骨嵴（mylohyoid ridge）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"當上下顎牙弓的距離較小，因而必須將人工牙齒的齒頸部修短時，通常建議使用壓克力樹脂的人工牙齒，下 列最主要之原因為何？","options":["(A) 美觀佳","(B) 易於修整咬合","(C) 耐磨耗","(D) 可和義齒基底做化學鍵結"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-13","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"有關全口義齒平衡咬合的調整，下列敘述何者錯誤？","options":["(A) 首先去除中心關係咬合的誤差，再進行側方以及前突運動的咬合調整","(B) 在解剖形態牙齒建立平衡咬合（balanced occlusion）模式時，工作側的咬合干擾是指發生於上顎頰側咬頭的 舌側傾斜面與下顎舌側咬頭的舌側斜面之間的過早接觸","(C) 在舌側化咬合（lingualized occlusion）模式的全口義齒中，側方運動的咬合調整主要在去除出現在上顎頰側 咬頭與下顎咬合面上的過早接觸","(D) 採用零度牙排成平面咬合（monoplane occlusion）模式時，咬合調整主要在下顎人工牙咬合面進行"],"answer":1,"clinical_level":"重點"},{"id":"ya5-110-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"有一患有巴金森氏症（Parkinson's disease）之全口義齒患者，下顎無牙嵴已嚴重吸收。此患者最宜採用何種 咬合模式（occlusal scheme）？","options":["(A) 舌側咬合（lingualized occlusion）","(B) 雙側平衡咬合（bilateral balanced occlusion）","(C) 平面咬合（monoplane occlusion）","(D) 圓球模式咬合（spherical scheme occlusion）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"配戴全口義齒時，應有的口腔及義齒保養的注意事項，下列敘述何者錯誤？","options":["(A) 患者在餐後必須盡可能的沖洗口內以及義齒","(B) 義齒無需每天浸泡於含清潔劑的液體內，以去除微生物","(C) 必須要用軟毛牙刷以及無研磨粉的清潔用品清除義齒所有表面的牙菌斑","(D) 殘嵴的黏膜表面與舌頭的表面需要每天使用軟毛牙刷清潔"],"answer":1,"clinical_level":"重點"},{"id":"ya5-110-1-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"患者抱怨配戴新的義齒數小時之後，覺得黏膜疼痛且顏面下半部的肌肉會疲倦，下列何者最可能造成此種現 象？","options":["(A) 義齒邊緣（denture border）過長","(B) 錯誤的中心關係（centric relation）","(C) 垂直距離（vertical dimension）過大","(D) 義齒穩定性不佳"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"上顎是單顎全口義齒（single complete denture），下顎為自然牙的情況下，下列處理方式何者錯誤？","options":["(A) 為達咬合平衡下顎牙齒可做選擇性的修磨","(B) 下顎自然牙之選擇性修磨，只限於後牙","(C) 不規則咬合平面可以使用模板（template）修磨牙齒以矯正咬合平面","(D) 下顎牙齒可以做固定義齒（crown & bridge）以修正咬合平面"],"answer":1,"clinical_level":"重點"},{"id":"ya5-110-1-18","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"造成覆蓋式義齒支柱牙喪失的原因①牙周疾病 ②齲齒 ③牙髓病併發症。依其發生率由高至低排列，下列 何者正確？","options":["(A) ②①③","(B) ②③①","(C) ①②③","(D) ①③②"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-19","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"患者張老先生全口無牙，僅剩下顎右側犬齒的牙根，陳醫師利用此牙根裝置一球狀（ball type）附連體 （attachment），以製做下顎之覆蓋式義齒（overdenture），下列何者為此一製作法之最主要目的？","options":["(A) 支持（support）","(B) 固位（retention）","(C) 穩定（stability）","(D) 美觀（esthetics）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-20","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"下列那一種壓克力樹脂的全口義齒磨光面（polished surface），不易達到良好的磨光？","options":["(A) 傳統的熱活化聚甲基丙烯酸甲酯（heat-activated polymethyl methacrylate）","(B) 熱活化橡膠強化聚甲基丙烯酸甲酯（heat-activated rubber reinforced polymethyl methacrylate）","(C) 熱活化纖維強化聚甲基丙烯酸甲酯（heat-activated fiber reinforced polymethyl methacrylate）","(D) 光活化聚甲基丙烯酸甲酯（light-activated polymethyl methacrylate）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"在全口義齒之製作中，臨床重置位（clinical remount）做咬合調整的時機，通常在何時？","options":["(A) 在蠟型義齒試戴（wax denture try-in）時","(B) 在樹脂翻製後由包埋盒（flask）中取出時","(C) 在第一次全口義齒裝戴（delivery）時","(D) 在全口義齒裝戴後一個星期"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-22","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"患者因在其他醫療院所新製作的義齒穩定性不佳來尋求協助，你認為最合適的處理方式應該為下列何者？","options":["(A) 請患者回去找原來的牙醫師處理","(B) 向患者說明他的義齒困難度高，直接建議由專科醫師重作","(C) 檢查患者之義齒與口腔狀況，在告知患者並經其同意後，進行必要的處置","(D) 建議患者多練習及適應，義齒穩定性就會改善"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"下列有關可撤式局部義齒小連接體（minor connector）的敘述，何者錯誤？","options":["(A) 主要的功能是將可撤式局部義齒周邊組件連接到主連接體，使受力分散到支柱牙與殘嵴","(B) 常被放置在舌側齒間縫隙以減少異物感，並與主連接體成直角，而交接處呈柔和弧形","(C) 應具備足夠的剛硬性，才能夠將受力傳到周邊組織","(D) 下顎遠心端缺牙區義齒基底須覆蓋至臼齒後墊，因此小連接體也須延伸至臼齒後墊"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-24","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"下列關於牙鈎（clasp）的固位臂（retentive arm）與拮抗臂（reciprocal arm）的敘述，何者正確？","options":["(A) 固位臂末端不進入倒凹區，而拮抗臂末端則進入倒凹區","(B) 固位臂末端進入倒凹區，而拮抗臂末端則不進入倒凹區","(C) 固位臂末端與拮抗臂末端皆進入倒凹區","(D) 固位臂末端與拮抗臂末端皆不進入倒凹區"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-25","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"可撤式局部義齒主連接體（major connector）之設計，應該具備之特性不包括下列何者？","options":["(A) 應具備足夠的剛硬性","(B) 可提供作為義齒基底的功能","(C) 可提供垂直支持與保護軟組織的作用","(D) 可提供直接與間接的固位作用"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-26","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"依據甘迺迪四種缺牙區分類製作的可撤式局部義齒，在承接咬合力之後，那一類義齒比較能將作用力置於支 柱牙長軸上？","options":["(A) 第一類","(B) 第二類","(C) 第三類","(D) 第四類"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-27","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"關於可撤式局部義齒主連接體（major connector）使用旋鎖裝置（swing-lock design）的適應症，下列何者錯 誤？","options":["(A) 用於患者缺失重要支柱牙時，能利用此設計來穩定所有剩餘的牙齒","(B) 用於患者現存齒列外形或傾斜度，無法使用一般牙鈎設計時","(C) 用於患者有不良的軟組織外形，可能會妨礙到可撤式局部義齒的組件放置時","(D) 用於患者唇側與頰側的前庭很淺或唇側繫帶附著點很高時"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-28","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"下列何者是可撤式局部義齒使用下顎主連接體舌下槓（sublingual bar）的禁忌情況？①有舌側隆凸 ②舌繫 帶附著位置很高 ③舌側口底很淺 ④下顎前牙舌側有舌側倒凹","options":["(A) 僅①②③","(B) 僅①②④","(C) 僅②③④","(D) ①②③④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"製作可撤式局部義齒（removable partial denture）時，組織支持（tissue support）的效益是由下列何項因素決 定？①殘留骨嵴（residual ridge）之性質 ②義齒基底（denture base）所覆蓋的殘留骨嵴範圍 ③印模方式及 其精確性 ④義齒基底之精確性","options":["(A) 僅①②③","(B) 僅①②④","(C) 僅②③④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"有關RPI適用情況的敘述，下列何者最正確？","options":["(A) 頰側組織倒凹（tissue undercut）過大者","(B) 支柱牙頰側齒頸1/3（cervical third）倒凹（undercut）較深者","(C) 頰側前庭（buccal vestibule）較淺者","(D) 病人較重視美觀（esthetics）者"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"有關可撤式局部義齒三點定位法（tripoding）的敘述，下列何者錯誤？","options":["(A) 可記錄工作模型與析量器（surveyor）間的關係","(B) 在同一水平面上畫上不共線且分布很開的三個點","(C) 記錄齒模在析量器上的最合適角度","(D) 為了確實描繪出三點定位的連線，可以調整析量臂或轉動析量台之角度"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-32","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"設計可撤式局部義齒支柱牙的牙鈎（clasp）時，使用析量器（surveyor）標示固位牙鈎臂（retentive clasp arm）末端倒凹的敘述，下列何者錯誤？①倒凹測量器（undercut gauge）最大可量測到 0.03 inch 倒凹 ②鑄 造牙鈎（cast clasp）的固位端至少需要 0.02 inch 倒凹 ③錐形鍛製金屬線（tapered wrought-wire）牙鈎長度 達 8 mm 以上，可進入 0.02 inch 倒凹 ④當支柱牙只限於單側牙弓時，使用 0.03 inch 倒凹加大牙鈎的固位力","options":["(A) ①②","(B) ②④","(C) ③④","(D) ②③"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-33","subject":"ya5","topic":"臨床基礎與倫理","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"骨頭內的礦質化（mineralization）改變程度，最少要達多少百分比才能於一般X光片上診斷出來？","options":["(A) 5%","(B) 15%","(C) 25%","(D) 35%"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-34","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"在進行可撤式局部義齒明確的治療前，會先製作診斷用模型（diagnostic study cast），此模型之功能不包括下 列何者？","options":["(A) 可用於觀察頰側與舌側的咬合關係，以彌補口腔檢查不足之處","(B) 可用來析量牙齒與牙弓","(C) 用以向病人解釋可撤式局部義齒之治療計畫","(D) 可用來製作可撤式局部義齒之金屬義齒支架（metal framework）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-35","subject":"ya5","topic":"牙科材料學","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"下列何者不是造成水凝膠（hydrocolloid）印模不精確的原因？","options":["(A) 因脫水（dehydration）造成材料收縮","(B) 使用強直性高的印模托","(C) 因吸水（imbibition）造成材料膨脹","(D) 倒石膏時石膏已開始硬化"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-36","subject":"ya5","topic":"牙科材料學","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"下列何種顏色的熱塑性印模材料熔點最低？","options":["(A) 紅色","(B) 灰色","(C) 綠色","(D) 黃色"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-37","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"有關可撤式局部義齒的咬合，下列敘述何者錯誤？","options":["(A) 可撤式局部義齒與剩餘真牙間有協調的咬合，對於保存真牙支持組織之健康很重要","(B) 牙醫師無法掌控的咬合因素是髁導引（condylar guidance）","(C) 如果對側為全口義齒或上下牙弓僅存前牙時，可以全口義齒的排牙方式排牙","(D) 當不平衡的持續性咬合壓力存在時，因有支柱牙，故較不具軟組織傷害性"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya5-110-1-38","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"製作下顎可撤式局部義齒時，若患者配戴上顎全口義齒，則設計何種咬合關係最為適當？","options":["(A) 門齒保護性咬合（incisor protection）","(B) 群體功能咬合（group function）","(C) 平衡性咬合（balanced occlusion）","(D) 犬齒導引性咬合（canine guidance occlusion）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"製作可撤式局部義齒時，將診斷模型（diagnostic casts）置放到咬合器最主要的目的為何？","options":["(A) 作為牙鈎（clasp）設計的參考","(B) 作為鈎靠（rest）設計的參考","(C) 作為主連接體（major connctor）設計的參考","(D) 作為評估牙齒咬合間距與咬合接觸的檢查與分析"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"下列何種材料不適合用來確認可撤式局部義齒是否喪失咬合接觸（loss of contact）？","options":["(A) 綠色製模膠（green modeling compound）","(B) 2條28量器之分隔帶（2 strips of 28-gauge）","(C) 成型帶（matrix strips）","(D) 綠或藍色的鑄造用蠟（soft green or blue casting wax）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-1-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"10歲男性病人，因騎腳踏車跌倒失去上顎右側正中門齒已經六個月，母親帶他到診所診治，要求缺牙區做假 牙。檢查右側側門齒與左側正中門齒正常無症狀。下列何者是可行的治療計畫？①製作右側側門齒到左側正 中門齒三單位的陶瓷融合金屬牙橋（3 unit porcelain fused to metal bridge） ②上顎右側正中門齒處進行植體 （implant）手術，先以植體臨時牙冠恢復美觀，待適當時機置換成全瓷冠(full ceramic crown） ③上顎右側 正中門齒處以暫用可撤式局部義齒（interim removable partial denture）修復","options":["(A) 僅①","(B) 僅②","(C) 僅③","(D) ①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"可撤式局部義齒在模型上進行珠狀緣飾（beading）的深度，最合適者為多少mm？","options":["(A) 0.1","(B) 0.3","(C) 0.5","(D) 0.7"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-43","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"在設計可撤式局部義齒時，若倒凹區相同，則那一種狀況的牙齒可選擇直徑較大的鍛製金屬線牙鈎（wrought wire clasp），以獲得較大的固位性？","options":["(A) 牙周狀況佳的支柱牙","(B) 遠心游離端缺牙的支柱牙","(C) 近心游離端缺牙的支柱牙","(D) 對咬牙為自然齒的支柱牙"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-1-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"關於可撤式局部義齒主要模型的析量（survey），下列敘述何者最正確？","options":["(A) 牙齒的引導面決定平台的左右傾斜度","(B) 所有支柱牙上的固位倒凹程度要均衡","(C) 碳棒的尖端型態不會影響析量結果","(D) 主要模型利用三點定位法重新定位時會有高達0.5 mm的誤差"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"有關固定義齒支柱牙修形（abutment preparation）的敘述，下列何者正確？","options":["(A) 下顎第一大臼齒軸向（axial）修磨向舌側傾斜約5～8度","(B) 下顎第一大臼齒軸向（axial）修磨，須與下顎牙弓（mandibular arch）咬合平面（occlusal plane）垂直","(C) 羽毛邊緣（feather edge）是瓷鑲面（porcelain laminate veneer）支柱牙邊緣修磨的最佳選擇","(D) 修磨弧形緣（chamfer）的最佳磨針（bur）為漸細圓頭碳鋼磨針（a tapered carbide with a rounded tip）"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"有關固定義齒支柱牙抗力形（resistance form）的敘述，下列何者正確？","options":["(A) 同樣高度與角度的軸壁（axial wall）修磨，小臼齒的抗力形較大臼齒為佳","(B) 為達到可接受的抗力形，支柱牙修磨後高寬比至少為1：5","(C) 為了提供可接受的支柱牙抗力形，大臼齒牙冠修磨後的軸壁高度至少須有5 mm","(D) 頰側或舌側修磨，形成溝（groove）或箱（box）是增加抗力形的最有效方法"],"answer":0,"clinical_level":"重點"},{"id":"ya5-110-1-47","subject":"ya5","topic":"咬合學基礎","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"當下顎進行邊緣運動（border movement）中的側向運動時，下列敘述何者錯誤？","options":["(A) 非工作側（nonworking side）的髁頭（condyle head）向前內側運動","(B) 工作側（working side）的髁頭（condyle head）主要產生旋轉運動","(C) 工作側（working side）的髁頭（condyle head）運動受到關節窩（glenoid fossa）近心面及韌帶之限制","(D) 班奈特運動（Bennett movement）發生在工作側（working side）的髁頭（condyle head）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-110-1-48","subject":"ya5","topic":"臨床基礎與倫理","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"使用藥物來抑制口水分泌以利印模，下列何種藥物比較不會引起視覺模糊的副作用？","options":["(A) Atropine","(B) Propantheline","(C) Clonidine","(D) Dicyclomine"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-49","subject":"ya5","topic":"牙科材料學","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"有關加成式矽膠（addition silicone）印模材的使用，下列敘述何者錯誤？","options":["(A) 調拌時可能會受到乳膠（latex）手套的影響","(B) 可用2%戊乙醛（glutaraldehyde）作消毒","(C) 應該立刻灌模","(D) 精確又穩定，可以重複灌模"],"answer":2,"clinical_level":"重點"},{"id":"ya5-110-1-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"製作根柱時，使用3號的Gates Glidden drill可修形出的根管空間直徑為多少mm ？","options":["(A) 0.5","(B) 0.7","(C) 0.9","(D) 1.1"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-51","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"製作固定牙橋時，關於支柱牙牙周預後之考量，何種程度的附連喪失（attachment loss）屬於“questionable prognosis”？","options":["(A) 30%","(B) 40%","(C) 50%","(D) 超過50%"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-52","subject":"ya5","topic":"牙科材料學","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"在金屬瓷冠中，有關金屬與瓷之線性熱膨脹係數間，最佳的關係與瓷內部殘餘應力（residual stress）之敘 述，下列何者正確？","options":["(A) 金屬比瓷小0.5×10-6/℃，瓷內部呈抗張應力（tensile stress）狀態","(B) 金屬比瓷大0.5×10-6/℃，瓷內部呈抗張應力（tensile stress）狀態","(C) 金屬比瓷小0.5×10-6/℃之內，瓷內部呈壓縮應力（compressive stress）狀態","(D) 金屬比瓷大0.5×10-6/℃之內，瓷內部呈壓縮應力（compressive stress）狀態"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"下列橋體（pontic）的材質，何者最具生物親和性（biocompatibility），且易於清潔？","options":["(A) 拋光後（polished）的18K金合金","(B) 上釉瓷","(C) 拋光後瓷","(D) 拋光後複合樹脂"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"金屬瓷冠（metal-ceramic crowns）使用後，發生瓷破裂（porcelain fracture）的原因，可能為下列何者？①金 屬支架設計不良 ②咬合接觸點太靠近金屬瓷之交接面 ③燒瓷前金屬處理不佳","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-55","subject":"ya5","topic":"牙科材料學","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"牙科瓷（porcelain）成分中，長石（feldspar）因含有何種氧化物，可增加其黏性和硬度？","options":["(A) 氧化鎂（MgO）","(B) 氧化鋅（ZnO）","(C) 氧化矽（SiO2）","(D) 氧化鋁（Al2O3）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-56","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"關於使用間接－直接技術（indirect technique）製作暫用性（interim）固定義齒的敘述，下列何者正 確？①使用預製牙冠外殼（preformed crown form） ②使用修形不足（underprepared）的診斷模型 ③於病 患口內完成組織面型（tissue surface form） ④相較於間接技術（indirect technique），有比較精確的牙冠邊 緣（margin）","options":["(A) ①②","(B) ③④","(C) ②③","(D) ①④"],"answer":2,"clinical_level":"重點"},{"id":"ya5-110-1-57","subject":"ya5","topic":"牙科材料學","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"當兩個顏色在某個光源下看起來一樣，但在另一個光源下看，卻顯現出不同的顏色，這個現象稱為什麼？","options":["(A) 同分異構（isomerism）","(B) 同色異構（metamerism）","(C) 結構異構（structural metamerism）","(D) 螢光（fluorescence）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-58","subject":"ya5","topic":"植牙贋復","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"當後牙區因長期殘嵴吸收（residual ridge resorption），而造成贋復空間極大，為了補償crown-to-implant ratio，下列何種策略最佳？","options":["(A) angled implants","(B) screw-retained FPD","(C) titanium framework","(D) increase screw preload"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-1-59","subject":"ya5","topic":"植牙贋復","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"設計全顎植體固定義齒時，若採用多個單顆牙冠個別黏著在金屬或氧化鋯支架（framework）之上，相較於將 瓷燒附在支架上之傳統作法，其優點主要為何？","options":["(A) 增加支架（framework）被動式密合（passive fit）","(B) 當義齒出現問題時容易修復","(C) 患者清潔義齒較為容易","(D) 減少技工製作成本"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-60","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"當存在咬合干擾時，下列何者是進行選擇性咬合修形（selective occlusal reshaping）的時機？","options":["(A) 矯正治療前","(B) 使用咬合板治療前","(C) 進行全口重建後","(D) 製作兩側及上下顎多顆後牙固定義齒前"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"對於一個上顎側門牙先天缺失，卻懷抱模特兒夢想的16歲女性高中生，經齒顎矯正治療騰出適當空間後，下 列何種補綴方式最適合她？","options":["(A) 植牙固定義齒","(B) 三單位固定牙橋","(C) 黏著固定牙橋（adhesion bridge）","(D) 局部可撤式義齒"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-62","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"下列關於單齒模（die）之敘述，何者正確？","options":["(A) 環氧樹脂單齒模系統（epoxy resin die system）的製作，較硬石膏單齒模系統（stone die system）昂貴","(B) 可彎曲單齒模（flexible die）材料化學性質類似多硫化物（polysulfide）印模材","(C) 固形模－分離單齒模系統（solid cast-individual die system）無法保留牙齦組織形態","(D) 單齒模硬石膏（die stone）粉水比為100公克粉調拌30～35 mL水"],"answer":0,"clinical_level":"重點"},{"id":"ya5-110-1-63","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"關於PKT器械的用途，下列敘述何者錯誤？","options":["(A) 1號及2號是添蠟器（addition instrument）","(B) 3號及4號是研光器（burnisher）","(C) 5號是雕刻器（carver）","(D) 7號是大量添蠟時使用"],"answer":1,"clinical_level":"重點"},{"id":"ya5-110-1-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"關於全瓷冠的顏色或形態調整，下列敘述何者錯誤？","options":["(A) 修磨過金屬的碳化矽磨石（carborundum stone）不可以再用來修瓷","(B) 碳化矽磨石（carborundum stone）旋轉的方向要朝向瓷較薄的地方","(C) 確認顏色時，必須要有唾液潤濕鄰牙的牙齒表面","(D) 全瓷冠的最終顏色會受黏合劑影響"],"answer":1,"clinical_level":"重點"},{"id":"ya5-110-1-65","subject":"ya5","topic":"牙科材料學","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"下列何者最不影響蠟形包埋時的鑄道設計（sprue design）？","options":["(A) 鑄造物的大小與形式","(B) 使用的合金種類","(C) 包埋粉的種類","(D) 鑄造機的種類"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-66","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"下列何種黏合劑（cement）與鈦金屬（titanium）之間會有化學作用，因此不適合用來黏著牙冠於鈦金屬支柱 （abutment）上？","options":["(A) 玻璃離子體（glass ionomer）黏合劑","(B) 樹脂（resin）黏合劑","(C) 聚羧酸鋅（zinc polycarboxylate）黏合劑","(D) 磷酸鋅（zinc phosphate）黏合劑"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-67","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"關於嚼肌（masseter）與顳肌（temporalis）構造與功能的敘述，下列何者正確？①嚼肌深部（deep portion） 收縮可造成下顎前移（protrusion），此時嚼肌淺部（superficial portion）的功用是穩定髁（condyle） ②嚼 肌主要附著於下顎枝（mandibular ramus），而顳肌主要附著於喙狀突（coronoid process） ③顳肌前部 （anterior portion）與中部（middle portion）收縮，相較於後部（posterior portion），對上提下顎的影響較大","options":["(A) 僅①③","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-1-68","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"關於咀嚼肌牽張反射（stretch reflex）的敘述，下列何者正確？①因嚼肌（masseter）中的肌梭（muscle spindle）被意外拉長而引發 ②神經訊號透過三叉神經中腦核（trigeminal mesencephalic nucleus）傳入腦幹 ③腦幹中的三叉運動神經核（trigeminal motor nucleus）引發嚼肌收縮 ④該反射與維持下顎的靜止位置 （resting position）有關","options":["(A) 僅①④","(B) 僅②③","(C) 僅①②③","(D) ①②③④"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-69","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"下列肌肉中，何者的肌纖維組成（muscle fiber types）明顯異於另外三者？","options":["(A) 翼外肌（lateral pterygoid muscle）","(B) 二腹肌（digastric muscle）","(C) 顳肌（temporalis muscle）","(D) 咬肌（masseter muscle）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-70","subject":"ya5","topic":"咬合學基礎","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"下列何者咬合關係屬於安格式第二類臼齒關係（Angle class II molar relationship）？①下顎第一大臼齒的遠心 頰側咬頭對咬於上顎第一大臼齒與第二小臼齒之間的楔隙（embrasure） ②下顎第一大臼齒近心頰側咬頭對 齊上顎第一大臼齒的頰側溝（buccal groove） ③上顎第一大臼齒遠心舌側咬頭對咬於下顎第一大臼齒中心 窩（central fossa） ④上顎第一大臼齒遠心頰側咬頭對齊下顎第一大臼齒的頰側溝（buccal groove）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ④①"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-71","subject":"ya5","topic":"咬合學基礎","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"影響咬頭高度的因素，不包括以下何者？","options":["(A) 史比氏曲線（curve of Spee）","(B) 關節隆凸的角度","(C) 咬合平面","(D) 咬合力大小"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-72","subject":"ya5","topic":"咬合學基礎","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"造成下顎左側向滑動的中心關係干擾（CR interferences）產生的位置，下列敘述何者完全正確？①左側上顎 頰側咬頭舌側斜面接觸左側下顎頰側咬頭頰側斜面 ②左側上顎舌側咬頭舌側斜面接觸左側下顎舌側咬頭頰 側斜面 ③右側上顎舌側咬頭舌側斜面接觸右側下顎舌側咬頭頰側斜面 ④右側上顎頰側咬頭舌側斜面接觸 右側下顎頰側咬頭頰側斜面","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-1-73","subject":"ya5","topic":"咬合學基礎","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"關於泛得式描繪（pantographic tracing）的敘述，下列何者錯誤？","options":["(A) 總共有三組描繪平台，可以描繪受試者離心運動的軌跡與中心關係的位置","(B) 使用的是動態的面弓（kinematic facebow）在垂直與水平描繪平台上，試圖記錄接近所謂樞紐軸線上髁頭運 動的軌跡","(C) 利用中軸承器（central bearing device）位於口內，於前緣兩側記錄下顎離心運動描繪出中心關係（centric relaton）位置","(D) 在髁頭側水平描繪平台上的紀錄或軌跡，可以調整咬合器髁傾斜度（condyle inclination）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-74","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"關於下顎髁頭於開閉口時之運動，下列敘述何者正確？","options":["(A) 人類開閉口運動為純粹的樞紐運動","(B) 在顳顎關節上腔中允許髁頭沿著水平軸線向前旋轉","(C) 在顳顎關節下腔中伴隨關節盤滑動產生向前向下的平移","(D) 關節盤於閉口最後時向前滑動，主要是因韌帶連結髁頭發生牽引而被動發生的"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"關於顳顎關節風濕性骨關節炎（rheumatoid arthritis）的描述，下列何者正確？","options":["(A) 通常起始於滑液膜的發炎反應","(B) 關節會產生關節彈響（clicking）","(C) 不會有張口困難的症狀","(D) 發炎反應不會影響到關節運動"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"小林先生因練習大口快速吃熱狗，不幸受傷無法張口，而無法衛冕大胃王頭銜。請問小林先生受傷的部位最 可能是下列何者？","options":["(A) 顳顎韌帶（temporomandibular ligament）","(B) 翼內肌（medial pterygoid muscle）","(C) 二腹肌（digastric muscle）","(D) 莖突下顎韌帶（stylomandibular ligament）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"關於部分覆蓋咬合板，下列敘述何者錯誤？","options":["(A) 初期臨床治療的靈感來自於齒顎矯正之維持器，對於顎關節痛與肌肉痛有明顯療效","(B) 藉由增加咬合高度向前咬的趨勢，可以解除上下牙緊咬的狀態","(C) 可改變髁頭位置，解除髁之後壓與關節盤之向前異位","(D) 此類咬合板若消除肌肉疼痛顯著，可以長期讓患者使用"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"關於治療可復位關節盤前移（anterior disc displacement with reduction）的敘述，何者錯誤？","options":["(A) 咬合裝置治療的目的，主要是在減輕關節疼痛而非確保關節盤的復位（disc recapture）","(B) 應採用前置位咬合裝置（anterior positioning appliance）來取代傳統的穩定型咬合裝置（stabilization appliance）","(C) 關節一般要產生適應性的變化（adaptive changes），大約要八到十周或是更久","(D) 當患者的症狀逐漸緩解後，應減少配戴咬合裝置的頻率與時間"],"answer":1,"clinical_level":"重點"},{"id":"ya5-110-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"下列那幾種情形會造成不會疼痛之張口受限（chronic mandibular hypomobility）？①肌肉攣縮（muscle contracture） ②不可復性關節盤移位（disc displacement without reduction）之急性期 ③喙狀突阻抗 （coronoid impedance） ④關節腔黏連（adhesion of joint space）","options":["(A) 僅①②","(B) 僅②③","(C) ①②③","(D) ①③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"以前後貫上顎投影法（anteroposterior transmaxillary projection）拍攝時，顳顎關節髁頭所在位置於何處較適 當？","options":["(A) 關節窩內","(B) 隆凸嵴（crest of eminence）後方","(C) 隆凸嵴（crest of eminence）","(D) 隆凸嵴（crest of eminence）前方"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"關於使用抗真菌類的藥物，治療念珠菌義齒性口炎（Candida-associated denture stomatitis）的敘述，下列何者 錯誤？","options":["(A) 使用前必須有真菌學檢查（mycological examination）","(B) 當此感染擴及口腔其他區域或咽喉時為使用時機","(C) 全身性給藥副作用較多，應優先考慮使用局部性藥物治療","(D) 藥物的使用要連續2個月才會有效"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-2-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"患者臉型外觀呈現嘴唇變薄、鼻唇溝（nasolabial groove）變深或人中（philtrum）變不明顯，可能來自下列何 種原因？①患者急速體重喪失 ②患者年齡老化 ③輕度牙齒咬耗 ④全口缺牙未戴義齒","options":["(A) ①②③","(B) ②③④","(C) ①②④","(D) ①③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"關於全口無牙患者殘餘牙嵴的吸收，下列敘述何者錯誤？","options":["(A) 拔牙後第一年，上顎骨嵴的吸收比下顎骨嵴明顯","(B) 上顎骨弓會變窄","(C) 下顎骨遠心側變寬","(D) 會增加下顎骨的前突度"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-2-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"關於上顎全口義齒取模時，影響頰側前庭（buccal vestibule）大小與延伸程度的敘述，下列敘述何者錯誤？","options":["(A) 口輪匝肌（obicularis oris）收縮會影響頰側前庭大小","(B) 下顎的位置影響頰側前庭大小","(C) 咬肌（masseter muscle）收縮時，影響頰側前庭遠心端之大小","(D) 檢查頰側前庭延伸程度，病人口腔必須儘可能接近閉合狀態"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-2-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"下列何者不是全口義齒的主要力量承受區（primary bearing areas）？","options":["(A) 上顎齒槽骨嵴（maxillary alveolar ridge）","(B) 上顎粗隆（maxillary tuberosity）","(C) 下顎臼齒後墊（mandibular retromolar pad）","(D) 下顎頰側斜坡（mandibular buccal shelves）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"下列那項組合最適合實施下顎全口義齒的邊緣成形（border molding）？","options":["(A) 常備模托（stock tray），瓊膠印模材（agar）","(B) 常備模托（stock tray），棒狀混合材（stick impression compound）","(C) 客製化模托（custom tray），藻膠印模材（alginate）","(D) 客製化模托（custom tray），棒狀印模化合材（stick impression compound）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"下列何者無法利用中立區（neutral zone）之概念取得？①決定印模面（impression surface）的範圍 ②決定磨 光面（polished surface）的外形 ③決定咬合型式（occlusal scheme） ④決定咬合平面之角度（inclination）","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"關於全口義齒垂直距離（vertical dimension）和中心關係（centric relation）之敘述，下列何者錯誤？","options":["(A) 必須先決定中心關係（centric relation）後，才能決定垂直距離","(B) 下顎中心關係（centric relation）是指下顎最後退，且可重複取得的位置","(C) 若患者無法依照牙醫師之引導移動下顎位置，則難以取得正確關係位置","(D) 可讓患者進行吞嚥動作來記錄下顎中心關係（centric relation）"],"answer":0,"clinical_level":"重點"},{"id":"ya5-110-2-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"全口義齒的製作上，被認為是合理也是最常用的面弓（facebow）是那個種類？","options":["(A) kinematic","(B) arbitrary","(C) hinge axis locator","(D) true axis device"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"影響全口義齒雙側平衡性咬合的因素，下列何者最不重要？","options":["(A) 髁導引（condylar guidance）","(B) 前牙導引（incisal guidance）","(C) 代償曲線（compensating curve）","(D) 咬合平面（plane of occlusion）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-11","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"關於全口義齒蠟型的試戴，下列敘述何者錯誤？","options":["(A) 垂直高度過高會讓患者覺得作嘔（gagging）","(B) 讓患者發 S 音以評估垂直高度","(C) 讓患者以英語發 60s，評估人工前牙的位置","(D) 重複數次確認患者張口到最大時再閉合的位置是否一致"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"下顎全口義齒排列後牙時，有時會減少後牙之數目，其最重要的理由為下列何者？","options":["(A) 根據短牙弓（shortened dental arch）理論，不須這麼多的咬合接觸","(B) 防止咬到臉頰","(C) 怕排在斜面上而導致義齒不穩","(D) 怕咬合重心移向後方而加速骨頭吸收"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"有關全口義齒的平衡咬合（balanced occlusion），在下列何種條件下，小臼齒的咬頭角度（cusp angle）會大 於大臼齒的咬頭角度？","options":["(A) 髁頭導引（condylar guidance）為 45 度，門齒導引（incisal guidance）為 0 度","(B) 髁頭導引（condylar guidance）為 30 度，門齒導引（incisal guidance）為 10 度","(C) 髁頭導引（condylar guidance）與門齒導引（incisal guidance）皆為 20 度","(D) 髁頭導引（condylar guidance）為 10 度，門齒導引（incisal guidance）為 45 度"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"有關全口義齒患者其舌頭之大小與位置對義齒穩定性（stability）之影響，下列敘述何者正確？","options":["(A) 對上、下顎義齒影響相同","(B) 對上顎之影響較大","(C) 對下顎之影響較大","(D) 舌頭大小的影響比位置的影響大"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"當全口義齒的患者無法以英語清楚說數字60到63時，最不可能的原因為下列何者？","options":["(A) 上下顎義齒前牙水平覆蓋關係不當","(B) 上下顎義齒前牙垂直覆蓋位置不當","(C) 上顎義齒後牙排列的位置不當","(D) 義齒垂直咬合高度不當"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"關於牙齒拔除後殘嵴降低（residual ridge reduction）的敘述，下列何者錯誤？","options":["(A) 屬於慢性、漸進式與不可逆的過程","(B) 牙齒拔除後第一年，在正中矢狀平面，上顎殘嵴高度降低量平均約為4到5mm，下顎殘嵴高度降低量平均約 為2到3 mm","(C) 一年之後，下顎殘嵴高度的降低量每年平均約為0.1到0.2 mm","(D) 一般而言長期殘嵴吸收之後，上顎牙床會變窄，下顎牙床則會變寬"],"answer":1,"clinical_level":"重點"},{"id":"ya5-110-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"13 到 23 六顆前牙皆因嚴重牙周病而須拔除，而需製作上顎之即裝全口義齒（immediate complete denture）。 經口內檢查發現：正中線對齊，但 12、11、21 過度萌出（supraeruption），22 牙冠斷裂及13 病理性位移 （pathologic migration）。此時於技工室中之石膏模形修磨與排牙順序，下列何者最佳？（牙位依FDI命名 法）","options":["(A) 11、21 同時 → 12、22 同時 → 13、23 同時","(B) 11 → 22 → 21 → 12 → 13 → 23","(C) 12、22 同時 → 11、21 同時 → 13 → 23","(D) 22 → 13 → 12、11、21 同時 → 23"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-18","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"患者因鱗狀細胞上皮癌需切除上顎硬腭，有關手術閉孔器（surgical obturator）製作之敘述，下列何者錯誤？","options":["(A) 此裝置可恢復上顎的完整性","(B) 此裝置可幫助病人於手術後之說話及吞嚥","(C) 一般須配戴一個月的時間","(D) 此裝置可幫助術後之止血"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-19","subject":"ya5","topic":"植牙贋復","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"使用口服雙磷酸鹽藥物治療骨質疏鬆症的患者，如欲接受人工植牙時，下列敘述何者錯誤？","options":["(A) 服用口服藥物少於三年的患者，較不容易產生骨壞死","(B) 一般建議停藥六個月始可植牙","(C) 一般建議 serum C-terminal telopeptide之濃度大於 150 pg/ml 時，始可植牙","(D) 對於已經接受人工植牙多年的患者，亦可能於投藥後產生骨壞死"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-20","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"全口義齒之技工操作，於蠟型義齒（wax denture）完成後需包埋（flasking）。有關包埋之敘述，下列何者正 確？","options":["(A) 包埋盒有大小之分，但上下顎通用","(B) 包埋時人工牙的咬合平面必須低於包埋盒上緣約 3~6 mm","(C) 主模型之石膏與包埋盒之邊緣必須形成適當的銳角","(D) 包埋的石膏必須覆蓋過主模型之周邊"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"全口義齒進行煮聚之前必須完成後腭封（posterior palatal seal），下圖三種軟腭形式（soft palate form）可提供 之封閉區域，由大至小依序為何？","options":["(A) I＞II＞III","(B) III＞II＞I","(C) II＞III＞I","(D) III＞I＞II"],"answer":0,"image":"ya5-110-2-21.jpeg","clinical_level":"重點"},{"id":"ya5-110-2-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"牙醫師對於正在進行精神心理治療的全口無牙患者，下列那一種處置最為合宜？","options":["(A) 避免刺激患者，最好直接進行義齒製作","(B) 一邊製作一邊積極對患者進行教育改變他對義齒的態度","(C) 直接拒絕患者義齒製作的要求","(D) 需先照會患者之精神科醫師或心理師，才可進行全口義齒治療"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"對於可撤式局部義齒的設計，下列敘述何者正確？①外終接線（external finishing line）與主連接體連接之夾 角須小於90度 ②組織止點（tissue stop）的主要功能之一為類似間接固位體（indirect retainer）的作用 ③可 以用自聚式樹脂（autopolymerizing resin）塗在金屬支架之組織止點（tissue stop）上以維持接觸 ④主連接體 （major connector）與小連接體（minor connector）連接的腭側終接線（palatal finishing line）應位於距離缺牙 牙嵴腭側與後牙腭側假想線約5mm的位置","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-2-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"有關可撤式局部義齒上顎主連接體（major connector）的敘述，下列何者錯誤？","options":["(A) 磨光面應呈現平順圓滑外型","(B) 設計與缺牙區的位置及數量有關","(C) 儘可能圓弧形對稱設計且以鈍角方式跨過上顎中線","(D) 應該在組織面邊緣稍微隆起與上顎軟組織能夠緊密貼合"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya5-110-2-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"有關可撤式局部義齒鈎靠（rest）與鈎座（rest seat）的設計考量，下列敘述何者錯誤？","options":["(A) 鈎靠同時要維持固位性牙鈎正確位置，以確保牙鈎的固位能力","(B) 鈎靠在橫跨牙齒邊緣嵴（marginal ridge）時，須有1至1.5 mm的厚度","(C) 鈎座大小須占支柱牙（abutment）近遠心長度的1/2和頰舌徑寬度的1/3至1/2","(D) 牙齒縱軸與鈎座底部所形成的夾角應小於90度"],"answer":2,"clinical_level":"重點"},{"id":"ya5-110-2-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"使用所謂RPI的方式設計可撤式局部義齒時，下列敘述何者錯誤？","options":["(A) RPI 三個字母所代表的意思分別是 Rest、Proximal plate與I-bar","(B) 使用I型槓（I-bar）做為固位體時，其尖端應置於終端（terninal）支柱牙的遠心頰側","(C) 較短的鄰接板（proximal plate）相較於較長的鄰接板，較可均勻分配咬力給支柱牙與遠心端牙嵴組織","(D) 較長的鄰接板（proximal plate）與支柱牙有較多的接觸，咀嚼時將受到較多的水平分力"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"有關可撤式局部義齒引導面（guiding plane）功能之敘述，下列何者錯誤？","options":["(A) 提供一個義齒戴入及取出的途徑","(B) 確保抗衡性、穩定性、固位性的組件發揮其作用","(C) 沒有穩定義齒以抵抗義齒往水平方向旋轉的功能","(D) 避免食物堆積於支柱牙與義齒組件間"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya5-110-2-28","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"關於可撤式局部義齒主連接體（major connector）的敘述，下列何者錯誤？","options":["(A) 金屬必須與口腔組織有生物相容性（biocompatibility）","(B) 必須有足夠的剛性（rigidity），以提供義齒足夠的穩定性（stability）","(C) 下顎的主連接體（major connector）可以占據部分的舌頭空間，以提供足夠的強度","(D) 儘量不要改變下顎齒槽嵴（alveolar ridge）與上顎腭穹窿（palatal vault）的外形"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya5-110-2-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"遠心端游離（distal free end）可撤式局部義齒受力時，會呈現類似下列何種槓桿（lever）現象？","options":["(A) 第一級","(B) 第二級","(C) 第三級","(D) 第四級"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-2-30","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"下列何者為甘迺迪第一類（Kennedy Class I）可撤式局部義齒？","options":["(A) 缺雙側後牙","(B) 缺單側後牙","(C) 前牙跨越中線的缺牙","(D) 缺單側小臼齒"],"answer":0,"clinical_level":"重點(深度)"},{"id":"ya5-110-2-31","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"可撤式局部義齒固位區的固位作用，可由下列那些因素決定？①在外廓高隆線（height of contour）下之齒頸 聚合角度（angle of cervical convergence） ②牙鈎（clasp）末端進入到齒頸聚合角度之深度 ③牙鈎臂 （clasp arm）之可彎曲性（flexibility） ④間接固位體（indirect retainer）的位置","options":["(A) ①③④","(B) ①②④","(C) ①②③","(D) ②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-32","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"有關可撤式局部義齒後牙咬合面鈎座修形與鈎座設計理念的敘述，下列何者正確？","options":["(A) 後牙鈎座可以設計在支柱牙舊有陶瓷熔合金屬冠的陶瓷層上","(B) 鈎座可以協助防止支柱牙突出","(C) 楔隙鈎座（embrasure rest seat）修形應打開牙齒接觸點以利精確取模","(D) 後牙鈎座應設計在支柱牙咬合面舊有的大範圍銀粉填補物上"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"有關製作可撤式局部義齒時，獲取中心關係記錄（centric relation record）的方法，下列何者最不適用？","options":["(A) 記錄中心關係的介質材料的選擇，通常依據剩餘的牙齒數目和位置分布而定","(B) 缺牙區較廣泛或分布情況不佳，應使用石膏模型製作記錄基底（record base）和咬合堤（occlusal rim）備用","(C) 以記錄基底與咬合堤獲取中心關係記錄時，最好的記錄介質是加熱軟化的蠟","(D) 以生理性靜止的位置和發音的輔助，決定適當咬合垂直距離（occlusal vertical dimension），並依據此垂直距 離記錄中心咬合關係"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-34","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"擬定可撤式局部義齒製作之治療計畫時，必須由何步驟先開始？","options":["(A) 可撤式局部義齒之設計","(B) 可撤式局部義齒選擇之材料","(C) 瞭解患者之需求與全身及牙科病史","(D) 上下顎之咬合對應關係"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"關於可撤式局部義齒的印模，下列敘述何者錯誤？","options":["(A) 印模材料的厚度不一樣時，容易造成不正確的印模","(B) 使用修正模型印模技術（altered cast impression technique）取模的主要理由是考慮牙齒和黏膜具有不同的受 力反應","(C) 印模材皆須有流動性佳，且硬化後不易變形的特性","(D) 不可以用蠟來進行修正模型印模（altered cast impression）"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-2-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"有關可撤式局部義齒解剖形態印模（anatomic form impression）之敘述，下列何者錯誤？","options":["(A) 是一種一階段式的印模方式","(B) 能取出休止狀態下之軟硬組織狀態","(C) 以此模型製作義齒時，能將咬合力平均分散至支柱牙及殘嵴上","(D) 以此模型製作義齒時，咬合鈎靠（occlusal rest）提供主要支持"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-37","subject":"ya5","topic":"牙科材料學","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"關於多硫化橡膠印模材（polysulfide rubber impression material）的特性，下列敘述何者錯誤？","options":["(A) 屬於彈性印模材料（elastic impression material）的一種","(B) 凝固時間較藻膠瓊膠類印模材料來得久，可有較長的操作時間","(C) 完整的縮合式反應（condensation reaction）長達12小時，所以取模後應至少12小時後，方可進行石膏灌模","(D) 內含硫磺與二氧化鉛等成分而具褐色外觀與硫刺激氣味，病人較易感覺不適或是噁心嘔吐反應"],"answer":2,"clinical_level":"重點"},{"id":"ya5-110-2-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"欲取得可撤式局部義齒之正確對咬關係，須注意那些細節？①在口腔處理（mouth preparation）時，須先調整 成咬合協調之狀態 ②工作模型須精確 ③咬合記錄（bite record）若卡入倒凹及咬合面深溝處，須以銳利刀 片修整 ④若有足夠及穩定之對咬牙，可直接對合模型，不須取咬合記錄","options":["(A) 僅①④","(B) 僅①②③","(C) 僅②③④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-39","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"利用記錄基底上的咬合堤（occlusal rims on record bases）來記錄咬合關係，下列敘述何者錯誤？","options":["(A) 精確的記錄基底有助支持咬合關係","(B) 可見光聚合樹脂基底因不夠精確，需要加蠟片緩壓留出空間","(C) 自聚式丙烯酸樹脂待聚合完全後需要重換底墊（reline）","(D) 應於坐姿時記錄咬合關係"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"有關甘迺迪第三類（Kennedy Class III）可撤式局部義齒，以自聚式樹脂（self-curing resin）於口內直接換底 墊（direct reline）操作步驟的敘述，下列何者正確？①義齒基底（denture base）組織面（tissue surface）必須 磨掉相當的厚度 ②義齒基底（denture base）邊緣（border）必須磨掉相當的厚度 ③加上自聚式樹脂的義 齒放入病人口內前，須請病人以溫水漱口 ④義齒可放入壓力20 psi溫水壓力鍋內，讓自聚式樹脂聚合 （polymerization）","options":["(A) 僅①③","(B) 僅②④","(C) 僅①④","(D) ①②③"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-41","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"有關咬合鈎座（occlusal rest）斷裂的敘述，下列何者正確？","options":["(A) 修磨咬合鈎座的深度須小於1 mm","(B) 常發生於咬合鈎座越過邊緣嵴的部分","(C) 最主要原因是金屬結構上的缺陷","(D) 常因意外變形（accidental distortion）所致"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"關於可撤式局部義齒由鈷鉻合金（chromium-cobalt alloy）主連接體，樹脂義齒基底與樹脂人工牙組成，若鈎 靠（rest）斷裂需要利用銲接步驟來修復此義齒，下列敘述何者正確？","options":["(A) 可利用噴燈銲接（torch soldering）與氟化物類助熔劑（fluoride-type flux）","(B) 可利用電銲（electric soldering）與氟化物類助熔劑（fluoride-type flux）","(C) 可利用噴燈銲接（torch soldering）與硼砂類助熔劑（borax-type flux）","(D) 此種型態義齒不適用銲接法修復"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-43","subject":"ya5","topic":"臨床基礎與倫理","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"製作可撤式局部義齒的牙技師工作指示書，不包含下列那一個項目？","options":["(A) 工作執行完成的日期","(B) 患者的病歷號碼與出生年月日","(C) 牙醫師姓名及醫療院診所名稱","(D) 工作服務內容與指定使用材料"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"關於耐火模型（refractory cast）的製作下列何者錯誤？①可利用瓊膠（agar）的彈性，應直接將固化後的耐火 模型自膠體中取出 ②要依照廠商指示進行混合調拌，以獲得合金鑄造收縮所需的膨脹補償率 ③需使用石 膏研磨機加水研磨，以修整成適當外形 ④模型修整至接近蠟型設計範圍外至多 3～4 mm處，確保鑄造過程 空氣能及時外逸","options":["(A) 僅①③","(B) 僅②④","(C) 僅①④","(D) ①③④"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-45","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"有關上顎前牙全瓷冠 （all ceramic crown）支柱牙之修形，下列敘述何者正確？①相較於瓷金屬融合牙冠 （porcelain fused to metal crown），全瓷冠唇面（labial surface）之修磨較為保守 ②舌側緣（lingual margin） 理想上須修磨出90度窩緣角（cavosurface angle） ③舌面（lingual surface）修磨厚度約為0.4～0.6 mm ④切 緣修磨須大於3.0 mm ，以達到較佳的美觀透明度（translucency）","options":["(A) ①②","(B) ③④","(C) ①④","(D) ②③"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-2-46","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"有關鑄造式（cast）固定義齒支柱牙修磨（abutment preparation）的敘述，下列何者正確？①修磨器械施予支 柱牙修磨面持續性的接觸，可得到有效率的牙齒修磨並有最低的產熱效果 ②支柱牙修磨後使用含界面活性 劑（surfactant）的清潔溶液，可有效地去除修磨後的牙齒表面殘渣，增加義齒黏著性（cementation） ③鑄 造式固定義齒支柱牙修磨後，不需要做間接覆髓（indirect pulp capping）來保護牙髓的健康 ④為了保留支柱 牙更多的牙齒結構，支柱牙修磨時軸壁（axial wall）間應呈現最小聚攏角度（convergence angle）","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-47","subject":"ya5","topic":"咬合學基礎","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"使用樞紐式（hinge type）簡易型咬合器製作後牙固定義齒時，容易發生非工作側（nonworking side）咬合干 擾之原因為何？","options":["(A) 未使用咬合紀錄","(B) 上下部之間的空間較小","(C) 不容易鎖緊固定","(D) 旋轉軸與模型之間距離過小"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-48","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"下列何者不是排齦時常用收斂劑（astringent）的成分？","options":["(A) 正腎上腺素（8% epinephrine）","(B) 次氯酸鈉（sodium hypochloride）","(C) 硫酸鐵（ferric sulfate）","(D) 氯化鋁（aluminum chloride）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-49","subject":"ya5","topic":"牙科材料學","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"使用含有Al2(SO4)3或Fe2(SO4)3的排齦線進行排齦，可能會影響那一種印模材的精確度？","options":["(A) 多硫聚合物（polysulfide）","(B) 加成性矽膠（addition silicone）","(C) 聚乙醚（polyether）","(D) 縮合式矽膠（condensation silicone）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"根據學者針對根管治療後牙齒根柱與冠心修復的失敗率研究發現，下列何者錯誤？","options":["(A) 男性失敗率較高","(B) 年輕人失敗率較高","(C) 上顎失敗率較高","(D) 側門牙比正門牙失敗率高"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-51","subject":"ya5","topic":"植牙贋復","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"一個預定要拔除之牙齒，可以利用矯正強逼萌出（orthodontic forced extrusion, OFE）來取得較多軟硬組織， 以提供植牙有利的環境。下列關於OFE之描述，何者錯誤？","options":["(A) 是指利用矯正方式將牙齒向外拉出，平均每個月拉1～2 mm","(B) 相較於骨引導再生手術，OFE在垂直骨增高及角質牙齦增生上能得到較可預測之結果","(C) OFE完成後應固定2～3個月讓齒槽骨成熟","(D) OFE完成後的牙齒，由於牙周韌帶受到拉張鬆弛，在拔牙之後的軟硬組織流失量較一般拔牙少"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-52","subject":"ya5","topic":"牙科材料學","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"依美國牙醫學會（ADA）建議，牙科用貴金屬合金（noble metal alloy）的黃金含量百分比應為多少？","options":["(A) ＜25%","(B) ≧25%","(C) ≧60%","(D) 有無黃金皆可"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"下列何種橋體（pontic）之設計，其橋體與組織接觸面積最小？","options":["(A) 嵴疊（ridge-lap）橋體","(B) 改良式嵴疊（modified ridge-lap）橋體","(C) 錐形（conical type）橋體","(D) 卵形（ovate type）橋體"],"answer":2,"clinical_level":"重點"},{"id":"ya5-110-2-54","subject":"ya5","topic":"牙科材料學","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"金屬瓷修復體（metal-ceramic restorations）的本體瓷層（body porcelain）和切端瓷層（incisal porcelain）通常 在第一次烤瓷時大約會收縮多少%？","options":["(A) 10～15","(B) 27～45","(C) 60～75","(D) 80～95"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"金屬瓷修復體（metal-ceramic restorations）的製作過程中，素燒（bisque bake）先在口內試戴的目的為何？① 整體外形的評估 ②切緣可以稍作調整 ③測試咬合與發音","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-2-56","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"與直接技術（direct technique）相比，間接技術（indirect technique）製作暫用性固定義齒（interim fixed partial denture）的優點，下列敘述何者正確？①沒有聚合收縮（polymerization shrinkage） ②較精確的牙冠邊緣 ③較快速 ④較簡單","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":0,"clinical_level":"重點"},{"id":"ya5-110-2-57","subject":"ya5","topic":"臨床基礎與倫理","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"如果持續注視某個物體，色彩視覺敏銳度就會迅速下降，使得觀察的物體顏色飽和度持續下降，最後看起來 幾乎是灰色的，此一現象稱為下列何者？","options":["(A) 色覺適應（color adaptation）","(B) 色覺錯誤（deceptive color perception）","(C) 視覺暫留（visual persistence）","(D) 白晝視覺（photopic vision）"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-2-58","subject":"ya5","topic":"植牙贋復","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"檢查多單位義齒支架與植體之密合性時，下列何種方式較佳？","options":["(A) 鎖緊所有支柱螺絲，確認是否支柱與支架間之接縫","(B) 只鎖緊支架一端支柱螺絲後，以手指壓動其他單位測試支架是否穩定","(C) 只鎖緊支架兩端支柱螺絲後，以手指壓動其他單位測試支架是否穩定","(D) 只鎖緊支架中間支柱螺絲後，以手指壓動其他單位測試支架是否穩定"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-59","subject":"ya5","topic":"植牙贋復","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"當植牙區軟硬組織皆出現大量缺損時，下列何種植體贋復方式為較佳選擇？","options":["(A) metal-ceramic restoration","(B) hybrid prosthesis","(C) implant-tooth connection prosthesis","(D) New Taiwan Konus"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-60","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"當患者的左上第一小臼齒及第一大臼齒缺失，欲製作非剛性連接體（nonrigid connector）五個單位的固定牙 橋，楔槽（keyway）放於何處最洽當？","options":["(A) 左上犬齒的遠心側","(B) 左上第二小臼齒的近心側","(C) 左上第二小臼齒的遠心側","(D) 左上第二大臼齒的近心側"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"患者下顎第一大臼齒於青少年時期拔除，導致下顎第二、第三大臼齒向近心側傾斜超過30度，現欲以三單位 固定牙橋重建下顎第一大臼齒缺牙區，下列何者是最佳治療方式？","options":["(A) 於第二大臼齒使用鄰接面半冠設計（proximal half crown）","(B) 於第二小臼齒使用套疊冠設計（telescope crown）","(C) 於第二大臼齒近心側放置楔槽（keyway）","(D) 以矯正方式將臼齒扶正，再進行固定義齒重建"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-62","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"後牙蠟型雕刻時應注意蠟型形狀與鄰牙接觸區（contact area）位置之正確性，下列敘述何者錯誤？","options":["(A) 頰側面觀，大部分後牙之接觸區是位於牙冠近咬合1/3之位置","(B) 自然牙頰舌側外廓高隆線（height of contour）與其牙骨質牙釉質交界（CEJ）之寬度比較，很少大於1 mm","(C) 大部分牙齒的頰舌側外廓高隆線（height of contour）是位於近牙齦1/3之位置","(D) 上顎後牙的頰側楔隙（embrasure）較舌側楔隙為大"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-63","subject":"ya5","topic":"牙科材料學","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"關於磷酸結合（phosphate-bonded）包埋粉，下列敘述何者正確？","options":["(A) 比石膏結合（gypsum-bonded）包埋粉具有較低濃度的耐火材料（refractory materials）","(B) 比石膏結合（gypsum-bonded）包埋粉具有較低的熱膨脹（thermal expansion）","(C) 若含有碳成分，顏色會呈現灰色","(D) 因含有碳成分，所以適用於鑄造賤金屬（base metal）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-110-2-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"鑄造冠在進行靠近邊緣（margin）區域表面的拋光時，拋光輪旋轉方向和牙冠邊緣的關係應呈何種關係？","options":["(A) 30度角","(B) 60度角","(C) 垂直","(D) 平行"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-65","subject":"ya5","topic":"牙科材料學","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"使用下列何種鑄道材較易發生阻擋熔融金屬進入蠟型空間的情況？","options":["(A) 蠟","(B) 塑膠","(C) 金屬","(D) 樹脂"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-66","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"黏著瓷嵌體（ceramic inlay）時，最好使用下列何種黏合劑（cement）？","options":["(A) 磷酸鋅（zinc phosphate）黏合劑","(B) 聚羧酸鋅（zinc polycarboxylate）黏合劑","(C) 玻璃離子體（glass ionomer）黏合劑","(D) 黏著式樹脂（adhesive resin）黏合劑"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-67","subject":"ya5","topic":"咬合學基礎","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"關於口腔顏面肌肉功能的敘述，下列何者正確？①等張收縮（isotonic contraction）常見於關閉下顎咬穿食物 時 ②等長收縮（isometric contraction）常見於上下齒間咬住東西（例如咬鉛筆）時 ③離心收縮（eccentric contraction）意味著肌肉進行收縮時其長度卻伸長","options":["(A) 僅①","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-68","subject":"ya5","topic":"咬合學基礎","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"關於吞嚥與下顎的關聯性，下列何者明顯錯誤？","options":["(A) 完成吞嚥的重要因素之一是維持下顎的穩定，有助舌骨上（suprahyoid）與舌骨下（infrahyoid）肌進行收縮","(B) 對正常成人而言，維持下顎穩定主要仰賴牙齒接觸（tooth contact）","(C) 吞嚥時牙齒接觸的時間，平均而言，遠小於咀嚼時的牙齒接觸","(D) 當開始吞嚥時，舌尖會置於硬顎，位於上顎門齒後方處"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-69","subject":"ya5","topic":"臨床基礎與倫理","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"發送神經訊號到肌梭（muscle spindle），使 intrafusal muscle fiber 收縮的，是下列那一種神經纖維？","options":["(A) afferent fibers Ia","(B) afferent fibers II","(C) efferent fibers α","(D) efferent fibers γ"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-70","subject":"ya5","topic":"咬合學基礎","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"在安格氏第一類咬合關係，下顎進行前突運動（protrusive movement）時，後牙前突接觸點發生處，下列敘述 何者正確？①上顎舌側咬頭遠心斜面接觸對咬牙窩的近心斜面與邊緣嵴 ②下顎頰側咬頭近心斜面接觸對咬 牙窩的遠心斜面與邊緣嵴 ③上顎頰側咬頭近心斜面接觸對咬牙窩的遠心斜面與邊緣嵴 ④下顎舌側咬頭遠 心斜面接觸對咬牙窩的近心斜面與邊緣嵴","options":["(A) ①②","(B) ②③","(C) ③④","(D) ④①"],"answer":0,"clinical_level":"一般"},{"id":"ya5-110-2-71","subject":"ya5","topic":"咬合學基礎","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"關於理想咬合的敘述，下列何者錯誤？","options":["(A) 在最大咬頭嵌合位（maximum intercuspal position），後牙應均勻接觸","(B) 當下顎側向運動（lateratrusive movement）時，側方運動的牙齒接觸點應侷限於前牙接觸","(C) 當下顎前突運動（protrusive movement）時，牙齒接觸點應侷限於前牙接觸","(D) 坐正姿勢（upright head position）時，後牙接觸與前牙接觸輕重應一致"],"answer":3,"clinical_level":"重點"},{"id":"ya5-110-2-72","subject":"ya5","topic":"咬合學基礎","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"有關咬合側向運動（lateral movement）之敘述，下列何者正確？","options":["(A) 犬齒導引（canine guidance）之側向運動有較大的水平向量","(B) 群體功能（group function）之側向運動咬合模式，因咬合力量分散對後牙較具保護機制","(C) 在未經任何矯正或贋復治療下，患者之側向運動可能年輕時為群體功能（group function），年老時卻成為犬 齒導引（canine guidance）","(D) 側向運動模式有可能一側為犬齒導引（canine guidance），另一側為群體功能（group function）"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-73","subject":"ya5","topic":"咬合學基礎","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"關於下顎運動的敘述，下列何者正確？","options":["(A) 本奈氏運動是指下顎功能側髁頭繞中心軸旋轉的運動","(B) 本奈氏角（Bennett angle）是指下顎功能側髁頭向外側移與其前突直線運動的夾角","(C) 本奈氏運動會受到肌肉與關節的影響","(D) 當後牙有較平的咬合面型態時，常被發現髁頭有較為往下也較遲發生的側移（inferior and late lateral side shift）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-110-2-74","subject":"ya5","topic":"咬合學基礎","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"關於成人咀嚼功能的敘述，下列何者錯誤？","options":["(A) 開閉口的路徑在額平面（frontal plane）上的軌跡並不一致","(B) 食物的性質並不影響咀嚼的軌跡","(C) 牙齒數目的變化會影響咀嚼的軌跡","(D) 牙齒咬合面形態的改變會影響咀嚼的軌跡"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-75","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"下列關於磨牙症（bruxism）的敘述，何者錯誤？","options":["(A) 白天清醒時的牙關緊咬現象常被視為一種下顎運動異常功能（parafunction）","(B) 夜間磨牙常發生在深層睡眠過程中","(C) 齒頸部的裂耗（abfraction）和磨牙症可能有關","(D) 可能同時伴有發生阻塞性呼吸終止（obstructive apnea）的情況"],"answer":1,"clinical_level":"重點"},{"id":"ya5-110-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"由本環口攝影片可以推測，該患者最不可能有下列何種問題？","options":["(A) 咬肌肌筋膜疼痛","(B) 捻髮音（crepitation）","(C) 關節彈響（clicking）","(D) 關節張口疼痛"],"answer":2,"image":"ya5-110-2-76.jpeg","clinical_level":"一般"},{"id":"ya5-110-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"關於顳顎關節障礙症的處理，以下敘述何者有誤？","options":["(A) 一般來說，應優先考慮採取可逆（reversible）且較不侵入性（non-invasive）的治療為主","(B) 常用的藥物包含非類固醇的消炎藥（non-steroid anti-inflammatory drugs，NSAID）與肌肉鬆弛劑（muscle relaxants）","(C) 咬合板治療的有效機轉仍未完全明瞭，但是研究顯示其療效（treatment efficacy）可達百分之七十以上","(D) 研究顯示，不可逆的手術治療方式雖具風險，但與長期療效明顯優於保守的可逆治療法"],"answer":3,"clinical_level":"一般"},{"id":"ya5-110-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"下列關於咀嚼肌疼痛的治療，何者錯誤？","options":["(A) 若肌肉痛的原因是因為外傷所引發的保護性肌收縮（protective co-contraction）時，僅需支持療法 （supportive therapy）","(B) 肌肉鬆弛劑對大部分肌疼痛都有明顯療效","(C) 病患應儘量避免硬食","(D) 若疼痛的範圍涵蓋較廣，並且伴隨睡眠障礙，可給予低劑量的三環抗憂鬱藥物（tricyclic antidepressant）"],"answer":1,"clinical_level":"一般"},{"id":"ya5-110-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"下列關於下顎運動受限的敘述，何者正確？①閉口肌痙攣（muscle spasm），將造成張口運動受限 ②不可復 性關節盤移位（disc displacement without reduction），將造成往對側的側方運動受限 ③可復性關節盤移位 （disc displacement with reduction），將造成往對側的側方運動受限 ④顳顎關節上關節腔黏連 （temporomandibular joint ankylosis），將造成張口及側方運動都受限","options":["(A) ①③","(B) 僅②④","(C) ①②④","(D) ②③④"],"answer":2,"clinical_level":"一般"},{"id":"ya5-110-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"使用顳顎關節造影術（temporomandibular joint arthrography）觀察正常人的關節，於閉口時，顯影劑在前下關 節腔之呈像為何？","options":["(A) 圓球狀（spherical shape）","(B) 乙狀彎曲（sigmoid shape）","(C) 淚珠或水滴狀（tear drop）","(D) 水平帶狀向前延伸（horizontal band）"],"answer":2,"clinical_level":"重點"},{"id":"ya5-111-1-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"口腔灼感症候群（burning mouth syndrome）常會影響到口腔黏膜組織的健康狀態，而使得全口無牙患者適應全口義齒不易，下列何者常為造成此症候群的因素？①機械性的刺激（mechanical irritation）②糖尿病（diabetes mellitus）③骨質疏鬆（osteoporosis）④焦慮（anxiety）⑤肌筋膜疼痛（myofascial pain）","options":["(A)①②③④","(B)①②④⑤","(C)①③⑤","(D)僅②④⑤"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-2","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"下顎單顎全口義齒（single complete denture）有時需利用彈性底墊（resilient liner）以降低基底（denture base） 對牙床之壓力，下列關於彈性底墊的敘述何者正確？","options":["(A) 矽膠底墊（silicon liner）較組織調理劑（tissue conditioner）性質不穩定且與壓克力樹脂床（acrylic denture base）之黏著效果佳","(B) 彈性底墊會增加整體義齒基底床之強度","(C) 彈性底墊較易滋生白色念珠菌（candida albicans），應建議患者就寢時將義齒浸泡於具抗菌效果的義齒清潔 劑中","(D) 彈性底墊其生物相容性（biocompatibility）與硬質壓克力樹脂床相似，可以放心長期使用"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-3","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"下列何者為上顎無牙閉孔器（maxillary edentulous obturator）最不能解決的問題？","options":["(A) 改善外觀（facial profile）","(B) 缺乏固位性（retention）","(C) 食物鼻逆流（nasal reflux）","(D) 改善鼻音（hypernasality）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-4","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"下列何種處置對於覆蓋式義齒（overdenture）支柱牙（abutment）齲齒的預防及牙周病的防治最有效？","options":["(A) 使用氟化物（fluoride）","(B) 氟化物（fluoride）和chlorhexidine併用","(C) 使用四環素（tetracycline）","(D) 不需任何藥物"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-5","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"相較於一般的全口義齒，有關覆蓋式義齒（overdenture）優點的敘述，下列何者會影響美觀？","options":["(A) 改善義齒的穩定性（stability）","(B) 改善義齒的固位性（retention）","(C) 保留上顎犬齒可減少殘嵴吸收（resorption）","(D) 提高全口義齒咬力之感受（occlusal stress awareness）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"全口義齒技工製作時，開始進行聚合周期（curing cycle）之前，約須將包埋盒靜置幾分鐘？","options":["(A) 10","(B) 20","(C) 50","(D) 80"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-7","subject":"ya5","topic":"臨床基礎與倫理","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"近年來因社群軟體的發展，牙醫師常將其治療過程之症例照片上傳後，作為與同儕先進討論切磋之用，如未經 患者同意，可能觸犯了倫理學的那一個原則？","options":["(A) 尊重自主原則","(B) 不傷害原則","(C) 行善原則","(D) 正義原則"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-8","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"關於殘嵴的減少（residual ridge reduction），下列敘述何者正確？","options":["(A) 上顎比下顎明顯","(B) 屬於黏滯材料（viscoelastic material）的黏膜骨膜（mucoperiosteum）和海綿骨（cancellous bone）具有吸收 能量的特性，影響殘嵴減少的速率和形態","(C) 適當的垂直高度以提供足夠的休憩間隙（freeway space），無助於降低殘嵴的減少","(D) 殘嵴的減少是骨頭的形成與吸收不平衡所致，因此骨質疏鬆症患者的下顎會較正常人有較明顯的殘嵴減少"],"answer":[1,3],"image":"","clinical_level":"重點"},{"id":"ya5-111-1-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"關於下顎之頰棚（buccal shelf）的敘述，下列何者錯誤？","options":["(A) 其範圍介於下顎頰繫帶（buccal frenum）至咬肌（masseter muscle）之後緣","(B) 由緻密（dense）的皮質骨（cortical bone）組成","(C) 為下顎全口義齒的主要力量承載區（primary stress- bearing area）之一","(D) 外斜嵴（external oblique ridge）是頰棚的外側邊界"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"關於唾液及其對全口義齒的影響，下列敘述何者錯誤？","options":["(A) 正常休息時，唾液流速約 1 ml/minute","(B) 年紀是影響唾液分泌的主要因素（primary factor）","(C) 配戴上顎義齒多年可能會破壞腭腺體（palatal gland）","(D) 黏稠的唾液容易讓義齒脫落（dislodge）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-11","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"有關翼下顎縫（pterygomandibular raphe）之敘述，下列何者錯誤？","options":["(A) 為界於下咽縮肌（inferior pharyngeal constrictor muscle）與頰肌（buccinator muscle）之間的結構","(B) 限制下顎活動義齒向後延伸","(C) 其下方與臼齒後墊（retromolar pad）相連","(D) 其上方與上顎粗隆（tuberosity）相連"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"下圖為全口無牙之上顎解剖形態圖，在代號 12 部位之名稱為何？","options":["(A) 唇繫帶（labial frenum）","(B) 唇前庭（labial vestibule）","(C) 門齒乳頭（incisive papilla）","(D) 中腭縫（median palatine raphe）"],"answer":2,"image":"ya5-111-1-12.jpeg","clinical_level":"一般"},{"id":"ya5-111-1-13","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"臨床上製作全口義齒時，決定適當咬合垂直高度的方法，下列何者最不常使用？","options":["(A) 下顎生理靜止位置（rest position）之觀察","(B) 咬合力測試","(C) 整體顏面外觀評估","(D) 發S音的說話空間（speaking space）評估"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-14","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"製作全口義齒時，使用面弓（facebow）的敘述，下列何者錯誤？","options":["(A) 全口義齒製作時為避免造成咬合錯誤，面弓轉移是必要的","(B) 使用面弓轉移與不使用作比較，不一定能產生較佳的臨床結果","(C) 使用面弓將下顎模型定位到咬合器上","(D) 面弓可分為髁桿型（condyle rods）與耳桿型（ear rods），使用的臨床結果無明顯差異"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-15","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"關於全口義齒中心關係位置紀錄（centric relation record）之敘述，下列何者錯誤？","options":["(A) 基底的穩定，是取得正確義齒中心關係位置紀錄的首要條件","(B) 可使用義齒黏著劑幫助基底固位","(C) 垂直高度不影響義齒中心關係位置的記錄","(D) 臉部神經肌肉受損，會影響咬合紀錄之取得"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-16","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"關於全口無牙患者人工牙的選擇，下列敘述何者最正確？","options":["(A) 在印模的階段就要進行選牙","(B) 只需要選擇牙齒顏色即可","(C) 選擇牙齒的寬度比長度重要","(D) 下顎臼齒區骨頭高度喪失量最少，故要選用較短的臼齒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"排列全口義齒上顎門齒時，常以門齒乳頭（incisive papilla）作為參考點，下列敘述何者錯誤？","options":["(A) 門齒乳突與自然齒列正中門齒的相關位置相當穩定","(B) 自然齒列上顎正中門齒的切緣唇側大約在門齒乳頭中心前方 8 至 10 mm","(C) 若齒槽骨嵴嚴重垂直吸收，全口義齒上顎正中門齒的唇側與門齒乳頭的距離會稍微增加","(D) 自然齒列上顎兩側犬齒尖的連線，大約穿過門齒乳頭的後緣約 5 mm 的位置"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"排列下顎全口義齒，最遠心後牙應止於何處？","options":["(A) 水平齒槽嵴往上傾斜前","(B) 臼齒後墊（retromolar pad）之前緣","(C) 第二大臼齒","(D) 犬齒遠心側 25 mm處"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-19","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"當依循平面咬合（monoplane occlusion）觀念，並選用零度牙製作全口義齒時，下列排牙前準備工作何者正 確？①只需要上下顎的中心關係（centric relation）咬合紀錄 ②需要中心關係以及前突（protrusive）的咬合 紀錄 ③可以僅使用簡單型咬合器（simple articulator） ④應使用半調節式咬合器（semiadjustable articulator）","options":["(A) ①③","(B) ①④","(C) ②④","(D) ②③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-20","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"若採用平面咬合（monoplane occlusion）模式製作全口義齒，下列敘述何者錯誤？","options":["(A) 具異功能咬合習慣（parafunctional habits）患者，可減少全口義齒基底的側方壓力","(B) 下顎運動不協調者，如帕金森氏症（Parkinson's disease）患者，適合使用此類全口義齒","(C) 相對於有咬頭之後牙（cusped teeth），小臼齒比較容易產生不自然的外觀","(D) 相對於有咬頭之後牙（cusped teeth），可大幅提高咀嚼效率"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-21","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"全口無牙患者會因為殘嵴吸收以及下顎習慣位置的改變，造成義齒整體的移動。關於下顎旋轉運動（rotary movement）可能發生的現象，下列敘述何者錯誤？","options":["(A) 不影響義齒中心關係咬合（centric relation occlusion）","(B) 造成支持上顎義齒的結構組織改變","(C) 使下顎義齒向後移動，撞擊到下顎殘嵴","(D) 使下顎向前移動，造成下顎前突"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-22","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"全口義齒配戴一段時間後，患者會因為殘嵴吸收或是咬合問題，而抱怨義齒鬆動或者是咀嚼效率不佳，下列 診斷與處理何者錯誤？","options":["(A) 當義齒的密合度沒問題時，需進行咬合調整","(B) 當義齒在口內有1～2mm移動量與些許晃動（rocking）時，需更換基底（rebasing）","(C) 當口內因配戴義齒而造成廣泛性疼痛時，要懷疑義齒咬合垂直高度喪失，需重建咬合垂直高度","(D) 當患者殘嵴吸收比較多，觀察後發現其下顎義齒往前及往上位移過多，需重建其咬合位置"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"下列有關可撤式局部義齒中RPI的敘述，何者最正確？","options":["(A) R表示鈎靠（rest），通常放於遠心側","(B) P表示舌側板（lingual plate），須距牙齦緣（gingival margin）4 mm","(C) I表示I型槓（I bar），其尖端通常放在支柱牙牙冠距牙齦緣 0.5 mm處","(D) 分類上屬於膨下位型（infrabulge type）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"關於可撤式局部義齒下顎舌側槓主連接體（lingual bar major connector）的敘述，下列何者錯誤？","options":["(A) 病人下顎牙齦緣至口底間至少需8 mm之距離方可使用","(B) 若病人前牙齒槽骨嵴（alveolar ridge）之舌側面為一緩坡（slope），舌側槓主連接體與其下之軟組織間不需 緩壓（relief）","(C) 舌側槓主連接體約需4 mm寬","(D) 舌側槓主連接體之橫切面為半梨型（half-pear shape）"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-111-1-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"有關可撤式局部義齒的主要結構中，牙鈎組合不包含那些？①鈎靠 ②鈎座 ③小連接體 ④固位性鈎臂 ⑤拮抗性鈎臂 ⑥主連接體","options":["(A) ①②","(B) ④⑤","(C) ②⑥","(D) ①③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"下列影響可撤式局部義齒牙鈎臂（clasp arm）固位力（retention）的因素那些正確？①口內的溫度 ②牙鈎臂 的斷面型態（cross-section form） ③牙鈎臂的長度 ④義齒基底床的負壓（negative pressure） ⑤熱處理","options":["(A) ①③","(B) ①②⑤","(C) ②③④","(D) ②③⑤"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-27","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"下列有關可撤式局部義齒牙鈎組成中各部分（clasp assembly parts）的敘述，何者錯誤？","options":["(A) 鈎靠（rest）可能位於咬合面、舌側或切端緣，主要是提供支持（support）","(B) 小連接體（minor connector）主要是提供固位（retention）作用","(C) 牙鈎固持（retention）部分，一般是位於支柱牙齒冠部近牙齦三分之一的倒凹處","(D) 牙鈎穩定或抗衡（stabilization or reciprocation）部分，一般是位於支柱牙齒冠中三分之一處"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"製作可撤式局部義齒時，將會搖動的後牙以製作牙冠的方式和鄰接牙固定（splinting）起來後，對於前後向應 力（anteroposterior stress）和側方受力（lateral force）的抵抗能力，下列敘述何者最正確？","options":["(A) 對側方受力的抵抗能力大，對前後向應力的抵抗能力小","(B) 對側方受力的抵抗能力小，對前後向應力的抵抗能力大","(C) 對側方受力和前後向應力的抵抗能力均大為增加","(D) 對側方受力的抵抗能力大，對前後向應力的抵抗能力則沒有改變"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"除了牙鈎（clasp）之外，下列那些機制可以增加可撤式局部義齒之固持力（retentive force）？①增加義齒邊 緣之厚度 ②增加義齒基底與無牙區黏膜之適合度（fittness） ③增加引導面與局部義齒間的摩擦力 ④改 善患者神經肌肉系統之控制 ⑤非單一的置入途徑","options":["(A) ①②③","(B) ③④⑤","(C) ②③④","(D) ①②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-30","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"有關可撤式局部義齒上顎兩側遠伸性（distal extension）的敘述，下列何者錯誤？","options":["(A) 支柱牙可用I型槓（I-bar）做直接固位體（direct retainer）","(B) 應使用瓊膠水膠質（agar hydrocolloid）做功能性印模（functional impression）","(C) 上顎義齒支架要做緣飾（beading）","(D) 可用全覆蓋腭板（complete palate）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"可撤式局部義齒（removable partial denture）製作時析量器（surveyor）的操作，尋找置入及取出途徑（path of insertion and removal）時，下列何者為最正確的考量步驟？ ①鈎靠（rest）位置的考慮 ②固位倒凹 （retentive undercut）的提供 ③引導面（guiding plane）的考量 ④軟組織及硬組織的干擾","options":["(A) ③→②→④→①","(B) ③→④→①→②","(C) ②→③→①→④","(D) ②→④→①→③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-32","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"製作可撤式局部義齒時，診斷模型經過析量後，支柱牙需要進行的修磨順序為下列何者？ ①引導面 （guiding plane）修磨 ②牙齒形狀修正以得到正確抱持（bracing）及固位（retention） ③鈎座（rest seat） 修磨。","options":["(A) ①②③","(B) ③①②","(C) ①③②","(D) ③②①"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-33","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"甘迺迪分類（Kennedy classification）對齒列缺牙所依循的Applegate法則（Applegate's rules）中，下列敘述何 者錯誤？","options":["(A) 若第三大臼齒缺失，且不打算予以補綴時，則該缺牙不列入分類時的考量","(B) 甘迺迪分類由最後端的缺牙（區）來決定","(C) 變異型（modification）的數字為主要缺牙區以外，其他缺牙區的數目","(D) 甘迺迪第三類（Kennedy Class III）齒弓，不具變異型（modification）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-34","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"以甘迺迪分類（Kennedy classification）描述可撤式局部義齒分類的最大優點為下列何者？","options":["(A) 強調後牙區的缺牙","(B) 此分類法由大多數國家使用，有助於可撤式局部義齒的設計","(C) 此分類法可明確指出缺牙的區域與缺牙的數目","(D) 此分類法是根據對咬的關係訂定"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-111-1-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"製作可撤式局部義齒時，下列何種缺牙情況最常使用修正模型印模技術（altered cast impression technique）？","options":["(A) 上顎甘迺迪第 I 類（Kennedy Class I）缺牙","(B) 下顎甘迺迪第 I 類（Kennedy Class I）缺牙","(C) 上顎甘迺迪第 IV 類（Kennedy Class IV）缺牙","(D) 下顎甘迺迪第 III 類（Kennedy Class III）缺牙"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"利用鑄造完成之金屬支架，製作下顎雙側遠伸性可撤式局部義齒缺牙之無牙區印模牙托時，下列那項處置最 不適當？","options":["(A) 金屬支架必須於口腔中試戴完成","(B) 牙托必須深入倒凹區","(C) 牙托邊緣必須比前庭深處短2 mm","(D) 牙托之組織面必須適度緩壓（relief）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-37","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"患者之上、下顎都只剩6顆前牙，則製作可撤式局部義齒咬合面時，下列何者可以變動？①咬合平面 （occlusal plane） ②補償曲線（compensating curve） ③髁導引（condylar guidance） ④門齒導引 （incisal guidance） ⑤後牙牙尖高度（cusp height）","options":["(A) ①②⑤","(B) ①③④","(C) ②③⑤","(D) ②③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-38","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"下列何種情況較不需要藉助平衡性咬合（balanced occlusion）來增加可撤式局部義齒的穩定性？","options":["(A) 上顎全口義齒，下顎甘迺迪第一類（Kennedy Class I）可撤式局部義齒","(B) 上顎甘迺迪第一類（Kennedy Class I）可撤式局部義齒，下顎甘迺迪第一類（Kennedy Class I）可撤式局部 義齒","(C) 上顎甘迺迪第一類（Kennedy Class I）可撤式局部義齒，下顎甘迺迪第二類（Kennedy Class II）可撤式局部 義齒","(D) 上顎甘迺迪第二類（Kennedy Class II）可撤式局部義齒，下顎甘迺迪第一類（Kennedy Class I）可撤式局部 義齒"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-39","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"患者配戴可撤式局部義齒而對咬單顎全口義齒的狀況下，排牙時應該提供何種咬合關係以獲得較佳的穩定 性？","options":["(A) 平衡性咬合（balanced occlusion）","(B) 群體功能性咬合（group function）","(C) 犬齒導引咬合（canine guidance occlusion）","(D) 依患者的喜好"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-40","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"下列何者不是造成患者使用可撤式局部義齒時，常常咬頰（cheek biting）的主要原因？","options":["(A) 上顎義齒牙排得太內側","(B) 下顎義齒牙排得太外側","(C) 咬合平面（occlusal plane）太低","(D) 病人缺牙太久"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"清潔可撤式局部義齒之化學藥劑中，何者具有便宜、方便、無酸味又不傷金屬支架之優點？","options":["(A) 鹼性過氧化物（alkaline peroxide）","(B) 次氯酸（hypochlorite）","(C) 食用醋","(D) 酵素清潔劑（enzyme cleaners）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-42","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"鑄造活動義齒支架（framework）使用的金屬、翻模的材料和灌出翻模的包埋材料會影響義齒支架的密合度， 下列何項組合最佳？","options":["(A) 低溫合金（lower-heat alloy）＋可逆性水凝膠（reversible hydrocolloid）＋石膏系包埋粉（gypsum-bonded investments）","(B) 低溫合金（lower-heat alloy）＋甘油基底膠體（glycerin-based colloid）＋磷酸系包埋粉（phosphate-bonded investments）","(C) 高溫合金（high-heat alloy）＋甘油基底膠體（glycerin-based colloid）＋石膏系包埋粉（gypsum-bonded investments）","(D) 高溫合金（high-heat alloy）＋可逆性水凝膠（reversible hydrocolloid）＋磷酸系包埋粉（phosphate-bonded investments）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"關於可撤式局部義齒鑄道（sprue）設計的敘述，下列何者錯誤？","options":["(A) 鑄道要直接且愈短愈好","(B) 所有輔助（auxillary）及次級（secondary）鑄道和主鑄道（main sprue）相接，都應在同一高度上","(C) 所有彎曲要柔順圓滑，且避免粗糙及銳角","(D) 和蠟型（wax pattern）之夾角約90度"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-44","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"製作可撤式局部義齒時，有關上顎模型珠緣（beading）之敘述，下列何者錯誤？","options":["(A) 確保主連接體（major connector）和腭組織（palatal tissue）能緊密接觸","(B) 提供鑄造物清楚明確的終接線（finishing line）","(C) 便於轉移設計到耐火模型（refractory cast）","(D) 珠緣的寬度及深度應為1.0 mm以上"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"有關上顎小臼齒金屬3/4部分鑲面牙冠（three quarter partial veneer crown）支柱牙修磨的敘述，下列何者正 確？①頰－咬合面線角（bucco-occlusal line angle）可以修磨成斜面（beveled）或弧形（chamfer）邊緣 ②鄰 接溝（proximal groove）的深度在齒頸部至少為1.2 mm ③使用錐形（tapered）磨針修磨出鄰接溝 ④鄰接 溝理想的長度為3 mm","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"有關⾦屬嵌體（inlay）牙齒修磨的敘述，下列何者正確？①邊緣與鄰接牙最好有⾄ 少1.2 mm間隙以利取模 ②咬合⾯鴿尾形（occlusal dovetail）修磨有利嵌體抵抗往功能性咬頭⽅向的位移 ③牙齒修形的頰側壁與舌側壁提供嵌體主要的固著⼒ （retention） ④鄰接箱（proximal box）的牙齦底（gingival floor）近遠⼼寬度約 1.0 mm","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④ "],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-47","subject":"ya5","topic":"植牙贋復","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"Albrektsson等人於1986年提出人工植牙在義齒完成1年後，如果往後每年平均有超過多少 mm以上的邊緣骨垂 直喪失，就必須檢查潛在的問題？","options":["(A) 0.2","(B) 0.5","(C) 1.0","(D) 2.0"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-48","subject":"ya5","topic":"植牙贋復","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"全顎植體固定義齒（complete fixed implant prosthesis）在設計金屬支架時，下列那一種支架斷面設計最不常使 用？","options":["(A) L-shape","(B) I-shape","(C) E-shape","(D) elliptical"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-49","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"患者牙周狀況良好，上顎右側正中門齒水平斷裂至與牙齦等高，確認工作長度（working length）仍有17 mm，經根管治療（root canal treatment）後，需要重建，下列何者是最恰當的重建方式？","options":["(A) 直接製作牙冠","(B) 使用牙冠增長術（crown lengthening procedure）後製作牙冠","(C) 將牙根強逼萌出（forced eruption）合併牙冠增長術（crown lengthening procedure）後製作牙冠","(D) 將斷裂牙根拔除，植入人工牙根重建"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-50","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"患者缺少右側下顎第二小臼齒、第一大臼齒及第二大臼齒，以第一小臼齒與第三大臼齒為支柱牙的固定牙橋 重建後，可能遇到的問題為何？①瓷面破裂 ②金屬支架斷裂 ③支柱牙斷裂 ④支柱牙鬆脫 ⑤橋體下方 軟組織發炎","options":["(A) ①②③④⑤","(B) 僅①②③","(C) 僅①③④","(D) 僅②④⑤"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-51","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"進行多顆固定義齒重建時，常需要進行選擇性咬合調整以去除咬合干擾，對於安格氏一級咬合（Angle's class I occlusion）患者，下列那個位置應避免修磨？","options":["(A) 上顎後牙的頰側咬頭","(B) 上顎後牙的邊緣嵴","(C) 下顎後牙的頰側咬頭","(D) 下顎後牙的邊緣嵴"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-52","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"關於石膏硬化劑（gypsum hardener）的敘述，下列何者正確？","options":["(A) 可以明顯改善石膏的抗磨損能力（abrasion resistance）","(B) 會降低石膏之硬化膨脹（setting expansion）","(C) 可以明顯增加石膏之硬度（hardness）","(D) 會明顯增加石膏之硬化膨脹（setting expansion）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-53","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"包埋蠟型時，蠟型頂端到鑄造環頂端之間的距離至少應為多少mm？","options":["(A) 2","(B) 4","(C) 6","(D) 8"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-54","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"有關包埋粉（investment）的敘述，下列何者正確？","options":["(A) 磷酸結合（phosphate-bonded）包埋粉用來鑄造American Dental Association Type I的金合金","(B) 矽土結合（silica-bonded）包埋粉主要用在固定義齒的鑄造","(C) 石膏結合（gypsum-bonded）包埋粉用來鑄造金屬瓷牙橋（metal-ceramic bridge）之金屬支架","(D) 包埋粉可用結合劑（binder）的種類來分類"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"下列何者最不可能是金屬瓷修復體（metal-ceramic restoration）瓷破裂之原因？","options":["(A) 咬合力過重","(B) 對咬牙為樹脂修復體","(C) 義齒支架設計不當","(D) 意外撞擊"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-111-1-56","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"正常情況下，有關下顎運動的波賽特圖形（Posselt's diagram）（如下圖）之敘述，下列何者錯誤？","options":["(A) 點1到點0之間是「最大咬頭嵌合－顎中心關係」差異（MIC-CR discrepancy）","(B) 由點1到點2的移動主要受上顎前牙腭側面形態的影響","(C) 由點6到點7的移動，關節髁頭（condyle head）的運動包括位移及旋轉","(D) 由點7到點0的移動，與咀嚼運動有關"],"answer":3,"image":"ya5-111-1-56.jpeg","clinical_level":"一般"},{"id":"ya5-111-1-57","subject":"ya5","topic":"臨床基礎與倫理","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"進行印模時如須抑制病患口水分泌，下列那些疾病患者不宜使用抗膽素激性（anticholinergic）類藥物，如 Robinul（Glycopyrrolate）？①青光眼（glaucoma） ②心血管疾病 （cardiovascular disease） ③胃潰瘍 （gastric ulcer）","options":["(A) ①②③","(B) 僅①②","(C) 僅②③","(D) 僅①③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-58","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"下列何種消毒劑適合用在加成性矽膠（addition silicone）與聚乙醚（polyether）兩種印模材之消毒？","options":["(A) 酚類（phenolics）","(B) 碘化合物（iodophors）","(C) 2%活化鹼性戊乙醛（glutaraldehyde）","(D) 氯化合物（chlorine compounds）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-59","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"根管治療過的後牙，若齒質厚度足夠，且牙髓腔能提供冠心（core）足夠的固持力，則牙齦以上至少具有多 少齒質高度時，就可不必放置根柱（post）？","options":["(A) 1.5 mm","(B) 3 mm","(C) 4.5 mm","(D) 6 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-60","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"關於卵圓形橋體（ovate pontic）的設計與操作，下列敘述何者錯誤？","options":["(A) 拔牙時應做牙嵴保存補骨手續（site preservation grafting procedure）","(B) 拔牙後立即將卵圓形橋體伸入拔牙後齒槽（extraction socket）2.5 mm左右","(C) 拔牙後四週，要將卵圓形橋體伸入深度減為1.5 mm","(D) 最終牙橋卵圓形橋體底下，齒槽骨上的理想牙齦厚度應維持在1.0～1.5 mm範圍內"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"在金屬瓷冠上置放咬合面鈎座（occlusal rest seat）時，其位置與金屬瓷交界（metal-ceramic junction）的關係 應為何？","options":["(A) 在交界上","(B) 距交界1 mm，在瓷上","(C) 距交界0.5 mm，在金屬上","(D) 距交界1 mm，在金屬上"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-62","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"在瓷牙用的賤金屬（base metal alloys）中，下列何者不是加入鈹（Beryllium）的目的？","options":["(A) 增加強度","(B) 降低熔點","(C) 增加表面金屬氧化層的厚度，以促進瓷與金屬之結合","(D) 增加金屬鑄造時的流動性"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-63","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"將已完成外形而未經過上釉（glazing）的瓷，加熱至融合溫度，並在降溫前維持一段時間，瓷表面會產生熱 塑性流動的過程，稱為下列何者？","options":["(A) 外加式釉化（overglazing）","(B) 自體釉化（autoglazing）","(C) 加成式釉化（addglazing）","(D) 覆蓋式釉化（coverglazing）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"為避免金屬在烤瓷的過程中變形，金屬瓷修復體（metal-ceramic restorations）的金屬層厚度至少須為多少 mm？","options":["(A) 0.2～0.3","(B) 0.5～0.7","(C) 1.0～1.5","(D) 1.5～2.0"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-65","subject":"ya5","topic":"牙科材料學","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"金屬瓷合金（metal-ceramic alloys）的折斷強度約為一般聚甲基丙烯酸甲脂（polymethyl methacrylate）的多少 倍？","options":["(A) 10","(B) 20","(C) 30","(D) 40"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-66","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"在比色時，於蒙塞氏色系（Munsell color order system）的向度中，最不應該先選擇是那一項？","options":["(A) 明度（value）","(B) 色度（chroma）","(C) 色相（hue）","(D) 色溫（color temperature）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-67","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"關於顳顎關節（temporomandibular joint）的敘述，下列何者正確？","options":["(A) 部分翼外肌附著於顳顎關節之關節面（articular surface）","(B) 莖突下顎韌帶（stylomandibular ligament）可於顎運動時穩定髁頭與關節突起","(C) 翼內肌（medial pterygoid muscle）協助張口","(D) 顳顎關節盤（articular disc）位於下顎窩（mandibular fossa）及下顎骨之髁突（condylar process）之間"],"answer":3,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-111-1-68","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"關於異位痛（heterotopic pain）的概念在臨床上的應用，下列何者正確？①治療時應著重在痛源（source of pain）而非痛處（site of pain） ②對痛源進行局部刺激（local provocation），往往可見疼痛經驗明顯升高。 另一方面，刺激痛處的影響則較不大 ③對痛處（而非痛源）進行局部麻醉，對減緩疼痛的效果不大","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-69","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"有關咀嚼運動的神經控制之敘述，下列何者錯誤？","options":["(A) 三叉神經系統之中腦核（mesencephalic nucleus）在實驗動物中摘除後，就失去咀嚼動作的能力","(B) 當咀嚼吃到硬物或發生疼痛的情形時，急速的閉口停止屬於負向回饋（negative feedback）","(C) 當咬到較硬的食物時，原本不明顯的閉口肌活動會突然加大，以達到粉碎食物的功用屬於正向回饋 （positive feedback）","(D) 臨床上牙痛的病人在經過填補或牙髓抽除的治療之後，仍常見病人維持逃避的咀嚼方式一段時間"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-70","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"關於前篩板（anterior jig）主要功用的描述，下列何者正確？","options":["(A) 用於取得中心關係（centric relation）","(B) 用於治療顳顎關節障礙症（TMD）","(C) 用於測量垂直咬合高度（vertical dimension of occlusion）","(D) 用於協助評估假牙病患發音（phonation）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-71","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"安格氏第一型關係（Angle's class I relationship）於中心咬合（centric occlusion）時，左下第一大臼齒之遠心頰 側咬頭（distal buccal cusp）對咬於下列那個位置？","options":["(A) 左上第二小臼齒遠心邊緣嵴（distal marginal ridge）與左上第一大臼齒近心邊緣嵴（mesial marginal ridge）","(B) 左上第一大臼齒中心窩（central fossa）","(C) 左上第一大臼齒遠心邊緣嵴（distal marginal ridge）與左上第二大臼齒近心邊緣嵴（mesial marginal ridge）","(D) 左上第一大臼齒近心窩（mesial fossa）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-72","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"正常情況下，當下顎進行前突運動（protrusive movement）時，後牙可能的接觸狀況，下列那個斜面 （incline）會碰觸對咬牙的咬窩（fossa）與邊緣嵴（marginal ridge）？","options":["(A) 上顎頰側咬頭的遠心斜面","(B) 上顎頰側咬頭的近心斜面","(C) 上顎舌側咬頭的遠心斜面","(D) 上顎舌側咬頭的近心斜面"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-73","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"關於髁頭（condyle head）中心關係（centric relation）位置的敘述，下列何者錯誤？","options":["(A) 關於中心關係位置有很多種說法，一般而言與咬頭嵌合位置略有不同","(B) 髁頭接近最後最上之終軸位置（terminal hinge position），常受到顳顎韌帶（TM ligament）與關節盤後緣厚 度之限制","(C) 中心關係重複取得性高，位置的起始運動軸線接近單純的旋轉軸","(D) 後縮接觸位置（retruded contact position），是指髁頭位於中心關係，但牙齒並未發生接觸時的位置"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-1-74","subject":"ya5","topic":"咬合學基礎","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"下顎側向運動時，非工作側髁頭往內往前的運動是受到那條肌肉的影響？","options":["(A) 深層嚼肌","(B) 外翼肌","(C) 內翼肌","(D) 二腹肌"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"顳顎關節單聲彈響（single click）如果發生在開口運動的時期，最可能為下列何種顳顎關節障礙症的初期症 狀？","options":["(A) 顳顎關節炎（TMJ arthritis）","(B) 顳顎關節內部紊亂（internal derangement）","(C) 退行性顳顎關節疾病（degenerative TM joint disease）","(D) 顳顎關節半脫位（Subluxation）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"頭頸部肌筋膜痛（myofascial pain）的症狀有那些？①口腔顏面的痠痛 ②咀嚼肌壓痛 ③主動張口（active opening）小於 40 mm ④在運動範圍內有關節噪音（joint noise）","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"關於前置位咬合板（anterior positioning splint）的敘述，下列何者正確？①藉由此裝置改善關節聲響及疼痛 ②製作前置位咬合板時，當下顎前牙接觸前止位（anterior stop）時，無論下顎後牙有無接觸咬合板，只要能 達到關節症狀改善的情況，就可用自凝式壓克力樹脂（autocuring acrylic resin）重襯（reline）咬合面 ③藉 由下顎往前來達到理想髁頭與關節盤的關係（condyle-disc relationship） ④晚上睡覺時配戴上顎或下顎之前 置位咬合板，都能達到相同治療效果","options":["(A) 僅①③","(B) 僅①②③","(C) 僅①③④","(D) ①②③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"關於顳顎障礙症（temporomandibular disorders）治療方式的選擇為下列何者？①應以症狀治療為導向 ②應 以恢復正常解剖結構為導向 ③應以證據支持為導向 ④應以根治為導向","options":["(A) 僅①③","(B) 僅②④","(C) 僅①③④","(D) ①②③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"關於急性（acute）不可復性關節盤移位（disc displacement without reduction）的敘述，下列何者正確？①最大 開口約25-30 mm ②開口時下顎偏向患側 ③在最大開口時呈現有彈性的最終感覺（elastic end feel ) ④往 患側同一側做側方運動時，會受到限制","options":["(A) 僅①②","(B) ③④","(C) ①②③","(D) ①②④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"有關顳顎關節內部紊亂（internal derangement）之敘述，何者錯誤？","options":["(A) 可能表示關節盤移位","(B) 下顎運動時，顳顎關節常會出現輾軋音（crepitus sound）","(C) 為顱顎障礙症之臨床症狀之一","(D) 可影響下顎張口程度"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-111-2-1","subject":"ya5","topic":"臨床基礎與倫理","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"關於口腔結構的敘述，下列何者正確？","options":["(A) 硬腭和軟腭都是靜止不動的結構，可將口腔與鼻腔區隔","(B) 正常狀況下應同時以鼻腔和口腔來進行吸氣和呼氣","(C) 舌頭在呼吸、說話及咀嚼時扮演重要的角色","(D) 軟腭和咽壁（pharyngeal walls）可以形成咽腭帆關閉（velopharyngeal closure），說話時才不會造成鼻音過 重"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"謝格連氏症候群（Sjögren's syndrome）的病人，對於食物味覺（taste）及敏感度（sensitivity）的改變，下列敘 述何者錯誤？","options":["(A) 可能感覺食物有金屬（metallic）的味道","(B) 可能感覺食物有鹹（salty）的味道","(C) 可能對於酸性的（sour）食物敏感度降低","(D) 可能對於甜性的（sweet）食物敏感度降低"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"當以環口X光攝影（panoramic radiography）檢查全口無牙患者時，下列位置何者最難以辨識？","options":["(A) 上顎前牙區是否有埋伏齒","(B) 上顎頰側前庭（buccal vestibule）的深淺","(C) 頦孔（mental foramen）在下顎骨的相對位置","(D) 下顎管（mandibular canal）的走向"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"關於下顎全口義齒邊緣（border）的敘述，下列何者錯誤？","options":["(A) 頦肌（mentalis muscle）限制唇側凸緣的長度","(B) 口輪匝肌（orbicularis oris muscle）限制唇側凸緣的寬度","(C) 頰肌（buccinator muscle）限制義齒之遠伸性（distal extention）","(D) 下顎枝（mandibular ramus）限制義齒之遠伸性（distal extention）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"關於下顎全口義齒後頰側凸緣（posterior buccal flange）、後舌側凸緣（posterior lingual flange）之長度，下列 敘述何者正確？①咬肌（masseter muscle）決定後頰側凸緣的長度 ②頰肌（buccinator muscle）決定後頰側凸 緣的長度 ③下顎舌骨肌（mylohyoid muscle）決定後舌側凸緣的長度 ④頦舌骨肌（geniohyoid muscle）決定 後舌側凸緣的長度","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-6","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"下列何者是造成下顎唇側溝（labial sulcus）變淺的主要肌肉？","options":["(A) 頦肌（mentalis muscle）","(B) 降下唇肌（depressor labii muscle）","(C) 口輪匝肌（obicularis oris muscle）","(D) 頰肌（buccinator muscle）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-7","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"臉頰嘴角兩側肌肉匯聚成渦輪（modiolus），渦輪的形成與全口義齒咬合平面定位有關。下列何者非形成渦輪 的肌肉？","options":["(A) 頰肌（buccinator muscle）","(B) 顴大肌（zygomaticus major muscle）","(C) 笑肌（risorius muscle）","(D) 三角肌（triangularis muscle）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"關於全口義齒須重置位（remount）的時機，下列何者錯誤？","options":["(A) 排牙後試戴，發現垂直高度太高","(B) 義齒煮聚完成後","(C) 戴入患者口內，發現咬合錯誤","(D) 試戴時基底不穩"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"由美觀方法來測試全口無牙患者垂直高度時，下列敘述何者錯誤？","options":["(A) 美觀確實會受到上、下顎垂直關係所影響","(B) 比較唇部和臉部其他部分皮膚外觀，可作為指標","(C) 一開始做出咬合堤的唇面外形用來取代或恢復其組織支持的豐隆度","(D) 咬合堤沒有正確的唇部支持也沒有關係，只要增加垂直高度即可解決問題"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"在考量功能和美觀的因素下，上顎犬齒和第一小臼齒之間的空隙小於多少 mm 時不必調整犬齒的角度？","options":["(A) 1.0","(B) 1.5","(C) 2.0","(D) 2.5"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-11","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"下列何者是選擇全口義齒後牙區咬頭傾斜平面（inclined plane）最理想的參考因素？","options":["(A) 咬合力量","(B) 垂直高度","(C) 髁導引","(D) 牙嵴型態"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-12","subject":"ya5","topic":"牙科材料學","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"關於人工牙齒材料的選擇，下列何者錯誤？","options":["(A) 瓷牙（porcelain teeth）具有顏色穩定的特點","(B) 瓷牙和假牙基底之間容易有染色","(C) 空間不足時適用丙烯酸牙齒（acrylic teeth）","(D) 丙烯酸複合牙齒（acrylic composite teeth）與假牙基底的結合最好"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-13","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"依循平衡咬合（balanced occlusion）觀念並選用解剖形態人工牙製作全口義齒時，下列敘述何者錯誤？","options":["(A) 需要中心關係（centric relation）紀錄、面弓轉移以及前突（protrusive）的咬合紀錄","(B) 宜使用半調節式咬合器（semiadjustable articulator）","(C) 比起平面咬合模式，排牙過程較耗時","(D) 比起平面咬合模式，前牙排列的位置比較沒有限制"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"關於全口義齒咬合模式（occlusal scheme）與人工牙齒選擇的敘述，下列何者錯誤？","options":["(A) 若採用舌側咬合（lingualized occlusion）模式，下顎後牙可選擇使用零度牙","(B) 若採用平面咬合（monoplane occlusion）模式，可選擇使用零度牙","(C) 使用零度牙配合補償曲線（compensating curve），仍無法達成平衡咬合（balanced occlusion）","(D) 選擇解剖形態的人工牙齒較易達成平衡咬合（balanced occlusion）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"若全口義齒患者在回診時，發現殘嵴的斜坡上（slope）有疼痛現象出現時，此時對患者相對應的義齒，應該 要做何種處理措施？","options":["(A) 修短義齒的邊緣長度","(B) 修磨上顎義齒頰側咬頭之頰側面","(C) 修磨前突運動產生的干擾","(D) 修磨太重的平衡側咬合"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"若全口義齒配戴者抱怨吞嚥時會疼痛，則疼痛的區域最不可能的是下列何處？","options":["(A) 鈎狀切（hamular notch）","(B) 軟腭（soft palate）","(C) 臼齒後墊（retromolar pad）","(D) 下顎舌骨嵴（mylohyoid ridge）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"下列關於即裝全口義齒（immediate complete denture）排牙工作的敘述，何者錯誤？","options":["(A) 須拔除的牙齒雖多半已移位，但對未來排牙的位置仍具參考價值","(B) 牙周囊袋的深度為修磨模型的重要參考之一","(C) 修磨模型宜保守","(D) 拔牙處宜修磨成凹陷狀"],"answer":3,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-111-2-18","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"選擇上顎前牙作為覆蓋式義齒的支柱牙時，下列何者最不易產生組織倒凹而使義齒不易置入的問題？","options":["(A) 正中門齒","(B) 側門齒","(C) 犬齒","(D) 選用以上牙齒都無組織倒凹的問題"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-19","subject":"ya5","topic":"植牙贋復","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"下列那項不是牙科植體成功的必備要件？","options":["(A) 植體周圍沒有感染","(B) 植入後，每年的平均垂直骨喪失小於 0.3 mm","(C) 個別植體不會有生理性搖動","(D) 植體周圍沒有放射線穿透性影像"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-20","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"關於全口義齒技工製作時產生誤差的敘述，下列何者正確？","options":["(A) 填充之石膏不可漫過包埋盒，以確保加壓時包埋盒之金屬邊緣可直接接觸","(B) 義齒試戴時發覺後牙太高，可請牙技師降低 3 mm後直接完成","(C) 在攝氏 74 度煮聚 1.5 小時，接著在攝氏 100 度煮聚半小時，然後用冷水沖，快速冷卻，以減少樹脂聚合時 的收縮","(D) 樹脂於口內會造成吸水膨脹，所以應該置放在乾燥的地方"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-21","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"全口義齒製作後於咬合器上調整至平衡咬合（balanced occlusion），在側方運動時的工作側調整法則為 BULL，是指修磨人工牙齒那一個部位？①工作側上顎腭側咬頭之頰側斜面 ②工作側上顎頰側咬頭之腭側斜 面 ③工作側下顎舌側咬頭之頰側斜面 ④工作側下顎頰側咬頭之舌側斜面","options":["(A) ①④","(B) ②③","(C) ①③","(D) ②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-22","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"糖尿病患者血糖控制不良，裝戴全口義齒常常感疼痛，家屬要求製作新義齒，但病患不願製作新義齒，下列 何項處置最為正確？","options":["(A) 重新製作新義齒","(B) 製作新義齒時，應該複製患者已習慣的舊義齒","(C) 應評估舊義齒的缺陷與患者目前使用狀況，再做處置","(D) 建議先控制血糖，舊義齒不處理"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"對於可撤式局部義齒RPI的敘述，下列何者正確？①適用於往頰側傾斜（buccal tilting）的支柱牙 （abutment） ②對支柱牙有減壓的功用 ③適用於具有大倒凹的頰側軟組織（buccal site soft tissue） ④較 環周牙鈎（circumferencial clasp）美觀","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"有關可撤式局部義齒前後帶狀主連接體（anterior-posterior strap major connector）的敘述，下列何者正確？① 適用於甘迺迪第四類（Kennedy Class IV）缺牙之病人 ②前、後腭帶（anterior or posterior palatal strap）較側 腭帶（lateral palatal strap）寬，其寬度約為12～14 mm ③側腭帶（lateral palatal strap）較前、後腭帶 （anterior or posterior palatal strap）窄，其寬度約為4～6 mm ④遠心端缺牙之義齒，其後腭帶（posterior palatal strap）需延伸到鈎狀切迹區域（hamular notch areas）","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"對於可撤式局部義齒環周牙鈎（circumferential clasp）的敘述，下列何者正確？①鄰接小連接體（proximal minor connector）提供穩定（stabilization）功能 ②鄰接板（proximal plate）提供抗衡（reciprocation）功能 ③咬合鈎靠（occlusal rest）提供支持（support）功能 ④頰側固位牙鈎臂（buccal retentive clasp arm）的剛硬 部分（rigid portion），可提供抗衡（reciprocation）功能","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-26","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"以系統化建構設計（systematically developing design）可撤式局部義齒的支架時，下列何者應優先考慮？","options":["(A) 固位（retention）的方式","(B) 支持（support）的方式","(C) 缺牙區與相鄰支柱牙的連接方式","(D) 固位裝置與支持部分的連接方式"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"關於雪鞋原理（snowshoe principle）是指可撤式局部義齒的覆蓋範圍大，可以得到最好的支持效果，此原理 適用於何種類型的可撤式局部義齒？","options":["(A) 牙齒和組織支持（tooth and tissue borne）的可撤式局部義齒","(B) 牙齒支持（tooth borne）的可撤式局部義齒","(C) 牙齒和組織支持（tooth and tissue borne）與牙齒支持（tooth borne）的可撤式局部義齒皆適用","(D) 雪鞋原理（snowshoe principle）主要適用於下顎可撤式局部義齒"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"單側缺牙而製作雙側可撤式局部義齒，下列何者不是其優點？","options":["(A) 降低可撤式局部義齒誤吞的危險性","(B) 將咬合力平均分散","(C) 增加可撤式局部義齒的穩定性（stability）","(D) 減少可撤式局部義齒配戴的異物感"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"可撤式局部義齒製作時的義齒基底（denture base）設計考量，下列敘述何者錯誤？","options":["(A) 基底設計理念是以儘可能覆蓋廣泛的支持組織面積為原則","(B) 基底儘可能在生理性範圍內延伸至最長，有助義齒的水平穩定","(C) 一般而言，基底與殘嵴組織有愈精密的貼合作用，則義齒的固位作用也愈好","(D) 拋光的基底組織面與正確的造型，有助義齒的支持與穩定作用"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"有關可撤式局部義齒舌側鈎座（lingual rest seat）的修磨，下列敘述何者正確？①近-遠心（mesial-distal）長 度至少3.5～4.0 mm ②頰-舌（labiolingual）寬度約 2.0 mm ③切端-根尖端方向深度最少為2.5 mm ④下顎 牙若從舌側方向看，近似倒V型","options":["(A) 僅①③","(B) 僅②④","(C) ②③④","(D) ①③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-31","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"有關可撤式局部義齒設計中，對於往近心傾斜之第一大臼齒支柱牙，使用延展咬合鈎靠（extended occlusal rest）的敘述，下列何者正確？①近-遠心（mesial-distal）方向上的修磨長度至少為咬合面2/3 ②頰-舌 （buccal-lingual）方向上的修磨寬度約為牙齒的1/3 ③咬合-齒頸（occlusal-cervical）方向上的修磨厚度至少 為 1 mm ④近心引導面咬合-齒頸（occlusal-cervical）方向上的修磨長度約3～4 mm","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"下列何者不是決定可撤式局部義齒置入及取出途徑（path of placement and removal）之因素？","options":["(A) 引導面（guiding plane）","(B) 間接固位體（indirect retainer）的位置","(C) 干擾（interference）之部位","(D) 美觀（esthetics）需求"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-33","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"有關中心關係記錄（centric relation record）之取得，下列敘述何者錯誤？","options":["(A) 中心關係是可以重複取得的上、下顎間關係，可用以確認在咬合器上模型的定位","(B) 記錄中心關係位置時，患者應該舒適地躺在治療椅上，以方便操作","(C) 可引導病人做下顎前伸與後縮運動，以放鬆外翼肌","(D) 使用葉片量器（leaf gauge）可引導下顎至後縮位置"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-34","subject":"ya5","topic":"臨床基礎與倫理","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"下列何者對於擬定可撤式局部義齒（removable partial denture）的治療計畫（treatment plan）時，是不可或缺 的重要參考因素？①病人的全身健康狀況（general health） ②病人缺牙區殘留齒槽嵴（residual alveolar ridge）的狀況 ③病人口內軟組織的狀況（soft tissue condition）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"製作下顎遠伸性可撤式局部義齒（distal extension removable partial denture）時，下列何者不是使用個人牙托 於遠心缺牙區進行第二次印模的主要目的？","options":["(A) 取得較精確的上下顎間關係","(B) 取得缺牙區軟組織更精確的印模","(C) 取得較佳的邊緣封閉性","(D) 得到支柱牙與殘嵴組織之間的正確關係"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-111-2-36","subject":"ya5","topic":"牙科材料學","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"製作可撤式局部義齒使用下列何種最終印模材料最精確？","options":["(A) 不可逆性水凝膠（irreversible hydrocolloid）","(B) 橡膠印模材（rubber base impression material）","(C) 縮合式矽化物（condensation silicone）","(D) 加成式矽化物（addition silicone）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-37","subject":"ya5","topic":"牙科材料學","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"關於可撤式局部義齒選用樹脂牙或瓷牙的優缺點，下列敘述何者錯誤？","options":["(A) 當對咬牙為自然牙或瓷牙時，應使用頰舌寬度（buccolingual width）較寬的樹脂牙來緩衝，並分散咬力以降 低底下殘嵴的吸收","(B) 瓷牙與義齒基底樹脂只有機械性的結合，而樹脂牙則與基底的樹脂有較好的化學鍵結","(C) 瓷牙使用時較樹脂牙易破損，咀嚼時常會產生碰撞聲","(D) 樹脂牙較瓷牙易修正再塑形"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-38","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"為建立可撤式局部義齒之理想咬合，下列何者錯誤？","options":["(A) 須先分析現有咬合狀況","(B) 可修整原有牙齒之不協調咬合狀態","(C) 記錄已修整咬合後之中心咬合關係","(D) 試戴金屬支架時，不能修正咬合誤差"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-39","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"下列有關以單側遠伸性可撤式局部義齒（unilaterally distal extension removable partial denture）來處理單側後牙 缺失情況的敘述，何者錯誤？","options":["(A) 可避免對咬牙的突出（extrusion）以及位移（migration）","(B) 可大幅改善咀嚼效率（masticatory efficiency）","(C) 保持覆蓋並提供間歇（intermittent occlusion）咬力，可幫助維持上顎粗隆（maxillary tuberosity）的尺寸以及 位置","(D) 如果僅缺少第二大臼齒時，應優先考慮以植牙或以多顆支柱牙支撐懸臂的固定補綴方式（multiple-abutment cantilevered fixed restoration）來完成治療"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-111-2-40","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"關於可撤式局部義齒鄰接板（proximal plate）的敘述，下列何者正確？①其作用為戴入義齒時，對支柱牙產 生摩擦（friction）與應變（strain） ②確保義齒固位鈎（retentive clasp）的固位作用 ③避免義齒發生水平 旋轉 （horizontal rotation） ④防止義齒與支柱牙之間食物的嵌塞（trap）","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"有關可撤式局部義齒牙鈎臂（clasp arm）斷掉後，擬以鍛製金屬線（wrought-wire）取代之處置，下列何者最 正確？","options":["(A) 選擇適當的鍛製金屬線取代，銲接時包埋材的燒卻（burnout）溫度，不超過1300°F","(B) 鍛製金屬線與金屬義齒支架之結合點處，易發生金屬再結晶（recrystallization），故不易斷掉","(C) 可反覆調整鍛製金屬線牙鈎臂，不用擔心斷掉的可能性","(D) 銲接鍛製金屬線時，須使用高熔點銲劑（high-fusing solder）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"下列何種情況之可撤式局部義齒裝戴者需較常回診？① 殘嵴嚴重萎縮者 ② 牙周病患者 ③ 心血管疾病患 者 ④口乾症及高蛀牙率患者","options":["(A) 僅①②③","(B) 僅①②④","(C) 僅③④","(D) ①②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"關於可撤式局部義齒主模型的複製，下列敘述何者錯誤？","options":["(A) 主模型完成封凹（blockout）後，才進行複製","(B) 複製過程中，最好使用抽真空的設備","(C) 複製的模型一般會比原模型小","(D) 如因複製模型準確性不足，而需調整金屬支架，會影響義齒的穩定性"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-111-2-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"有關傳統鑄造可撤式局部義齒鈷鉻合金支架（Co-Cr metal framework）製作之敘述，下列何者錯誤？","options":["(A) 鈷鉻合金鑄造之收縮率達2.3%","(B) 包埋材硬化後要除去外圍金屬環圈","(C) 由於包埋材所形成的孔洞較多，不需要加排氣道（vent）","(D) 由於熔點高，須用高溫包埋材（high-heat investment）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"有關上顎犬齒3/4金屬牙冠（three quarter metal crown）修磨的敘述，下列何者正確？①理想的舌側軸壁需與牙 齒頰側面近齒頸1/3處平行 ②切緣斜面（incisal bevel）與牙齒長軸（long axis）之交角，一般呈45度 ③舌 側應修形為較寬的弧形緣（chamfer margin） ④在舌面隆突（cingulum）正中心修磨出針孔（pinhole）以加 強固著力（retention）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"有關上顎前牙全瓷冠（all ceramic crown）之敘述，下列何者正確？①傾斜肩形邊緣（sloping shoulder margin）設計較重圓弧邊緣（heavy chamfer margin）設計佳 ②舌面中心接觸點（centric contact）最好位於 牙冠中間1/3（middle third） ③鄰接面邊緣（proximal margin）之瓷厚度至少要達到0.5 mm ④唇面引導溝 （guiding groove）之修磨深度大約0.8 mm","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-47","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"有關下顎大臼齒金屬冠蓋體（onlay）牙齒修磨的敘述，下列何者正確？①頰側必須修磨成斜面肩台緣 （beveled shoulder margin） ②頰側緣（buccal margin）應位於牙髓底（pulpal floor）向下延伸約1.5 mm的位 置 ③鄰接盒型（proximal box）的範圍超出轉形線角（transitional line angle）具有最佳的抗力形（resistance form） ④在非功能性咬頭磨出約0.8 mm的導引深度溝（guiding depth groove）","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-48","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"製作上顎前牙固定義齒時，下列何種方式最能精確保留患者的前方導引（anterior guidance）？","options":["(A) 製作客製前方導引檯（custom anterior guide table）","(B) 修形前，記錄前牙之垂直覆蓋（overbite）及水平覆蓋（overjet）","(C) 取得牙齒修形前的前伸咬合紀錄（protrusive checkbite）","(D) 使用咬合器的前方導引檯（anterior guide table）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-49","subject":"ya5","topic":"牙科材料學","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"對磺酸鹽（sulfonate）過敏者，應該避免使用下列何種印模材？①多硫聚合物（polysulfide） ②縮合式矽膠 （condensation silicone） ③聚乙醚（polyether）","options":["(A) 僅①","(B) ①②","(C) ②③","(D) ①③"],"answer":[0,1,2,3],"image":"","clinical_level":"一般","explanation_pending":false},{"id":"ya5-111-2-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"根管治療後，牙冠的長度和根柱（post）長度的比例，下列何者最適宜？","options":["(A) 1:1","(B) 2:1","(C) 3:2","(D) 4:3"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-51","subject":"ya5","topic":"臨床基礎與倫理","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"當兩牙齒鄰接面到骨嵴（bone crest）至少距離多少mm 時，乳突（papilla）即可能無法填滿齒間楔隙 （interproximal embrasure）？","options":["(A) 8","(B) 5","(C) 4","(D) 3"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-52","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"在製作析量牙冠（surveyed crown）時，下列敘述何者錯誤？","options":["(A) 在咬合－齒頸徑（occlusal-cervical dimension）上的引導面（guiding plane）應愈長愈好","(B) 在前牙製作析量牙冠，並放置舌面隆凸鈎座（cingulum rest），可改善自然牙上放切端鈎座（incisal rest）的 美觀問題","(C) 預留固位倒凹（retentive undercut）時，應考慮未來的牙鈎（clasp）材質","(D) 若使用type Ⅳ gold為牙鈎材質，則預留固位倒凹量應為0.12～0.25 mm"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"在垂直空間有限且咬合力量較大的狀況下，下列後牙金屬瓷橋體的設計，何者最適宜？","options":["(A) 咬合面金屬，橋體組織面金屬","(B) 咬合面瓷，橋體組織面金屬","(C) 咬合面金屬，橋體組織面瓷","(D) 咬合面瓷，橋體組織面瓷"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"全瓷局部固定義齒（all-ceramic fixed partial dentures）的連接體（connector），廠商建議其尺寸應為多少？","options":["(A) 2 mm×2 mm","(B) 4 mm×4 mm","(C) 6 mm×6 mm","(D) 8 mm×8 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-55","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"金屬瓷修復體（metal-ceramic restorations）的金屬瓷交界應該遠離中心咬合接觸至少多少mm？","options":["(A) 0.5","(B) 1.5","(C) 2.5","(D) 3.5"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-56","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"有關後牙黏著牙橋（adhesion bridge）支柱牙的修磨，下列敘述何者正確？①咬合鈎靠（rest）除了提供固著 力（retention）之外也可抵抗側向力與咬合力 ②降低舌側軸面（lingual axial surface）的外廓高隆線（height of contour）離牙齦嵴（gingival crest）約2.5 mm ③鄰接面（interproximal surfaces）齒頸部區域修磨成弧形邊 緣（chamfer margin） ④從咬合面觀察牙橋支架需環繞支柱牙至少180度","options":["(A) ①②","(B) ③④","(C) ②③","(D) ①④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-57","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"上顎小臼齒缺牙區採用下列何種橋體（pontic）設計可以得到較美觀的結果？","options":["(A) 改良式覆嵴（modified ridge-lap）橋體","(B) 衛生型（sanitary）橋體","(C) 錐形（conical）橋體","(D) 馬鞍型（saddle）橋體"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-111-2-58","subject":"ya5","topic":"植牙贋復","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"相較於implant framework傳統作法，口內掃描與CAD/CAM technology能夠提供的優點不包括下列何者？","options":["(A) CAD/CAM technology可減少鑄造及銲接誤差","(B) CAD/CAM technology可使用ceramic或titanium為framework材質","(C) 口內掃描準確度優於傳統印模法","(D) 口內掃描可減少印模時軟組織的塌陷形變"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-59","subject":"ya5","topic":"植牙贋復","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"關於人工植牙之咬合設計策略，下列何者錯誤？","options":["(A) 咬合力儘量朝向植體之軸向","(B) 若需提供側方接觸，則儘可能置於前牙區","(C) 增高咬頭以增加咀嚼之效率","(D) 無法避免側向力時，應增加植體數量"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-60","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"關於懸臂式牙橋 （cantilever bridge）的敘述，下列何者正確？①支柱牙需有健康的牙周支撐 ②牙髓治療後 的牙齒不可當支柱牙 ③懸臂橋體最好不要超過一個 ④懸臂橋體上不可有任何咬合接觸","options":["(A) 僅①②③","(B) 僅①③","(C) 僅②③④","(D) ①②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"製作下顎後牙三單位牙橋前，將嚴重傾斜的後側支柱牙（大臼齒）以齒顎矯正方式扶正的處置方 式，可能獲致的好處為下列何者？①保留支柱牙牙髓活性 ②建立適當的楔隙（embrasure）型態 ③得到較長的臨床牙冠 ④使咬合力與支柱牙長軸一致 ⑤縮小橋體長度","options":["(A) ①②④","(B) ①③④","(C) ②③④","(D) ②⑤"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-62","subject":"ya5","topic":"臨床基礎與倫理","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"擬定固定義齒治療計畫時，需要考慮下列那些因素？①患者的需求及經濟能力 ②單一的治療計畫方便決 策 ③患者的外觀與功能 ④必須重建完整的齒列 ⑤治療後的口腔維護需求","options":["(A) ①②③④","(B) ①②④⑤","(C) ①③⑤","(D) ③④⑤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-63","subject":"ya5","topic":"牙科材料學","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"在製作蠟型之前，若齒模上有缺損需先填補時，下列何種材料最合適？","options":["(A) 汞齊（amalgam）","(B) 玻璃離子體黏合劑（glass ionomer cement）","(C) 硬石膏（stone）","(D) 樹脂（resin）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"固定義齒裝戴後，如果患者抱怨會塞食物，下列何者是最可能的原因？","options":["(A) 鄰接面太緊","(B) 鄰接面太鬆","(C) 表面太粗糙","(D) 表面太平滑"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-65","subject":"ya5","topic":"牙科材料學","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"有關鑄道（sprue）放置的敘述，下列何者錯誤？","options":["(A) 必須遠離蠟型邊緣和咬合接觸點","(B) 通常放置在最大的非功能性咬頭（nonfunctional cusp）","(C) 使蠟型放置在鑄造環（casting ring）的中心","(D) 使蠟型最末端離鑄造環的頂端3 mm即可"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-66","subject":"ya5","topic":"牙科材料學","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"下列黏合劑（cement）中，何者之微滲漏（microleakage）最小？","options":["(A) 聚羧酸鋅（zinc polycarboxylate）黏合劑","(B) 玻璃離子體（glass ionomer）黏合劑","(C) 樹脂離子體（resin ionomer）黏合劑","(D) 磷酸鋅（zinc phosphate）黏合劑"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-67","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"關於人類咀嚼的敘述，下列何者錯誤？","options":["(A) 咀嚼是一種由中樞模式產生器（central pattern generator）控制的節律性（rhythmic）運動","(B) 咀嚼包括上下顎分離（separation）與關閉（closure）兩種運動交替進行","(C) 完成咀嚼運動主要仰賴肌肉與牙齒的功能，與口腔軟組織無關","(D) 在下顎關閉時，咀嚼又分為壓碎（crushing）與研磨（grinding）兩個階段"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-111-2-68","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"關於保護性共同收縮（protective co-contraction）的敘述，下列何者明顯錯誤？","options":["(A) 高度的情緒壓力可能透過γ傳出纖維（gamma efferent）的作用，降低肌梭的敏感度並升高肌肉張性 （tonicity）","(B) 肌肉以外的深度疼痛（deep pain）也可能引發保護性共同收縮，進而影響肌肉痛","(C) 在休息狀態下，保護性共同收縮只會讓病患感到些許疼痛或不痛","(D) 持續的保護性共同收縮可能引發局部肌肉痠痛（local muscle soreness）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-69","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"關於閉顎反射（jaw-closing reflex），下列敘述何者錯誤？","options":["(A) 又稱為顎跳反射（jaw jerk reflex）","(B) 可經由輕敲下巴產生","(C) 與下顎在休憩位置時的張性活動（tonic reflex）有關","(D) 是多突觸反射，不受中樞神經的調節與影響"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-2-70","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"在安格氏第一類咬合關係，下顎進行後突運動（retrusive movement）時，後牙可能會有接觸點產生，請問對 這可能的接觸位置的描述，下列敘述何者正確？","options":["(A) 下顎頰側咬頭遠心斜面接觸對咬牙窩的近心斜面（mesial inclines）與邊緣嵴","(B) 下顎舌側咬頭遠心斜面接觸對咬牙窩的近心斜面（mesial inclines）與邊緣嵴","(C) 下顎頰側咬頭近心斜面接觸對咬牙窩的遠心斜面（distal inclines）與邊緣嵴","(D) 上顎舌側咬頭遠心斜面接觸對咬牙窩的近心斜面（mesial inclines）與邊緣嵴"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-71","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"關於中心自由（freedom in centric）的敘述，下列何者錯誤？","options":["(A) 在年輕的自然齒列不常見到","(B) 不應建立於全口義齒的咬合","(C) 可藉由咬合調整得到","(D) 涵蓋長中心（ long centric）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-72","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"病患計畫進行咬合治療（occlusal therapy）時發現其上下模型有穩定的咬合嵌合位置，但有明顯的中心關係- 到-咬頭嵌合位置的滑動（centric relation–to–intercuspal position slide），若模型要置位（mounting）於咬合器 作進一步的咬合分析，選用何種顎間關係來置位模型較為理想？","options":["(A) 最大咬頭嵌合位置（maximum intercuspal position）","(B) 中心關係位置（CR position）","(C) 姿勢性靜止位置（postural rest position）","(D) 肌電圖靜止位置（electromyographic rest position）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-73","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"關於咬合器之面弓轉移，下列敘述何者錯誤？","options":["(A) 面弓轉移是用來決定上下顎顎間關係的方法","(B) 適當使用面弓轉移，可以減少在咬合器上直接改變患者的垂直咬合關係時的誤差","(C) 雖然依樞紐軸線（hinge axis）的設置與否存在爭議，使用平均值的面弓來置位（mounting）上顎模型仍是較 為適當","(D) 面弓轉移的利用有助於減少下顎關閉弧線（arc of closure）位置的偏移"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-111-2-74","subject":"ya5","topic":"咬合學基礎","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"有關咀嚼時之下顎運動的敘述，下列何者錯誤？","options":["(A) 在閉口期，下顎運動的軌跡會受到牙齒咬合面形態與食物大小及硬度所影響","(B) 安格氏骨性第三級咬合（Angle's skeletal Class III）者，於咀嚼時之運動傾向於垂直開閉口","(C) 牙齒磨耗較少者，其咀嚼較無滑導咬合（gliding occlusion）","(D) 咀嚼時，下顎僅有純粹的移動（pure translation）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-111-2-75","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"下列何者是顳顎關節症正確的診斷描述？","options":["(A) 最大張口達40毫米，表示顳顎關節內部結構一定沒有問題","(B) 胸鎖乳突肌的附著位置常阻礙前雙腹肌的有效觸診","(C) 良性的全身性鬆弛會使顳顎關節的預後更好","(D) 側方運動若最大側移小於5毫米，需檢查異側顱顎關節是否有內部運動限制"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"下列對於顳顎關節運動時的雜音，何者錯誤？","options":["(A) 輾軋音（crepitation）多發生在退化性關節炎的末期","(B) 下顎張口時的彈響被認為發生在關節盤前移的瞬間","(C) 關節盤移位又不能回復原位時，張口量會減少，且彈響會消失","(D) 交互性彈響（reciprocal clicking）多伴隨著可復位關節盤移位的情況"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"比較上顎及下顎全覆蓋型咬合板（full coverage splint）的敘述何者正確？①上顎覆蓋易獲得固持力 （retention） ②下顎覆蓋易造成咬頰（cheek-biting） ③下顎覆蓋能提供上顎門牙垂直終止點（vertical stop） ④選擇在缺後牙區較多的牙弓製作咬合板","options":["(A) 僅①②","(B) 僅③④","(C) ①②④","(D) ①③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"對於肌筋膜疼痛（myofascial pain），下列敘述何者錯誤？","options":["(A) 此類患者常伴有睡眠障礙","(B) 可利用氟代甲烷（fluoromethane）噴劑作用於板機點（trigger point），解除部分症狀","(C) 可按壓板機點（trigger point）解除部分症狀","(D) 優先使用布比卡因（bupivacaine）做板機點（trigger point）注射，以迅速解除症狀"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"下列何種情況可能造成顳顎關節盤於開口時，關節盤往後移位（disc posterior displacement）？","options":["(A) 上關節腔黏著（adhesion）","(B) 下關節腔黏著（adhesion）","(C) 上外翼肌痙攣（muscle spasm）","(D) 骨關節炎（osteoarthritis）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-111-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"對於不可復性關節盤移位（disc displacement without reduction）的支持性療法（supportive treatment）下列何 者正確？① 剛卡住時，可建議病人強制張口，嘗試使關節盤復位 ② 當疼痛存在時，熱敷或冰敷都可用 ③ 對於疼痛及發炎，可使用非類固醇消炎藥（NSAID） ④ 關節脫離牽開術（joint distraction）對慢性病人也很 有幫助","options":["(A) ①③","(B) 僅②③","(C) 僅②④","(D) ②③④"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-1","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"關於口腔黏膜的性質，下列敘述何者錯誤？","options":["(A) 硬腭（hard palate）的黏膜是屬於咀嚼性黏膜（masticatory mucosa）","(B) 殘嵴（residual ridge）的黏膜是由複層柱狀上皮（stratified columnar epithelium）以及固有層（lamina propria）所組成","(C) 黏膜下層（submucosa）的厚度太薄時，軟組織會變得比較沒彈性而黏膜容易受傷","(D) 配戴全口義齒的患者，夜間將義齒移除而使黏膜有6到8小時的休息時，將可以增加黏膜上皮角化現象與降低 黏膜下層（submucosa）發炎情形"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"關於老化的敘述，下列何者錯誤？","options":["(A) 口腔黏膜的彈性纖維（elastic fibers）數量減少","(B) 下顎的垂直運動（vertical movement）量減少","(C) 功能性運動神經元（functional motor neurons）數量減少","(D) 快速肌肉纖維（fast muscle fibers）數量減少"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"一位年長的全口義齒患者配戴義齒多年未定時回診，若在義齒邊緣處出現增殖性組織（hyperplastic tissues）， 下列敘述何者錯誤？","options":["(A) 此現象與殘嵴嚴重吸收及全口義齒不穩有關","(B) 此增殖性組織的正確診斷應為腫裂齦瘤（epulis fissuratum）","(C) 此類現象最容易出現於上顎後牙區","(D) 可以先於義齒邊緣修整或組織調理材襯墊處理，沒有效果才考慮手術切除"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"最適合用於印取全口義齒初模（preliminary impression）的材料，下列何者錯誤？","options":["(A) 不可逆性水凝膠（irreversible hydrocolloid）","(B) 矽化物塑土（silicone putty）","(C) 多硫化物（polysulfide）","(D) 印模化合材（impression compound）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"製作全口義齒，印模時於邊緣成形（border molding）過程中，如何決定下顎舌側凸緣（lingual flange）前方部 位的厚度？","options":["(A) 要求病人舌頭往前方伸","(B) 要求病人舌頭左右振動","(C) 要求病人舌頭頂在上顎的前方部位","(D) 要求病人做吞口水的動作"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"做下列何種動作時，可表現下顎喙狀突（coronoid process）對上顎全口義齒的影響？①張大嘴巴 ②閉口 ③ 做吸吮動作 ④下顎左右側移","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"臨床上使用咬合堤的四個步驟如下，其操作之順序為何？①決定咬合平面之高度及位置 ②尋求合適之咬合垂 直高度 ③調整咬合堤之牙弓形態 ④取得正中關係紀錄","options":["(A) ①②③④","(B) ③②①④","(C) ③①②④","(D) ①③②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"關於全口義齒製作時，取得圖形紀錄（graphic records）的敘述，下列何者正確？","options":["(A) 描繪裝置（tracing device）必須裝置於口腔外","(B) 其描繪記錄板（tracing central-bearing plate）必須放在上顎","(C) 若咬合堤基底不穩，不影響紀錄取得","(D) 決定全口義齒的中心關係（centric relation）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-9","subject":"ya5","topic":"咬合學基礎","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"隨著年齡增長，咬合間隙（interocclusal distance）的變化最可能的情形為何？","options":["(A) 減小","(B) 增大","(C) 不變","(D) 因人而異"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-10","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"關於全口義齒試戴時，下列何者不是對患者進行發音測試的主要目的？","options":["(A) 垂直高度","(B) 中心關係","(C) 休憩間隙","(D) 舌頭空間"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-11","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"全口義齒選擇前牙時的臨床步驟，下列敘述何者錯誤？","options":["(A) 一般來說建議依照牙齒的顏色、大小、形狀（mold）之先後順序來選擇義齒的前牙","(B) 人工牙的形狀（mold）相較於大小及顏色，個別差別較為細微，但對於複製呈現真實牙齒有最後修飾的作用","(C) 在讓病人做選擇時，宜採用“pair comparison” 的方法，可有效簡化選項，以幫助患者做決定","(D) 義齒前牙的選擇最好要在正式印模之後才決定"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"有關全口義齒的後牙排列，下列敘述何者錯誤？","options":["(A) 上顎後牙在頰舌方向要將牙齒排列在現存齒槽嵴的位置，以避免造成義齒的鬆脫","(B) 當上顎後牙排列過於向後延伸，而接近義齒的後緣時，患者可能會出現咬頰的問題","(C) 下顎後牙排列時，應注意義齒於頰側肌向內以及舌頭向外的力量，是否相互平衡","(D) 下顎後牙不宜排列於上升的齒槽嵴上，當因空間的限制只排三顆後牙時，通常是少排第一小臼齒"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"有關全口義齒進行側方運動的咬合調整，下列敘述何者錯誤？","options":["(A) 應先求得中心咬合位置的最大咬頭嵌合（maximum intercuspation）後，再進行此項咬合調整","(B) 工作側的咬合干擾是指發生於上顎頰側咬頭的舌側傾斜面與下顎頰側咬頭的頰側傾斜面之間的過早接觸","(C) 平衡側的接觸干擾常是因為下顎補償曲線（compensating curve）與上顎舌側咬頭的不和諧所造成","(D) 當平衡側的干擾出現在中心咬合最大咬頭嵌合的位置很接近時，兩者可一併修磨除去"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"一個全口義齒的病患若有較大的髁頭導引（condylar guidance），下列何種選擇較易達到平衡咬合（balanced occlusion）？","options":["(A) 若病人能接受的話，增加前牙的垂直覆蓋（overbite）","(B) 減緩前後的補償曲線（compensating curve）","(C) 增加左右的補償曲線（compensating curve）","(D) 減少咬合平面（occlusal plane）的傾斜度"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"當患者初次配戴全口義齒時，身為牙醫師需要了解並告知患者一些配戴後注意事項，下列敘述何者錯誤？","options":["(A) 一般而言，年長者對於全口義齒的適應能力會比年輕者差","(B) 配戴新全口義齒的外觀將會隨時間而變得更自然","(C) 學習用新的全口義齒發音與講話，需要幾個星期即可熟練","(D) 學習用新的全口義齒咀嚼時，只須1個月的時間就能滿意"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"若全口義齒患者在回診時，抱怨戴了新的義齒幾小時後，牙床產生疼痛，且顏面下半部肌肉感覺疲勞。下列 何者是最可能的原因？","options":["(A) 中心關係（centric relation）位置不正確","(B) 垂直咬合高度（vertical dimension of occlusion）不正確","(C) 咬合平衡側有干擾","(D) 義齒邊緣延伸過長"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"關於傳統即裝全口義齒（conventional immediate complete dentures）的敘述，下列何者錯誤？","options":["(A) 後牙拔除後需等待數個月，俟傷口癒合再製作義齒","(B) 需製作客製化模托（custom tray）以做最終印模（final impression）","(C) 通常可利用殘存牙齒取得適當之咬合關係，且不需要面弓轉移（facebow transfer）","(D) 前牙拔除後可立即配戴義齒，以提供病患美觀與功能需求"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-18","subject":"ya5","topic":"植牙贋復","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"對於因鼻咽癌接受放射線治療後的全口無牙病患，下列敘述何者錯誤？","options":["(A) 口水少，使用全口活動義齒較為困難","(B) 若口中有現存已骨整合之植體，應於放射線治療前移除，以免造成放射線骨壞死（osteoradionecrosis）","(C) 放射線治療後的口腔植體成功率較正常人低","(D) 高壓氧治療（hyperbaric oxygen treatment）可改善口腔植體的成功率"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-19","subject":"ya5","topic":"植牙贋復","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"有關植體斷裂的敘述中，下列何者錯誤？①斷裂的位置，多在外六角的底部 ②多數伴有骨質喪失 ③骨中 殘留的植體，可加以修改繼續使用","options":["(A) ①②③","(B) 僅①②","(C) 僅②③","(D) 僅①③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-20","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"有關全口義齒製作中，記錄基底材料的選擇，下列敘述何者錯誤？","options":["(A) 記錄基底之強度、精確與穩定性很重要，以基底蠟製作方便且排牙較易，但並非好的材料","(B) 蟲膠（shellac）可用熱塑形，亦可用金屬線提高強度，操作方便，尤其適合外形不規則或條件不佳之牙床","(C) 冷聚樹脂（cold-curing resin）可獲得足夠的強度與精確度，但主模型上之倒凹需先以蠟封凹（block-out）","(D) 熱聚樹脂（heat-curing resin）穩定性與強度最佳，且可成為最後全口義齒之義齒床，對於牙床條件差的患者 很適合"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-21","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"有關全口義齒蠟齦綵成型（festooning）的敘述，下列何者錯誤？","options":["(A) 蠟刀在切出牙齦邊界時，應與牙齒長軸成 30° 夾角","(B) 上顎前牙區犬齒之牙根最長","(C) 下顎前牙區正中門齒之牙根最短","(D) 蠟齦綵成型若不當，會影響義齒的清潔"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"當全口義齒患者進入你的診間，向你抱怨不滿意別的牙醫師新製作完成的義齒，若患者希望你來幫忙重新做 一副義齒，下列處置何者較不適宜？","options":["(A) 傾聽患者的抱怨，找出問題的來源","(B) 試圖修改舊有義齒找出解決之道","(C) 勸患者植牙","(D) 若沒有把握應考慮轉診"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-23","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"下列那一個區域在可撤式局部義齒製作翻製耐火模型（refractory cast）時，主模型需進行平行堵凹（parallel blockout）？ ①支柱牙作為引導面（guiding plane）的鄰接面 ②金屬支架小連接體（minor connector）覆蓋 的區域 ③槓鈎（bar clasp）覆蓋牙齦的區域","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-24","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"有關可撤式局部義齒RPI 的設計概念，下列敘述何者錯誤？","options":["(A) 可降低支柱牙（abutment）承受側向力，引導咬力沿牙齒長軸傳遞","(B) 若為遠心端游離（distal free end）義齒，鈎靠（rest）多置放在支柱牙的近心咬面，以利咬力傳遞","(C) 遠心鄰接板（distal proximal plate）自咬合面邊緣延伸至牙齦處須緊密貼合，以防止食物堆積","(D) 鄰接板的功能除了穩定義齒外，也可提供義齒戴入與取出時的路徑及適當的抗衡作用"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-25","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"可撤式局部義齒的小連接體（minor connector）是將咬合鈎靠（occlusal rest）與牙鈎（clasp）組成的裝置，連 接到義齒的何種組件上？","options":["(A) 引導面（guiding plane）","(B) 主連接體（major connector）","(C) 活動義齒的基底（denture base）","(D) 活動義齒的間接固位體（indirect retainer）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"有關可撤式局部義齒間接固位體（indirect retainer）的敘述，下列何者錯誤？①支撐間接固位體的連接體必須 剛硬（rigid） ②主要是用來降低對主要支柱牙左右翻轉的扭力（torque） ③間接固位體可以用來判斷遠伸 性（distal extension）義齒基底是否需要換底墊（reline）","options":["(A) 僅①","(B) 僅②","(C) 僅③","(D) ①③"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"一般而言，屬於牙齒支持（tooth borne）的可撤式局部義齒是屬於甘迺迪分類（Kennedy classification）的那 幾類？","options":["(A) 第一類（Class I）與第二類（Class II）","(B) 第一類（Class I）與第三類（Class III）","(C) 第二類（Class II）與第三類（Class III）","(D) 第三類（Class III）與第四類（Class IV）"],"answer":3,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-112-1-28","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"可撤式局部義齒的下顎主連接體（major connector）若是要使用舌側槓（lingual bar），下顎牙齦緣到口底的 距離至少要多少mm？","options":["(A) 2","(B) 4","(C) 6","(D) 8"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-29","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"有關可撤式局部義齒主模型（master cast）製作時的緩壓（relief）及封凹（blockout），下列敘述何者錯誤？","options":["(A) 缺牙區牙嵴鞍部（saddle area）需做緩壓處理","(B) 骨隆凸（bony torus）區域應給予緩壓","(C) 引導面（guiding plane）及小連接體（minor connector）的外廓高隆線（height of contour）以下區域需做平台 （ledge）處理","(D) 舌側槓（lingual bar）接觸的區域應給予緩壓"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"關於可撤式局部義齒內藏式咬合鈎靠（internal occlusal rest）的敘述，下列何者正確？①提供義齒最主要的固 位（retention） ②可以省略頰側牙鈎（buccal clasp） ③固位功能類似內藏式附連體（internal attachment） ④適用於牙齒支持（tooth supported）的可撤式局部義齒","options":["(A) 僅①③","(B) 僅②④","(C) ①②③","(D) ②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"製作可撤式局部義齒使用析量器（surveyor）做主模型析量時，為考量模型的適當傾斜度，下列敘述何者正 確？①決定合適的倒凹區 ②確立支柱牙鈎座位置 ③美觀考量 ④確立適當的引導面 ⑤避開軟或硬組織 的干擾 ⑥由模型前方觀察傾斜方向","options":["(A) ②③④⑤","(B) ②③④⑥","(C) ①③④⑤","(D) ①②⑤⑥"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"影響可撤式局部義齒置入途徑（path of insertion）的因素，包括下列那些？①引導面（guiding plane） ②美 觀（esthetics） ③固位區域（retentive area） ④咬合鈎靠（occlusal rest）","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"有關可撤式局部義齒主模型的緩壓（relief）處理，下列何者錯誤？","options":["(A) 金屬義齒支架（metal framework）若跨越牙齦及牙齦溝處，需緩壓處理","(B) 金屬義齒支架（metal framework）下方做緩壓處理，可留出空間提供樹脂基底附著","(C) 使用低熔點鑄造蠟容易均勻貼附","(D) 使用蠟刀將邊緣封好，以免複製模型時蠟片邊緣剝離"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-34","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"關於可撤式局部義齒的診斷與治療計畫，下列敘述何者最正確？","options":["(A) 牙醫師和患者之間的關係不是最重要的因素","(B) 牙醫師和牙技師之間的關係是最重要的因素","(C) 患者無須參與牙齒拔除或保留的決定","(D) 應包括骨頭、黏膜、牙周韌帶、咬合及咬合力量之檢視"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-35","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"下列何種印模材料最不適合使用於遠伸性可撤式局部義齒（distal extension removable partial denture）的功能 性印模（functional impression）？","options":["(A) 氧化鋅丁香酚（zinc oxide eugenol）","(B) 瓊膠水膠質（agar hydrocolloid）","(C) 假牙重襯材料（denture reline material）","(D) 多硫化橡膠（polysulfide rubber）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"有關製作可撤式局部義齒時進行主模型封凹（blockout）與緩壓（relief）的處理，下列敘述何者錯誤？","options":["(A) 一般常使用蠟作為封凹的材料","(B) 缺後牙的局部義齒製作，上顎唇側前庭倒凹區的封凹處理，屬於任意式封凹處理","(C) 模型上牙齒的析量線（survey line）以下所有倒凹區，均須進行封凹處理","(D) 模型上缺牙區貼透明緩壓蠟時，應距離支柱牙牙齦邊緣1.5mm以上"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"可撤式局部義齒要進行換底墊（reline）或換底（rebase）時，下列關於取模方法的敘述何者錯誤？","options":["(A) 牙齒支持類（tooth-borne）的可撤式局部義齒以開口或閉口（open- or closed-mouth）取模法並無太多差異","(B) 遠伸性可撤式局部義齒主要需考慮遠心無牙區齒嵴上黏膜組織的彈性（resiliency），來選擇開口或閉口取模 法","(C) 遠伸性可撤式局部義齒的遠心無牙嵴上黏膜組織較為堅實（firm）時，可用開口法選擇性加壓印模法（open- mouth selective pressure technique）","(D) 遠伸性可撤式局部義齒的遠心無牙嵴上黏膜組織較易移位（displaced）時，則可使用閉口（closed-mouth） 取模法以獲得黏膜受力時的實際變形量"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-38","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"下列對於可撤式局部義齒之後牙使用丙烯酸樹脂齒（acrylic resin tooth）之敘述，何者錯誤？","options":["(A) 丙烯酸樹脂齒比瓷牙較方便使用","(B) 若對咬自然牙為黃金咬合面，丙烯酸樹脂齒表面最好要加上黃金咬合面較佳","(C) 丙烯酸樹脂齒若內含磨耗顆粒（abrasive particle）也會磨耗對咬之黃金咬合平面","(D) 後牙的咬合面大小與自然牙相同即可，不須縮小"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-39","subject":"ya5","topic":"咬合學基礎","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"有關可撤式局部義齒的咬合關係，下列敘述何者最正確？","options":["(A) 局部義齒的咬合目標是自然齒與義齒有和諧的關係，修改人工牙外形才有可能達到","(B) 局部義齒與全口義齒的咬合原則完全相同","(C) 後牙人工牙原有的咬合形態對於後牙咬合來說很重要","(D) 縮小樹脂後牙義齒的咬合台（occlusal table）可防止咬合面過度磨損"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"可撤式局部義齒若進行換底之後，咬合面太低，則應如何處置？①在咬合面上直接加上自聚性樹脂 （autopolymerizing resin） ②在咬合面上直接加上光聚性樹脂（light-cured resin） ③製作並黏上黃金咬合 面 ④重新置換樹脂牙","options":["(A) 僅①④","(B) 僅①②③","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"可撤式局部義齒遠伸性基底（distal extension base）因殘嵴形態改變而失去支持，須要換底墊（reline）時，下 列何者非判斷依據？","options":["(A) 義齒較容易取出","(B) 遠伸性局部義齒區與對咬牙齒列間無咬合接觸","(C) 可用28-gauge綠色鑄造用蠟片檢查上下牙間的差距","(D) 使用咬合紙檢查，看不到義齒有咬合接觸"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"有關可撤式局部義齒執行換底墊（reline）之敘述，下列何者錯誤？","options":["(A) 換底墊前需先將基底的組織面磨掉相當一層的厚度","(B) 印模過程中所增加的咬合垂直高度，會影響咬合鈎靠（occlusal rest）的定位，可藉由後續的咬合調整來回復","(C) 牙醫師須以手指固定義齒的主要咬合鈎靠","(D) 確定間接固位體（indirect retainer）於印模過程中完全貼合在牙齒上"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-43","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"下列何者不會影響可撤式局部義齒（removable partial denture）間接固位體（indirect retainer）之功能？","options":["(A) 間接固位體距支點線之距離","(B) 間接固位體的連接體之堅硬度","(C) 間接固位體支柱牙的搖動度","(D) 口腔內唾液之分泌量"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-44","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"可撤式局部義齒金屬義齒支架（metal framework）的製作過程中，有關加鑄道（sprue）的敘述，下列何者錯 誤？","options":["(A) 全部鑄道交接區域均要保持圓滑無尖銳邊緣","(B) 鑄道要夠大（8～12 gauge圓蠟）","(C) 鑄道要加在蠟型較厚處","(D) 彎曲及長的鑄道可提供足夠的融熔合金進入模腔"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-45","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"有關白榴石（leucite）、二矽酸鋰（lithium disilicate）及Y-TZP 氧化鋯（zirconia）三種不同瓷材性質之比較， 下列敘述何者正確？①化學耐久力（chemical durability）值，Y-TZP氧化鋯＞二矽酸鋰＞白榴石 ②彈性係 數（elastic modulus）值，Y-TZP氧化鋯＞二矽酸鋰＞白榴石 ③膨脹係數（expansion coefficient），Y-TZP氧 化鋯＞二矽酸鋰＞白榴石 ④維氏硬度（Vickers hardness），Y-TZP氧化鋯＞二矽酸鋰＞白榴石","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-46","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"相較於鑄造式全牙冠（complete cast crown），金屬部分鑲面牙冠（metal partial veneer crown）有何優點？① 支柱牙修磨較簡單 ②較容易調整牙冠的置入途徑 ③固著後黏合劑較容易去除 ④置入時黏合劑較容易排 出","options":["(A) ①②","(B) ③④","(C) ②③","(D) ①④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-47","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"有關牙冠的敘述，下列何者正確？","options":["(A) 牙冠外形不足（undercontoured crown）較牙冠外形過大（overcontoured crown）更容易引起牙肉的發炎","(B) 減少前牙牙冠鄰接面外形（proximal crown contour）較增加前牙牙冠鄰接面外形，更容易維持住鄰接面牙齦 乳頭（interproximal papilla）","(C) 一般而言，下顎第一大臼齒牙冠的置入途徑（path of placement）約往舌側傾斜9～14度","(D) 就牙齒修磨量而言，肩形緣（shoulder margin）較弧形緣（chamfer margin）的修磨量少"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-48","subject":"ya5","topic":"咬合學基礎","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"在正常安格式一級咬合（Angle's class I）情況下，此圖屬於何種咬合狀況？","options":["(A) 工作側咬合導引","(B) 工作側咬合干擾","(C) 非工作側咬合導引","(D) 非工作側咬合干擾"],"answer":1,"image":"ya5-112-1-48.jpeg","clinical_level":"一般"},{"id":"ya5-112-1-49","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"利用電刀排齦時，需注意下列那些事項？①不可用於裝置心律調整器病患 ②不可使用可燃性局部麻醉藥劑 如ethylchloride者 ③於使用NO-O2麻醉時，口內應儘量保持乾燥","options":["(A) 僅①","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-50","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"為了達到良好的牙冠修復體密合度，根管治療後的牙齒如果需要製作鑄造式的根柱－冠心（post and core） 時，建議使用下列何種技術？","options":["(A) 牙冠修復體和根柱－冠心分開的二階段技術","(B) 牙冠修復體和根柱結合的一體技術","(C) 牙冠修復體和冠心結合的一體技術","(D) 牙冠修復體、冠心和根柱分開的三階段技術"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-51","subject":"ya5","topic":"植牙贋復","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"植牙前因缺牙處殘嵴缺損而做骨導引再生手術（guided bone regeneration），所應注意的事項，下列何者錯 誤？","options":["(A) 應維持10～12週primary flap closure以取得最大的骨增生","(B) 過渡時期應給予患者活動義齒以保護手術區","(C) 使用再生膜（barrier membrane）覆蓋人工骨可增加骨增生","(D) 咀嚼有可能讓翻瓣受壓導致再生膜外露"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-52","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"有關金屬瓷牙橋（metal-ceramic bridge）的橋體設計，下列敘述何者錯誤？","options":["(A) 金屬瓷交界（metal-ceramic junction）處，應避免與無牙嵴接觸","(B) 顎間距離小的臨床狀況，與無牙嵴之接觸應使用瓷材","(C) 瓷鑲面的厚度應約為1.2 mm，且儘量一致","(D) 前牙橋體底部易因厚度太厚而產生瓷破裂"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-53","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"局部可撤式義齒的牙冠固位體（retainer）上，若欲放置冠內附連體（intracoronal attachment），此附連體應距 離金屬瓷交界（metal-ceramic junction）至少幾mm？","options":["(A) 0.5","(B) 1.0","(C) 1.5","(D) 2.0"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-54","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"金屬瓷冠（metal-ceramic crowns）燒瓷時發生氣泡（bubbles）的原因，可能為下列何者？①燒瓷太多次 ② 在堆瓷時包入空氣 ③堆瓷時濕度控制不良 ④燒瓷前金屬層處理不良","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-55","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"加強牙科瓷（dental ceramics）材料強度的方法包括下列那些？①晶體強化（crystalline reinforcement） ②化 學強化（chemical strengthening） ③應力誘導變形（stress-induced transformation）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-56","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"製作暫用性牙冠（interim crowns）時，與直接技術相比，下列何者是使用數位技術（digital technique）的優 點？ ①較低的殘餘單體（residual monomer） ②沒有聚合收縮 （polymerization shrinkage） ③較佳的抗 磨耗 （wear resistant）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-57","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"齒列完整、排列整齊、垂直覆蓋量少、齲齒率低的20歲女性，因意外導致右上正中門齒切緣斷裂，牙本質外 露，但無敏感問題，患者尋求美觀重建，且不希望未來五年內就發生色澤改變狀況，則下列治療方式中何種 最適合她？","options":["(A) 使用金屬瓷牙冠（metal-ceramic crown）","(B) 先根管治療後，使用玻璃瓷牙冠（glass-ceramic crown）","(C) 使用瓷鑲面（porcelain veneer）","(D) 使用複合樹脂直接填補"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-58","subject":"ya5","topic":"植牙贋復","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"下列關於植體nonsegmented abutment的敘述，何者錯誤？","options":["(A) 又稱UCLA abutment","(B) 其做法是將最終贋復物（final restoration）直接連接在植體之上，沒有居間的abutment","(C) 是一種必須使用黏著的植體支柱（cement-retained abutment）","(D) 可用於垂直贋復空間不足的情況"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-59","subject":"ya5","topic":"植牙贋復","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"下列何者不是使用植牙手術導板（implant surgical guide）之目的？","options":["(A) 界定適當的楔隙（embrasure）","(B) 將植體位置規劃在義齒輪廓內","(C) 協助選擇植牙支柱的種類","(D) 辨認cementoenamel junction位置或義齒露出軟組織之外形"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-60","subject":"ya5","topic":"植牙贋復","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"為了提供適當的清潔通道，兩支人工植體之間的距離應至少有多少mm？","options":["(A) 1.0","(B) 1.5","(C) 2.0","(D) 3.0"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"下列關於局部覆蓋牙冠（partial coverage crown）的敘述，何者正確？","options":["(A) 可保留較多齒質","(B) 固位性（retention）較全牙冠（full coverage crown）佳","(C) 適用於長徑距固定牙橋（long span bridge）","(D) 適用於高齲齒率的患者"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-62","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"以三單位固定牙橋重建缺失的下顎第一大臼齒時，下顎第二大臼齒修形後，近遠心錐度過大（overtaper）， 下列第二大臼齒的處理方式中何者較能避免牙橋固位體鬆脫？","options":["(A) 使用牙齦下修形完成線 （subgingival finish line）","(B) 在支柱牙的遠心側修磨固位溝 （retentive groove）","(C) 在支柱牙的頰、舌側修磨固位溝 （retentive groove）","(D) 在咬合面修磨固位溝（retentive groove）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-63","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"有關牙科用蠟的性質及操作，下列敘述何者錯誤？","options":["(A) 需在較高溫度才能融化的蠟，其冷卻收縮亦較多","(B) 以蠟刀加熱法添加蠟時，蠟是流向熱源的方向","(C) ADA type I蠟的硬度高於ADA type II蠟","(D) 熱膨脹係數（coefficient of thermal expansion）相當高，易受環境溫度改變之影響"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-64","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"檢測鑄造牙冠的咬合高度時，其鄰牙與對咬牙必須能咬住厚度大約為多少µm的咬合箔片（shim stock），就 算完成咬合高度調整？","options":["(A) 6","(B) 13","(C) 25","(D) 38"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-65","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"使用實心的塑膠鑄道時，下列何者是造成鑄造物表面粗糙度增加的主要原因？","options":["(A) 要比蠟較高的溫度才能軟化","(B) 與蠟沒有良好的相容性","(C) 強度比蠟還要堅固","(D) 容易吸附包埋粉"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-66","subject":"ya5","topic":"牙科材料學","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"下列何種黏合劑（cement）之放射線不透性（radiopacity）低於牙本質（dentin）？","options":["(A) 玻璃離子體（glass ionomer）黏合劑","(B) 氧化鋅丁香油酚（zinc oxide eugenol）黏合劑","(C) 聚羧酸鹽（polycarboxylate）黏合劑","(D) 磷酸鋅（zinc phosphate）黏合劑"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-67","subject":"ya5","topic":"咬合學基礎","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"關於咀嚼時軟組織功能的敘述，下列何者正確？①舌頭的功能之一是將食物推向牙齒咬合面，以利咀嚼 ② 舌頭將食物推向上顎，有助於將食物分斷 ③頰肌（buccinator）的活動也有助於將食物置於牙齒咬合面","options":["(A) 僅①","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-68","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"關於肌梭（muscle spindle）的結構與功能，下列何者正確？①肌梭由梭外（extrafusal）與梭內（intrafusal） 兩種纖維共同組成 ②肌梭的感覺訊息主要透過Ia與II兩型纖維來傳遞 ③肌梭的感覺訊息傳入三叉神經中腦 核（trigeminal mesencephalic nucleus），常與反射運動有關 ④γ運動神經元與α運動神經元分別支配梭外肌與 梭內肌兩種纖維","options":["(A) ①②","(B) ①④","(C) ②③","(D) ③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-69","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"下列那一條神經受損會導致貝爾氏麻痺（Bell's palsy）？","options":["(A) 第五對腦神經的感覺神經","(B) 第五對腦神經的運動神經","(C) 第七對腦神經的感覺神經","(D) 第七對腦神經的運動神經"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-70","subject":"ya5","topic":"咬合學基礎","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"下顎進行右側向運動（right lateral movement）時，工作側（functional side）可能的接觸位置，下列何者正 確？①工作側上顎後牙頰側咬頭舌斜面（lingual incline）接觸工作側下顎後牙頰側咬頭頰斜面（buccal incline） ②工作側上顎後牙頰側咬頭舌斜面（lingual incline）接觸工作側下顎後牙頰側咬頭舌斜面（lingual incline） ③工作側上顎後牙舌側咬頭舌斜面（lingual incline）接觸工作側下顎後牙舌側咬頭頰斜面（buccal incline） ④工作側上顎後牙舌側咬頭舌斜面（lingual incline）接觸工作側下顎後牙頰側咬頭頰斜面（buccal incline）","options":["(A) ①③","(B) ②④","(C) ①④","(D) ②③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-71","subject":"ya5","topic":"咬合學基礎","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"對於相互保護性咬合（mutually protected occlusion），下列敘述何者錯誤？","options":["(A) 咬頭嵌合位置（intercuspal position），前後牙接觸點要均勻且受力一致","(B) 側向運動（laterotrusive）時後牙不可接觸","(C) 側向運動（laterotrusive）時犬齒引導（canine guidance）是最佳的選項","(D) 前突運動（protrusive）為前齒引導（anterior guidance）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-72","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"下列何者是選擇性磨修（selective grinding）的最佳適應症？","options":["(A) 病人有嚴重的異常咬合（malocclusion）","(B) 病人配戴咬合裝置後治癒了顳顎關節障礙症狀","(C) 病人有顳顎關節障礙症狀","(D) 病人需要做全口重建（full mouth rehabilitation）治療"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-73","subject":"ya5","topic":"咬合學基礎","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"根據波氏圖（Pösselt’s diagram）水平面觀（horizontal view）中的敘述，下列何者錯誤？","options":["(A) 在此平面上主要是記錄下顎往兩側與前後運動的狀態","(B) 此平面上描繪的圖形主要受到關節結構、肌肉與韌帶的影響","(C) 臨床上可利用這項記錄找到中心關係（centric relation），常為兩側運動軌跡匯集處","(D) 此最大運動範圍會受到齒列接觸影響"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-74","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"功能性咀嚼運動不包括下列何項？","options":["(A) 在矢狀面上的旋轉","(B) 下顎向外側的瞬間偏移","(C) 髁關節頭上純粹的樞紐軸線運動","(D) 顳顎關節內合於六個自由度的運動"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"關於顳顎關節攝影，下列敘述何者錯誤？","options":["(A) 電腦斷層攝影術（computed tomography）作為顳顎關節的例行檢查是不需要的","(B) 關節造影術（arthrography）可以顯示關節功能的動態資訊，關節內黏連及關節盤穿孔","(C) 磁共振攝影（MRI）可以清楚顯現軟組織的位置，但無法顯現關節盤的位置","(D) 關節鏡（arthroscopy）建議使用在和關節盤障礙有關的明顯疼痛及機械性功能障礙"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"下列何者不屬於磨牙症（bruxism）的肇因？","options":["(A) 可能和遺傳有關","(B) 可能與情緒壓力有關","(C) 病患都喜歡吃硬的食物","(D) 某些藥物會引發夜間磨牙"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"關於夜間磨牙症（nocturnal bruxism）的敘述，下列何者正確？①咬合干擾是造成夜間磨牙症的原因之一 ② 夜間磨牙症通常發生於由淺眠階段（lighter stage of sleep）進入深眠階段（deeper stage of sleep）期間 ③夜 間磨牙症通常伴隨有交感神經的活動（sympathetic activity） ④大多數夜間磨牙的傷害度大於咀嚼","options":["(A) 僅①②","(B) 僅③④","(C) 僅②③④","(D) ①②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"以下關於顳顎關節障礙症物理治療的敘述，何者錯誤？","options":["(A) 一般來說，乾熱法（dry-warm）較可以穿透到較深層的組織，有益於肌肉的修補癒合","(B) 利用低周波電氣刺激來刺激肌肉，達到類似按摩的效果","(C) 多數相關物理治療成效的研究仍侷限在臨床病例報告，尚缺少強而有力的科學實證，來確認特定物理治療的 療效","(D) 因為物理治療多為可逆（reversible）且非侵入性（non-invasive），因此受醫師及患者的接受度高"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"下列何種情形的發生較易造成顳顎關節（temporomandibular joint）髁盤複合體（condyle-disc complex）紊 亂？①關節盤側韌帶（disc collateral ligament）的延長（elongation） ②下關節盤後層（inferior retrodiscal lamina) 的延長（elongation） ③關節盤後緣（posterior border）變厚 ④上外翼肌（superior lateral pterygoid muscle）收縮","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②④","(D) ①②③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"下列造成急性異常咬合（acute malocclusion）的敘述何者正確？①上外翼肌（superior lateral pterygoid muscle）肌肉痙攣（muscle spasm），造成同側後牙無接觸 ②內翼肌（medial pterygoid muscle）肌肉痙攣 （muscle spasm），造成同側後牙無接觸 ③顳顎關節關節腔注射玻尿酸，造成同側後牙無接觸 ④關節盤後 炎（retrodiscitis），造成同側後牙無接觸","options":["(A) 僅①③","(B) ②④","(C) ③④","(D) ①②③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-1","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"關於口腔黏膜組織在承受咬合壓力後之變形與恢復，下列敘述何者錯誤？","options":["(A) 年輕者的口腔黏膜組織，承受壓力後的總下沉量比較多","(B) 口腔黏膜組織在壓力移除後，短時間內，年紀輕的黏膜厚度恢復比較快","(C) 印模前不戴舊的義齒或是舊義齒配合組織調理材（tissue conditioner）均可以讓組織恢復","(D) 不健康的口腔黏膜組織會影響到顎間關係的取得，而造成義齒製作的失敗"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"下列那些因素是增加高齡患者全口義齒治療困難度的原因？①傷口癒合能力降低 ②學習能力低下 ③具有較 複雜的全身性疾病 ④口腔衛生較不易保持","options":["(A) 僅①②","(B) ①②③④","(C) 僅①③④","(D) 僅②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"有關腫裂齦瘤（epulis fissuratum）之敍述，下列何者正確？","options":["(A) 此種患者之環口放射照片（panoramic radiogram）上，在腫裂齦瘤處可見牙嵴嚴重萎縮","(B) 多由於不合適之全口義齒凸緣（flange）刺激前庭（vestibule）所致","(C) 須手術去除","(D) 患者須立即重新製作全口義齒"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"關於口輪匝肌（obicularis oris）的敘述，下列何者正確？","options":["(A) 與上顎唇繫帶（labial frenum）連接","(B) 直接影響上顎全口義齒唇側凸緣（labial flange）的長度","(C) 附著於上顎頰繫帶（buccal frenum）之下方","(D) 拉上顎頰繫帶（buccal frenum）往前的力量"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-5","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"當嘴巴張開時，舌頭位置在何種狀況下，有助於下顎全口義齒舌側緣的封閉性？","options":["(A) 舌頭平放，舌尖置於下顎前牙舌側","(B) 舌尖向上，舌頭後縮","(C) 舌尖向下，舌背向後","(D) 舌頭平放，後縮"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"下列有關上顎全口義齒後緣（posterior border）部位的敘述，何者最不適當？","options":["(A) 義齒後緣至少要延伸至振動線（vibrating line）","(B) 客製化模托（custom tray）後緣不可越過振動線（vibrating line）","(C) 振動線（vibrating line）通常位於腭小窩（fovea palatinae）前方 2 mm 處","(D) 振動線（vibrating line）通常位於軟腭（soft palate）上"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"全口義齒排牙後，試戴時發現下顎牙齒高於下唇太多，下列何者不是造成此現象的原因？","options":["(A) 咬合平面太高","(B) 前牙垂直重疊太多","(C) 垂直高度太高","(D) 下顎前牙排列太靠舌側"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"全口義齒製作時，須將病人齒模（dental cast）轉移至半調節型咬合器，下列敘述何者錯誤？","options":["(A) 面弓是轉移齒模與張口軸（opening axis）的關係","(B) 咬合紀錄用以轉移上下顎間關係","(C) 前突位置紀錄可調整髁導引（condylar guidance）","(D) 上下顎門齒切緣對切緣位置紀錄，可調整本奈氏角（Bennett angle）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"關於全口義齒製作時，中心關係（centric relation）的敘述，下列何者錯誤？","options":["(A) 最好與中心咬合（centric occlusion）位置相同","(B) 具有可重複取得（reproducible）的特性","(C) 用圖形紀錄（graphic records）取得中心關係操作容易正確性高","(D) 須先確定垂直高度（vertical dimension）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"關於全口義齒使用不同咬頭設計的人工牙齒進行排牙時，下列敘述何者最不合理？","options":["(A) 無論是使用解剖型態（anatomical mold）或是非解剖型態（nonanatomical mold）的人工牙齒，全口義齒都可 以達成平衡咬合（balanced occlusion）","(B) 相較於非解剖型態（nonanatomical mold）以及零度牙，選擇解剖型態（anatomical mold）的人工牙齒可大幅 提昇全口義齒患者的咀嚼效率","(C) 使用非解剖型態（nonanatomical mold）的人工牙依照平面咬合觀念（monoplane occlusal concept）去排牙 時，咬合器的髁導引（condylar guidance）應設定為零度","(D) 當使用解剖型態（anatomical mold）的人工牙依照舌側化咬合（lingualized occlusion）的觀念，排列下顎後 牙時，其頰舌徑方向的補償曲線通常不超過 5 到 10 度"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"有關全口義齒前牙的敘述，下列何者錯誤？","options":["(A) 樹脂（acrylic resin）牙易染色","(B) 選用較方且具長接觸點（contact point）的前牙，會增加鄰間（interproximal）空間之粉紅色樹脂的顯露","(C) 當咬合間隙（interocclusal space）不夠時，最好不選瓷牙","(D) 當對咬為自然牙時，最好用樹脂牙"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-12","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"有關克里斯坦森現象（Christensen phenomenon），下列敘述何者錯誤？","options":["(A) 會出現上下顎後牙區間隙","(B) 下顎做前突或側方運動時，咬合面會出現空隙的現象","(C) 幫助義齒穩定性","(D) 在自然齒列出現此現象有保護牙齒的作用"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"關於安格氏骨性第三類咬合（Angle's class III）的全口義齒患者，下列敘述何者錯誤？","options":["(A) 下顎人工齒排列須向舌側及遠心側傾斜","(B) 後牙排列的威爾生氏曲線（curve of Wilson）較安格氏第一類咬合患者平緩","(C) 一般第三類咬合的患者，其上下前牙排列呈對切緣咬合（end to end）關係","(D) 嚴重下顎前突的患者，上下前牙可以呈錯咬（crossbite），但切端不接觸"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"當全口義齒依循平面咬合（monoplane occlusion）觀念，並選用零度牙進行人工牙排列時，下列敘述何者錯 誤？","options":["(A) 上下顎前牙排列可有較大的水平重疊（overjet）但須儘量減少垂直重疊（overbite）","(B) 上下顎後牙應依照咬頭嵌合關係（intercuspation）排列","(C) 下顎牙齒應排列在嘴角與臼齒後墊（retromolar pad）連線的平面上","(D) 排牙時下顎最後一顆牙的後緣，不可超過殘嵴開始上升至臼齒後墊（retromolar pad）的位置"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-15","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"關於使用靜態印模法（static impression technique）進行換底墊（relining）與換基底（rebasing）的臨床印模步 驟，下列敘述何者錯誤？","options":["(A) 可以使用閉口或是開口的方式","(B) 閉口的方式必須先確定現有的中心關係是否穩定","(C) 印模前義齒的樹脂表面需修除 1 到 2 mm的厚度","(D) 義齒後腭側封閉性（posterior palatal seal）不需要特別處理"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"當全口義齒製作完成後以及回診時，臨床上評估義齒基底的貼合會使用壓力顯示膏（pressure-indicating paste）如下圖，關於使用壓力顯示膏的敘述，下列何者錯誤？","options":["(A) 塗壓力顯示膏於義齒基底時需要同一方向且薄薄的一層","(B) 圖中1的位置是因為義齒放入口內頰側黏膜擦拭到的，不需要調整","(C) 圖中3的位置與圖中2相比，代表前者義齒基底貼合的很均勻，不需要調整","(D) 圖中4的位置代表義齒基底壓迫黏膜較重，需要做調整以緩壓"],"answer":2,"image":"ya5-112-2-16.jpeg","clinical_level":"一般"},{"id":"ya5-112-2-17","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"王先生上顎無牙，下顎僅存六顆前牙，且左下犬齒是經過根管治療之牙齒。今需要製作左下犬齒析量牙冠 （surveyed crown），下顎可撤式局部義齒與上顎全口義齒，下列製作步驟之先後次序何者最正確？ ①析量牙冠之印模、製作、試戴 ②下顎可撤式局部義齒之印模與金屬支架製作 ③下顎可撤式局部義齒之基底蠟型及義齒試戴 ④上顎全口義齒之印模與咬合基底之製作 ⑤決定上下顎垂直與水平咬合關係 ⑥上顎全口義齒之蠟型義齒試戴","options":["(A) ①②③④⑤⑥","(B) ①②④⑤⑥③","(C) ④⑤⑥①②③","(D) ④①⑤②⑥③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-18","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"如果病患抱怨軟腭閉孔器的後緣過長或鼻音太重（hypernasality），下列處理何者錯誤？","options":["(A) 壓力顯示劑（pressure indicating paste）可以準確地確認過長的後緣","(B) 使用組織調理材（tissue conditioner）重做功能性印模","(C) 鼻音之改善可以藉由之後的發音訓練來增強咽部的閉縮（pharyngeal constriction）","(D) 鼻音改善時間的長短，因人而異"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-19","subject":"ya5","topic":"植牙贋復","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"為全口無牙患者進行重建時，有關植體支持之固定式義齒（implant-supported fixed prostheses）及植體支持之 覆蓋式義齒（implant-supported overdentures）兩種治療方式，下列敘述何者錯誤？","options":["(A) 在治療完成後，植體支持之固定式義齒不需拿上拿下，故在口腔清潔的維持上較容易","(B) 植體支持之固定式義齒的製作較複雜，相對的費用也比較高","(C) 不論那種治療方式，其完成後的咬合面大小（size of occlusal table）皆需減小，以減少人工植體的負擔","(D) 植體支持之覆蓋式義齒較能達到患者對於美觀的要求，尤其是在前牙齒槽骨嚴重吸收的病例上"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-20","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"有關全口義齒最終印模（final impression）之客製化模托（custom tray），下列敘述何者錯誤？","options":["(A) 可以冷凝式樹脂（cold-cured resin）製作，但必須於印模前 24 小時做好","(B) 依患者牙床狀況與不同之印模理論，選擇適當的緩壓區（relief area）","(C) 邊緣通常比預定義齒範圍短 2～3 mm，以容納邊緣成形（border molding）之材料","(D) 牙托厚度應少於 2 mm，且握把（handle）處不可太長，以避免干擾印模的邊緣成形"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"全口義齒之技工操作於壓克力樹脂填充（resin packing）時，下列敘述何者正確？","options":["(A) 樹脂之粉液體積比要正確，通常是 2 比 1","(B) 樹脂糰於糰狀期（dough stage）與橡膠狀期（rubber stage）時填充","(C) 樹脂糰多置於包埋盒（flask）人工牙側，少數放在主模型（master cast）之深倒凹處","(D) 需試壓（trial pack）數次，壓力快速上升至包埋盒無明顯樹脂之溢出"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-22","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"王先生 78 歲，身體健康且經濟情況良好，使用全口義齒逾 20 年並無不適，因想改善咬合力，自行前來就 診，經檢查，上下牙床均嚴重萎縮，其最合適的處理方式應該是下列何者？","options":["(A) 植牙後以覆蓋式義齒贋復","(B) 製作新的全口義齒","(C) 依牙醫師的技術能力而定","(D) 分析各種治療計劃之優缺點，並由患者決定"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"上顎主連接體的設計原則與臨床考量，下列敘述何者正確？","options":["(A) 上顎主連接體製作時全部皆需要緩壓處理","(B) 珠狀緣飾（beading）的設計可以增加主連接體與組織的緊密接觸，同時增加結構的強度，故上下主連接體 均需要製作珠狀緣飾","(C) 為了避免不當壓迫上顎之中間縫合線（median suture line），金屬支架在製作過程中需在模型上先緩壓 （relief）","(D) 上顎主連接體的邊緣與牙齦的邊緣距離至少有4 mm的距離"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-24","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"關於可撤式局部義齒的鈎靠（rest）與鈎靠座（rest seat）的敘述，下列何者錯誤？","options":["(A) 提供支持（support）是鈎靠與鈎靠座的最主要功能","(B) 當支柱牙填補物過大時，建議可以使用析量牙冠（survey crown）設計","(C) 舌面隆凸鈎靠（cingulum rest）最常也最主要用於下顎犬齒","(D) 可做為延伸性可撤式局部義齒的間接固位體（indirect retainer）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"下圖（左圖為頰側/右圖為舌側）可撤式局部義齒的固位體（retainer），是屬於那一種牙鈎組合？","options":["(A) 迴力牙鈎（back-action clasp）","(B) 反作用牙鈎（reverse-action clasp）","(C) 多牙牙鈎（multiple clasp）","(D) 雙半牙鈎（half-and-half clasp）"],"answer":3,"image":"ya5-112-2-25.jpeg","clinical_level":"一般"},{"id":"ya5-112-2-26","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"關於上顎可撤式局部義齒腭板主連接體（palatal plate major connector）的敘述，下列何者錯誤？","options":["(A) 後緣位於後腭封區（posterior palatal seal）之後","(B) 前緣沿著皺摺間的凹處（valleys between rugae）不可往前延伸超越位於第一小臼齒處的間接固位體（indirect retainer）","(C) 經常使用Kennedy class I的義齒設計","(D) 全覆蓋腭板主連接體（complete coverage palatal major connector）建議使用於Kennedy class I最後僅存支柱牙 為犬齒或第一小臼齒"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-27","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"若上腭有巨大無法手術的隆凸（palatal torus），最常使用何種主連接體（major connector）？","options":["(A) 全腭板（complete palatal plate）","(B) 前後腭帶（anteroposterior palatal strap）","(C) 單腭帶（single palatal strap）","(D) U形腭板（U-shaped palatal plate）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-28","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"關於下顎可撤式局部義齒主模型（master cast）在翻模前最不需進行何種步驟？","options":["(A) 以蠟進行封凹（blockout）","(B) 以蠟進行緩壓（relief）","(C) 進行珠狀緣飾（beading）","(D) 畫出析量線（survey line）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"下列何者具有最多可撤式局部義齒的引導面（guiding plane）？","options":["(A) Kennedy class I","(B) Kennedy class II, modification 1","(C) Kennedy class III, modification 1","(D) Kennedy class IV"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-30","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"關於Kennedy class I可撤式局部義齒的設計考量，下列何者錯誤？","options":["(A) 牙鈎（clasp）合併近心鈎靠（mesial rest）可能傳遞較小的應力給終端支柱牙（terminal abutment）","(B) 減壓裝置（stress-breakers）可降低槓桿作用（leverage）對支柱牙影響的方法","(C) 使用較短的鍛製金屬線（wrought wire）固位性牙鈎臂減少與支柱牙的接觸","(D) 較長的鄰接板（proximal plate）會產生對支柱牙更多的水平應力"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"關於牙科用析量器，下列敘述何者正確？","options":["(A) 尼氏（Ney）析量器的水平臂可旋轉","(B) 金尼可（Jelenko）析量器的垂直臂藉由摩擦力固定軸承","(C) 尼氏（Ney）析量器的的軸桿可在軸承中上下移動","(D) 尼氏（Ney）析量器使用時需抵抗彈簧的張力"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"關於析量後可撤式局部義齒置入途徑，下列敘述何者錯誤？","options":["(A) Kennedy class III牙弓的置入途徑通常只有一個","(B) Kennedy class IV牙弓的置入途徑通常只有一個","(C) 沒有modification的Kennedy class II牙弓的置入途徑通常只有一個","(D) Kennedy class II牙弓的置入途徑會由其modification決定"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-33","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"對於牙周支持不佳牙齒的可撤式局部義齒設計，下列敘述何者錯誤？","options":["(A) 可考慮固定（splinting）在一起","(B) 不應優先考慮拔除","(C) 固定（splinting）後會造成清潔上更困難","(D) 旋鎖裝置式（swing-lock）的設計不適合使用於固定（splinting）牙周狀況不佳的牙齒"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-34","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"關於牙齒喪失的敘述，下列何者正確？","options":["(A) 上顎與下顎牙齒喪失的發生率沒有太大的差異","(B) 同一牙弓後牙比前牙先喪失","(C) 通常上顎門牙相較於下顎門牙有較低的蛀牙敏感性（caries susceptibility）","(D) 角質化口腔黏膜會增加，以因應牙齒喪失後齒槽骨的吸收"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-35","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"關於牙鈎固位型（clasp retained）可撤式局部義齒可能的缺點，下列敘述何者最不適當？","options":["(A) 支柱牙（abutment teeth）承受應變（strain）經常是主連接體的設計所造成","(B) 牙鈎的位置通常會影響美觀","(C) 齲齒常發生在牙鈎下方","(D) 製作成本比內藏式附連體（internal attachment）低"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-36","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"關於縮合式矽膠印模材（condensation silicone）的特性，下列何者錯誤？","options":["(A) 可藉由調整催化劑的量改變工作時間","(B) 不需要1小時內完成倒模","(C) 置於消毒溶液中不容易改變精準性","(D) 具有中高度的抗撕裂強度"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"關於可撤式局部義齒修正模型印模技術（altered cast impression technique）的敘述，下列何者錯誤？","options":["(A) 可獲取牙齒及殘嵴之理想支持形態","(B) 可獲得理想的遠伸性義齒基底之形態","(C) 金屬支架試戴完成後才能施作","(D) 常用於上顎雙側遠伸性可撤式局部義齒之取模"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-38","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"全口義齒與兩側游離端（free end）可撤式局部義齒，以蠟堤與記錄基底（wax rim and record base）進行咬合 記錄時，下列敘述何者正確？","options":["(A) 兩者相同，均須於軟組織支持處（soft tissue borne area）加壓","(B) 兩者相同，均不得於軟組織支持處（soft tissue borne area）加壓","(C) 兩側游離端義齒之軟組織支持處（soft tissue borne area）不得加壓，但全口義齒可加壓","(D) 兩側游離端義齒之軟組織支持處（soft tissue borne area）須加壓，但全口義齒不可加壓"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-39","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"製作可撤式局部義齒時，使用片狀尺規（leaf gauge）之時機與放置位置分別為何？","options":["(A) 於印模時，放置於印模牙托上","(B) 取中心關係（centric relation）時，放置於前牙","(C) 取中心咬合（centric occlusion）時，放置於後牙","(D) 支架試戴（framework try-in）時，檢查過高咬點"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-40","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"義齒基底所覆蓋的牙嵴軟組織移位性較高時，通常選擇下列那一種印模材最適當？","options":["(A) 聚乙醚（polyether）印模材","(B) 氧化鋅丁香油酚基（zinc oxide-eugenol）印模材","(C) 聚乙烯矽氧烷（polyvinylsiloxanes）印模材","(D) 多硫化橡膠（polysulfide rubber bases）印模材"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"關於可撤式局部義齒更換底墊（relining）技工室包埋工作，下列敘述何者錯誤？","options":["(A) 一般換底墊的包埋分層大多為兩層式包埋法","(B) 包埋時上、下包埋盒如果沒有緊密閉合，將造成義齒對咬無法接觸的現象","(C) 以氧化鋅丁香油酚或口腔溫度蠟當取模材時，可先將包埋盒加熱以利包埋盒分開","(D) 樹脂材料操作須依照廠商指示進行混合後置入包埋盒，反覆加壓去除多餘樹脂直到包埋盒完全閉合"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"當可撤式局部義齒基底沒有足夠延伸覆蓋全部義齒承壓組織時，應該選擇下列那一種處理方式較為適合？","options":["(A) 換底墊（relining）","(B) 換基底（rebase）","(C) 修復處理（repair）","(D) 重製作（reconstruction）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"當可撤式局部義齒金屬支架（metal framework）的蠟型完成以後，檢查的項目有那些？①是否依照原來的設 計來製作 ②配合對咬牙弓來看有無咬合干擾 ③蠟型與耐火模之間緊密接觸固位良好 ④表面光滑，接點 平順","options":["(A) 僅①②","(B) ①②③④","(C) 僅②③④","(D) 僅③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"製作可撤式局部義齒過程中，有關複製耐火模型（refractory cast）的敘述，下列何者錯誤？","options":["(A) 常使用瓊膠（agar）作為複製印模用的材料，融化後儲存在63℃的恆溫槽備用","(B) 石膏鍵結式耐火材為低溫包埋材，適用於第四類金合金和Ticonium合金鑄造","(C) 磷酸鍵結式耐火材為高溫包埋材，適用於鈷鉻合金與鈦合金等金屬鑄造","(D) 耐火模型在貼蠟前須浸泡在138℃～149℃的蜂蠟中，15分鐘後取出冷卻備用"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-45","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"在製備支柱牙時，下列何者不符合固定式義齒的生物性要求（biologic requirements）？","options":["(A) 保護牙齒的結構","(B) 牙齦上的邊緣（supragingival margin）","(C) 協調的咬合","(D) 瓷咬合表面"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"關於全瓷嵌體（all-ceramic inlay）支柱牙修形的敘述，下列何者正確？①斜面邊緣（beveled margin）為邊緣 設計的選項之一 ②髓深（pulpal depth）需要有1.5～2.0 mm ③軸壁聚攏角度（axial wall convergence）約為 6度 ④峽寬（isthmus width）至少需有2.0 mm","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-47","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"下列何種情況在印完最終模型後必須做咬合記錄（bite registration）？①缺失上顎14, 15, 16，要製作上顎右側 第二大臼齒的瓷金屬析量冠（surveyed crown） ②前牙開咬而要製作上顎右側中門齒的全瓷冠 ③安格氏一 級咬合，智齒已被拔除，要製作下顎左側35×37的金屬牙橋 ④安格氏第二級咬合，要製作上顎24×26瓷融合 金屬牙橋 ⑤製作上顎右側中門齒的瓷貼面（laminate）","options":["(A) ②③⑤","(B) ②③④","(C) ①②⑤","(D) ①③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-48","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"控制安格氏第一類咬合型之下顎運動之前方因子包括那些？①門齒之垂直覆蓋 ②門齒之水平重疊 ③下顎 門齒之舌側凹陷 ④上顎門齒之舌側凹陷 ⑤上下顎間之垂直距離 ⑥上下顎間之休憩間隙（free-way space）","options":["(A) ①③⑤","(B) ④⑤⑥","(C) 僅①②④","(D) ①②④⑤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-49","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"下列各類印模材料中，何者的抗撕裂強度最差？","options":["(A) 多硫化聚體","(B) 可逆性水凝膠","(C) 聚乙醚印模材","(D) 加成式矽化物印模材"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-50","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"關於印模前使用電刀修整牙齦以露出修形邊緣（margin）的敘述，下列何者錯誤？","options":["(A) 不可使用在裝置有心律調整器（cardiac pacemaker）或是胰島素幫浦（insulin pump）的患者上","(B) 使用時電刀頭在牙齒邊緣的移動速度越慢越好","(C) 不要在短時間內重複以電刀頭碰觸同一個手術點","(D) 使用完畢後可用H2O2清潔電刀頭"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-51","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"有關根管治療完成後，牙齒之根柱（post）製作，下列敘述何者正確？","options":["(A) 根柱的長度越長，固位性越佳，但理想上須有1 mm的根尖封閉","(B) 根柱的直徑以不超過牙根直徑的1/2為佳","(C) 上、下顎大臼齒在根管治療完成後製作牙冠前，必須先製作根柱以增加牙冠之固位性","(D) 螺紋根柱（threaded post）的固位性比平行根柱（parallel-sided post）的固位性為佳"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-52","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"牙冠邊緣置放到牙齦下之深度考量，下列敘述何者錯誤？","options":["(A) 鄰接面之牙周囊袋探測深度若為3 mm，則最多容許鄰接面牙冠邊緣置放於牙齦下1.5 mm","(B) 較淺的牙周囊袋，會比發炎的牙齦較不易萎縮","(C) 將牙冠邊緣置放到牙齦下通常是為了遮蓋牙冠邊緣及增加牙冠固位力（retention）","(D) 超過牙齦下1 mm之牙冠邊緣會造成修形及印模困難"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"非剛性連接體（nonrigid connector）的設計中，榫眼（mortise）需放在那裡？①中間支柱牙（pier abutment） 的近心面 ②前面牙齒固位體（anterior retainer）的遠心面 ③前面牙齒固位體的近心面 ④後面牙齒固位體 （posterior retainer）的近心面","options":["(A) 僅①④","(B) 僅②④","(C) ①③","(D) ①②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"關於卵型橋體（ovate pontic）的敘述，下列何者正確？","options":["(A) 可用來保留前牙拔牙後相鄰的齒間乳頭（interdental papillae）","(B) 用臨時牙橋橋體進入拔牙窩（extraction socket）的深度約 3.5 mm","(C) 在拔牙窩逐漸癒合過程中，需修整橋體使其進入窩洞越來越深","(D) 橋體處癒合的軟組織若不足3 mm則需要修骨頭"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-55","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"傳統全瓷材的缺點是脆弱且強度低，關於瓷強度的敘述，下列何者錯誤？","options":["(A) 單體瓷（monolithic ceramics）是利用瓷鑲面加上高強度瓷內冠，可改善瓷強度","(B) 瓷材產生斷裂的原因可能是製造時有瑕疵或是表面有裂痕","(C) 增強結晶（crystalline reinforcement）可加強瓷強度","(D) 加入表面瓷釉可以增加瓷強度"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-56","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"金屬瓷修復體（metal-ceramic restorations）在素燒（bisque bake）時破裂的原因包括下列何項？①堆瓷時填壓 （condensation）不正確 ②堆瓷時濕度控制不好 ③金屬支架設計不良 ④金屬與瓷物理性質不相配","options":["(A) 僅①③","(B) 僅①②④","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-57","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"臨時性固定補綴物所使用的樹脂，其成分各有不同的功能，下列敘述何者錯誤？","options":["(A) 單體（monomer）：為主要成分，決定樹脂的特性，單體的分子越大，樹脂的強度較優","(B) 色素（pigments）：可使樹脂的顏色接近自然牙的顏色","(C) 充填劑（filler）：可增加樹脂的強度（strength），降低聚合時所放出的熱量及收縮量","(D) 引發劑（initiator）：可分解出free radicals，使單體（monomer）進行聚合作用形成聚合體（polymer）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-58","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"用於製作臨時牙冠時，聚甲基丙烯酸甲脂（polymethyl methacrylate）與bis-GMA相比，下列敘述何者錯誤？","options":["(A) 有較明顯的臭味","(B) 有較差的顏色穩定性","(C) 有較大的牙肉刺激性","(D) 有較差的流動性"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-59","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"下列何者不是牙齒一般老化（aging）的現象？","options":["(A) 牙齒因為磨耗（attrition）而使得牙冠長度變短","(B) 微笑時，露出的牙齒漸少","(C) 逐漸喪失門齒的齒間楔隙（loss of incisal embrasure）","(D) 門齒切緣出現淺灰色的透明層"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-60","subject":"ya5","topic":"植牙贋復","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"製作上顎全牙弓六支植體相連固定義齒時，由於上顎齒槽骨吸收而使得所有植體軸向往牙弓頰側外展，此時 最適合的印模方式為下列何者？","options":["(A) 開放式個別模托（open individual tray）＋縮合式矽膠印模材（condensation silicone）","(B) 開放式個別模托（open individual tray）＋加成式矽膠印模材（addition silicone）","(C) 封閉式個別模托（close individual tray）＋聚乙醚印模材（polyether）","(D) 金屬普通模托（metal stock tray）+ 加成式矽膠印模材（addition silicone）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-61","subject":"ya5","topic":"植牙贋復","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"下列何者並非植體補綴物螺絲鬆脫的原因？","options":["(A) 過大的側方力量","(B) 過大的咬合力量，且沒有經過植體的長軸","(C) 螺絲旋緊的力量不足","(D) 植體補綴物與植體間是passive fit的關係"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-62","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"牙科贋復治療的診斷與擬定計畫時，關於咬合的考量，下列敘述何者錯誤？","options":["(A) 多數證據顯示，對患者剩餘的自然牙齒列進行全面的咬合重塑（generalized occlusal reshaping），可以提高 舒適度，使顳顎關節恢復健康","(B) 在沒有明顯與咬合相關病變的情況下，可以保留患者現有的咬合排列，但應消除新修復體中所有不當的咬合 干擾（occlusal interference）","(C) 為改善長期預後，在對咬牙牙齒過度萌出（supra-eruption）或傾斜（tipping）時，牙醫師可能會進行對咬牙 之咬合調整（occlusal adjustment）和重塑（reshaping）","(D) 當牙橋以牙周受影響的自然牙當支柱牙，其對咬牙為植體固定義齒比對咬牙為全口義齒時，更容易出現併發 症"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-63","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"製作左下顎第二大臼齒至第二小臼齒之固定義齒，若第二大臼齒有近心傾斜，其長軸與第二小臼齒長軸之間 的角度，不宜超過幾度？","options":["(A) 5～10度","(B) 15～20度","(C) 25～30度","(D) 35～40度"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-64","subject":"ya5","topic":"臨床基礎與倫理","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"關於替患者比色的敘述，下列何者錯誤？","options":["(A) 詳實的比色是牙醫師的義務","(B) 比色時，如有使用額外光源輔助，其色溫應低於5000K","(C) 比色時，牙齒表面需清潔吹乾，但不可至脫水狀態","(D) 可以使用自製的比色板"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-65","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"關於鑄道及其材料選擇的敘述，下列何者錯誤？","options":["(A) 進行蠟型燒除時，鑄道大小應能容許熔融的蠟流出鑄模","(B) 鑄造時，鑄道不可太小，要能使熔融的金屬流入鑄模","(C) 鑄造時，鑄道內的熔融態合金會比已流入鑄模內的先硬化，以避免鑄件不當收縮","(D) 金屬材料亦可作為鑄道材料的選擇"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-66","subject":"ya5","topic":"牙科材料學","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"關於石膏結合包埋粉（gypsum bonded investment），為了獲得較大的膨脹，下列作法何者錯誤？","options":["(A) 用較少的水來混合包埋粉","(B) 金屬環內多一層石棉紙","(C) 燒卻（burnout）的時間增加","(D) 稍微增加包埋粉攪拌的時間"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-67","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"關於顳顎關節關節盤（articular disc）之解剖構造，下列敘述何者錯誤？","options":["(A) 關節盤為非骨化（non-ossified）組織","(B) 正常情況下顎髁（condyle）位置對應於關節盤的中間區（intermediate zone）","(C) 關節盤本身及周圍完全無神經支配","(D) 聯繫關節盤後方的是關節盤後組織（retrodiscal tissue），該處受較多神經血管支配"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-68","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"關於深度疼痛（deep pain）的神經與生理機制，下列何者正確？①所謂深部疼痛，指疼痛源自深部（非表皮 或肌肉）的組織，例如血管或內臟 ②深度疼痛是引發保護性共同收縮（protective co-contraction）的原因之 一 ③深部疼痛的來源可能是口腔顏面以外的部位（例如頸部） ④若口腔功能障礙（例如張口受限）與深 部疼痛有關，治療需聚焦於處理深部疼痛之處置","options":["(A) 僅①②④","(B) 僅①③④","(C) 僅②③④","(D) 僅①②③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-69","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"當咬合力太大，興奮了牙周韌帶（periodontal ligament）的感覺神經末梢，所產生的神經訊號通常會對部分咀 嚼肌產生抑制作用，下列那一塊肌肉不受此一抑制作用影響？","options":["(A) 二腹肌（digastric muscle）","(B) 咬肌（masseter muscle）","(C) 內翼肌（medial pterygoid muscle）","(D) 顳肌（temporalis muscle）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-70","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"安格氏第二型關係（Angle's class II relationship），中心咬合（centric occlusion）時，左下第一大臼齒之近心 頰側咬頭（mesiobuccal cusp）對咬於下列那個位置？","options":["(A) 左上第二小臼齒遠心邊緣嵴（distal marginal ridge）與左上第一大臼齒近心邊緣嵴（mesial marginal ridge）","(B) 左上第一大臼齒中心窩（central fossa）","(C) 左上第一大臼齒遠心邊緣嵴（distal marginal ridge）與左上第二大臼齒近心邊緣嵴（mesial marginal ridge）","(D) 左上第一大臼齒近心窩（mesial fossa）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-71","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"下列有關哥德式弧（Gothic arch）描繪的敘述，何者錯誤？","options":["(A) 哥德式弧描繪所作出的交叉點，常用來作為中心關係位置","(B) 肌夾護（muscle splinting）不影響描繪","(C) 不當導引可能造成描繪誤差","(D) 操作時應避開牙齒接觸"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-72","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"有關自然齒咬合及咬合調整的敘述，下列何者錯誤？①所有自然齒列中，平衡側的干擾都應立刻去除，以避 免將來造成顳顎關節障礙症 ②所有過早接觸皆應預防性的去除以穩定咬合關係 ③不適當的平衡側補綴可 能會干擾到工作側的咬合，進而影響患者咬合習慣的改變 ④矯正治療若拔除四顆小臼齒則容易引發顳顎關 節的障礙 ⑤當對單一顆牙齒進行局部選擇性修磨時，應同時針對咬頭嵌合位置（intercuspal position）以及 所有離心運動時的咬合接觸去除","options":["(A) 僅①②③","(B) 僅①③④⑤","(C) 僅②④⑤","(D) 僅①②④⑤"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-73","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"關於前突咬合記錄在半調節咬合器上的運用，下列敘述何者錯誤？","options":["(A) 前突咬合記錄可以用來調整髁頭的傾斜（inclination）程度","(B) 此種顎間關係記錄（bite registration）可以粗略模擬下顎向前向下的運動狀態","(C) 使咬合器表現出前突運動中髁頭平移（translation）與旋轉（rotation）的運動狀態","(D) 前突咬合記錄必須配合正確的上下顎間記錄的設定，同時在中心關係向前約4mm取得，方能正確使用"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-74","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"根據波氏圖（Pösselt’s diagram）矢狀面觀（sagittal view）中的描繪，下列敘述何者錯誤？","options":["(A) 主要是描繪下顎正中門齒切端相對於上顎牙齒運動的軌跡","(B) 影響下顎邊界運動描繪的主要結構並不包含肌肉與韌帶系統","(C) 下顎邊界運動描繪受到後牙咬合與關節盤的影響也很大","(D) 主要是描繪垂直方向與前後方向上最大範圍的運動"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-75","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"顳顎關節的輾軋音（crepitus），下列何者是最可能的原因？","options":["(A) 關節滑液炎（synovitis）","(B) 可復位性關節盤異位（disc displacement with reduction）","(C) 不可復位性關節盤異位（disc displacement without reduction）","(D) 骨關節炎（osteoarthritis）末期或是退行性關節炎（degenerative arthritis）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"顳顎關節內部紊亂（internal derangement）時，關節盤（disc）大多往那個方向移位？","options":["(A) 往後、內側","(B) 往後、外側","(C) 往前、內側","(D) 往前、外側"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-112-2-77","subject":"ya5","topic":"咬合學基礎","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"下列那些裝置長期配戴容易造成永久性咬合改變？①前咬合平面板（anterior bite plane） ②後咬合平面板 （posterior bite plane） ③單顎樞軸裝置（pivoting appliance）","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"以下何項物理治療較不適宜治療肌肉長期因疲勞或活動性過高所引起的疼痛？","options":["(A) 濕熱敷","(B) 冰敷","(C) 經皮神經電刺激（TENS）","(D) 被動性肌肉伸展"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"關於可復性關節盤移位（disc displacement with reduction）的敘述，下列何者正確？①開口聲響可發生在開口 過程中任何時段 ②當移位的關節盤復位時，在開口過程中可察覺有偏差（deviation） ③閉口聲響大多發 生在閉口初期時段 ④開口初期若下顎往對側偏移，有助於開口，且較不易閉鎖（lock）","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②④","(D) ①②③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-112-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"關於不可復性關節盤移位（disc displacement without reduction）的治療，下列敘述何者正確？①對於急性發生 的病例，可嘗試給予手動操作（manual manipulation）使關節盤復位 ②可使用前置位咬合板（anterior position splint），以減輕關節盤後組織（retrodiscal tissue）的壓力 ③對於同時伴有夜間磨牙的病人，可給予 穩定型咬合板（stabilization splint） ④對於疼痛的病人，可先用關節穿刺（arthrocentesis）法，經由沖洗去 除發炎物質","options":["(A) 僅①③","(B) ②④","(C) ①②③","(D) ①③④"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"關於義齒性口炎（denture stomatitis）的敘述，下列何者錯誤？","options":["(A) 主要是因為外傷引起第三類顆狀粒的形式（granular type）","(B) 口乾症（xerostomia）是局部性因素之一","(C) 使用免疫抑制的藥物（immunosuppressive drugs）是系統性因素之一","(D) 可使用抗黴菌藥物來治療"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"下列何種疾病可能與唾液分泌過多（hypersalivation）具有相關性？①帕金森氏症（Parkinson’s disease） ②腦性麻痺（cerebral palsy） ③糖尿病（diabetes mellitis） ④類風濕關節炎 （rheumatoid arthritis）","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"製作新的全口義齒時，關於評估唾液對義齒製作影響之敘述，下列何者錯誤？","options":["(A) 休息狀態下，正常人之唾液流量每分鐘約1毫升","(B) 可以輕輕擠壓顎下腺（submandibular gland）與沃頓管（Wharton duct），觀察是否有唾液自管口流出","(C) 可用兩隻手指用力觸診顎下腺（submandibular gland），觀察有無唾液之流出以確定顎下腺管道是否異常","(D) 顎下腺（submandibular gland）管道結石（sialolith）無法以觸壓方法診斷"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"關於全口義齒製作對於後腭封﹙posterior palatal seal﹚的敘述，下列何者錯誤？","options":["(A) 側方終點位於兩側的溝狀切迹（hamular notch）","(B) 中間位置位於腭小孔（fovea palatinae）前方約1至2mm處","(C) 位於振動線（vibrating line）的前方，在軟腭處形成壓跡","(D) 後腭封（posterior palatal seal）不能對於義齒用樹脂於煮聚時的收縮做補償，增加全口義齒後緣的密 合度"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"關於組成臼齒後墊後部（posterior portion of retromolar pad）的組織，下列敘述何者錯誤？","options":["(A) 顳肌腱纖維（fibers of the temporalis tendon）","(B) 頰肌纖維（fibers of the buccinator muscle）","(C) 上縮肌纖維（fibers of superior constrictor muscle）","(D) 咬肌纖維（fibers of masseter  muscle）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-6","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"有關拔牙後齒槽骨的吸收，下列敘述何者正確？","options":["(A) 一個月後就趨於穩定","(B) 屬於漸進式與不可逆的過程","(C) 一年後齒槽骨會穩定不變","(D) 每年平均骨的吸收量約1 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-7","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"下列何者與全口義齒咬合平面之決定最不相關？","options":["(A) 渦輪（modiolus）","(B) 臼齒後墊區（retromolar pad）","(C) 發S音（S sound）","(D) 瞳孔連線（interpupillary line）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-8","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"針對全口義齒的舌側咬合（lingualized articulation），下列敘述何者錯誤？","options":["(A) 咬合接觸區是在上顎腭側咬頭（palatal cusp）及下顎中心窩（central fossae）和頰側構造（buccal anatomy）","(B) 上下顎的頰側咬頭（buccal cusp）在咬合與側方運動時都無接觸","(C) 舌側咬合（lingualized articulation）的美觀效果通常被認為比平坦咬合面（flat occlusal surface） 佳","(D) 應遵循中立區（neutral zone）的概念，將下顎牙齒排成符合史比曲線（curve of Spee）與魏爾生曲線 （curve of Wilson）的補償曲線（compensating curve）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"全口義齒製作時，關於咬合垂直距離（vertical dimension of occlusion）的敘述，下列何者最不適當？","options":["(A) 拔牙前的咬合垂直距離為最值得信賴的參考數據","(B) 當下顎處於生理性靜止位置（physiological rest position）時，上、下顎的牙齒或蠟堤（occlusal rim）間應有一定的空間","(C) 可藉由判斷整體的臉部美觀支撐來決定咬合垂直距離","(D) 藉由發音測試（phonetic tests），可用來評估適當的咬合垂直距離"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-10","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"歌德式弧形描軌器（Gothic arch tracer）最主要的功能是用以記錄下列何者？","options":["(A) 中心關係（centric relation）","(B) 最小說話空間（closest speaking space）","(C) 下顎的靜止位置（rest position）","(D) 咬合垂直高度"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"關於全口義齒前牙排列的敘述，下列何者錯誤？","options":["(A) 全口義齒要減輕前方導引（anterior guidance）的目的，是為了義齒的穩定性","(B) 不論顎間關係如何，前牙至少要維持1～2 mm的overjet","(C) 選用不同咬頭角度之後牙時，前牙overbite的量可以不同","(D) Overbite與overjet組合的改變會影響前方導引（anterior guidance）的輕重"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"排列上下顎前牙時，對臉部的那一個區域影響最大？","options":["(A) 上1/3","(B) 中1/3","(C) 下1/3","(D) 整個臉部"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"全口活動義齒採用30度牙排成Angle's class Ⅰ咬合關係時，下列敘述何者最不適當？","options":["(A) 下顎向右突出時，咬合器門齒導柱離開門齒導引檯超過3mm，需檢查下顎左側頰咬頭之舌斜面（lingual incline of buccal cusp）","(B) 下顎向左突出時，咬合器門齒導柱離開門齒導引檯約1.5mm，兩側後牙皆有接觸為可接受的平衡式咬合 （balanced occlusion）","(C) 下顎向右突出時第一大臼齒有工作側干擾，應先修磨右側上顎第一大臼齒的頰咬頭之腭斜面（palatal incline of buccal cusp）","(D) 下顎向左突出時有平衡側干擾，應修磨左側上顎第一大臼齒的頰咬頭之腭斜面（palatal incline of buccal cusp）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"有關全口義齒舌側咬合型式（lingualized occlusion）的敘述，下列何者正確？","options":["(A) 不適於第二類安格氏咬合（Angle's class Ⅱ）的患者","(B) 下顎頰側咬頭，要對準上顎牙齒的近心窩（mesial fossa）","(C) 可選擇上顎有角度，下顎零度的人工牙","(D) 工作側（working side）的上、下顎頰側咬頭必須互相接觸"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"關於全口義齒義齒基底（denture base）與凸緣（flange）的敘述，下列何者錯誤？","options":["(A) 用顏色標記黏膜破皮潰瘍處來修整義齒凸緣是快速又有效的辦法","(B) 義齒凸緣過度延伸會造成義齒不穩或黏膜破皮潰瘍","(C) 如果病人覺得在鈎狀切迹（hamular notch）處不舒服，很有可能是後封區（postdam）的壓力太大","(D) 若在上顎唇繫帶（frenum）處感受到有刺激不適，在義齒邊緣切迹處不宜修整得太寬"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-16","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"全口活動義齒與病人嘔吐（gagging）關係的敘述，下列何者錯誤？","options":["(A) 上顎或下顎全口活動義齒都有可能造成患者嘔吐（gagging）","(B) 嘔吐有可能是病人心理因素（psychological component）造成","(C) 上顎全口活動義齒後緣（posterior border）過短時，易造成病人嘔吐","(D) 上顎全口活動義齒後緣（posterior border）不應超過振動線（vibrating line）2 mm，否則可能引起病 人嘔吐"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-17","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"裝置全口活動義齒，使用pressure-indicating paste（PIP）測試義齒基底（denture base）的適合度 （fitness）時，判讀的方式下列敘述何者錯誤？","options":["(A) 全口活動義齒置入時，臉頰造成的乾淨磨痕無需去做調整","(B) 被擾動的刷痕（disturbed brush lines）代表不適當的組織接觸，需要去做調整","(C) 沒有被擾動的刷痕（undisturbed brush lines）代表並無組織接觸","(D) 若粉紅色的樹脂基底顯現出來，表示過多的組織接觸與壓力，這些點需磨除舒緩"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-18","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"全口義齒於包埋（flasking）前必須做最後拋光面（polished surface）修形與齦綵成形（festooning）的 敘述，下列何者錯誤？","options":["(A) 下顎義齒舌側面必須形成適當的凹陷，以提供舌頭空間","(B) 人工牙齦邊緣蠟型形成約30度角的斜面，並依患者的年齡形成似自然牙齦之弧形","(C) 齒間乳頭處要修成平或稍凹，防止食物堆積","(D) 上顎義齒犬齒牙根處應形成犬齒隆凸（canine eminence），以防止嘴唇咬傷"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-19","subject":"ya5","topic":"植牙贋復","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"有關植牙手術後，贋復（prosthodontic）前，常見的併發症為何？①支柱體（abutment）鬆脫 ②口腔感 染 ③癒合支柱體（healing abutment）鬆脫","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-20","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"活動義齒樹脂床拋光後，在給病人裝戴前，下列步驟何者最適當？","options":["(A) 義齒保持乾燥以免黴菌滋生","(B) 義齒浸泡於漱口水中消毒72小時","(C) 義齒浸泡於水中72小時","(D) 義齒浸泡於假牙清潔錠溶液中72小時"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-21","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"製作上下顎全口義齒，因美觀要求，前牙使用瓷牙（porcelain teeth），但後牙因顎間空間較小而使用壓 克力樹脂牙（acrylic resin teeth）。有關這種人工牙齒材料的選擇與組合，下列敘述何者正確？","options":["(A) 合理：可兼顧前牙美觀，並利於後牙調整","(B) 合理：前牙較不易變色，後牙與樹脂床黏著佳","(C) 不合理：後牙較易磨耗，易致前牙區咬力過重","(D) 不合理：不同材質於顏色與形態上較難配合"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"關於牙醫師為產品代言或廣告的規範，下列何者錯誤？","options":["(A) 牙醫師應儘量避免參與任何醫療及健康有關之商業廣告或代言","(B) 可以為基於社會公益或促進醫學進步目的，為產品做醫療廣告","(C) 醫療專業意見之發表或陳述，應以曾於醫學會或醫學領域之專業期刊或學術活動公開或發表之論文著作內 涵或研究報告為準","(D) 不宜介紹、功能描述或影射其未經科學研究證實功效之產品"],"answer":[0,1,2,3],"image":"","clinical_level":"一般","explanation_pending":false},{"id":"ya5-113-1-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"小連接體（minor connector）終接線（finishing line）的敘述，下列何者錯誤？","options":["(A) 樹脂與金屬交接面，位於主連接體的內側朝向軟組織稱之為內終接線（internal finishing line）","(B) 內終接線（internal finishing line）需要以少於90度角的設計，以改善樹脂的機械性固持作用","(C) 內終接線（internal finishing line）是在主模型上貼24至26號（gauge）的緩壓蠟而形成","(D) 外終接線（external finishing line）是在金屬支架的製作過程中雕刻蠟型而形成"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"小連接體（minor connectors）模型止位（cast stops）之敘述，下列何者錯誤？","options":["(A) 牙齒支持（tooth-supported）的可撤式局部義齒必須具有此設計","(B) 可以防止在樹脂填充（resin packing）的過程中造成金屬支架變形","(C) 製作方法是在無牙嵴正中部分移除緩壓蠟2x2 mm的小方塊而成","(D) 金屬支架應與主模型的表面有接觸"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"關於舌側隆凸鈎靠（cingulum rest）與切緣鈎靠（incisal rest）的敘述，下列何者正確？","options":["(A) 犬齒缺失時，能以多顆門牙的舌側隆凸鈎靠取代切緣鈎靠支持的功能","(B) 切緣鈎靠比舌側隆凸鈎靠力量傳導更接近牙齒長軸，故優先考量使用","(C) 舌側隆凸鈎靠縱切觀時的外型呈現V型，位於咬合1/3與中間1/3的交界位置","(D) 舌側隆凸鈎靠的近遠心長度約2.5～3.0 mm，切緣根尖深度需要0.5 mm"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"在可撤式局部義齒牙鈎設計中，關於楔隙牙鈎（embrasure clasp）的敘述，下列何者錯誤？","options":["(A) 主要由兩個環狀牙鈎經由兩個支柱牙間的邊緣嵴與咬合面所組成","(B) 可用於沒有modification的Kennedy class II or III","(C) 應使用在缺牙區的一側，以增加支柱牙的固位力","(D) 最常見斷裂原因是位於接觸區的牙齒修磨量不足所造成"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"關於遠伸性可撤式局部義齒（distal extension removable partial denture），受到咬合力時，下列敘述 何者正確？","options":["(A) 無牙嵴最遠心黏膜比近心處會有較大下沉量","(B) 鄰近無牙嵴的支柱牙受力與引導面（guiding plane）設計無關","(C) 無牙嵴型態與黏膜下沉量無關","(D) 鄰近無牙嵴的支柱牙引導面（guiding plane）不會下沉"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-113-1-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"下列何種可撤式局部義齒主要由鈎靠（rest）提供支持（support）？","options":["(A) Kennedy class I","(B) Kennedy class II","(C) Kennedy class III","(D) 僅餘雙側臼齒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"Kennedy class IV 短徑距缺牙區合併嚴重齒槽骨缺損，若以美觀為考量，下列何者為最佳選擇？","options":["(A) 固定式義齒","(B) 傳統可撤式局部義齒","(C) 使用連接槓（splint bar）","(D) 彈性可撤式局部義齒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"設計可撤式局部義齒時，小連接體與鈎靠須考量的事項，下列敘述何者錯誤？","options":["(A) 鄰接板（proximal plate）應可提供可撤式局部義齒戴入與取出的明確路徑","(B) 鄰接板（proximal plate）應可協助抵抗水平方向的作用力，以提供義齒的支持與固位作用","(C) 鈎靠與小連接體須小於90度","(D) 鈎靠在鈎座應可將咬合受力傳遞到支柱牙"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"下列那些是牙科用析量器的共通構造？①與桌面平行的水平平台 ②支撐上方結構的垂直柱 ③水平臂 ④ 析量臂 ⑤模型研磨機","options":["(A) ①②③④⑤","(B) 僅②③④⑤","(C) 僅③④⑤","(D) 僅①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-32","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"上顎前牙牙齒往顏面側傾斜（facial tipping）或牙弓單側牙往頰側傾斜，通常會造成什麼析量結果？","options":["(A) 微調析量台傾斜度無法改善高隆線","(B) 高隆線往齒頸部移動","(C) 頰側鈎更容易放置","(D) 牙齦組織易位於倒凹中"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-33","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"關於可撤式局部義齒咬合鈎座（occlusal rest seat）的修形，下列敘述何者正確？①輪廓外形是圓三角形 （rounded triangular shape）頂尖朝向咬合面中心 ②在邊緣嵴處三角形的底邊（base）小臼齒至少2.5 mm寬，大臼齒3.5 mm寬 ③在邊緣嵴處大約需要1.5 mm的深度 ④底部相對於邊緣嵴是水平且無尖銳邊緣及 線角","options":["(A) ②④","(B) 僅①③","(C) ①②③","(D) ①③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-34","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"關於可撤式局部義齒甘迺迪分類系統（Kennedy classification system），下列敘述何者正確？①便於區 分義齒是由牙周支持或牙齒和組織支持（tooth-supported and tooth- and tissue-supported）的分類 ②分類系統的數字順序部分基於發生頻率 ③Class IV缺牙牙弓最不常見 ④此分類有助於牙醫師與牙技師 理解、溝通和設計","options":["(A) ①②③④","(B) 僅①③④","(C) 僅②③","(D) 僅①②④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-35","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"可撤式局部義齒設計時，間接固位（indirect retention）的考量，下列敘述何者正確？①Kennedy class IV的義齒設計無需考慮間接固位    ②設計時間接固位體（indirect retainer）應儘可能遠離可撤式局部 義齒做旋轉運動時的支點線（fulcrum line）   ③特別是在缺牙區較長的情況下，Kennedy class IV的義 齒設計應被視為Kennedy class I反向可撤式局部義齒 ④Kennedy class II的義齒設計必須考慮 I 和 III 類設計的特徵","options":["(A) ①②③④","(B) 僅①③","(C) 僅②③④","(D) 僅①②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"製作可撤式局部義齒時造成模型不精確的原因，下列何者錯誤？","options":["(A) 水凝膠印模材會因吸水造成模型膨脹","(B) 使用石膏時，水粉比太高","(C) 30分鐘足夠石膏初期硬化，即可拆模","(D) 混合石膏材料及倒模時未充分使用震盪器，使模型表面有氣泡"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"關於製作上顎個人壓克力模托，下列敘述何者錯誤？","options":["(A) 須在診斷模型上畫出模托須覆蓋的部分","(B) 貼蠟時，在組織及牙齒表面皆貼上一層基底板蠟","(C) 此蠟片間隙（wax space）須比模托預期會涵蓋處短少2～3mm","(D) 後顎封（posterior palatal seal）的部分不可被蠟覆蓋，但必須涵括在模托內"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"有關可撤式局部義齒之敘述，下列何者錯誤？","options":["(A) 遠伸性（distal extension）義齒在咬合器上調整比在口內調整更精確","(B) 加大遠伸性義齒人工牙（artificial teeth）之咬合面頰舌側寬度可降低支持組織之壓力","(C) 咬合調整應在義齒其他部位調整後再實施","(D) 牙齒支持性（tooth-supported）局部義齒可在口內調整"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-39","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"製作可撤式局部義齒時，下列何者不屬於Hanau Quint影響咬合的重要因素？","options":["(A) 牙尖高度（cusp height）","(B) Bonwill三角（Bonwill triangle）","(C) 髁導傾斜度（condyle guidance inclination）","(D) 門齒導引傾斜度（incisal guidance inclination）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"下列何者不是可撤式局部義齒換底（rebase）的適應症？","options":["(A) 義齒基底之覆蓋範圍太少","(B) 義齒金屬床之軟組織支持（soft tissue support）不夠","(C) 義齒基底變色","(D) 義齒基底大範圍斷裂"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"下列何者最不適用於可撤式局部義齒的清潔？","options":["(A) 鹽水","(B) 重碳酸鈉（sodium bicarbonate）","(C) 鹼性次氯酸清潔劑（alkaline hypochlorite cleaner）","(D) 鹼性過氧化物清潔劑（alkaline peroxide cleaner）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"下列何者不是患者使用可撤式局部義齒時，發生咬頰或咬舌（cheek or tongue biting）的最主要原因？","options":["(A) 選擇人造陶瓷牙","(B) 咬合平面過低","(C) 上下顎人工牙排列的水平覆蓋（horizontal overlap）不足","(D) 患者缺牙過久舌頭鬆弛肥大"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-43","subject":"ya5","topic":"牙科材料學","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"可撤式局部義齒基底樹脂的填塞製作過程，關於操作注意事項的敘述下列何者錯誤？","options":["(A) 樹脂依正確粉、液比調和後放密閉容器內直到呈現麵團狀黏稠度即可填壓","(B) 分離式填塞技術常用於可撤式局部義齒的製作，每次填塞時應提供足夠樹脂","(C) 包埋盒組合後置於加壓機內，逐步漸進式加壓提供足夠時間給多餘樹脂往周邊移動","(D) 可以使用小調刀或銳利的器械將周邊溢流出來多餘樹脂沿著義齒基底邊緣作修整"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"製作可撤式局部義齒金屬支架（metal framework）主模型時，下列那一部位最需要做外形封凹（shaped blockout）？","options":["(A) 小連接體（minor connector）所覆蓋之深層鄰接空間","(B) 堅硬的連接體所要跨越過的組織倒凹（tissue undercut）","(C) 舌側槓（lingual bar）連接體下方","(D) 用來標示牙鈎臂（clasp arm）下緣置放在牙齒的頰舌側面的位置"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"關於邊緣設計的考量，下列何者錯誤？","options":["(A) 在窩緣角（cavosurface）不要留下無支撐的牙釉質","(B) 使邊緣在光學掃描或是印模時清晰可見","(C) 完成線（finish line）須明確可辨","(D) 為儘量保留牙齒結構，邊緣修磨量可小於材料所需之最小厚度"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"關於修磨支柱牙時，溫度造成支柱牙傷害的敘述，下列何者錯誤？","options":["(A) 過大的壓力會增加熱產生","(B) 水霧不應直接噴在牙齒上","(C) 需清除鑽針上的雜質以維持切削效率","(D) 降低電動手機（electric handpieces）的轉速時，可以降低噴出的水量"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-47","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"關於顳顎關節（temporomandibular joint）韌帶的敘述，下列何者正確？①顳顎韌帶（temporomandibular ligaments）限制髁突與關節盤的分離 ②顳顎韌帶限制下顎旋轉 ③莖突下顎韌帶（stylomandibular ligaments）限制下顎往前運動 ④莖突下顎韌帶限制下顎的邊緣運動","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-48","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"為患者製作13×15的固定牙橋，發現患者做下顎向右的側方運動（right jaw excursion）時，會有左側的平 衡側干擾（balanced interference），下列處理方式何者最適當？","options":["(A) 不用管平衡側干擾，直接修磨牙齒印模就好","(B) 先印製一組參考模型置位於咬合器上，然後在咬合器上修磨石膏模型，看有那些平衡側干擾需要去除","(C) 先印製兩組參考模型置位於咬合器上，一組模型當作參考，另一組則可修磨，看有那些干擾需要去除","(D) 直接在口內修除平衡側干擾"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-49","subject":"ya5","topic":"牙科材料學","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"根據美國ADA分類牙科用的石膏（dental gypsum products），可分成五種，由type I 至type V，所謂高強 度dental stone 是屬於那一型？","options":["(A) type I","(B) type II","(C) type III","(D) type IV"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-50","subject":"ya5","topic":"牙科材料學","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"下列何者不是市售排齦線（gingival cord）中常用的收斂劑（astringent）？","options":["(A) Al2K(SO4)2","(B) AlCl3","(C) Fe2(SO4)3","(D) FeK(SO4)2"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-51","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"113年第1次第51題","year":113,"session":1,"number":51,"question":"根管治療後的牙齒需要製作根柱（dowel）和牙冠時，為兼顧固持力與壓力分布，根柱長度最好為牙根長度 的多少倍？","options":["(A) 1/4","(B) 1/3","(C) 1/2","(D) 2/3"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-52","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第1次第52題","year":113,"session":1,"number":52,"question":"關於卵形橋體（ovate pontic）的敘述，下列何者錯誤？","options":["(A) 卵形橋體通常深入拔牙傷口約2.5 mm深，同時進行骨保留骨移植術","(B) 拔牙後約4星期，卵形橋體深入齒槽窩（socket）1.5 mm以利維持口腔清潔","(C) 無牙齒槽嵴進行修形以支撐卵形橋體，顏面側需深2～2.5 mm以達到美觀","(D) 骨頭與卵形橋體間的牙齦組織厚度至少要達到2 mm厚"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第1次第53題","year":113,"session":1,"number":53,"question":"牙橋金屬部位焊接（soldering）時，下列焊接縫隙的寬度何者最適合？","options":["(A) 0.1 mm","(B) 0.25 mm","(C) 0.5 mm","(D) 0.75 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第1次第54題","year":113,"session":1,"number":54,"question":"若橋體的齦切長度（incisogingival length）較長，下列改善其外形的方法中，那一種因有最多的組織接 觸而需要繁瑣的清潔維護？","options":["(A) 修整橋體唇側近牙齦1/5處的外形","(B) 修整橋體唇側近牙齦1/2處的外形","(C) 橋體牙骨質牙釉質交界處（cementoenamel junction）模擬牙根外形","(D) 使用粉紅色瓷（pink porcelain）模擬牙齦"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第1次第55題","year":113,"session":1,"number":55,"question":"下列何者為製作全瓷牙冠的禁忌？","options":["(A) 磨牙症","(B) 鄰接面蛀牙","(C) 根管治療過後的牙齒","(D) 牙齦萎縮"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-56","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第1次第56題","year":113,"session":1,"number":56,"question":"有關金屬瓷牙冠牙橋金屬設計之敘述，下列何者錯誤？","options":["(A) 金屬厚度最少0.3～0.5 mm","(B) 金屬厚度最多1.0 mm","(C) 金屬表面不能有尖角度外形（sharp angle）","(D) 不影響美觀及清潔之情況下，連接體（connector）愈粗愈好"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-57","subject":"ya5","topic":"牙科材料學","meta":"113年第1次第57題","year":113,"session":1,"number":57,"question":"製作暫用性牙冠（interim crowns）的樹脂（resin）材料，下列敘述何者正確？①bis-GMA相較於自聚性 PMMA有較強的生物毒性 ②bis-GMA相較於自聚性PMMA有較穩定的顏色 ③自聚性PMMA較bis-GMA斷裂韌性 （fracture toughness）低","options":["(A) ①","(B) 僅②","(C) 僅③","(D) ②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-58","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第1次第58題","year":113,"session":1,"number":58,"question":"根據Beyer的研究，當製作前牙固定義齒時，在美觀的考量上，牙齒中線（dental midline）與臉部中線之 間，臨床上可以接受的偏移量平均值最多不宜超過多少？","options":["(A) 0.5 mm","(B) 1.2 mm","(C) 2.2 mm","(D) 3.2 mm"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-59","subject":"ya5","topic":"植牙贋復","meta":"113年第1次第59題","year":113,"session":1,"number":59,"question":"美觀區人工植體上緣與預計贋復物露出牙齦的位置，較理想的距離為多少mm？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-60","subject":"ya5","topic":"植牙贋復","meta":"113年第1次第60題","year":113,"session":1,"number":60,"question":"關於單顆植體要做closed-tray implant level impression，下列步驟何者錯誤？","options":["(A) impression post先鎖在植體上，檢查X光片確認到位","(B) 印模材硬化後，取出前須先轉鬆impression post screw","(C) 將implant analog鎖緊到impression post之上","(D) 以彈性材製作植體軟組織之後再倒模"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-61","subject":"ya5","topic":"咬合學基礎","meta":"113年第1次第61題","year":113,"session":1,"number":61,"question":"關於jaw manipulation取得中心關係（CR）紀錄的敘述，下列何者錯誤？","options":["(A) 應盡可能用力地將下顎後推，方能取得正確的位置","(B) 使用bimanual manipulation technique時，大拇指應施力向下，其他四指應稍微向上施力，將關節髁及關 節盤推向關節窩的位置","(C) 使用single-handed technique時，手指應施力朝上，使用此法較難確保關節髁位於正確的位置","(D) 當CR與最大咬頭嵌合（MI）位置不一致時，可先使用anterior deprogramming devices來處理（例如Lucia jig）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-62","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第1次第62題","year":113,"session":1,"number":62,"question":"以a-f圖示為例，a與b、c與d、e與f互相比較，各組中何者較適合成為固定贋復裝置之支柱牙 （abutment）？","options":["(A) a+c+e","(B) b+d+f","(C) a+d+e","(D) b+c+f"],"answer":2,"image":"ya5-113-1-62.jpeg","clinical_level":"一般"},{"id":"ya5-113-1-63","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第1次第63題","year":113,"session":1,"number":63,"question":"使用數位微笑設計軟體（digital 3D smile design）進行前牙牙齒形狀設計時，訂出那條線是微笑設計過 程中最重要的一步？","options":["(A) 瞳孔間線（interpupillaryline）","(B) 牙齒中線（dental midline）","(C) 顏面中線（facial midline）","(D) 切緣位置（incisal edge position）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-64","subject":"ya5","topic":"牙科材料學","meta":"113年第1次第64題","year":113,"session":1,"number":64,"question":"關於鑄道大小的考量，下列何者錯誤？","options":["(A) 鑄造臼齒牙冠時，可考慮使用直徑大小2.5 mm的鑄道","(B) 鑄造小臼齒牙冠時，可考慮使用直徑大小2.0 mm的鑄道","(C) 相對於離心鑄造機，使用氣壓式鑄造機應改用直徑較大的鑄道以避免熔融態合金提前流入鑄模","(D) 鑄造時，鑄道內的熔融態合金需比已流入鑄模內的晚硬化，以避免鑄件不當收縮"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-65","subject":"ya5","topic":"牙科材料學","meta":"113年第1次第65題","year":113,"session":1,"number":65,"question":"關於鑄造用金合金選擇的考量，下列何者錯誤？","options":["(A) 牙冠鑄造一般使用第三型金合金","(B) 活動義齒支架鑄造一般使用第四型金合金","(C) 以硬度來區分，第四型金合金的硬度最低","(D) 與金合金相比，鎳鉻合金的鑄造精準度較低，且其鑄件的表面粗糙度較高"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-1-66","subject":"ya5","topic":"牙科材料學","meta":"113年第1次第66題","year":113,"session":1,"number":66,"question":"下列黏合劑何者適用於瓷鑲面（ceramic veneer）？①強化氧化鋅丁香油酚（reinforced ZOE）  ②樹脂 離子體（resin ionomer） ③黏著樹脂（adhesive resin） ④自酸蝕黏著樹脂（self-etch adhesive resin）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-67","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第1次第67題","year":113,"session":1,"number":67,"question":"關於人類肌肉的運動單位（motor unit），下列敘述何者錯誤？","options":["(A) 由單一個運動神經元（motor neuron）與其所支配的肌纖維構成","(B) 運動神經元支配的肌纖維數目越少，該運動單位則參與越精密（precise）的運動","(C) 運動神經元支配的肌纖維數目可能少至個位數，多至數百","(D) 嚼肌（masseter）的單一運動神經元比外翼肌（lateral pterygoid muscle）支配較少的肌纖維"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-68","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第68題","year":113,"session":1,"number":68,"question":"關於顳顎關節症檢查的各種功能性操作（functional manipulation）的生理機制，下列何者正確？①外翼 肌（lateral pterygoid muscles）不易以觸診（palpation）檢查，適用功能性操作檢查 ②假使下 （inferior）外翼肌是痛源（the source of pain），則前突（protrusion）運動常引發疼痛 ③假使上 （superior）外翼肌是痛源，則張口（opening mouth）時常引發疼痛 ④假使內翼肌是痛源，則緊咬 （clenching）時常引發疼痛","options":["(A) 僅②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-69","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第69題","year":113,"session":1,"number":69,"question":"下列結構何者不會表現顳顎關節疼痛？","options":["(A) 關節盤中央（central part of disc）","(B) 關節盤韌帶（discal ligament）","(C) 關節囊韌帶（capsular ligament）","(D) 關節盤後組織（retrodiscal tissue）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-70","subject":"ya5","topic":"咬合學基礎","meta":"113年第1次第70題","year":113,"session":1,"number":70,"question":"關於臨床靜止位置（clinical rest position）時下顎的位置，下列敘述何者正確？","options":["(A) 此位置咀嚼肌（mastication muscles）有最小的電肌活動力（electromyographic activities）","(B) 在咬頭嵌合位置（intercuspal position）上方約 2 到 4 毫米","(C) 跟中心關係（centric relation）位置交疊（overlap）","(D) 會受頭部位置（head position）及角度影響"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-71","subject":"ya5","topic":"咬合學基礎","meta":"113年第1次第71題","year":113,"session":1,"number":71,"question":"功能性的牙齒磨損，齒列可能出現的變化不包含下列何者？","options":["(A) 牙齒再萌出","(B) 鄰接面磨損","(C) 後牙的遠心移動（distal drift）","(D) 從額面觀呈現顛倒的威爾生氏曲線（inverted Wilson's curve）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-72","subject":"ya5","topic":"咬合學基礎","meta":"113年第1次第72題","year":113,"session":1,"number":72,"question":"側方運動時的咬合干擾，於上顎牙齒需修磨的位置，下列何者正確？","options":["(A) 在工作側（working side），修磨的位置為頰側咬頭舌側斜嵴（lingual incline）","(B) 在工作側（working side），修磨的位置為頰側咬頭頰側斜嵴（buccal incline）","(C) 在非工作側（non-working side），修磨的位置為頰側咬頭頰側溝（buccal groove）","(D) 在非工作側（non-working side），修磨的位置為中央溝（central groove）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-73","subject":"ya5","topic":"咬合學基礎","meta":"113年第1次第73題","year":113,"session":1,"number":73,"question":"臨床上關於模型置位（mounting）上咬合器相關的操作方式，下列何者錯誤？","options":["(A) 中心關係（centric relation）咬蠟記錄不應發生牙齒的接觸","(B) 若有可能改變模型的咬合垂直高度時，建議使用面弓轉移","(C) 咬合紀錄不應與軟組織有過多接觸","(D) 不可使用平均值來設定髁頭傾斜度（condylar inclination）與角度（condylar angle），因容易出現重 大誤差"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-74","subject":"ya5","topic":"咬合學基礎","meta":"113年第1次第74題","year":113,"session":1,"number":74,"question":"在前牙贋復時常使用的客製化前方導引平台（custom anterior guidance table），下列敘述何者錯誤？","options":["(A) 用來記錄患者原有的或臨時贋復物的前牙導引，包括前突與側方運動","(B) 產生主要記錄時，髁頭沿著關節隆突斜面平移，並環繞著水平與垂直的軸線旋轉","(C) 調整原有咬合器導引平臺的前後角度及側翼角度，就可以得到客製化前方導引","(D) 主要是記錄穩定前牙的動態接觸關係，此時它的導引遠大於髁頭運動的影響"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第75題","year":113,"session":1,"number":75,"question":"有關夜間磨牙（bruxism）之敘述，下列何者正確？①會造成牙齒不正常磨耗（tooth wear） ②可能會導 致咀嚼肌群或顳顎關節疼痛 ③磨牙之程度不受患者本身情緒壓力影響 ④可用咬合板根治","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②③","(D) ①②③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第76題","year":113,"session":1,"number":76,"question":"鄭小姐於春節連假期間在吃完一包魷魚絲之後第二天發現咬肌（masseter muscle）疼痛，但開口正常。下 列何項敘述最符合鄭小姐的狀況？","options":["(A) 顳顎關節拉傷；給予非類固醇消炎藥物（NSAIDs）","(B) 咀嚼肌肉過度負擔；建議休息、軟食","(C) 咬合不良導致咀嚼效率低；建議進行咬合調整","(D) 關節盤移位；施以咬合板治療"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-77","subject":"ya5","topic":"咬合學基礎","meta":"113年第1次第77題","year":113,"session":1,"number":77,"question":"關於顳顎障礙症的治療方法，下列何者錯誤？","options":["(A) 顳顎障礙症不可逆治療，利用咬合調整，義齒贋復、手術或矯正治療，皆應屬於第二階段所採取的方法","(B) 咬合問題與顳顎障礙症的關聯性，因為難以釐清因果，目前普遍被認為只有中或低程度的相關性","(C) 前牙開咬仍被認為是顳顎障礙症的病因之一，手術與矯正治療可以儘量恢復患者舊觀","(D) 可逆與不可逆治療的治療效果似乎類似，對於咬合干擾的治療越來越趨向採取保守可逆的方式來治療"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-113-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第78題","year":113,"session":1,"number":78,"question":"下列有關密西根咬合板之敘述，何者正確？","options":["(A) 為咬合面具有牙齒形狀之咬合板","(B) 側向運動時宜使用群體功能（group function）咬合模式","(C) 必須全天候配戴","(D) 厚度亦受患者本身垂直覆蓋（overbite）之影響"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第79題","year":113,"session":1,"number":79,"question":"單側骨關節炎（osteoarthritis）當造成嚴重髁頭骨吸收時，下列敘述何者正確？①可能造成同側後牙開 咬 ②可能造成對側後牙開咬 ③可能造成同側過早咬合接觸 ④可能造成對側過早咬合接觸","options":["(A) 僅③","(B) 僅④","(C) ①④","(D) ②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第1次第80題","year":113,"session":1,"number":80,"question":"使用前置位咬合板（anterior position splint）治療可復性關節盤移位（disc displacement with reduction），若造成後牙開咬，下列何種解釋被認為是最可能的原因？","options":["(A) 配戴前置位咬合板的時間不夠長所致","(B) 上外翼肌（superior lateral pterygoid muscle）纖維化肌短縮（myofibrotic contracture）","(C) 前牙變長","(D) 因為形成較厚的關節盤後組織（retrodiscal tissue）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"關於義齒性口炎（denture stomatitis）的敘述，下列何者正確？","options":["(A) 出現在下顎的比例比上顎高","(B) 根據1962年Newton的分類，第二型狀況是硬腭（hard palate）有出現發炎性的增生（inflammatory hyperplasia）","(C) 口角炎（angular cheilitis）常與念珠菌義齒性口炎（Candida-associated denture stomatitis）相關","(D) 口乾症（xerostomia）並非可能的肇因"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"關於老年無牙狀態的咬合適應與變化，下列敘述何者錯誤？①保護反射（protective reflex）增加 ②殘嵴 （residual ridge）隨著時間漸漸吸收 ③神經肌肉適應性（neuromuscular adaptability）增加 ④異常 功能活動（parafunctional movement）減少 ⑤對活動義齒佩戴不良經驗的風險增加","options":["(A) ②③④","(B) ①③④","(C) ②④⑤","(D) ①③⑤"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"有關全口無牙病人初診時之觸診（palpation），下列敘述何者正確？①不能確實測量組織倒凹的大小 ②主 要及次要義齒支持區皆須觸診 ③口腔外的觸診須經病人同意始能實施 ④為避免影響觸感，觸診時脫掉手 套較好","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"關於全口義齒製作的敘述，下列何者錯誤？","options":["(A) 下顎齒槽骨吸收比較多時，印模時牙托的邊緣會比較短","(B) 舌頭進行前突動作是為了確認義齒後緣寬度","(C) 舌頭與完成義齒邊緣成形（border molding）的牙托要輕微接觸","(D) 舌頭的動作會受到咬合蠟堤的高度與位置所影響"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"關於全口義齒客製化模托（individual tray）的製作流程，下列何者錯誤？","options":["(A) 需要用蠟片留下約1至2mm的空間給正式印模材料","(B) 邊緣需要比預想的假牙邊緣短約2至3mm","(C) 要用堅硬的材料製作，維持約1至2mm的厚度","(D) 需要到口內試戴及調整，才可以進行印模的步驟"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"有關下顎舌骨嵴（mylohyoid ridge）和下顎舌骨肌（mylohyoid muscle）的敘述，下列何者正確？","options":["(A) 下顎義齒的舌側邊緣不可延伸覆蓋它","(B) 可以藉移動舌頭的尖端來記錄下顎舌骨肌收縮的狀態","(C) 義齒舌側的下顎舌骨嵴附近呈現凹陷的磨光面（polished surface）可以增加義齒的固位（retention）和 穩定（stability）","(D) 舌下腺（sublingual glands）位於下顎舌骨肌之下，當吞嚥時，舌下腺會上升，造成下顎義齒移位"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"有關以撒佈法（sprinkle-on method）製作樹脂記錄基底（recording base）的敘述，下列何者錯誤？","options":["(A) 使用自聚式樹脂（auto-polymerizing resin）","(B) 模型上要塗分離劑","(C) 模型於倒凹區（undercut area）不需要封凹（blockout）","(D) 可置入壓力鍋中以促進聚合反應"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"關於決定與記錄全口義齒垂直咬合高度，下列敘述何者最適當？","options":["(A) 最正確的垂直咬合高度為病人拔牙前模型的記錄","(B) 如果根據自由間隙（freeway space）方法取出較高的垂直咬合關係，病人配戴這樣的全口義齒在 發“S”音時，上下牙齒必然會發生碰撞","(C) 以外觀、發音與吞嚥法決定全口義齒病人的垂直咬合關係得到不同結果時，絕對是病人的神經肌肉控制不 好","(D) 有無配戴咬合蠟堤－基底會得出不同的垂直咬合高度"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-9","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"如果病人在配戴全口義齒時發/t/時聽起來像/d/，最可能的原因為何？","options":["(A) 上顎門牙排得太偏舌側（lingual）","(B) 顎間垂直關係太高","(C) 舌頭空間太大","(D) 上顎義齒基底（denture base）往後延伸太多"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"全口活動義齒的排牙規則，下列敘述何者錯誤？","options":["(A) 上下前牙垂直覆蓋（overbite）應大於水平覆蓋（overjet）","(B) 目前沒有學術證據顯示那一種後牙的牙齒型態是最理想的","(C) 後牙的咬合平面建議從下顎犬齒的遠心接觸點延伸到臼齒後墊（retromolar pad）的中點","(D) 避免將牙齒排列在下顎往臼齒後墊（retromolar pad）的上升枝（ascending ramus）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-11","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"關於全口義齒舌側咬合（lingualized occlusion）的敘述，下列何者最為正確？","options":["(A) 主要是靠下顎後牙的頰側咬頭（buccal cusp）對咬在上顎的中心窩（central fossa）","(B) 排牙必需由上顎前後牙先排起","(C) 可減少側向咬合接觸","(D) 由於牙齒接觸面積少，因此必需要排滿到第二顆大臼齒才能提供足夠咀嚼效率"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"關於全口義齒的雙側平衡性咬合，下列敘述何者正確？","options":["(A) 與吞嚥口水時無關","(B) 與骨頭吸收速率無關","(C) 與義齒的穩定性有關","(D) 與病人神經肌肉系統無關"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"單顎全口義齒在排牙時若無法達到雙側平衡咬合（bilateral balanced occlusion），下列何種為合理的方 式？①選用更大顆、角度更陡的樹脂牙再進行修改 ②改用注射成型技術（injection molding technique）煮聚樹脂床以減少義齒形變 ③鑄造金屬（cast gold）做出客製化的咬合面覆蓋在樹脂牙上 ④根據理想的咬合平面修整對咬的自然牙 ⑤排牙前要用面弓轉移置位模型","options":["(A) ①②③④","(B) ①②③⑤","(C) ①③④⑤","(D) ②④⑤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"製作全口義齒時，為獲得多個工作側接觸及至少一個平衡側接觸，以獲得平衡咬合（balanced occlusion），下列模式何者最不適用？","options":["(A) 採用上顎解剖形態後牙與下顎零度牙後牙排成舌側化咬合（lingualized occlusion）模式","(B) 採用零度牙排成平面咬合（monoplane occlusion）模式","(C) 採用零度牙配合補償曲線（compensating curves）模式","(D) 採用零度牙配合第二大臼齒斜坡（second molar ramp）的排列模式"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-15","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"當病人在配戴全口義齒的隔天，黏膜出現廣泛性的發炎及紅腫，下列情況何者的可能性最大？","options":["(A) 對義齒的材料有過敏的現象","(B) 印模產生誤差","(C) 義齒煮聚產生誤差","(D) 垂直咬合高度太低"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"下列何者不是全口義齒內使用組織調理材（tissue conditioner）的適應症？","options":["(A) 讓受傷的組織恢復健康","(B) 拔牙後避免傷口的壓迫","(C) 避免口腔念珠菌（Candida albicans）感染","(D) 當作功能性印模（functional impression）材料"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"全口義齒的病人回診時，若抱怨講話時不太順暢，特別是發m音時，下列何者為最可能的原因？","options":["(A) 上顎門牙太長","(B) 上顎義齒的嘴唇支撐（lip support）不足","(C) 上下顎義齒的中心關係（CR）位置不正確","(D) 上下顎義齒前牙垂直覆蓋太少"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"關於單顎全口義齒（single denture）的敘述，下列何者錯誤？","options":["(A) 製作於下顎較上顎容易達到需求","(B) 當訂定治療計畫時，醫師需考慮到對咬牙的咬合面，以期待能達到咬合的平衡（occlusal balance）","(C) 可使用鑄造金屬的覆蓋體（overlay）於對側牙來完成平衡咬合","(D) 可用咬合蠟堤（occlusion rim）在缺牙齒列建造一個理想的咬合平面，藉由這咬合平面來調整 （selective recontouring）對咬牙的咬合"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-19","subject":"ya5","topic":"植牙贋復","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"有關上顎植體支持的覆蓋式義齒，所需植體數量的敘述，下列何者正確？①一般至少要4至6根 ②植體的種 植方向不同時，可選用2根 ③弧形的牙弓可選用2根 ④骨質較鬆的牙弓，不可選用2根","options":["(A) ①②③","(B) ②③④","(C) ①④","(D) 僅②③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-20","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"全口活動義齒換底墊（reline）以及換基底（rebase）時，若採用功能性印模法（functional impression technique），其所使用的組織調理材（tissue conditioner）應達到何種階段？","options":["(A) 塑料期（plastic stage）","(B) 彈性期（elastic stage）","(C) 穩固期（firm stage）","(D) 硬化期（hard stage）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-21","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"全口義齒壓克力樹脂床（acrylic resin denture base）使用熱水浴煮聚（processing）時，若溫度上升太 快則易於樹脂床內形成孔洞（porosity）。有關孔洞形成之敘述，下列何者正確？","options":["(A) 因各處聚合速度不均，而形成孔洞","(B) 通常是細小而均勻分布之球狀孔洞","(C) 多出現於樹脂基底床較薄處","(D) 孔洞多藏於樹脂床內部，對美觀及義齒清潔影響不大，但強度會減弱"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"關於「牙醫師倫理規範」的敘述，下列何者錯誤？","options":["(A) 它是屬於專業倫理規範的一種","(B) 無任何法律約束力","(C) 在我國由中華民國牙醫師公會全聯會制訂","(D) 醫師懲戒委員會可認定與判斷是否有違牙醫師倫理規範事件"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"為了讓患者感覺舒適以及降低口內組織的刺激，可撤式局部義齒主連接體（major connector）的特點與設 計要求，下列敘述何者錯誤？","options":["(A) 上顎主連接體需要以直角方式跨越腭中線（palatal midline）","(B) 骨性隆凸（tori）的覆蓋應盡量避免","(C) 上顎主連接體的前緣設計需要放置於皺摺區（rugae area）的前波段（anterior slope）","(D) 主連接體應呈現圓滑的外型設計，避免尖銳角度"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"可撤式局部義齒基底的小連接體（minor connector）設計與製作的敘述，下列何者正確？","options":["(A) 開放式結構（open construction）之小連接體的縱桿（longitudinal struts）必須設計在無牙嵴的頂 端，以抵抗咬合的力量","(B) 開放式結構（open construction）之小連接體的橫桿（transverse struts）的置放不需要考量到義齒的 排列","(C) 珠粒式結構（bead construction）之小連接體的金屬底部會直接與口腔組織接觸，口腔衛生及溫度傳導都 優於樹脂基底","(D) 網狀結構（mesh construction）之小連接體在樹脂填充（resin packing）時較容易"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"下列那些臨床狀況一定需要間接固位體（indirect retainer）？ ① ② ③ ④ ⑤","options":["(A) ①②③④⑤","(B) 僅①③④","(C) 僅②③⑤","(D) 僅②④⑤"],"answer":3,"image":"ya5-113-2-25.jpeg","clinical_level":"重點(深度)"},{"id":"ya5-113-2-26","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"有關可撤式局部義齒舌側槓（lingual bar）主連接體的敘述，下列何者正確？①舌側槓下緣較舌側槓上緣 厚 ②舌側槓上緣離牙齦緣（gingival margin）至少需要6 mm ③適用於齒槽舌溝（alveolar lingual sulcus）與舌側牙齦緣（lingual gingival margin）之間距足夠的病人 ④舌側槓斷面為水梨狀（pear shaped）","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-27","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"當遠伸性可撤式局部義齒（distal extension removable partial denture）受到咬合力時，支柱牙 （abutment teeth）與無牙嵴黏膜的變化，下列敘述何者錯誤？","options":["(A) 牙周健康的支柱牙不會下沉","(B) 無牙嵴黏膜會下沉","(C) 無牙嵴黏膜的下沉量有與咬合力大小有關","(D) 無牙嵴長短與黏膜的下沉量有關"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"關於 Kennedy class I可撤式局部義齒的設計，若缺牙顆數增加，下列敘述何者正確？","options":["(A) 義齒基底涵蓋面積與密合度影響更大","(B) 是否放置間接固位體（indirect retainer）則較不重要","(C) 義齒主連接體（major connector）選擇更多","(D) 應採用金屬義齒基底（metal denture base）來增加強度"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-29","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"下顎遠伸性局部義齒（distal extension partial denture）之金屬支架（framework），連結樹脂基底的 小連接體（minor connector）應往後延伸至缺牙區全長的多少範圍？","options":["(A) 二分之一","(B) 三分之二","(C) 四分之三","(D) 全部"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"當可撤式局部義齒的咬合鈎靠（rest）跨在支柱牙之邊緣嵴（marginal ridge）上時，其厚度至少需要多少 mm？","options":["(A) 0.5","(B) 1.0","(C) 1.5","(D) 2.0"],"answer":[1,2],"image":"","clinical_level":"一般"},{"id":"ya5-113-2-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"關於析量時的注意事項，下列敘述何者正確？","options":["(A) 支柱牙的倒凹區需有0.05英吋的倒凹","(B) 鑄造金屬鈎的倒凹區通常比鍛製金屬線大","(C) 倒凹位置通常在近咬合部1/3","(D) 倒凹區的考量，咬合面儘量平行析量器平台"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-32","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"有關不密合可撤式局部義齒對支撐的組織產生的刺激，下列敘述何者正確？","options":["(A) 舌頭或嘴唇有燒灼感與之無關聯","(B) 使用組織調理材前應該適度移除義齒基底5 mm左右來提供空間","(C) 一般間隔4～7週置換組織調理材是臨床可接受的","(D) 如果組織調理3～4週仍效果不彰，應會診內科醫師"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-33","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"關於引導面（guiding plane）的敘述，下列何者正確？","options":["(A) 寬度是以頰舌側咬頭間約1/8的距離為範圍","(B) 高度是以臨床的牙冠長度約2/3為原則","(C) 不需因缺牙區的位置而改變高度","(D) 儘量形成銳利面"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-34","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"13歲病人因打籃球撞飛左上正中門齒與側門齒，造成左上正中門齒與側門齒缺失與左上犬齒牙根斷裂，經由 臨床與影像學檢查，建議將左上犬齒拔除。除此之外，口內其餘牙齒皆可保留。依可撤式局部義齒甘迺迪分 類系統（Kennedy's classification system）標準，此口內情況屬何分類？","options":["(A) Kennedy class I","(B) Kennedy class II","(C) Kennedy class III","(D) Kennedy class IV"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-35","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"關於咀嚼運動的敘述，下列何者錯誤？","options":["(A) 由於失去了來自牙齒牙周機械感受器（periodontal mechanoreceptors）的微調貢獻，影響在肌肉引導中 的精確度降低","(B) 通過舌頭和臉頰的選擇性操作，將粗大的顆粒分揀出來，帶到牙齒的咬合面進一步分解","(C) 在有效的咀嚼過程中，細顆粒食物比粗顆粒食物能更迅速地減小食物顆粒尺寸","(D) 咀嚼過程中，主要受到身體感知減少食物的能力和神經感覺監測食物減少過程的兩大能力影響"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-36","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"可撤式局部義齒印模時，一般情況下，硫醇橡膠印模材（mercaptan rubber base impression materials） 的操作固化時間需要多久？","options":["(A) 3分鐘以內","(B) 4～7分鐘","(C) 8～10分鐘","(D) 11分鐘以上"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-37","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"可撤式局部義齒印模時，使用水凝膠（hydrocolloid）印模材的操作，下列何者正確？①為避免體積變化， 取模後15分鐘內須完成倒模 ②選擇模托時，距離牙齒或組織至少要有4～5 mm空間 ③操作不可逆水凝膠 印模材時，最合宜的水溫是80℉ ④一般而言，調拌時要少於1分鐘，置於口內至少3分鐘","options":["(A) 僅①②","(B) 僅①②③","(C) 僅①②④","(D) ①②③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-38","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"上顎戴人工牙為樹脂牙（resin teeth）的全口義齒，若欲製作可撤式局部義齒時，則下顎人工牙材質之選 擇，以下列何種最合適？","options":["(A) 瓷牙（porcelain teeth）","(B) 貴重金屬牙（precious metal teeth）","(C) 非貴重金屬牙（non-precious metal teeth）","(D) 樹脂牙（resin teeth）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"有關可撤式局部義齒後牙人工牙的選擇與排列，下列何者正確？","options":["(A) 記錄顎間關係的義齒基底不可移除，可加上蠟直接排牙","(B) 相較於全口義齒，牙醫師選擇可撤式局部義齒後牙的限制較少","(C) 為保持後牙人工牙外形完整，應避免人工牙的修磨","(D) 後牙人工牙的數目不一定要和失去的牙齒數目一樣"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-40","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"在決定遠伸性（distal extension）可撤式局部義齒是否需要換底墊（reline）時，下列何者可當指標？① 鈎靠（rest）及間接固位體（indirect retainer） ②可撤式局部義齒與自然牙形成之咬合平面 （occlusal plane） ③殘嵴（residual ridge）和義齒基底（denture base）間的關係 ④牙鈎 （clasp）和支柱牙間的關係","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-41","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"使用中的可撤式局部義齒發生鑄造固位鈎（retentive clasp）斷裂，其原因可能為何？①鑄造缺陷 ②金 屬疲勞 ③鈎臂進入太大的倒凹 ④病人摘戴不慎","options":["(A) 僅①②③","(B) ①②③④","(C) 僅②③","(D) 僅①④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"正常情況下，製作可撤式局部義齒時，下列的步驟何者應最先實施？","options":["(A) 調整義齒之咬合使達到和諧（occlusal adjustment）","(B) 調整義齒基底組織面（tissue surface）","(C) 調整義齒基底磨光面（polishing surface）","(D) 調整義齒金屬支架（framework）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"關於可撤式局部義齒主模型重三點定位（retripoding），下列敘述何者錯誤？","options":["(A) 牙醫師先行預設假牙置入與移出路徑，可經由放置三點標記在診斷用模型上作為參考紀錄","(B) 牙技師開始牙架製作步驟之前，要先確認由三點定位重新呈現在主模型上假牙置入與移出之路徑","(C) 在模型不同的水平面上放置三個容易辨認的標記，這些標記應分散在石膏模型的解剖部位上放置","(D) 牙技師利用標記以快速定位主模型，劃出析量線、診斷模型上的設計轉移及模型封凹和緩壓工作"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"局部活動義齒的主模型（master cast）以蠟封凹（blockout）之前，必須於模型進行如圖之步驟，進行該 步驟之目的及注意事項為何？","options":["(A) 深度至少要1 mm","(B) 確定主連接體（major connector）和腭部組織有正接觸（positive contact）","(C) 上顎和下顎模型都要進行此步驟","(D) 可以提高義齒的穩定度"],"answer":1,"image":"ya5-113-2-44.jpeg","clinical_level":"重點"},{"id":"ya5-113-2-45","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"關於固定義齒置入路徑（path of insertion）的敘述，下列何者最不適當？","options":["(A) 通常面舌（faciolingually）向平行牙齒直軸","(B) 通常近遠（mesiodistally）向平行鄰牙的接觸區（contact area）","(C) 面舌（faciolingually）向的置入路徑不會影響義齒的美觀","(D) 前牙製作3/4牙冠時，需平行唇側的切端1/2至2/3"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"關於修磨牙齒的敘述，下列何者正確？","options":["(A) 無法藉由牙齒上的過度傾斜面（overinclination）修磨獲得足夠的義齒空間","(B) 深的弧形邊緣（deep chamfer）設計提供義齒瓷材的支持優於肩台邊緣（shoulder）設計","(C) 改良式肩台邊緣（modified shoulder）是指具有大半徑圓形內角（rounded internal angle）","(D) 軸向修磨（axial reduction）不足會造成義齒過度成型（overcontoured）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-47","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"對於相互保護性咬合（mutually protected articulation）的特徵，下列敘述何者錯誤？","options":["(A) 當髁頭在最上的位置時，牙弓上的所有牙齒有均勻的咬合接觸","(B) 具有最終合力為垂直方向的後牙咬合接觸","(C) 中心關係位置與最大咬頭嵌合位置不一致","(D) 下顎進行側向或是前突運動時後牙無咬合接觸"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-48","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"當為病人取得一中心咬合紀錄後，如果再取得下顎前突的咬合紀錄（protrusive record），則關於咬合器 設定的敘述，下列何者錯誤？","options":["(A) 可以利用下顎前突的咬合紀錄來設定咬合器上的髁導傾斜（condylar guidance inclination）","(B) 可以重現患者口內所有的下顎移動情形","(C) 可以重現患者下顎前突時的靜止咬合狀態","(D) 兩側的髁導傾斜（condylar guidance inclination）角度可能不同"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-49","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"下列何者不是排齦時常用的止血劑之主要成分？","options":["(A) AlCl3","(B) Racemic epinephrine HCl","(C) Fe2(SO4)3","(D) 25% Polyacrylic acid"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-50","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"當製作一正常牙齒咬合的上顎個人模托（custom tray）時，其終止點（stop）若放置在後牙區，則應放置 在牙齒的那一個部位為佳？","options":["(A) 上顎未修形牙齒（unprepared teeth）之頰側咬頭","(B) 上顎未修形牙齒（unprepared teeth）之腭側咬頭","(C) 上顎修形牙齒（prepared teeth）之頰側咬頭","(D) 上顎修形牙齒（prepared teeth）之腭側咬頭"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-51","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"113年第2次第51題","year":113,"session":2,"number":51,"question":"在牙骨質牙釉質交界處（cementoenamel junction），單根牙根柱（dowel）空間的直徑和牙根面直徑的比 例，最好不要超過多少？","options":["(A) 1/4","(B) 1/3","(C) 1/2","(D) 2/3"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-52","subject":"ya5","topic":"臨床基礎與倫理","meta":"113年第2次第52題","year":113,"session":2,"number":52,"question":"上顎前牙拔牙後，骨頭與牙齦組織平均萎縮量的敘述，下列何者正確？","options":["(A) 垂直方向2.0～3.5 mm","(B) 垂直方向4～5.5 mm","(C) 頰舌方向2.5～4 mm","(D) 頰舌方向4.5～6.0 mm"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第2次第53題","year":113,"session":2,"number":53,"question":"關於金屬瓷贋復物金屬支架的設計，下列敘述何者正確？","options":["(A) 在瓷－金屬分界面（interface），瓷應保留至少0.3 mm的厚度","(B) 為達到理想的瓷厚度，避免瓷裂，厚度應保持一致","(C) 金屬瓷贋復物的正中咬合（centric stop）應建立在金屬上較理想，而且無需考慮對咬牙的狀況","(D) 為避免因金屬變形引起的瓷裂，正中咬點應遠離瓷－金屬交接處至少1.5 mm"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"113年第2次第54題","year":113,"session":2,"number":54,"question":"橋體設計分類（pontic design）中，衛生橋體（sanitary pontic）與牙嵴（ridge）之間的空隙至少需為 多少mm？","options":["(A) 0.5","(B) 1","(C) 1.5","(D) 2"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-55","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第55題","year":113,"session":2,"number":55,"question":"金屬瓷系統（porcelain fused to metal）在燒瓷前對金屬進行的初始氧化（initial oxidation）步驟， 下列何者正確？①Pd-Cu-Ga合金，不需要執行此步驟 ②鈹會影響氧化層的厚度 ③氧化層越厚，瓷與金屬 之結合力越強 ④此程序在加熱循環過程中，會導致合金中的氣體損失，在鑄件中形成微觀孔隙，增加結合 力","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-56","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第56題","year":113,"session":2,"number":56,"question":"關於上釉（glaze）的敘述，下列何者錯誤？","options":["(A) 上釉的加熱處理過程中，陶瓷的表層會有些微熔融","(B) 在上釉時做色彩修飾通常會使明度（value）下降","(C) 金屬瓷牙冠通常在真空中上釉，以減少氣泡產生","(D) 未經磨光的瓷比磨光後的瓷或上釉後的瓷更容易磨損對咬牙的牙釉質"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-57","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第57題","year":113,"session":2,"number":57,"question":"使用聚丙烯（polypropylene）類的熱塑性透明片（thermoplastic sheet）來製作臨時牙冠時，下列透明片 的厚度何者最適當？","options":["(A) 0.5 mm","(B) 0.7 mm","(C) 1.0 mm","(D) 1.5 mm"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-58","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第58題","year":113,"session":2,"number":58,"question":"以Vita比色板（Vita Lumin Vacuum shade guide）作色調選擇（shade selection）時，下列敘述何者正 確？","options":["(A) A、B、C、D代表不同的色別（hue）","(B) 牙齒的切端部位有最高的色度（chroma）","(C) 以自然光比色時，傍晚較正午為佳","(D) 比色時要迅速，二次比色間可注視綠色平板使眼睛休息"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-59","subject":"ya5","topic":"植牙贋復","meta":"113年第2次第59題","year":113,"session":2,"number":59,"question":"以四支植體支持全牙弓植體固定義齒時，下列何者不是使用遠心傾斜植體（tilted implant） 的好處？","options":["(A) 可減少遠心懸桁（cantilever）的長度","(B) 有較理想的萌發形態（emergence profile）","(C) 可使用立即負重（immediate loading）","(D) 可增加近遠心植體間的anterior-posterior（AP）distance"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-60","subject":"ya5","topic":"植牙贋復","meta":"113年第2次第60題","year":113,"session":2,"number":60,"question":"植體治療時，相鄰植體間齒槽骨（interdental bone）至鄰間接觸點（interproximal contact）的距離為 多少，才能確保齒間乳突（interdental papilla）的存在？","options":["(A) 必須小於5 mm","(B) 必須大於8 mm","(C) 必須大於10 mm","(D) 兩者之間的距離與齒間乳突的存在與否無關"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-61","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第61題","year":113,"session":2,"number":61,"question":"關於磨牙症（bruxism）的敘述，下列何者正確？①此類患者可能需要調整治療順序，以防止治療期間臨時 修復體過度折斷 ②是痙攣性非功能性（spasmodic nonfunctional）磨牙 ③可能導致咬合創傷 （occlusal trauma） ④牙科種植體失敗率並不會因磨牙症受影響","options":["(A) 僅①②","(B) ②③④","(C) ①②③","(D) 僅③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-62","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"113年第2次第62題","year":113,"session":2,"number":62,"question":"使用傾斜牙齒製作三單位固定牙橋，下列何種狀況最不會發生？","options":["(A) 牙齒修形時，容易發生支柱牙牙髓侵犯（pulp involvement）","(B) 固定牙橋置入方向易受鄰牙干擾","(C) 固定牙橋較易鬆脫","(D) 固定牙橋容易變形"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-63","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第63題","year":113,"session":2,"number":63,"question":"關於牙科技工製程數位化積層製造（additive manufacturing）與減材製造（subtractive manufacturing）的敘述，下列何者錯誤？","options":["(A) 以現有技術而言，不論以積層製造或是減材製造方法，都可準確輸出模型及蠟型","(B) 金屬結構（如：可撤式義齒支架）若採用積層製造，可以減少材料的浪費","(C) 減材製造比較容易解決倒凹的問題","(D) 不論以積層製造或是減材製造方法，牙醫師於備牙時，都須留意不可於支柱牙上留有尖銳線角"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-64","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第64題","year":113,"session":2,"number":64,"question":"脱蠟鑄造過程中，下列何種失敗的原因與蠟型本身缺陷或蠟型在鑄造環中的擺位無關？","options":["(A) 鑄件和模型邊緣產生差異","(B) 不完全鑄件","(C) 鑄件表面出現小型球狀突起（nodule）","(D) 鑄件表面出現鰭狀突起（fin）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-65","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第65題","year":113,"session":2,"number":65,"question":"金合金修復體的最佳焊接間隙寬度（gap width）是多少mm？","options":["(A) 0.1","(B) 0.2","(C) 0.4","(D) 0.6"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-66","subject":"ya5","topic":"牙科材料學","meta":"113年第2次第66題","year":113,"session":2,"number":66,"question":"關於長石陶瓷（feldspathic porcelain）贋復物的敘述，下列何者錯誤？","options":["(A) 可使用於瓷鑲面、嵌體以及較不受力的前牙全瓷冠製作","(B) 黏著過程使用氫氟酸做贋復物黏著面處理","(C) 黏著時需使用矽烷偶合劑（silane）","(D) 要使用複合樹脂黏合劑"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-67","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第67題","year":113,"session":2,"number":67,"question":"下列咀嚼肌中，何者附著於顳顎關節（temporomandibular joint）之關節囊（capsule）上？","options":["(A) 外翼肌（lateral pterygoid muscle）","(B) 咬肌（masseter muscle）","(C) 顳肌（temporalis muscle）","(D) 頰肌（buccinator muscle）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-68","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第68題","year":113,"session":2,"number":68,"question":"關於異常功能活動（parafunctional activity）的敘述，下列何者正確？①在夜間發生的異常功能活動， 例如磨牙症（bruxism），通常病患本身並不自覺 ②在日間發生的異常功能活動，例如咬筆或吸手指，大 多是病患自覺且刻意為之 ③夜間發生的異常功能活動，除了節律性的磨牙，也可能持續地緊咬牙齒 ④日 間發生的異常功能活動也可能與病患本身的職業或工作活動有關","options":["(A) 僅①②","(B) 僅①③④","(C) 僅②③④","(D) ①②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-69","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第69題","year":113,"session":2,"number":69,"question":"關於情緒壓力（stress）影響口顎系統的生理與神經機制，下列敘述何者正確？①可能透過降低γ傳出纖維 （gamma efferent）的活動，使肌肉張性（muscle tonicity）升高   ②可能透過下視丘（hypothalamus） 的活動，影響自主神經系統（autonomic nervous system）  ③可能持續提升交感神經系統（sympathetic nervous system）活動，影響肌肉張性   ④個體對壓力源（stressor）主觀感受的程度，有很大的個體差 異","options":["(A) 僅②③","(B) 僅①④","(C) 僅②③④","(D) ①②③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-70","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第70題","year":113,"session":2,"number":70,"question":"關於哥德式弧形描軌器（Gothic arch tracer），下列何者正確？①可用於中心關係（centric relation） 的紀錄   ②可用於下顎邊界運動（border movement）的紀錄   ③可用於顳顎關節（TMJ）運動途徑的紀 錄   ④可用於上顎與關節盂窩（glenoid fossa）關係的紀錄","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-71","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第71題","year":113,"session":2,"number":71,"question":"上顎小臼齒的咬合台（occlusal table）對總頰舌寬度的比例，下列描述何者正確？","options":["(A) 約35-45%","(B) 約50-60%","(C) 約65-75%","(D) 約80-90%"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-72","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第72題","year":113,"session":2,"number":72,"question":"下顎從中心關係（centric relation）到咬頭嵌合位置（intercuspal position）產生前上與右向的滑動 （anterosuperior and right slide），導致此滑動干擾的可能位置，下列何者正確？","options":["(A) 右側上顎舌側咬頭的內側斜面對到下顎頰側咬頭的內側斜面","(B) 左側上顎舌側咬頭的內側斜面對到下顎頰側咬頭的內側斜面","(C) 右側上顎舌側咬頭的外側斜面對到下顎舌側咬頭的內側斜面","(D) 左側上顎舌側咬頭的外側斜面對到下顎舌側咬頭的內側斜面"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-73","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第73題","year":113,"session":2,"number":73,"question":"關於波氏圖（Pösselt’s diagram）對下顎邊界運動的敘述，下列何者錯誤？","options":["(A) 最大咬頭嵌合MICP（maximum intercuspation）位置出現在波氏圖矢狀面觀上緣","(B) 中心咬合（centric occlusion）常位在咀嚼循環軌跡中的終點（end point），也常是執行吞嚥功能時下 顎的位置","(C) 當下顎後退運動且後牙輕微接觸時，下顎門齒會與上顎門齒分開並往後、往下方移動","(D) 正常受試者的下顎運動中，最上的位置主要是由顳顎關節（tempomandibular joint）來決定"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-74","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第74題","year":113,"session":2,"number":74,"question":"當患者髁頭瞬間側移（immediate side shift）愈明顯時，下列敘述何者正確？","options":["(A) 可賦予較大的前方引導（anterior guidance），來增長後牙功能咬頭之長度","(B) 可賦予較小的前方引導（anterior guidance），來增長後牙功能咬頭之長度","(C) 可使後牙中央窩變窄","(D) 與前方導引（anterior guidance）無關"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-75","subject":"ya5","topic":"咬合學基礎","meta":"113年第2次第75題","year":113,"session":2,"number":75,"question":"患者因輕微或想像的面部不對稱而造成先入為主的咬合不對稱感，稱為下列何者？","options":["(A) 去程式（deprogramming）","(B) 強迫性症狀（obsession）","(C) 幻咬症（phantom bite）","(D) 鞭甩傷（whiplash）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第76題","year":113,"session":2,"number":76,"question":"下列何種症狀及變化，與風溼性顳顎關節炎（TMJ rheumatoid arthritis）最無關連？","options":["(A) 關節疼痛，張口困難","(B) 顳顎關節變形，有關節聲響","(C) 漸進的前牙開咬（progressive anterior bite opening）","(D) 下顎脫臼"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第77題","year":113,"session":2,"number":77,"question":"關於顳顎障礙症的治療法有很多，下列何種不屬於物理治療？","options":["(A) 超音波","(B) 低頻率電刺激","(C) 雷射","(D) 咬合板"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-113-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第78題","year":113,"session":2,"number":78,"question":"關於穩定型（stabilization）密西根式咬合板（Michigan splint）的製作要點，何者錯誤？","options":["(A) 一般來說，咬合板需覆蓋單一顎上的所有牙齒，且與對咬齒弓的每一顆牙齒都有咬點接觸","(B) 前牙的腭部覆蓋應止於中心咬位後方1～1.5 mm，不可過度向後延伸而侵犯到舌頭的空間","(C) 一般來說咬合板的中心咬位的接觸應該是一個明確的咬點，以提供較為精確的下顎活動導引","(D) 在咬合板上提供犬齒導引，可以避免後牙區有不均勻的過早咬合，造成干擾或甚至激發磨牙、緊咬等問題"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第79題","year":113,"session":2,"number":79,"question":"關於退化性顳顎關節炎（osteoarthritis）的治療，下列敘述何者正確？① 當發現X光片中關節有骨變化 時，無論有無臨床症狀，都建議給予咬合板治療 ② 給予穩定型咬合板（satbilization splint）以減輕 負荷力（loading force） ③ 關節囊內注射類固醇（intracapsular injection of corticosteroid）是 控制發炎的首選 ④ 利用熱療法（thermotherapy）以減輕肌肉症狀","options":["(A) 僅①②","(B) 僅②④","(C) 僅①③④","(D) ①②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-113-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"113年第2次第80題","year":113,"session":2,"number":80,"question":"下列那些顳顎關節攝影，可藉由張大口，避免髁頭被關節窩疊加（superimpose）遮蔽？① 貫顱投影法 （transcranial projection） ② 貫咽投影法（transpharyngeal projection） ③ 環口放射攝影 （panoramic x-ray） ④ 前後貫上顎投影法（anteroposterior transmaxillary projection）","options":["(A) 僅①③","(B) 僅②④","(C) 僅②③④","(D) ①②③④"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"關於腫裂齦瘤（epulis fissuratum）的敘述，下列何者最適當？","options":["(A) 是一種急性刺激的結果","(B) 會干擾假牙邊界延伸","(C) 常發生於假牙清潔不良的病人","(D) 手術移除是優先的處置"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-2","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"關於紅斑性狼瘡（systemic lupus erythematosus）病人的敘述，下列何者錯誤？","options":["(A) 男性高於女性","(B) 多為自體免疫疾病第三型過敏反應","(C) 通常因口內皮下發炎使得黏膜無法承載活動義齒","(D) 植牙手術可能會有凝血不全的顧慮"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"製作全口義齒時，關於唾液對義齒製作之影響，下列敘述何者錯誤？","options":["(A) 唾液之流量及黏稠度會影響病人對全口義齒的適應力","(B) 口乾症患者義齒之固持力較低","(C) 剛剛裝戴新義齒時，出現短暫的唾液流量增加是正常的生理反應","(D) 黏稠的唾液有利於全口義齒的裝戴"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"關於頰棚（buccal shelf）的敘述，下列何者正確？","options":["(A) 構成頰棚支持組織主要為較疏鬆的海綿骨","(B) 因分布於義齒後方，無法做為下顎主要應力承載區","(C) 其上方平面和咬合力量方向平行","(D) 隨著殘嵴的吸收，可動的舌側組織會漸往頰棚上方延伸"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"全口義齒正式印模前，關於軟、硬組織的處理，下列敘述何者最不適當？","options":["(A) 如果上顎隆凸﹙torus palatinus﹚向後延伸至振動線（vibrating line）時，需要手術移除","(B) 正式印模前24小時，病人應避免戴舊義齒","(C) 可以在舊義齒內使用組織調理材（tissue conditioning materials），使軟組織恢復健康","(D) 在牙齒拔除後約等待一個月使軟組織癒合，為正式印模的最佳時機"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"關於製作全口義齒初步印模（preliminary impression）時的注意事項，下列敘述何者錯誤？","options":["(A) 無牙的常備模托（stock tray）需比無牙嵴寬約5mm","(B) 雖然還會有正式印模，邊緣的延伸還是需要儘量準確","(C) 低黏稠性（low viscosity）的印模材是最佳選擇","(D) 上顎的模托後緣需要覆蓋到上顎粗隆（maxillary tuberosity）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"製作全口義齒時，關於咬合蠟堤－基底製作與使用的敘述，下列何者錯誤？","options":["(A) 基底最好用軟性彈性材料增加舒適感","(B) 咬合蠟堤可以用來記錄中立區（neutral zone）","(C) 如果影響排牙，可以磨掉一些基底材料","(D) 咬合蠟堤－基底可以用來記錄顎間關係"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-8","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"關於全口義齒上下顎門牙排列的敘述，下列何者錯誤？","options":["(A) 需減少overjet並增加overbite以維持上顎義齒的穩定度","(B) 排列下顎門牙時其長軸通常須朝向殘嵴（residual ridge）","(C) 犬齒的遠心部分（distal half）排列需與後牙配合","(D) 隨著年紀增加，病人在說話時會露出越來越多的下顎前牙"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-9","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"關於以記錄基底（record base）與咬合蠟堤（occlusal wax rim）決定垂直咬合高度（vertical dimension of occlusion）的敘述，下列何者錯誤？","options":["(A) 發S音時，如果上、下蠟堤會相互撞擊，有可能是垂直咬合高度太高","(B) 發S音時，如果上、下蠟堤會相互撞擊，有可能是記錄基底不穩","(C) 如果蠟堤的位置與形態不對，會影響以發音法決定垂直咬合高度的正確性","(D) 以發S音比以吞嚥法決定之垂直咬合高度較低"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"全口義齒製作時，對於臉部骨骼屬於後縮顎（retrognathic）或凸顎（prognathic）的下顎排牙， 下列敘述何者錯誤？","options":["(A) 屬於Angle class Ⅱ division Ⅰ的患者通常需要有明顯的垂直覆蓋（overbite）與水平覆蓋 （overjet）","(B) 屬於Angle class Ⅱ division Ⅱ的患者通常只需排列4顆小臼齒","(C) 屬於Angle class Ⅲ的患者，上顎前牙通常會排成切端對切端（end-to-end）的關係","(D) 屬於Angle class Ⅲ的患者，後牙常排成錯咬（crossbite），並且會加深史比曲線（curve of Spee）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-11","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"上顎咬合蠟堤於口內試戴時，需根據下列何者作為唇側輪廓的參考？①牙弓形狀（arch form） ②牙齒大小（tooth size） ③唇支持（lip support） ④臉部外觀（facial contour）","options":["(A) ①②③","(B) ①③④","(C) ②③④","(D) ①②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"製作全口假牙時，如果病人的顎間關係是安格氏第三級咬合關係，下列敘述何者錯誤？","options":["(A) 下顎嚴重前突（prognathism）狀態下，上、下顎前牙在中心咬合關係可以不接觸","(B) 後牙排成錯咬（cross bite）","(C) 前牙可以排成切端對切端（edge to edge）的咬合關係","(D) 由於下顎殘嵴條件比上顎好，所以咬合面高度可以高於臼齒後墊（retromolar pad）的上緣"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"單顎全口活動義齒比起全口活動義齒更不容易達到雙側平衡咬合（bilateral balanced occlusion）最主要的原因為下列何者？","options":["(A) 樹脂牙的咬頭形態（cusp form）與自然牙相同","(B) 樹脂牙的硬度與自然牙不同","(C) 缺牙區牙弓形狀與排牙位置符合","(D) 自然牙咬合平面可能有高低不平的情況"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"全口活動義齒使用零度牙排牙並要達到平衡性咬合（balanced occlusion），則當病人下顎向左突 出時，平衡斜坡（balancing ramp）應該在那裡？","options":["(A) 上顎左側","(B) 下顎左側","(C) 上顎右側","(D) 下顎右側"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"關於全口義齒使用假牙黏著劑（denture adhesives）的適應症，下列何者錯誤？","options":["(A) 密合的全口義齒，但是病人對於義齒的固持性（retention）不滿意","(B) 有口乾症（xerostomia）的病人","(C) 因健康因素不適合植牙的病人，但是病人又想要有比較好的義齒固持性（retention）","(D) 不密合的全口義齒，但是病人不想要調整或是重新製作義齒"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"全口活動義齒裝置後，對於病人殘嵴的保存與維護，下列敘述何者錯誤？","options":["(A) 若義齒下組織有受損，建議病人暫時不配戴義齒，讓口腔休息一段時間","(B) 若無不適，應告知病人晚上配戴義齒就寢，以讓殘嵴組織適應義齒","(C) 若病人未配戴義齒時，應將義齒浸置於水裡，以避免因為乾躁而造成義齒體積改變","(D) 病人因疼痛而不配戴義齒，仍建議看診前一天需配戴義齒，這樣牙醫師才能觀察出疼痛點（sore spots）並予以修正調整"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"使用全口義齒之患者，睡前應清潔義齒，之後須如何處理最為適當？","options":["(A) 取出義齒泡於自來水中","(B) 戴著義齒，以促進口腔組織之適應性","(C) 取出義齒泡於義齒清潔劑中至少30分鐘","(D) 取出義齒並保持於乾燥處"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"關於即裝義齒（immediate denture）術後的照護及對患者的指導，下列敘述何者正確？","options":["(A) 拔完牙後裝戴的即裝義齒在24小時內不應自口中取出","(B) 患者裝戴即裝義齒24小時內如果因為拔牙傷口造成疼痛時，將即裝義齒移除可以減輕疼痛","(C) 告知患者拔完牙齒3天後，晚上不可以再持續裝戴即裝義齒","(D) 因為拔牙後的軟組織會持續的變化及齒槽骨會吸收，所以術後1至2個月再進行義齒的重置位 （remount）與咬合調整"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-114-1-19","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"咽帆關閉（velopharyngeal closure）無法形成時，下列敘述何者錯誤？","options":["(A) 巴沙溫氏嵴（Passavant's ridge）在軟腭（soft palate）切除的病患很明顯，臨床上可以閉孔器 （obturator）來矯正","(B) 不會影響吞嚥功能","(C) 無法關閉鼻咽（nasopharynx），造成鼻音過重（hypernasality）","(D) 巴沙溫氏嵴（Passavant's ridge）在嘔吐反射（gag reflex）時很明顯"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-20","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"熱聚式聚甲基丙烯酸甲酯（polymethyl methacrylate，PMMA）常用於製作全口義齒之義齒床。有 關此材料之成分與技工室操作，下列敘述何者錯誤？","options":["(A) 通常製備成粉與液狀兩部分，依廠商指示正確粉液比例很重要","(B) 以過氧化苯甲醯（benzoyl peroxide）做為塑化劑 ，放置於粉中","(C) 液體之單體（monomer）具揮發性且易燃，並可能是過敏原，必須於通風且安全處做樹脂填充","(D) 粉液調拌後置於密閉玻璃盒中，到糰狀期（dough stage）才能取出進行填充"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-21","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"壓克力樹脂床（acrylic resin denture base）若出現孔洞（porosity），有關孔洞形成的原因及 形狀之敘述，下列何者錯誤？","options":["(A) 樹脂填塞時壓力不足，形成大而不規則的孔洞","(B) 填塞時材料不足，形成大而不規則的孔洞","(C) 樹脂調拌時不當之粉液調拌，導致樹脂聚合收縮不一，形成大而均勻的孔洞","(D) 煮聚時溫度上升太快，易在樹脂床較薄處形成細小均勻的孔洞"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"病人決定以植體支持式義齒來替代全口義齒作為治療選項，但是牙醫師卻在執行植體手術時，沒有 進行術前影像分析，而致植體置入後壓迫下齒槽神經。此一行為違背了那一項醫學倫理基本原則？","options":["(A) 尊重自主原則（the principle of respect for autonomy）","(B) 不傷害原則（the principle of non-maleficence）","(C) 行善原則（the principle of beneficence）","(D) 公平正義原則（the principle of justice）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"可撤式局部義齒主連接體的適應症，下列敘述何者錯誤？","options":["(A) 上顎剩餘的自然牙具有足夠的牙周支持且需要較少的額外支持時，主連接體可以選用腭帶 （palatal strap）或是前後腭帶（anteroposterior palatal strap）","(B) 上顎前牙缺失需要可撤式局部義齒重建時，前後腭帶（anteroposterior palatal strap）與馬蹄 型主連接體（horseshoe connector）皆適用","(C) 如果剩餘牙齒的牙周狀況不好時，腭部的覆蓋便應該要相對地增加，建議使用比較寬的腭帶 （palatal strap）或是全腭（complete palate）的設計","(D) 有很多適用腭槓（palatal bar）設計的案例"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"可撤式局部義齒主連接體（major connector）的特點與設計要求，下列敘述何者錯誤？","options":["(A) 足夠的剛性（rigidity）是主連接體的主要需求","(B) 在下顎牙弓，主連接體的邊緣應該放置於距離游離牙齦（free gingival margin）最少1 mm處","(C) 主連接體的邊緣應儘量與剩餘牙齒的牙齦邊緣平行","(D) 當主連接體需要跨越牙齦邊緣時，應儘量以呈90度角方式跨越"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-25","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"上顎可撤式局部義齒小連接體（minor connectors），在遠心側基底的延伸，大部分覆蓋範圍應該 比較接近無牙嵴長度 x 的多少？","options":["(A) 1x","(B) 3/4x","(C) 2/3x","(D) 1/2x"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"下圖可撤式局部義齒設計的間接固位體（indirect retainer）位置之考量，下列何處最為合適？","options":["(A) 左上第二小臼齒","(B) 左上第二大臼齒","(C) 右上第二大臼齒","(D) 左上犬齒"],"answer":1,"image":"ya5-114-1-26.jpeg","clinical_level":"重點(深度)"},{"id":"ya5-114-1-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"可撤式局部義齒的設計，下列何者需經析量（surveying）的步驟？①牙鈎（clasp） ②無牙嵴區 小連接體（minor connector） ③終接線（finishing line） ④鈎靠座（rest seat） ⑤引導 面（guiding plane）","options":["(A) ①②③④⑤","(B) 僅①⑤","(C) 僅①③⑤","(D) 僅①②⑤"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-28","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"上顎可撤式局部義齒主連接體（major connector），珠狀緣飾（beading）應在下列何模型完成？ ①研究模型（study cast） ②主模型（master cast） ③耐火模型（refractory cast）","options":["(A) 僅①","(B) 僅②","(C) 僅③","(D) ①②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-29","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"關於可撤式局部義齒牙鈎臂（clasp arm）可擔任減壓裝置（stress-breakers）的敘述，下列何者 錯誤？","options":["(A) 在單一方向具有高度可彎曲性（flexibility）","(B) 圓、錐形牙鈎形態（round, tapered clasp forms）提供更廣效的可彎曲性","(C) 可減少牙齒的接觸且較美觀","(D) 具備長的鍛製金屬線（wrought wire）組合牙鈎（combination clasp）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-30","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"Kennedy class I的雙側遠心端游離可撤式局部義齒，其兩側後端對稱支柱牙鈎靠連接形成的水平 支點線（fulcrum line），會使得義齒在承受咬合力之後沿著那一個平面發生旋轉？","options":["(A) 額狀面（frontal plane）","(B) 矢狀面（sagittal plane）","(C) 水平面（horizontal plane）","(D) 引導面（guiding plane）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-31","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"析量時最佳傾斜度的考量，下列敘述何者正確？","options":["(A) 需尋找最大倒凹區的存在","(B) 可保留軟硬組織的干擾","(C) 美觀是最主要的考量","(D) 建立適當的引導面（guiding plane）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-32","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"關於鈎靠座（rest seat）在可撤式局部義齒的修磨，下列敘述何者正確？","options":["(A) 鈎靠座的修磨在鄰接面平行修磨之前","(B) 預備製作咬合鈎靠座的支柱牙不需在修磨時就計算空間","(C) 一般先用8號圓型磨針（round bur）再用6號在底部加深","(D) 鈎靠座修磨最常發生的錯誤是修磨太深"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"下列那些工具可放置析量臂中協助析量？①尼氏蠟刀（Ney wax trimmer） ②麥特蠟刀（Matt wax trimmer） ③金尼可倒凹尺（Jelenko undercut guage） ④尼氏倒凹尺（Ney undercut guage）","options":["(A) ①②③④","(B) 僅①③④","(C) 僅①②③","(D) 僅②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-34","subject":"ya5","topic":"咬合學基礎","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"可撤式局部義齒的咬合，下列敘述何者正確？①最大咬合嵌合位置（maximal intercuspal position）是指牙齒最完整的嵌合位置（complete interdigitation），與髁突位置 （condylar position）有關 ②中心咬合位置（centric occlusion position）是指當下顎髁頭 （mandibular condyles）位於中心關係位置（centric relation position）時，牙齒發生第一次 接觸的關係位置 ③牙齒經過適當調整，最大咬合嵌合位置和中心關係位置可以重合 ④中心關係 位置是由牙齒與牙齒的關係（tooth-to-tooth relationships）來決定的上下顎關係 （maxillomandibular relationship） ⑤最大咬合嵌合位置是由骨與骨關係（bone-to-bone relationships）決定的上下顎關係","options":["(A) ①②③④⑤","(B) 僅①③④","(C) 僅②③","(D) 僅①②④⑤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-35","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"在確定可撤式局部義齒的治療計畫前，印製診斷模型（diagnostic cast）的功用，下列何者錯 誤？","options":["(A) 在不會損傷模型的前提下可用來製作個別印模托（individual impression tray）","(B) 對牙弓先進行析量（survey）作為口內修磨（prepartion）前的計畫準備","(C) 如果以超硬石膏（die stone）取代牙科硬石膏（dental stone）灌製模型，可用來製作金屬義齒 支架（metal framework）","(D) 分析咬合過度閉合的程度（degree of overclosure）和咬合間隙（interocclusal space）的量是 否足夠"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-36","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"可撤式局部義齒印模時，使用硫醇橡膠印模材（mercaptan rubber base impression materials） 的考量，下列何者錯誤？①有極佳的長時間體積穩定度 ②取模完成後可以直接倒模 ③強度及彈 性極佳，可以用於有多處倒凹區之取模 ④精密度高","options":["(A) 僅①②","(B) 僅①③","(C) ②③④","(D) ①②③"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-37","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"關於以藻膠（alginate）取模時，造成模型不精確的敘述，下列何者錯誤？","options":["(A) 印模材料未與牙托緊密接合","(B) 取模後1小時內灌模","(C) 過早把模型從印模材分開","(D) 倒模時沒有適當的使用震盪器"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-38","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"建立可撤式局部義齒的咬合模式（occlusal scheme）時，最重要的原則為何？","options":["(A) 達成群體功能（group function）","(B) 在中心關係（centric relation）處應建立最大咬頭嵌合（maximum intercuspation）","(C) 人工牙必須與殘留自然牙達成協調的咬合","(D) 人工牙應儘量避免咬合接觸"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-39","subject":"ya5","topic":"咬合學基礎","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"下列所列的牙齒為上、下顎殘存牙齒的狀態（顎間關係與殘存牙齒的條件都一樣），何者為咬合記 錄取得最困難之症例？","options":["(A) 上:7654|4567 下:_321|123_","(B) 上:_76__|_678 下:_76__|_678","(C) 上:87654|45678 下:876_4|45678","(D) 上:7_43|234_7 下:7_432|234_7"],"answer":0,"image":"ya5-114-1-39.jpeg","clinical_level":"一般"},{"id":"ya5-114-1-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"可撤式局部義齒修復（replacement of denture teeth）的處理步驟，下列順序何者正確？①製作 咬合定位基板 ②選擇適當的替代牙齒 ③假牙基底適度舒緩處理 ④替代齒底部修出固位性倒凹 ⑤小毛刷置入自聚修復樹脂 ⑥置入壓力鍋完成樹脂聚合作用 ⑦假牙基底完成修磨與拋光處理","options":["(A) ③④①⑤②⑥⑦","(B) ⑤③⑥②①⑦④","(C) ③④⑤⑥②①⑦","(D) ②①④③⑤⑥⑦"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-41","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"關於義齒性口炎（denture stomatitis）的敘述，下列何者正確？","options":["(A) 多半發生在樹脂基底（resin base）下，不常發生在金屬基底（metal base）下","(B) 患者經常會抱怨疼痛","(C) 受影響之黏膜多會紅腫，但表面平滑","(D) 只需局部投與抗黴菌藥物即可治癒"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"有關可撤式局部義齒製作時，組織調理材（tissue conditioner）的使用，下列敘述何者錯誤？","options":["(A) 可使過度受壓迫的組織恢復","(B) 要先去除舊義齒的咬合干擾","(C) 要使用足夠的量以保持其緩衝效果（cushioning effect）","(D) 可在口腔中維持一個月以上"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"可撤式局部義齒金屬支架製作過程中，義齒基底（denture base）覆蓋區若有組織倒凹（tissue undercut）情形時，應進行何種封凹（blockout）？","options":["(A) 平行封凹（parallel blockout）","(B) 成型封凹（shaped blockout）","(C) 任意封凹（arbitrary blockout）","(D) 不需做任何封凹"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-44","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"在設計Kennedy class I可撤式局部義齒，若是支柱牙的牙周支持（periodontal support）不佳而 需特別保護，應採用下列何種牙鈎為佳？","options":["(A) T 型槓鈎（T-bar clasp）","(B) 環鈎（ring clasp）","(C) 阿克斯牙鈎（Akers clasp）","(D) 鍛製金屬線牙鈎（wrought wire clasp）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"將鑽針的直軸垂直咬合面進行下顎大臼齒修磨時，通常會造成何處修磨量不足？","options":["(A) 頰側上半部","(B) 頰側下半部","(C) 舌側上半部","(D) 舌側下半部"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-46","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"關於上顎前牙瓷金屬融合牙冠（porcelain fused to metal crown）的敘述，下列何者正確？①唇 側面瓷厚度至少需1.2 mm ②切緣瓷厚度至少需1.5 mm ③腭側面瓷厚度至少需1 mm","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-47","subject":"ya5","topic":"咬合學基礎","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"對於長中心（long centric）理論的敘述，下列何者錯誤？","options":["(A) 中心關係與最大咬合嵌合位較少在同一位置","(B) 適當的垂直高度下，長中心長度的範圍約0.5 mm到1.5 mm","(C) 髁頭（condyle）在髁窩（condylar fossa）內先進行水平位移再向下位移","(D) 上顎前牙的舌側凹陷較淺"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-48","subject":"ya5","topic":"咬合學基礎","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"檢查下顎離中心（eccentric）運動時，後牙有無接觸，下列那個方法最靈敏？","options":["(A) 以咬合色紙檢查接觸點","(B) 以手指觸診","(C) 使用超薄咬合箔片（shimstock）檢查","(D) 用咬合蠟片檢查"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-49","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"固定補綴物的臨床取模以數位掃描技術與傳統印模相比，下列敘述何者錯誤？","options":["(A) 取得單顆牙冠模型之精準度與傳統印模相近","(B) 需耗費較多時間才能獲取診斷用模型","(C) 一般而言，患者之舒適度較高","(D) 兩者皆可使用於牙冠之製作流程"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-50","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"有關印模材料與單齒模材（die material）的敘述，下列何者正確？","options":["(A) 樹脂單齒模材（resin die）具有高強度及抗磨損能力，可用於任何印模材料","(B) 電鍍齒模材（electroplated die）具有高抗磨損能力，可用於任何印模材料","(C) 樹脂單齒模材（resin die）適用於polysulfide及silicone印模材料","(D) 樹脂單齒模材（resin die）不適用於polysulfide及hydrocolloid印模材料"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-51","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第1次第51題","year":114,"session":1,"number":51,"question":"在製作客製鑄造根柱（custom cast post）時，根柱蠟型包埋前，鑄造環內應放幾層襯裡 （liner）為佳？","options":["(A) 不用放","(B) 放一層","(C) 放兩層","(D) 放三層"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-52","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"114年第1次第52題","year":114,"session":1,"number":52,"question":"與傳統牙冠增長術相比，關於生物修形（biologic shaping）的敘述，下列何者正確？","options":["(A) 增加牙冠對牙根比例（crown to root ratio）","(B) 100%去除牙齒原有的修形邊緣（existing margin）","(C) 不改變原有的角化組織（keratinized tissue）","(D) 術後牙齦下牙根（subgingival root）較難清潔"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-53","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第53題","year":114,"session":1,"number":53,"question":"下列何種合金用來製作牙橋時，牙橋連接體（connector）所需的最小截面積最大？","options":["(A) Au-Pt-Pd","(B) Au-Pd-Ag","(C) Pd-Cu-Ga","(D) Pd-Ag"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第1次第54題","year":114,"session":1,"number":54,"question":"下列何種修復體最不適合做為固定牙橋的固位體（retainer）？","options":["(A) 3/4牙冠（three-quarter crown）","(B) 冠蓋體（onlay）","(C) 全金屬冠","(D) 金屬瓷牙冠（metal-ceramic crown）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第1次第55題","year":114,"session":1,"number":55,"question":"製作上顎門齒金屬瓷牙冠時，門齒切緣的瓷厚度最多不可以超過多少mm？","options":["(A) 1.5","(B) 2","(C) 2.5","(D) 3"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-56","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第56題","year":114,"session":1,"number":56,"question":"在潮濕的環境中，水會在瓷裂紋尖端和瓷產生化學變化，而導致瓷裂痕加大，此一現象稱為下列何 種疲乏（fatigue）？","options":["(A) 動態","(B) 靜態","(C) 壓力","(D) 動力"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-57","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"114年第1次第57題","year":114,"session":1,"number":57,"question":"關於製作臨時性固定補綴物的敘述，下列何者錯誤？","options":["(A) 製作過程全部在模型上完成時，樹脂中的單體（monomer）不會接觸到牙齒及牙齦，可減少組織破 壞的機會","(B) 在口內製作時，樹脂的聚合作用（polymerization）會放出很多熱量，容易造成牙髓的不可逆傷害","(C) 製作過程全部在模型上完成的補綴物，其強度比直接在口內完成的強很多，且不易變形","(D) 製作過程全部在模型上完成的補綴物，其邊緣密合度（marginal fit）比直接在口內完成的差"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-58","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第1次第58題","year":114,"session":1,"number":58,"question":"根據Rosenstiel SF的研究，最好看的上顎正中門齒的寬度／高度比（width/height ratio）約為 多少？","options":["(A) 61%～63%","(B) 68%～70%","(C) 75%～78%","(D) 85%～89%"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-59","subject":"ya5","topic":"植牙贋復","meta":"114年第1次第59題","year":114,"session":1,"number":59,"question":"關於人工植牙手術前放射線學檢查的敘述，下列何者錯誤？","options":["(A) 全景放射線攝影可能有5%～35%的尺度誤差","(B) 使用錐狀射束電腦斷層掃描（CBCT）的放射線暴露劑量較傳統電腦斷層掃描少","(C) 電腦斷層掃描可提供立體測量","(D) 後牙區的頰舌寬度可透過全景放射線攝影的結果來測量"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-60","subject":"ya5","topic":"植牙贋復","meta":"114年第1次第60題","year":114,"session":1,"number":60,"question":"製作上顎正中門牙人工植體牙冠時，為獲得適當的emergence profile，植體頂端平台 （platform）與牙冠露出軟組織位置（emergence position）之間的理想距離為多少mm？","options":["(A) 0.5～1.0","(B) 1.5～2.0","(C) 2.5～3.0","(D) 3.5～4.0"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第1次第61題","year":114,"session":1,"number":61,"question":"關於牙橋徑距長（span length）的敘述，下列何者錯誤？","options":["(A) 過長可能會造成瓷剝落、連接體斷裂、固持體鬆脫、牙齒動搖或不利的軟組織反應等影響","(B) 前牙使用兩顆橋體相較於後牙兩顆橋體的長期預後較佳","(C) 跨牙弓的牙橋可藉由分段的方式，使用key and keyway來提高假牙製作的精準度","(D) 在其他條件一樣的情況下，相較於一顆橋體，兩顆橋體可能會帶來四倍的形變量，同理，三顆橋體 會帶來高達九倍的形變量"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-62","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第1次第62題","year":114,"session":1,"number":62,"question":"下列何者不屬於贋復牙科診斷指數（Prosthodontics Diagnostic Index）的分類四（class IV）？","options":["(A) 垂直高度需要重建","(B) 口腔癌放射線治療患者","(C) 3～5個六分儀（sextant）單位有缺牙","(D) 上下顎運動障礙（maxillomandibular dyskinesia）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-63","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第63題","year":114,"session":1,"number":63,"question":"和研磨模型（milled cast）相較，下列何者不是製作3D列印模型（3D-printed cast）的優點？","options":["(A) 比較精確","(B) 比較輕","(C) 比較省時","(D) 產生廢棄物較少"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-64","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第64題","year":114,"session":1,"number":64,"question":"下列何者最不可能造成鑄件上出現多顆小球狀突起？","options":["(A) 沒有使用真空調拌機混合包埋材","(B) 以筆刷法塗覆包埋材時操作不當","(C) 鑄模溫度不足","(D) 包埋前，於蠟型上塗覆的表面作用劑不足"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-65","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第1次第65題","year":114,"session":1,"number":65,"question":"燒瓷前焊接法（preceramic application soldering）焊接金屬瓷牙固定式義齒的敘述，下列何者 正確？","options":["(A) 使用低熔點銲劑","(B) 使用瓦斯－氧焊槍（gas-oxygen torch）操作","(C) 和燒瓷後焊接法相較，外觀較為自然是燒瓷前焊接法比較容易達成的優勢","(D) 此法對高金含量合金不易產生凹陷（sag）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-66","subject":"ya5","topic":"牙科材料學","meta":"114年第1次第66題","year":114,"session":1,"number":66,"question":"關於磷酸鋅黏合劑的敘述，下列何者正確？","options":["(A) 最小的薄膜厚度約為35 μm","(B) 多餘的黏合劑容易移除","(C) 彈性係數較複合樹脂高","(D) 溶解度較玻璃離子體黏合劑低"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-67","subject":"ya5","topic":"咬合學基礎","meta":"114年第1次第67題","year":114,"session":1,"number":67,"question":"臨床檢查時，下列肌群何者通常最不會進行壓痛檢測？","options":["(A) 二腹肌（digastric muscle）","(B) 胸鎖乳突肌（sternocleidomastoid）","(C) 肩胛提肌（levator scapulae）","(D) 腭帆提肌（levator veli palatini）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-68","subject":"ya5","topic":"咬合學基礎","meta":"114年第1次第68題","year":114,"session":1,"number":68,"question":"有關顳顎韌帶（temporomandibular joint ligament）的敘述，下列何者錯誤？","options":["(A) 與關節囊（capsule）不易區分","(B) 可分成不同走向的纖維帶（band）","(C) 可限制髁頭（condyle）向前方的移動量","(D) 可限制工作側（working side）髁頭的側方移動能力"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-69","subject":"ya5","topic":"咬合學基礎","meta":"114年第1次第69題","year":114,"session":1,"number":69,"question":"關於中樞神經系統的敘述，下列何者錯誤？","options":["(A) 腦幹（brainstem）是三叉神經核（trigeminal nucleus）主要分布的位置","(B) 丘腦（thalamus）與處理大腦、小腦與腦幹間的溝通有關","(C) 下視丘（hypothalamus）的活動與交感神經系統（sympathetic nervous system）有密切關聯","(D) 咀嚼的節律運動模式主要由大腦運動皮質（motor cortex）掌控"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-70","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第70題","year":114,"session":1,"number":70,"question":"關於肌緊張度（muscle tonus）的意涵與調控，下列敘述何者錯誤？","options":["(A) 伸張反射（stretch reflex）對維持提顎肌（elevator muscles）的肌張力有重要影響","(B) 腦皮質與腦幹的活動影響肌張力，主要是透過提高γ傳出纖維（gamma efferent）的活動來影響梭 內肌纖維（intrafusal fibers）","(C) 當梭內肌纖維收縮時，使得肌梭較為敏感，較少的伸長即可引發反射","(D) 當梭內肌纖維收縮時，使得肌梭的靜止期（silent period）較長，肌肉較不易收縮"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-71","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第71題","year":114,"session":1,"number":71,"question":"對於葉片量尺（leaf gauge）的描述，下列何者正確？","options":["(A) 可測量垂直高度（vertical dimension）","(B) 可協助取得中心關係（centric relation）位置","(C) 可評估肌肉收縮（muscle contraction）力量","(D) 可評估顳顎關節側方位移（side shift）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-72","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第1次第72題","year":114,"session":1,"number":72,"question":"有關記錄臨床靜止位置（clinical rest position）的敘述，下列何者正確？","options":["(A) 為建立全口義齒咬合垂直高度的起始參考","(B) 病患斜躺45度角，頭需有適當的支撐","(C) 要求病患發「阿」音之後，放鬆下顎以取得","(D) 在取得姿勢性靜止位置（resting postural position）後，減去約2～4 mm後取得"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-73","subject":"ya5","topic":"咬合學基礎","meta":"114年第1次第73題","year":114,"session":1,"number":73,"question":"關於半調節咬合器的敘述，下列何者錯誤？","options":["(A) 多數的設計可以接受面弓轉移、前突運動的咬合記錄","(B) 若使用個別化的前突與側向運動紀錄的設計，即可避免誤差","(C) 使用側向咬合記錄可以調整咬合器關節髁頭的角度（angulation）與傾斜（inclination）程度","(D) 半調節咬合器可分為髁關節型（arcon type）與非髁關節型（nonarcon type）兩種"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-74","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第74題","year":114,"session":1,"number":74,"question":"關於下顎運動的敘述，下列何者錯誤？","options":["(A) 下顎往右側運動時，右側為工作側（working side）","(B) 非工作側的關節髁被內翼肌往前和往內拉動","(C) 工作側的關節髁以垂直軸（vertical axis）進行旋轉","(D) 非工作側顳顎關節之解剖形態允許發生側移"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-114-1-75","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第75題","year":114,"session":1,"number":75,"question":"下列何者不屬於肌電圖（electromyography）在咬合領域上的運用？","options":["(A) 生物回饋治療（biofeedback）","(B) 顎反射（jaw reflex）","(C) 關節彈響（clicking）","(D) 磨牙症（bruxism）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第76題","year":114,"session":1,"number":76,"question":"有關咀嚼肌壓痛（tenderness）的敘述，下列何者錯誤？","options":["(A) 此肌為肌炎狀態","(B) 可以是過久的中央神經系統過度激化（central hyperexcitability）造成","(C) 顳顎關節發炎亦可能使咀嚼肌肉呈現疼痛","(D) 原發性頸椎受傷亦可能使咀嚼肌肉呈現疼痛"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第77題","year":114,"session":1,"number":77,"question":"下列症狀何者最不是顳顎障礙症的共病（comorbid）？","options":["(A) 急性肝炎","(B) 偏頭痛","(C) 慢性下背痛","(D) 纖維肌痛"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第78題","year":114,"session":1,"number":78,"question":"關於穩定型咬合板（stabilization splint）的覆蓋程度，下列敘述何者正確？","options":["(A) 製作於上顎的咬合板應該完全覆蓋所有牙齒，以確保最佳效果","(B) 咬合板應該只需要覆蓋後牙，以減少不必要的接觸","(C) 咬合板的覆蓋程度對其功能沒有實質影響","(D) 下顎缺牙較多，特別是後牙缺失，應考慮製作下顎咬合板"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第79題","year":114,"session":1,"number":79,"question":"所附X光片右側髁頭（condyle）上之紅色圓點標示處，最可能的解剖位置為下列何者？","options":["(A) 髁頭的內側","(B) 髁頭的外側","(C) 髁頭的前側","(D) 髁頭的後側"],"answer":1,"image":"ya5-114-1-79.jpeg","clinical_level":"一般"},{"id":"ya5-114-1-80","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第1次第80題","year":114,"session":1,"number":80,"question":"下顎門牙的投射疼痛最可能來自那一條肌肉？","options":["(A) 顳肌（temporalis m.）","(B) 咬肌（masseter m.）","(C) 內翼肌（medial pterygoid m.）","(D) 二腹肌（digastric m.）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"關於製作上顎全口義齒的考量，下列敘述何者正確？","options":["(A) 厚且可動的黏膜是適合的口腔條件","(B) 異常咬合（malocclusion）不是造成軟組織異常的原因","(C) 纖維性的粗隆（fibrous tuberosity）不可去除","(D) 前牙過大咬合力會造成前牙區域過度動性牙床組織（hypermobile ridge tissue）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"上顎單顎全活動義齒（upper single denture, USD）與全口義齒的上顎義齒（upper complete denture, UCD）差別有那些？①USD 承受比較多咬合力量 ②USD 通常需要在義齒床內埋入金屬網 ③USD 的咬合設計不 應該為雙側平衡咬合 ④USD 與 UCD 的印模方式不同","options":["(A) ①②③④","(B) 僅②③","(C) 僅①③","(D) 僅①②"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-3","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"關於老年人配戴全口義齒常見的口角炎（angular cheilitis），下列敘述何者錯誤？","options":["(A) 口角炎與義齒性口腔炎（stomatitis）無關","(B) 與念珠菌（candida）感染有關","(C) 可以用細胞學抹片（cytosmear）進行確診","(D) 與金黃色葡萄球菌（Staphylococcus aureus）感染亦有關"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"上顎全口活動義齒印模時，下列何處不需要緩壓？","options":["(A) 腭隆突（palatal torus）","(B) 齒槽骨嵴（alveolar ridge）","(C) 腭皺區（rugae）","(D) 上顎骨粗隆（maxillary tuberosity）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-5","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"關於後腭封（posterior palatal seal）的敘述，下列何者錯誤？","options":["(A) 可建立義齒後緣周邊封閉，以確保義齒在行使功能的時候不致脫位","(B) 需設置於振動線前方","(C) 不可延伸至鈎狀切迹（hamular notch）處，以防止義齒脫位","(D) 可於個人牙托邊緣成形（border molding）時進行設置，以評估義齒的固持性"],"answer":[1,2],"image":"","clinical_level":"重點","explanation_pending":false},{"id":"ya5-114-2-6","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"關於臼齒後墊（retromolar pad）的敘述，下列何者正確？①下顎全口義齒後緣必須蓋到臼齒後墊 ②部分角 質化（keratinized）組織組成 ③部分腺體（glandular）組織組成 ④部分咬肌（masseter muscle）纖維 組成","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"關於全口義齒基底板（baseplate）之製作，下列敘述何者錯誤？","options":["(A) 必須要堅硬、精確且穩定","(B) 可用自聚式或光聚式樹脂製作","(C) 自聚式樹脂基底板可使用撒佈法（sprinkle-on）製作，可增加基底貼合性","(D) 可用硬基底板蠟（hard baseplate wax）製作，且需先將模型上所有的倒凹封閉"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-8","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"下列何者為全口活動義齒重置位（remount）發生的時機點？①雕蠟成型（wax-up）後試戴時 ②丙烯酸樹脂 煮聚（acrylic resin processing）後 ③義齒裝戴（denture delivery）","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-9","subject":"ya5","topic":"牙科材料學","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"關於全口活動義齒人工牙（denture teeth）的材料，下列敘述何者正確？","options":["(A) 瓷牙（porcelain teeth）耐磨，應廣泛使用","(B) 與義齒基底的結合，瓷牙靠的是物理機械式結合","(C) 瓷牙可應用在有限的咬合間隙（interocclusal space）","(D) 相對於丙烯酸樹脂牙（acrylic resin teeth）而言，複合樹脂牙（acrylic composite teeth）與義齒基底 的結合更好"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"全口義齒患者，將記錄基底及咬合堤（occlusion rim）置入口中後，利用生理性靜止位置（physiological rest position）法取得垂直距離（vertical dimension），接著取中心關係（centric relation）紀錄，然 後在咬合器上排牙。下次患者在戴上已排上義齒之試戴基底（trial base），最常採用何種方法來確認垂直 距離是否適當？","options":["(A) 生理性靜止位置","(B) 唇部美觀法（esthetics）","(C) 發音法（phonetics）","(D) 無牙嵴平行法（parallelism of the ridges）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-11","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"下列何種全口義齒咬合形式最常使用第二大臼齒平衡斜坡（second molar balancing ramp）排牙？","options":["(A) 符合舌側化咬合（lingualized occlusion）設計的人工牙","(B) 具解剖形態的 30°人工牙","(C) 平面式（monoplane）的人工牙","(D) 具解剖形態的 15°人工牙"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-12","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"基於舌側化咬合（lingualized occlusion）概念來進行全口義齒的排牙，下列敘述何者錯誤？","options":["(A) 下顎後牙一般選用零度牙來做排列","(B) 相對於平面式咬合（monoplane occlusion）咀嚼效率較好","(C) 無須任何非工作側接觸即可達成側方運動時的義齒穩定","(D) 在中心咬合（centric occlusion）時，僅有上顎後牙的腭側咬頭與其對咬牙接觸"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-13","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"全口活動義齒排牙時，下列何種樹脂後牙形狀的組合，要達到平衡咬合（balanced occlusion），需要先取 下顎前伸（protrusive）咬合記錄？","options":["(A) 上顎 30 度牙＋下顎零度牙","(B) 上顎零度牙＋下顎零度牙","(C) 上顎 30 度牙＋下顎 30 度牙","(D) 上顎零度牙＋下顎 30 度牙"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-14","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"關於全口義齒舌側化咬合觀念（lingualized occlusion concept）的組合，下列何者最常使用？","options":["(A) 上顎解剖形態義齒（anatomical resin teeth），下顎單一平面義齒（monoplane resin teeth）","(B) 上顎單一平面義齒（monoplane resin teeth），下顎解剖形態義齒（anatomical resin teeth）","(C) 上顎解剖形態義齒（anatomical resin teeth），下顎解剖形態義齒（anatomical resin teeth）","(D) 上顎單一平面義齒（monoplane resin teeth），下顎單一平面義齒（monoplane resin teeth）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-15","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"如果全口義齒右下第二顆大臼齒排在上升殘嵴（ascending residual ridge），最可能造成何處黏膜的刺 激？","options":["(A) 右下犬齒與第一小臼齒區頰側","(B) 右下犬齒與第一小臼齒區舌側","(C) 左下犬齒與第一小臼齒區頰側","(D) 左下犬齒與第一小臼齒區舌側"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"造成或加速全口義齒患者殘嵴降低（residual ridge reduction）的因素，下列何者最不可能？","options":["(A) 密集（intensively）使用義齒的患者","(B) 義齒咬合狀況不穩定者（unstable denture）","(C) 骨質疏鬆症（osteoporosis）","(D) 藥物引起的口乾症（xerostomia）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"關於全口義齒不適當的基底設計與咬合安排，可能造成的臨床表現，下列敘述何者錯誤？","options":["(A) 患者有嘔吐反射（gagging reflex）與上顎義齒的後緣長度有關","(B) 患者在張大口或打哈欠時，上顎義齒會鬆脫，此現象與義齒頰側邊緣（buccal border）太厚有關","(C) 上顎義齒剛戴上時是緊的，幾個小時後變鬆，此現象與義齒的後障（postdam）設計有關","(D) 患者抱怨於咬合平面處的頰黏膜有咬痕，與上下顎義齒後牙咬頭間的水平覆蓋（overjet）有關"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"對全口即裝義齒（immediate denture）的敘述，下列何者錯誤？","options":["(A) 上顎的預後通常會比下顎來的好","(B) 通常會先拔前牙而留下後牙","(C) 裝置後，建議患者 24 小時後回診評估其義齒的固著性、支撐性與穩定性","(D) 仍需印製初模（preliminary impression），以達到診斷、治療計畫訂定、與客製化印模托（custom impression tray）製作"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-114-2-19","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"有關覆蓋式義齒（overdenture）製作之目的，下列何者錯誤？","options":["(A) 義齒支持（support）作用可增強","(B) 減少殘嵴之吸收","(C) 增加病人咀嚼之觸感及提升咬力","(D) 可增加美觀之效果，但對義齒之固位（retention）作用沒有幫助"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-20","subject":"ya5","topic":"牙科材料學","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"全口活動義齒使用熱聚式樹脂（heat-activated PMMA）在包埋煮聚過程中的誤差，常造成咬合高度提高，應 以下列何種方式記錄最合理？","options":["(A) 測量包埋盒煮聚前後的高度變化","(B) 拆開包埋盒時小心露出樹脂牙，測量盒底至樹脂牙的高度變化","(C) 將義齒主模型重置回咬合器上，測量門齒釘（incisal pin）至門齒檯（incisal table）的距離","(D) 將全口活動義齒置入病人口內，測量鼻尖（nose tip）至頦前點（progonion）的距離變化"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"全口活動義齒使用熱聚式樹脂（heat-activated PMMA）於包埋煮聚（processing）的過程中若操作不當，可 能會導致義齒基底（denture base）裡產生氣泡（void），圖 1 與圖 2 的氣泡最可能發生的原因為下列何 者？","options":["(A) 圖 1 包埋盒加熱過快、圖 2 包埋樹脂量不足","(B) 圖 1 包埋樹脂量不足、圖 2 包埋盒加熱過快","(C) 圖 1 樹脂粉液混和不均勻、圖 2 施加在包埋盒上的壓力不足","(D) 圖 1 包埋樹脂量不足、圖 2 施加在包埋盒上的壓力不足"],"answer":1,"image":"ya5-114-2-21.jpeg","clinical_level":"一般"},{"id":"ya5-114-2-22","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"患者在進入全口無牙的狀態前，經醫師詳細解說拔牙的原因後，簽署拔牙同意書，符合醫學倫理中的那一個原則？","options":["(A) 尊重自主原則（the principle of respect for autonomy）","(B) 不傷害原則（the principle of non-maleficence）","(C) 行善原則（the principle of beneficence）","(D) 公平正義原則（the principle of justice）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"下顎可撤式局部義齒舌側板（lingual plate）的敘述與臨床適應症，下列何者錯誤？","options":["(A) 舌側板因為具有足夠的寬度，其下緣不需要遵循舌側桿的半梨形（half-pear shape）","(B) 舌側板適用於舌繫帶位置很高或是可用於舌側槓距離口底空間不足時","(C) 舌側板本身並不當做間接固位體（indirect retainer）使用，若需要時，則須包含明確的鈎靠設計","(D) 舌側板於前牙處，外型盡可能的順著牙齒與牙齒楔隙（embrasure）而呈現扇形"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-24","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"上顎可撤式局部義齒間接固位體（indirect retainer）的設計，下列敘述何者正確？①覆蓋皺摺區（rugae area）在任一條件下均可作為間接固位 ②使用皺摺（rugae）支撐來取得間接固位，通常是腭馬蹄形設計（palatal horseshoe design）的一部分 ③在僅剩前牙的上顎弓中，通常需要全腭覆蓋 ④覆蓋皺摺區的基底材料以樹脂較佳 ⑤在沒有完全覆蓋的情況下，間接固位體應與Kennedy class II義齒的主要連接體（major connectors）的其他設計一起使用","options":["(A) ①②③④⑤","(B) 僅②③④⑤","(C) 僅②③","(D) 僅①④⑤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-25","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"使用舌側板（lingual plate）或舌側槓（lingual bar）為下顎可撤式局部義齒的主連接體（major connector）時，下列敘述何者錯誤？","options":["(A) 可使用牙周探針測量口底的深度來決定下緣的位置","(B) 舌側板的上緣不要超過牙齒舌側面中間三分之一的高度","(C) 舌側板上、下緣要越薄越好以減少舌頭的不適","(D) 兩種設計的下緣皆為半梨形（half-pear shape）"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-114-2-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"下列何種可撤式局部義齒牙鈎（clasp）有減壓作用（stress breaking action）？①鍛製金屬線的組合牙鈎 （combination clasp with wrought wire） ②Kratochvil's RPI ③使用近心鈎靠（mesial rest）及遠 心倒凹（distal undercut）的反作用牙鈎（reverse action clasp） ④反向迴力牙鈎（reverse back action clasp） ⑤反向環周牙鈎（reverse circumferential clasp） ⑥雙半牙鈎（half-and-half clasp）","options":["(A) ①②④","(B) ①③④⑤","(C) ①③⑤⑥","(D) ②③④⑥"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"可撤式局部義齒之 RPI 固位設計，最常用於下列何種情況？","options":["(A) 下顎 Kennedy class I","(B) 上顎 Kennedy class III","(C) 下顎 Kennedy class VI","(D) 支柱牙太過度往舌側傾"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"關於 Kennedy class III 缺牙，下列敘述何者錯誤？","options":["(A) 無牙區較短時可採用固定式義齒","(B) 可撤式局部義齒支持及固位與缺牙區大小、齒槽骨殘嵴（residual ridge）的型態都無關","(C) 可撤式局部義齒支持及固位主要相關者是支柱牙","(D) 為牙齒支持（tooth-supported）可撤式局部義齒"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-29","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"製作遠伸性（distal extension）可撤式局部義齒時，將鈎靠（rest）放置於最終端支柱牙上的近心側的原 因為何？①可減少該支柱牙因受力而往遠心傾斜 ②可減少活動義齒往近心滑動 ③可增加該處牙鈎的固持 力（retention） ④可使黏膜的負擔平均","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-30","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"可撤式局部義齒上顎單腭帶主連接體（single palatal strap major connector）的設計，主要是用於甘迺 迪分類（Kennedy classification）的那一類？","options":["(A) 第一類（class I）","(B) 第二類（class II）","(C) 第三類（class III）","(D) 第四類（class IV）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-31","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"析量時工具使用注意事項，下列敘述何者正確？","options":["(A) 可使用炭筆（carbon marker）切割蠟型，產生平行路徑","(B) 倒凹量測量可利用 2 度或 6 度錐狀工具","(C) 析量刀（surveyor blade）使用石膏牙的修整成期望的外廓高隆線","(D) 0.01～0.02 mm 的倒凹量是常用的固位倒凹量"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"關於引導面（guiding plane）的修形，下列何者錯誤？","options":["(A) 後牙區常使用的工具是柱形鑽針（cylindrical diamond bur）","(B) 當缺牙區前後有牙時，咬合牙齦向（occlusogingival height）引導面的修形高度是 2～4 mm","(C) 當缺牙區是後方無牙時，咬合牙齦向（occlusogingival height）引導面的修形高度是 3～5 mm","(D) 引導面由咬合面觀應該仍然順著原牙齒外形，不必完全拉直"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"關於析量時的平行封凹（parallel blockout）與成型封凹（shaped blockout），下列敘述何者正確？","options":["(A) 平行封凹通常為了牙鈎臂蠟型定位","(B) 平行封凹可位在所有小連接體的下方或剛性連接體跨過的組織倒凹","(C) 通常使用的材料是黏性蠟（adhesive wax）或油性黏土（oil-based clay）","(D) 成型倒凹的厚度由析量刀與表面接觸點下倒凹區來決定"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-34","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"關於面弓（face-bow）的敘述，下列何者最適當？①如果要使用聽筒式面弓（earpiece facebow），應提醒 患者耳道中的塑料聽筒會降低噪音 ②可以轉移患者上顎骨與軸－眶平面（axis-orbital plane）的關係 ③可以記錄髁突到上中切牙切端接觸點的半徑 ④可以記錄咬合平面與軸－眶平面（axis-orbital plane） 的角度關係 ⑤如果使用眶下指針（infraorbital pointer），通常將其放置在面弓的最左側，並用墨點標 識眶下點（infraorbital point）","options":["(A) ①②③④⑤","(B) 僅①③⑤","(C) 僅②③④","(D) 僅②④⑤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-35","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"下圖為上顎可撤式局部義齒咬合面觀之簡圖，屬於何種缺牙型態？","options":["(A) Kennedy class II，modification 1","(B) Kennedy class III，modification 1","(C) Skinner class I","(D) Bailyn class I"],"answer":0,"image":"ya5-114-2-35.jpeg","clinical_level":"一般"},{"id":"ya5-114-2-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"可撤式局部義齒印模時，下列何者是印模用蠟（impression wax）的使用時機？①記錄無牙嵴的功能性型態 （functional form） ②作為已完成義齒換底墊（reline）之印模材 ③若要在咬合負荷下記錄組織樣貌， 可先製作咬合堤或排好人工牙，並請患者模擬功能性活動 ④可用於修正義齒邊緣成形不足","options":["(A) 僅①②③","(B) 僅①②④","(C) ①②③④","(D) 僅②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"可撤式局部義齒印模時，使用下列何種材料於口內多處倒凹區最適當？","options":["(A) 製作塑膠（modeling plastic）","(B) 水凝膠（hydrocolloids）","(C) 金屬氧化物糊劑（metallic oxide plate）","(D) 聚乙醚（polyether）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-38","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"關於可撤式局部義齒排牙時，下列敘述何者錯誤？","options":["(A) 最好須排列於殘嵴（residual ridge crest）之上","(B) 最好咬合力之傳導方向垂直殘嵴","(C) 選擇與自然齒頰、舌側同等寬度之人工齒","(D) 咬合重心位於殘嵴（residual ridge crest）之上"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-39","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"對下顎齒列完整，上顎後牙全無的病人，應如何正確地置放上顎診斷模型於咬合器（articulator）？","options":["(A) 觀察病人咬合，依經驗將上顎齒模置放於咬合器","(B) 製作上顎後牙基底板與咬合堤，於口內固定咬合叉於前牙及咬合堤上，再做面弓轉移","(C) 在咬合叉後牙位置置放較多之軟蠟後，於病人口中確定蠟與前牙及後牙殘嵴穩固接觸位置，再做面弓轉移， 置放上顎齒模","(D) 以咬合叉固位於下顎齒列咬合面，做面弓轉移置放下顎齒模，再以咬合記錄置放上顎齒模"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"當可撤式局部義齒基底明顯破壞或變質但支架仍完整且貼合程度佳時，下列那一種處理方式最適當？","options":["(A) 換底墊（reline）","(B) 換基底（rebase）","(C) 修復處理（repair）","(D) 重製作處理（reconstruction）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"如果患者在配戴新的可撤式局部義齒會發生嘔吐反應（gagging），下列敘述何者錯誤？","options":["(A) 可能為心理因素所造成","(B) 可能因義齒基底（denture base）過度延伸所引起","(C) 若上顎義齒之主連接體（major connector）與硬腭間不密合時，可能引發嘔吐反應","(D) 過高的義齒垂直間距（vertical dimension）可能引發嘔吐反應，但過低則不會"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"關於可撤式局部義齒咬合調整的敘述，下列何者錯誤？","options":["(A) 超薄咬合箔片（shim stock）能用來確定咬合接觸是否存在","(B) 被咬合紙轉印上顏色的區域，不表示一定有咬合干擾","(C) 若在診間作義齒之咬合調整，建議直接在口內修磨咬合干擾點","(D) 如果義齒穩定性不足，建議採取臨床重置位（clinical remounting）的方法調整"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"下列製作上顎可撤式局部義齒金屬支架（metal framework）的技工操作，其步驟之先後次序何者最適當？① 翻製耐火模型（refractory cast） ②放置珠狀緣飾（beading） ③去蠟處理與燒卻（wax elimination and burnout） ④進行封凹與緩壓（blockout and relief） ⑤支架上鑄道處理（spruing the framework） ⑥包埋耐火模型（investing the refractory cast） ⑦蜂蠟浸泡（beeswax dip） ⑧支架 蠟型製作（waxing the framework）","options":["(A) ④②⑦①⑧⑤⑥③","(B) ②④①⑦⑧⑤⑥③","(C) ④②①⑦⑤⑧⑥③","(D) ②④⑦①⑤⑧⑥③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-44","subject":"ya5","topic":"牙科材料學","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"關於可撤式局部義齒的金屬支架材料鈷鉻合金（cobalt-chromium alloy）和鈦合金（titanium alloy）的比 較，下列敘述何者最適當？","options":["(A) 鈷鉻合金有較佳的生物相容性（biocompatibility）","(B) 鈦合金有較高的楊氏係數（Young's modulus）","(C) 鈷鉻合金有較高的磨耗量（wear volume）","(D) 鈦合金鑄造時較容易有鑄造缺陷（defect）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-45","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"關於支柱牙成型時，溫度的不當提升可能造成牙髓傷害，下列敘述何者錯誤？","options":["(A) 當使用高速牙科手機進行切削，大約 100 克重左右之間歇接觸即可達有效率之切削且不會過度提升切削溫度","(B) 當水霧影響視線需降低水霧的量，轉速應降至每分鐘 17,000 轉","(C) 使用肩台形（shoulder）或是弧形（chamfer）鑽針切削時較不容易累積碎屑","(D) 製備溝（groove）或是釘孔（pin hole）時，應使用高速手機以減少溫度提升"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"關於上顎前牙瓷金屬融合牙冠（porcelain fused to metal crown）支柱牙修磨的敘述，下列何者正確？① 下顎前突運動時，切緣需有 1.5～2.0 mm 的修磨量 ②舌側修形為厚度 0.5 mm 的弧形緣（chamfer margin） ③修磨唇側面近切緣 1/3 的導引溝（labial reduction guide groove）方向須與牙冠置入方向相同 ④修磨 唇側面近牙頸 2/3 的導引溝，建議使用火焰形鑽石磨針（flame shape diamond bur）","options":["(A) ①②","(B) ③④","(C) ②③","(D) ①④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-47","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"當患者僅下顎第一大臼齒缺損，需要以牙冠治療時，下列敘述何者正確？","options":["(A) 需先作咬合調整，使中心關係（centric relation）與最大咬頭嵌合（maximum intercuspation）一致","(B) 咬合關係必須將上顎大臼齒的功能性咬頭咬在下顎大臼齒的中心窩上","(C) 使所有後牙在中心關係（centric relation）時都同時接觸到","(D) 維持患者原有的咬合關係"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-48","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"功能軌徑生成術（functionally generated path technique）適用於製作那個部位的固定補綴物？①上顎前 牙 ②下顎前牙 ③上顎後牙 ④下顎後牙","options":["(A) ①②","(B) ①③","(C) ②④","(D) ③④"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-49","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"下列有關排齦的敘述，何者錯誤？","options":["(A) 排齦線一定要先浸泡收斂劑才能達到排齦效果","(B) 排齦時，應將排齦線壓入微濕之牙齦溝內","(C) 排齦時，排齦線應從鄰間牙齦處開始壓入牙齦溝內 排齦器械應斜向牙齒的方向壓擠排齦線","(D) 排齦器械應斜向牙齒的方向壓擠排齦線"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-50","subject":"ya5","topic":"牙科材料學","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"下列何種印模材可以在印完模後隔天再灌模，也不會影響印模結果？","options":["(A) 多硫化物（polysulfide）彈性印模材 彈性印模材","(B) 聚乙酯（polyether）彈性印模材","(C) 縮合式矽膠（condensation silicone）彈性印模材","(D) 不可逆性水凝膠（hydrocolloid）印模材 印模材"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-51","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"114年第2次第51題","year":114,"session":2,"number":51,"question":"根管治療完成後之牙齒，其根柱（post）的設計，在防止牙齒斷裂方面扮演重要的角色，但當剩餘冠部齒質的高度在至少幾 mm 以上時，根柱設計所扮演的角色就較為不重要？","options":["(A) 0.5","(B) 1","(C) 1.5","(D) 2"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-52","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第2次第52題","year":114,"session":2,"number":52,"question":"關於較厚牙齦生物型態（thick biotype）特徵的描述，下列何者正確？","options":["(A) 拔牙後會有大於 4 mm 的牙齦萎縮","(B) 拔牙後頰側齒槽骨會有大於 2 mm 的吸收量 的吸收量","(C) 翻瓣手術後常無明顯的牙齦萎縮與骨吸收","(D) 植牙手術後會有長且薄的乳頭（papillae）留存"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第2次第53題","year":114,"session":2,"number":53,"question":"下列簡圖為四種橋體中央部位的斷面圖，何者最不適合用在咬合垂直距離不足的情況下？","options":["(A) [見附圖]","(B) [見附圖]","(C) [見附圖]","(D) [見附圖]"],"answer":3,"image":"ya5-114-2-53.jpeg","clinical_level":"一般"},{"id":"ya5-114-2-54","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第2次第54題","year":114,"session":2,"number":54,"question":"下列何者不是樹脂黏著性牙橋（resin- -bonded fixed partial denture）的禁忌？","options":["(A) 失活牙齒（non-vital teeth）","(B) 容易蛀牙的牙齒","(C) 較短的牙齒","(D) 頰舌徑較厚的牙齒"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-55","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第2次第55題","year":114,"session":2,"number":55,"question":"有關瓷片鑲面（porcelain laminate veneer）的敘述，下列何者錯誤？","options":["(A) 適用於四環素變色之前牙修復","(B) 適用於牙釉質發育不全症（enamel hypoplasia）之前牙修復","(C) 不適用於磨牙症（bruxism）之前牙修復 之前牙修復","(D) 不適用於齲齒率高患者之前牙修復"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-56","subject":"ya5","topic":"牙科材料學","meta":"114年第2次第56題","year":114,"session":2,"number":56,"question":"下列何者是選擇全瓷修復體系統（all--ceramic system）的主要考量？①抗破裂性 ②美觀 ③磨耗性","options":["(A) 僅①②","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-57","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第2次第57題","year":114,"session":2,"number":57,"question":"下顎左右兩顆正中門齒的缺失，將製作黏著牙橋（adhesion bridge）修復缺牙區，下列敘述何者正確？","options":["(A) 橋體連接在一起（connecting pontic）的失敗率比橋體分開（separating pontic）者低","(B) 樹脂黏合劑必須隔絕氧氣以免影響聚合","(C) 一般樹脂黏合劑與高貴金屬合金鍵結強度（bond strength）比與賤金屬合金鍵結強度高","(D) 較容易失敗的位置為金屬與樹脂的黏著界面（the bond of resin to metal）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-58","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第2次第58題","year":114,"session":2,"number":58,"question":"對於暗視覺（scotopic vision）的敘述，下列何者正確？","options":["(A) 只有視錐細胞（cones）發揮作用","(B) 只有視桿細胞（rods）發揮作用","(C) 約 80%視錐細胞（cones）與 20%視桿細胞（rods）協同作用","(D) 對紅色較敏銳"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-59","subject":"ya5","topic":"植牙贋復","meta":"114年第2次第59題","year":114,"session":2,"number":59,"question":"關於人工植體放置的原則，下列敘述何者錯誤？","options":["(A) 避免傷及下齒槽神經，下顎前牙區植體須至少距離 mental foramen 往前 5 mm","(B) 上顎前牙區應儘量避開 incisive foramen，因此種植時應避開中線位置","(C) 上顎後牙區放置人工植體須保留植體根部與鼻竇腔底部有 1 mm 的距離，且不要碰觸鼻竇腔底部的皮質骨以 避免傷及鼻竇","(D) 下顎後牙區須注意下顎舌骨肌底部可能存在的舌側凹陷"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-60","subject":"ya5","topic":"植牙贋復","meta":"114年第2次第60題","year":114,"session":2,"number":60,"question":"下列何種設計可以讓植體支持式修復體（implant restoration）承受較少的側應力？","options":["(A) 加寬牙冠的咬合檯（occlusal table）","(B) 加高牙冠的牙尖角度（cusp angle）","(C) 盡可能建立無側向接觸的牙尖咬窩（cusp-fossa）關係","(D) 使用懸桁式（cantilevered）設計"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第2次第61題","year":114,"session":2,"number":61,"question":"關於懸桁式（cantilevered）牙橋的敘述，下列何者錯誤？","options":["(A) 側門牙缺失時，使用懸桁式牙橋的設計可以保持較多的齒質，及減少使用三單位牙橋可能帶來的困難","(B) 臨床上，在 resin-retained FPDs 使用懸桁式牙橋的設計比黏著在兩側鄰接牙的設計成功率來得低","(C) 懸桁式牙橋的設計會對牙齒周遭的支持性組織帶來傷害而造成支柱牙可能的角度偏移、旋轉或飄移","(D) 大部分的情況下，單一支柱牙使用懸桁式牙橋的長期成功率普遍不佳"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-62","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"114年第2次第62題","year":114,"session":2,"number":62,"question":"下列狀況何者以自然牙支持之固定式贋復治療優於可撤式贋復治療？","options":["(A) 高齡病患缺少遠心端支柱牙（distal abutment）","(B) 上顎前牙美觀區有大範圍缺牙及骨缺損","(C) 兩側後牙區長距離缺牙","(D) 年輕病患下顎四顆門牙因蛀牙拔除"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-63","subject":"ya5","topic":"牙科材料學","meta":"114年第2次第63題","year":114,"session":2,"number":63,"question":"下列何種印模材無法以環氧樹脂（epoxy resin）製作模型？","options":["(A) 多硫化物（polysulfide）","(B) 縮合矽化物（condensation silicone）","(C) 加成矽化物（addition silicone）","(D) 聚乙醚（polyether）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-64","subject":"ya5","topic":"牙科材料學","meta":"114年第2次第64題","year":114,"session":2,"number":64,"question":"關於蠟型（wax pattern）包埋（investing）前的準備過程，下列敘述何者最適當？","options":["(A) 不必使用放大鏡檢視是否有多餘的蠟超過完成線（finish line）","(B) 離開模型的蠟型，需要靜置一段時間讓應力釋放之後才能包埋","(C) 鑄道（sprue）的尺寸越大越好","(D) 鑄道（sprue）的材質可以是蠟、塑膠或中空金屬"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-65","subject":"ya5","topic":"牙科材料學","meta":"114年第2次第65題","year":114,"session":2,"number":65,"question":"與石膏結合（gypsum-bonded）包埋粉比較，下列何者是磷酸結合（phosphate-bonded）包埋粉的特點？","options":["(A) 膨脹變化的可控性較小","(B) 不需要特殊液體來混合","(C) 不會產生氣體","(D) 工作時間較短"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-66","subject":"ya5","topic":"植牙贋復","meta":"114年第2次第66題","year":114,"session":2,"number":66,"question":"對於固定式植體贋復物，下列敘述何者錯誤？","options":["(A) 贋復物不可有凸緣（flange）","(B) 短期使用含 chlorhexidine 漱口藥水","(C) 術後需定期 X 光片檢查","(D) 術後需使用金屬牙周探針來探測囊袋深度"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-67","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第67題","year":114,"session":2,"number":67,"question":"外翼肌（lateral pterygoid muscle）下腹（inferior belly）之功能不包含下列何者？","options":["(A) 開口","(B) 閉口","(C) 下顎前突","(D) 下顎側向運動"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-68","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第2次第68題","year":114,"session":2,"number":68,"question":"顳顎關節盤之盤中央部分，大多數膠原纖維之走向為何？","options":["(A) 左右橫向","(B) 上下縱向","(C) 前後走向","(D) 交叉斜向"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-69","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第2次第69題","year":114,"session":2,"number":69,"question":"關於咀嚼肌痛（masticatory muscle pain）的生理與神經機制，下列何者正確？①即使在休息的狀態下，咀 嚼肌依然會維持些微的收縮與緊張（tonus） ②保護性共同收縮（protective co-contraction）是指作用 肌與拮抗肌兩者同時收縮 ③拮抗肌收縮往往是為了預防更嚴重的傷害發生 ④持續的保護性共同收縮可能 引發肌肉疼痛","options":["(A) 僅①④","(B) 僅①②③","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-70","subject":"ya5","topic":"臨床基礎與倫理","meta":"114年第2次第70題","year":114,"session":2,"number":70,"question":"下列有關腦之邊緣系統（limbic system）的敘述，何者錯誤？","options":["(A) 參與情緒和記憶的形成與調節","(B) 主要組成部分包括海馬體、杏仁核等","(C) 係分布於延腦中的多個區域","(D) 對於理解疼痛與情緒及行為控制尤為重要"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-71","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第71題","year":114,"session":2,"number":71,"question":"在安格氏第一類咬合關係中，下顎進行側向運動（lateral movement）時，非工作側上下顎後牙可能的接觸 位置，下列何者正確？","options":["(A) 上顎舌側咬頭內斜面（inner incline）接觸下顎頰側咬頭內斜面","(B) 上顎頰側咬頭內斜面（inner incline）接觸下顎頰側咬頭內斜面","(C) 上顎舌側咬頭內斜面（inner incline）接觸下顎頰側咬頭外斜面（outer incline）","(D) 上顎頰側咬頭內斜面（inner incline）接觸下顎頰側咬頭外斜面（outer incline）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-72","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第72題","year":114,"session":2,"number":72,"question":"附圖為患者上下顎位於中心關係位置時的咬合，若病人要求治療，下列治療方式何者最適當？","options":["(A) 選擇性修磨","(B) 固定贋復治療","(C) 矯正治療","(D) 活動贋復治療"],"answer":2,"image":"ya5-114-2-72.jpeg","clinical_level":"一般"},{"id":"ya5-114-2-73","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第73題","year":114,"session":2,"number":73,"question":"第一類咬合者，下顎處在最前方位置的情況是下列何者？","options":["(A) 前牙切端對切端","(B) 咀嚼的初期階段","(C) 咀嚼的後期階段","(D) 最大張口範圍"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-74","subject":"ya5","topic":"咬合學基礎","meta":"114年第2次第74題","year":114,"session":2,"number":74,"question":"關於咀嚼運動之敘述，下列何者錯誤？","options":["(A) 對澳洲土著的研究發現，經過嚴重功能性咬耗的齒列，在平衡側會發生干擾性接觸","(B) 咀嚼咬穿食物時，對平衡側關節的壓力較工作側大","(C) 吃軟性食物時，咀嚼速率較吃硬性食物慢","(D) 習慣性單側咀嚼的人，可能是適應咬合干擾的結果。"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-75","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第2次第75題","year":114,"session":2,"number":75,"question":"咀嚼系統可能因外力創傷，造成所謂生理性調適反應（adaptive physiological response），下列那個項目 不是此反應？","options":["(A) 硬組織修復（如顎骨修復）","(B) 軟組織修復（如顎關節韌帶修復）","(C) 咀嚼肌群張度調整","(D) 生長與發育"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第2次第76題","year":114,"session":2,"number":76,"question":"有關基因因子可能是造成顳顎關節障礙病因之敘述，下列何者最不正確？","options":["(A) 特定基因的單核甘酸多態性（SN Polymorphism）可能有關","(B) 男女性患者因性別有異，造成顳顎關節障礙機轉可能不相同","(C) 高疼痛敏感度（high-pain sensitivity）族群較易產生顳顎關節障礙","(D) 糖尿病患者的胰島素基因可能有關"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第2次第77題","year":114,"session":2,"number":77,"question":"以針刺法（needling）去除肌筋膜激痛點（myofascial trigger points）的敘述，下列何者正確？①使用的 局部麻醉劑為 1：100,000 epinephrine 的 2％ lidocaine ②使用局部麻醉劑有診斷意義 ③針刺所有按壓 疼痛的區域，都會有效果 ④針刺時若能引發局部抽搐反應（twitch response），即可確認扳機點 （trigger point）已被碰觸","options":["(A) 僅②④","(B) ①②③","(C) ②③④","(D) ①③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第2次第78題","year":114,"session":2,"number":78,"question":"下列何者較不會影響咬合板製作時厚度的決定？","options":["(A) 門牙垂直覆蓋（overbite）","(B) 前牙開咬（anterior open bite）","(C) 史比曲線（curve of Spee）","(D) 缺牙數目"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-114-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第2次第79題","year":114,"session":2,"number":79,"question":"下列關於顳顎關節內部紊亂症（internal derangement）的敘述，何者錯誤？","options":["(A) 其定義為關節盤、髁頭及關節窩之間的相對關係異常","(B) 下顎張口過程中，髁頭和移位之關節盤在關節窩內互相擠壓","(C) 不可回復性的關節盤移位，具有明顯的張口彈響","(D) 張口時，下顎常會往患側偏移"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-114-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"114年第2次第80題","year":114,"session":2,"number":80,"question":"有關顳顎關節半脫臼（subluxation），下列何者正確？①下顎半脫臼的原因通常不是病理性的 ②關節突的 後斜坡較長且較平坦 ③關節突前斜坡較短且陡 ④在達到髁頭的最大移動之前，關節盤的最大旋轉運動已 經完成","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-1","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"關於配戴全口義齒的病人與全口自然牙者，兩者在咀嚼系統的生物機械性質差異的敘述，下列何者錯誤？","options":["(A) 配戴全口義齒的病人，其平均咬合力只有全口自然牙的 1/5～1/6","(B) 配戴全口義齒的病人，其咀嚼效率較低，但若咀嚼效率達 25%左右即可符合生理需求","(C) 全口自然牙者之咀嚼及吞嚥時，一整天內的咬合接觸總時間約 35 分鐘","(D) 全口自然牙者之下顎牙周膜承載區，約為下顎無牙義齒承載區的 4 倍"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"病人原先僅以下顎少數自然前牙長期對咬上顎全口活動義齒，後來拔除下顎剩餘前牙並製作了新的下顎全活動 義齒後，出現適應困難的情形，下列敘述何者正確？①新下顎全口活動義齒限制舌頭的形狀可能導致病人不適 應 ②應常配戴下顎全活動義齒使舌頭重新適應活動範圍 ③下顎後牙殘嵴感受到咀嚼時傳導的壓力需要適應 ④病人缺乏動機可能會延長適應期 ⑤上顎義齒穩定度改變導致病人不適應","options":["(A) ①②③④⑤","(B) 僅①②③④","(C) 僅③④⑤","(D) 僅②⑤"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-3","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"關於全口義齒最終印模所使用的材料，下列敘述何者錯誤？","options":["(A) 金屬氧化物類印模材的流動性較彈性印模材差","(B) 金屬氧化物類印模材一般不可使用於有嚴重倒凹之殘嵴","(C) 彈性印模材通常在印模托內須預留印模材之空間（spacer）","(D) 使用彈性印模材取模後，如果發現有微小孔洞，可使用蠟進行修補"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-4","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"關於臼齒後墊（retromolar pad）的敘述，下列何者錯誤？","options":["(A) 被視為下顎全口活動義齒主要咬合壓力承載區之一","(B) 表面皆覆蓋角質化黏膜","(C) 製作下顎全口活動義齒時需要覆蓋臼齒後墊","(D) 為頰棚（buccal shelf）的遠心緣界線"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-5","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"全口義齒的咬合垂直距離（occlusal vertical dimension），通常以生理靜止位置（physiological rest position）減去 2 至 4 mm 來決定，這是以那一顆牙齒為座標的說法？","options":["(A) 第一小臼齒","(B) 第一大臼齒","(C) 中門齒","(D) 犬齒"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-6","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"下列何者不是舌側化咬合（lingualized articulation）的優點？","options":["(A) 上顎小臼齒的外觀較平面式（monoplane）自然","(B) 咀嚼效率較平面式（monoplane）咬合好","(C) 咬合調整的步驟較平衡式（balanced）咬合簡單","(D) 上下顎義齒的咬合接觸較平面式（monoplane）緊密"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-7","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"有關全口義齒上顎正中門齒區拔牙後的牙弓與齒槽嵴的敘述，下列何者錯誤？","options":["(A) 齒槽頰側的骨頭吸收量較多且較迅速","(B) 齒槽骨吸收的方向是往上（upward）及往外（outward）","(C) 門齒乳突在上顎的位置大致穩定，可作為全口義齒門齒排列時的參考","(D) 若上顎為單顎全口義齒（single denture），且下顎前牙仍為自然齒，上顎前牙區常出現鬆贅齒齦嵴 （flabby ridge）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-8","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"有關全口義齒之舌側咬合模式（lingualized occlusion）的敘述，下列何者正確？","options":["(A) 不適用於下顎較後縮的患者","(B) 不適用於覆蓋式義齒（overdenture）","(C) 下顎可選擇零度人工牙","(D) 咬合調整相對困難與耗時"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-9","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"義齒熱聚式樹脂（heat-activated PMMA）的粉與液體經過混合後，在那一階段最適合置入包埋盒中進行填充 （packing）？","options":["(A) 砂狀期（sandy stage）","(B) 絲狀期（sticky stage）","(C) 糰狀期（dough stage）","(D) 硬化期（stiff stage）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-10","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"病人就診時，口內仍有些許殘存齒，下列拔牙的理由何者可能違反醫學倫理？","options":["(A) 殘存齒皆有嚴重齲蝕","(B) 因肢體不便，無法潔牙","(C) 為了符合申請政府全口義齒製作補助的條件","(D) 殘存齒會影響義齒之製作"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-11","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"上顎全口義齒選擇使用金屬床（metal denture base）時，是基於那些性質的考慮？①導熱性 ②機械性質 ③義齒體積 ④製作費用 ⑤義齒換底墊（reline）方便性","options":["(A) 僅①②","(B) ①②③","(C) 僅③④⑤","(D) ②③④⑤"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-12","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"進行下顎全口義齒顎舌骨肌後窩（retromylohyoid fossa）邊緣成形（border molding）時，牙醫師應引導 病人做何種動作？①舌頭舔下嘴唇 ②舌頭舔上嘴唇 ③舌頭舔雙側臉頰 ④舌頭舔硬腭","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-13","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"有關記錄基底（record base）及咬合堤（occlusion rim）之製作，下列敘述何者錯誤？","options":["(A) 記錄基底必須用基底板蠟（baseplate wax）製作，以獲得堅固且穩定之基底","(B) 咬合堤以使用基底板蠟製作較為方便、合適","(C) 使用樹脂製作記錄基底，需先將模型上之倒凹作封平，因而可能較鬆","(D) 以樹脂製作記錄基底時，宜置入壓力鍋（pressure cooker）內聚合"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-14","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"關於全口義齒製作時咬合器使用的敘述，下列何者錯誤？","options":["(A) 咬合器通常無法完全模擬病人的咀嚼運動","(B) 咬合器的選擇跟選用的牙齒形態及咬合理論有關","(C) 義齒製作時，以零度牙排牙而不提供平衡咬合，不能使用僅提供樞紐（hinge）開閉運動的簡易型咬合器","(D) 即使採用全調節咬合器排牙，完成的義齒仍需咬合調整"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-15","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"製作全口義齒時，關於記錄上、下顎水平顎間關係的敘述，下列何者錯誤？","options":["(A) 可重複性最高的顎間關係必然是生理與功能上最好的顎間關係","(B) 穩定記錄基底（record base）是哥德式描記法（Gothic arch tracing）取得正確顎間關係必要條件","(C) 上、下顎咬合蠟堤（occlusal wax rim）接觸狀態會影響取出顎間關係的正確性","(D) 對神經肌肉控制不好的病人，可能無法記錄出可重複的顎間關係"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-16","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"當全口活動義齒的病人下顎容易亂動、取不到穩定的咬合紀錄時，下列何種樹脂牙組合最適合？","options":["(A) 上顎 20 度牙＋下顎 20 度牙","(B) 上顎 20 度牙＋下顎零度牙","(C) 上顎與下顎都是零度牙","(D) 上顎零度牙＋下顎 20 度牙"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"當配戴全口義齒的病人，抱怨張大嘴巴要咬三明治的時候，上顎全口義齒容易有鬆脫的現象，此現象與下列 何種構造最相關？","options":["(A) 振動線（vibrating line）","(B) 喙狀突（coronoid process）","(C) 口輪匝肌（orbicularis oris）","(D) 咬肌（masseter muscle）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-18","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"當配戴全口義齒的病人，被診斷為白色念珠菌感染的口腔炎（Candida-associated denture stomatitis）， 下列何項處理正確？①服用抗黴菌藥物 ②加強病人口腔衛生 ③儘量減少配戴義齒 ④保持義齒乾燥","options":["(A) ①②③④","(B) 僅①②③","(C) 僅①②","(D) 僅④"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-19","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"有關全口活動義齒的衛生清潔，下列敘述何者錯誤？","options":["(A) 牙菌斑要清除，因為它是義齒性口炎（denture stomatitis）、炎性乳頭狀增生（inflammatory papillary hyperplasia）、慢性念珠菌病（chronic candidiasis）和口臭的致病因","(B) 每次進食後，需將口內與義齒沖洗乾淨","(C) 用軟毛牙刷及牙膏清潔義齒","(D) 每天用軟毛牙刷清潔殘嵴的黏膜表面還有舌頭的背部表面（dorsal surface）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-20","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"有關上顎單顎全口義齒（single complete denture）之製作，下列敘述何者最正確？","options":["(A) 因下顎對咬牙存在，咬合平面（occlusal plane）大致決定，故面弓轉移（facebow transfer）非必要","(B) 下顎之齒列常需做適當之咬合調整，以去除上顎排牙之咬合干擾","(C) 下顎若雙側大臼齒（molar）缺失，可採短化牙弓（shortened dental arch）咬合設計，以減少裝戴下顎可 撤式局部義齒之異物感","(D) 上顎單顎全口義齒於後牙區之排牙，必要時要排列成錯咬（crossbite），如此則不需達成平衡咬合 （balanced occlusion）之排列"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-21","subject":"ya5","topic":"植牙贋復","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"病人上顎全口無牙，醫師在考量以植體贋復物來重建時，下列何者不是最主要的考慮因素？","options":["(A) 說話空間（speaking space）","(B) 前牙切緣於靜止及微笑時露出之程度","(C) 年齡及性別","(D) 齒槽骨之吸收狀況"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-22","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"全口活動義齒使用熱聚式樹脂（heat-activated PMMA）於包埋煮聚（processing）的過程中若操作不當，可 能會導致義齒基底（denture base）裡產生氣泡（void）。當置入包埋盒的樹脂量不足時，最可能產生下列 何種結果？","options":["(A) 氣泡出現在義齒局部較厚處","(B) 氣泡形態為均勻圓孔","(C) 氣泡數量少","(D) 整個義齒的顏色看起來較淺且不透明"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-23","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"可撤式局部義齒長型咬合面鈎靠座（extended occlusal rest seat）的敘述，下列何者錯誤？","options":["(A) 適用於 Kennedy class II modification 1 與 Kennedy class III 中，最後面支柱牙為近心傾斜之大臼齒 時","(B) 此咬合面鈎靠座不能超過支柱牙咬合面近遠心的 1/2","(C) 此咬合面鈎靠座的頰舌寬度為支柱牙咬合面頰舌寬度的 1/3","(D) 此設計可以減少支柱牙往前傾斜，並將力量傳達至支柱牙長軸"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-24","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"使用單腭帶（single palatal strap）為可撤式局部義齒的主連接體（major connector）時，下列敘述何者 錯誤？","options":["(A) 適用於長徑距牙齒支持的雙側缺牙區","(B) 前後兩側的厚度應儘量薄避免干擾舌頭及說話","(C) 從矢狀切面來看中間部分可以輕微隆起（slight elevation）","(D) 特別適用於後牙缺失 Kennedy class III 的義齒設計"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-25","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"關於可撤式局部義齒主連接體（major connector）下顎連續槓（mandibular continuous bar）的敘述，下 列何者正確？①適用於下顎前牙往舌側較嚴重傾斜（lingual tilt）的病人 ②需設計成薄且窄（thin and narrow）的金屬帶（metal strap），其上下緣寬度約為 3 mm ③可用於下顎前牙牙間隙（diastema）大的 病人 ④金屬帶（metal strap）由中間往上下緣漸漸變薄（taper）","options":["(A) 僅①②","(B) 僅②④","(C) ①③④","(D) ①②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-26","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"下列可撤式局部義齒的固位牙鈎（retentive clasp），那一種最常被使用在朝近心側傾斜的大臼齒？","options":["(A) 環鈎（ring clasp）","(B) 楔隙牙鈎（embrasure clasp）","(C) C-型牙鈎（C-shape clasp）","(D) 反向環狀牙鈎（reverse circlet clasp）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-27","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"關於可撤式局部義齒支柱牙高隆線（height of contour）修形的敘述，下列何者錯誤？","options":["(A) 環周型牙鈎的起源（origin of circumferential clasp）在牙齦三分之一中間三分之一的連接處","(B) 固位性牙鈎的終端（retentive clasp terminals）在牙冠的牙齦三分之一處","(C) 拮抗鈎臂（reciprocal clasp）不低於牙冠中間三分之一及高隆線之上","(D) 降低高隆線可獲得較好的機械優勢及美觀"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-28","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"關於如何確保遠伸性可撤式局部義齒（distal extension removable partial denture）穩定性的敘述，下 列何者錯誤？","options":["(A) 不可只考量對咬牙咬合面及切緣面有和諧的關係","(B) 須考慮牙齒與殘嵴間的關係","(C) 下顎遠伸性可撤式局部義齒應雙側平衡性咬合（bilateral balanced occlusion）","(D) 將下顎頰側咬頭排列於可將壓力傳導至頰棚（buccal shelf）區之位置"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-115-1-29","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"關於可撤式局部義齒換底墊（reline）的理由，下列何者錯誤？","options":["(A) 當失去軟組織支持，導致剩餘的自然牙與對咬牙間的咬合接觸變重，而承受較大的咬合力量","(B) 對咬自然牙的垂直向突出（extrusion），咬合檢查仍有接觸，但看不出遠伸性基底已下沉","(C) 下壓遠伸性義齒床會繞著支點線旋轉，且間接固位體（indirect retainer）離開其鈎座（rest seat）","(D) 義齒之人工牙有相當程度的咬耗"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-30","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"有關初次使用可撤式局部義齒之敘述，下列何者錯誤？","options":["(A) 當下顎可撤式局部義齒穩定度不足時，須在遠心舌側處延伸基底邊緣並增加其厚度","(B) 舌頭通常較能接受平滑而不厚的義齒基底外形","(C) 戴上可撤式局部義齒後的發音問題，一般可在數天後改善","(D) 告知病人，清洗義齒時不要掉到地上，導致斷裂或變形"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-31","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"可撤式局部義齒金屬支架鑄造完成，經修形噴砂處理後，須以下列何種酸做電解處理？","options":["(A) 85%硫酸","(B) 85%磷酸","(C) 85%鹽酸","(D) 85%硝酸"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"有關遠伸性可撤式局部義齒（distal extension removable partial denture）設計，若將鈎靠（rest）放 置於支柱牙（abutment teeth）遠心側，當咬合力作用於殘嵴時，下列敘述何者正確？","options":["(A) 第一類槓桿作用力","(B) 第二類槓桿作用力","(C) 第三類槓桿作用力","(D) 基底延伸只需殘嵴的 2/3"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-115-1-33","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"當上顎僅剩少數前牙，在不改變咬合垂直高度的情況，下列何者不適用舌面隆凸鈎座（cingulum rest seat）？①舌面隆凸處有明顯的咬合磨耗面（wear facet） ②下顎為 Kennedy class IV 缺牙 ③下顎前牙 咬到門齒乳頭（incisive papilla） ④下顎為 Kennedy class III 缺牙","options":["(A) ①②③④","(B) 僅①②③","(C) 僅②④","(D) 僅①③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-34","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"關於遠伸性局部義齒（distal extension partial denture）支架的穩定作用構件（stabilizing components），下列何者正確？①引導面（guiding plane） ②所有接觸垂直牙面（vertical tooth surfaces）的小連接體（minor connectors） ③拮抗鈎臂（reciprocal clasp arm） ④間接固位體 （indirect retainer）","options":["(A) ①②③④","(B) 僅①②④","(C) 僅①③④","(D) 僅②③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-35","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"關於可撤式局部義齒上顎主連接體（major connector）設計與製作的敘述，下列何者最適當？","options":["(A) 上顎主連接體通常使用單腭槓（single palatal bar）","(B) 主連接體之後緣應儘可能往後延伸","(C) 應該於上顎主模型（master cast）上放置寬度與深度為 0.5 mm 之珠狀緣飾（beading）","(D) 單腭帶（single palatal strap）的設計為了發音及舒適度，厚度需越薄越好"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-36","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"當病患下顎牙弓雙側牙齒往舌側傾移，在製作可撤式局部義齒時，下列敘述何者最適當？","options":["(A) 主連接體容易與舌側組織分離","(B) 不容易形成食物堆積","(C) 支柱牙舌側面外形再造通常無法解決問題","(D) 矯正後再做可撤式局部義齒是絕對不當的選擇"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"關於可撤式局部義齒於完好牙釉質的支柱牙修形（abutment preparations），其施行步驟下列何者最適當？ ①平行置放途徑（path of placement）做鄰接面（proximal surface）修形 ②沿著支柱牙長軸做咬合鈎靠 （occlusal rest）修形 ③使用不可逆性水凝膠（irreversible hydrocolloid）印模，並用快速硬化石膏 灌製模型，再放回析量器（surveyor）評估 ④修改牙齒的外形以降低高隆線（height of contour）","options":["(A) ①②③④","(B) ④①②③","(C) ①④③②","(D) ②④①③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-38","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"關於牙齒喪失的敘述，下列何者最適當？","options":["(A) 通常下顎牙齒先於上顎牙齒脫落","(B) 通常口內最後剩下的牙齒是上顎犬齒","(C) 通常前牙先於後牙喪失","(D) 通常口內狀況是上顎無牙與下顎前牙相對"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-39","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"依下圖牙齒分布狀況，屬可撤式局部義齒甘迺迪分類系統（Kennedy classification System）何分類？① Kennedy class II ②Kennedy class IV ③modification 3 ④modification 2","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":1,"image":"ya5-115-1-39.jpeg","clinical_level":"重點"},{"id":"ya5-115-1-40","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"關於水凝膠（hydrocolloid）印模材的敘述，下列何者正確？①相較於橡膠印模材（rubber base impression materials），不可逆性水凝膠（irreversible hydrocolloid）印模材有較低的抗撕裂強度 （tear strength） ②水凝膠類印模材以 2%酸性戊二醛（acid glutaraldehyde）消毒，存放於 100%濕度 中，一小時內倒模是可接受的 ③不可逆性水凝膠印模材可作為可撤式局部義齒的主模型印模材 ④不可逆 性水凝膠印模材可以很容易操作材料邊緣的寬度及長度","options":["(A) 僅①③","(B) ①②③","(C) ②④","(D) ①③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-41","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"關於可撤式局部義齒印模材的敘述，下列何者錯誤？","options":["(A) 印模蠟（impression wax）屬於熱塑性（thermoplastic）的印模材，可用於記錄殘嵴的功能性支撐形態 （functional supporting form）","(B) 使用橡膠基底（rubber base）印模材印模後，至少應等 1 小時，俟其復位回彈後再進行倒模","(C) 氧化鋅丁香油酚印模劑（zinc oxide-eugenol impression paste）屬於剛硬印模材（rigid impression material）","(D) 水凝膠（hydrocolloids）印模材的凝析（syneresis）現象是造成石膏模型表面產生模糊的原因之一"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-42","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"上顎是 Kennedy class I 可撤式局部義齒，下顎是自然牙，關於其義齒咬合製作的敘述，下列何者錯誤？","options":["(A) 正中應有咬合接觸","(B) 工作側應有咬合接觸","(C) 平衡側不應有咬合接觸","(D) 前突運動（protrusion）時後牙可以沒有咬合接觸"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"針對各項配戴可撤式局部義齒的患者在回診時的主訴，下列何者為相對應的可能之診斷？①上顎義齒的後緣 太厚或是過度延伸，都可能會造成病人出現嘔吐反射（gagging reflex） ②上下顎人工牙齒排列的水平覆 蓋（horizontal overjet）過大，易造成咬頰（cheek biting）的現象 ③咬合垂直高度過高，可能會造成 吞嚥困難 ④說話時牙齒會碰撞，可能是因為咬合垂直距離太小 ⑤上顎單腭帶（single palatal strap） 主連接體的位置太前方，可能會影響病人發音","options":["(A) 僅①④","(B) 僅①③⑤","(C) 僅②③⑤","(D) ①②③④⑤"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"關於可撤式局部義齒分模式四層包埋法處理，去蠟後樹脂填壓是介於下列那兩層之間進行？","options":["(A) 第一層與第二層","(B) 第二層與第三層","(C) 第三層與第四層","(D) 第四層與包埋盒"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"關於固持／抗力性（resistance）的敘述，下列何者錯誤？","options":["(A) 箱（box）的頰壁和舌壁必須與牙髓壁（pulpal wall）呈約 90 度","(B) V 形的溝（groove）相較於有明確舌壁的溝，對舌向位移的阻力大","(C) 咬合牙齦（occlusogingival）高度對固持／抗力性是一項重要因子","(D) 在直徑較小的牙齒，咬合牙齦（occlusogingival）高度雖短，仍可能提供足夠的固持／抗力性"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"下列何種義齒完成線（finish line）較容易在牙齒上出現缺乏支持的牙釉質（unsupported enamel）？","options":["(A) knife edge","(B) deep chamfer","(C) shoulder","(D) radial shoulder with bevel"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-47","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"關於使用客製前牙導引台（custom anterior guide table），下列敘述何者錯誤？","options":["(A) 適用於製作上顎前牙的固定補綴物","(B) 以患者原本的牙齒或是現有的暫時固定義齒為參考","(C) 必須要先使用面弓轉移（facebow transfer）上顎的關係","(D) 製作導引台時咬合器上的門齒導柱（incisal guide pin）要緊貼導引台"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-48","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"傳統的加成式矽膠（addition silicone）在聚合反應後會有氫氣的產生，加入何種成分可吸附氫氣以減少誤 差？","options":["(A) 鈣（calcium）","(B) 鈉（sodium）","(C) 鉀（potassium）","(D) 鈀（palladium）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-49","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"承受正常咬壓的情況下，用為固定局部義齒的支柱牙，其可接受的最高牙冠／牙根比（crown-root ratio） 為何？","options":["(A) 2：1","(B) 1：1","(C) 2：3","(D) 1：2"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-50","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"上顎前牙缺失，且非常注重美觀的患者，何種橋體設計最能符合臨床需求？","options":["(A) 嵴疊形（ridge lap）","(B) 鞍狀（saddle）","(C) 卵圓形（ovate）","(D) 圓錐形（conical）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-51","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第1次第51題","year":115,"session":1,"number":51,"question":"金屬瓷修復體（metal-ceramic restorations）在烤瓷前，須先氧化鑄體合金，此過程稱為何者？①條件化 燒烤（conditioning bake） ②除氣（degassing） ③氧化還原（oxidization-reduction）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-52","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第1次第52題","year":115,"session":1,"number":52,"question":"關於前牙美觀考量的敘述，下列何者錯誤？","options":["(A) 微笑線應垂直中線，平行瞳間線（interpupillary line）","(B) 隨年紀增長，微笑時上顎前牙露出之長度漸減","(C) 越往齒列遠心側，鄰間接觸區（interproximal contact）越靠近牙齦","(D) 隨著年紀越大，切緣楔隙（incisal embrasure）漸大"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-53","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第53題","year":115,"session":1,"number":53,"question":"對於牙科用黏合劑（luting cement）的敘述，下列何者錯誤？","options":["(A) 薄膜厚度（film thickness）：磷酸鋅＜黏著樹脂","(B) 凝固時間（setting time）：玻璃離子體＜樹脂離子體","(C) 抗壓強度（compressive strength）：聚羧酸鹽＜自酸蝕黏著樹脂","(D) 牙髓刺激（pulp irritation）：磷酸鋅＜玻璃離子體"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-54","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第54題","year":115,"session":1,"number":54,"question":"下列那一種韌帶會限制下顎的前突運動？","options":["(A) 莖突下顎韌帶（stylomandibular ligament）","(B) 蝶下顎韌帶（sphenomandibular ligament）","(C) 表淺的顳顎韌帶（superficial temporomandibular ligament）","(D) 內側的顳顎韌帶（medial temporomandibular ligament）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-55","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第1次第55題","year":115,"session":1,"number":55,"question":"下列降低口水分泌的藥物中，何者不屬於抗膽鹼能類（anticholinergics）藥物？","options":["(A) Clonidine","(B) Glycopyrrolate","(C) Dicyclomine","(D) Propantheline"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-56","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第1次第56題","year":115,"session":1,"number":56,"question":"關於根管治療完成後牙齒製作鑄造根柱（cast post）的敘述，下列何者正確？","options":["(A) 男性患者根管治療完成並製作鑄造根柱後之牙齒，失敗率高於女性","(B) 年輕患者根管治療完成並製作鑄造根柱後之牙齒，失敗率高於 60 歲以上之患者","(C) 上顎牙齒根管治療完成並製作鑄造根柱後之失敗率低於下顎牙齒","(D) 鑄造根柱的直徑越粗可以減少牙齒斷裂發生的機會"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-57","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第1次第57題","year":115,"session":1,"number":57,"question":"製作義齒時，關於牙周預後，下列因素何者較不需要考慮？","options":["(A) 牙根解剖形態","(B) 牙齒動搖度","(C) 年齡","(D) 顎間關係之類型"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-58","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第1次第58題","year":115,"session":1,"number":58,"question":"若選用瓷金屬融合冠作為析量冠（surveyed crown），咬合鈎靠座（occlusal rest seat）的位置應與金屬 －瓷交界面（metal-porcelain junction）至少有多少距離才足夠？","options":["(A) 0.25 mm","(B) 0.5 mm","(C) 1 mm","(D) 2 mm"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第1次第59題","year":115,"session":1,"number":59,"question":"暫時牙橋（provisional bridge）移除後，發現鄰接面牙齦有發炎現象，下列何者不是形成此現象的主要原 因？","options":["(A) 邊緣密合度不良","(B) 連接部（connector）的外形過大（overcontour）","(C) 多餘之黏合劑殘留","(D) 咬合調整不良"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-60","subject":"ya5","topic":"植牙贋復","meta":"115年第1次第60題","year":115,"session":1,"number":60,"question":"關於人工植體擺放的原則，下列何者錯誤？","options":["(A) 以 4 mm × 10 mm 植體為例，置放區須具有 10 mm 垂直高度及 6 mm 水平寬度之骨量","(B) 頰舌側需至少各有 1 mm 厚的骨頭包覆","(C) 若同時植入兩支人工植體，植體間應至少相距 3 mm","(D) 與頦孔（mental foramen）距離至少 2 mm"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-61","subject":"ya5","topic":"植牙贋復","meta":"115年第1次第61題","year":115,"session":1,"number":61,"question":"關於 implant screw preload 之敘述，下列何者正確？","options":["(A) 是指 abutment screw 因轉動拉長回彈與植體內部螺紋夾緊之力","(B) 人工植牙支柱螺絲之 preload 一般設定多在 40～50 Ncm 之間","(C) preload 提供植體在骨內的初期穩定度","(D) preload 力量可以長期不變留存在螺紋之間"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-62","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第1次第62題","year":115,"session":1,"number":62,"question":"關於中心關係（CR）記錄的取得，下列敘述何者錯誤？","options":["(A) CR 記錄提供上下顎間關係的終軸位置，此位置開口閉口將會是單純的旋轉運動","(B) CR 位置在上下顎間關係的關節髁與關節盤最薄處契合，此位置與牙齒的接觸無關","(C) 咬合器診斷模型以 CR 來置位，相較於最大咬頭嵌合（MI）位置可提供過早牙齒接觸的診斷","(D) 不論使用那種面弓，咬合記錄應越薄越好，並應稍微穿透"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-63","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第63題","year":115,"session":1,"number":63,"question":"使用藻膠類不可逆性水凝膠（alginate irreversible hydrocolloids）印製診斷模型（diagnostic casts），下列敘述何者最適當？","options":["(A) 藻膠材料凝膠化（gelation）後，2 至 3 分鐘內必須從口中取出","(B) 從口中取下的印模（impression）要直接拿去倒模以避免材料脫水變形","(C) 如果無法立刻倒模，可以使用濕紙巾包覆，等到有空再去倒模","(D) 為取得完整的模型，不可切除印模的邊緣"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-64","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第1次第64題","year":115,"session":1,"number":64,"question":"關於牙冠過度輪廓（overcontour）和輪廓不足（undercontour）與牙齦發炎關係的敘述，下列何者正確？","options":["(A) 過度輪廓和輪廓不足都會引起明顯牙齦發炎","(B) 過度輪廓比較會引起明顯牙齦發炎","(C) 過度輪廓比較不會引起明顯牙齦發炎","(D) 過度輪廓和輪廓不足都不會引起明顯牙齦發炎"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-65","subject":"ya5","topic":"牙科材料學","meta":"115年第1次第65題","year":115,"session":1,"number":65,"question":"關於助熔劑（flux）和抗熔劑（antiflux），下列敘述何者正確？①助熔劑會增加銲劑對金屬表面的潤濕性 （wetting） ②助熔劑會增加氧化物的形成，以利焊接 ③石墨是抗熔劑，會限制銲劑的流動範圍 ④助熔 劑與瓷接觸可能會造成瓷變色","options":["(A) 僅①④","(B) 僅①③④","(C) 僅①②④","(D) ①②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-66","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第1次第66題","year":115,"session":1,"number":66,"question":"關於蠟型包埋前的處理，下列敘述何者正確？","options":["(A) 建議在蠟型較薄的部位放置小的輔助性鑄道","(B) 為了避免膨脹，鑄造環內部應放置石棉紙","(C) 無環包埋技巧適用於低熔點的金屬","(D) 鑄道和蠟型的接觸區域越寬越好"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-67","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第1次第67題","year":115,"session":1,"number":67,"question":"關於人類咀嚼力（force of mastication）的敘述，下列何者錯誤？","options":["(A) 平均而言，成年男性咬合力約為成年女性四倍","(B) 咬合力並非固定不變，可因練習而增強","(C) 咀嚼時，最大的力量分布於第一大臼齒區","(D) 咀嚼時咬合力大小也與食物性質或肌肉疼痛有關"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-68","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第1次第68題","year":115,"session":1,"number":68,"question":"吞嚥過程中，食團到達軟腭之後，下列敘述何者最不正確？","options":["(A) 會誘發咽收縮，將食團推入食道","(B) 軟腭將下降以防止食團進入鼻腔","(C) 舌骨及喉上升以防止食團進入氣道","(D) 食道上括約肌會自發性啟動，經由蠕動將食團推向胃"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-69","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第1次第69題","year":115,"session":1,"number":69,"question":"關於顎反射，下列敘述何者錯誤？","options":["(A) 閉顎反射向心輸入的神經元位於中樞神經系統內","(B) 開顎反射向心輸入的神經元位於三叉神經結內","(C) 咬到舌頭時會產生開顎反射（jaw-opening reflex）","(D) 開顎反射為單突觸反射（monosynaptic reflex）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-70","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第70題","year":115,"session":1,"number":70,"question":"有關中心關係（centric relation）與最大嵌合位（maximum intercuspation）之敘述，下列何者錯誤？","options":["(A) 咀嚼運動的軌跡大部分發生於最大嵌合位附近","(B) 中心關係通常位於最大嵌合位之後","(C) 中心關係接觸與下顎最大嵌合位常常不一致","(D) 中心關係會受牙齒的型態和排列影響"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-71","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第1次第71題","year":115,"session":1,"number":71,"question":"進行咬合治療時，當顳顎關節位於中心關係（centric relation），且下顎臼齒中心咬頭碰觸到上顎中心咬 頭內側斜面三等份的外 1/3 時（如下圖），下列何者為首要治療選項？","options":["(A) 選擇性修磨（selective grinding）","(B) 固定贋復（fixed prosthesis）","(C) 矯正治療（orthodontic treatment）","(D) 正顎手術（orthognathic surgery）"],"answer":2,"image":"ya5-115-1-71.jpeg","clinical_level":"一般"},{"id":"ya5-115-1-72","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第72題","year":115,"session":1,"number":72,"question":"關於咬合治療，下列何者錯誤？","options":["(A) 患者口內有咬合干擾，應立即進行選擇性修磨","(B) 矯正治療是一種不可逆的咬合治療","(C) 固定義齒的製作是一種不可逆的咬合治療","(D) 選擇性修磨是一種不可逆的咬合治療"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-73","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第73題","year":115,"session":1,"number":73,"question":"下列何種牙齒形態，比較不會出現明顯的下顎側向運動之本奈氏側移？","options":["(A) 較寬的後牙咬窩","(B) 較陡的後牙咬頭角度","(C) 較平緩的前牙舌側面","(D) 較不明顯的前牙兩側嵴"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-74","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第74題","year":115,"session":1,"number":74,"question":"關於下顎開閉口的敘述，下列何者錯誤？","options":["(A) 最大咬頭嵌合位置，於立位與臥位時相同","(B) 俯位閉合時，下顎牙先觸及上顎牙咬頭之近心側","(C) 後退咬合位置在臥位時較立位時為後","(D) 關節運動受阻擋時，開口路徑即向被阻擋的一側偏斜"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-75","subject":"ya5","topic":"咬合學基礎","meta":"115年第1次第75題","year":115,"session":1,"number":75,"question":"有關前方導引（anterior guidance）之敘述，下列何者正確？","options":["(A) 建立後牙咬合面形態時，前方導引會影響後牙咬頭高度","(B) 水平覆蓋（horizontal overlap）越大者，前方導引角度亦較大","(C) 垂直覆蓋（vertical overlap）越大者，前方導引角度較小","(D) 水平覆蓋（horizontal overlap）與前方導引角度無關"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-76","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第1次第76題","year":115,"session":1,"number":76,"question":"探討社會精神因素（psychosocial factors）與顳顎關節障礙致病因研究中，下列那項較難確認？","options":["(A) 負面情緒（negative emotion）","(B) 焦慮（anxiety）","(C) 強迫症（obsessive-compulsive disorder）","(D) 裝病（malingering）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-77","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第1次第77題","year":115,"session":1,"number":77,"question":"下列關於顳顎障礙症病因的敘述，何者錯誤？","options":["(A) 顳顎障礙症為多因性的","(B) 神經肌肉症狀與顳顎關節症狀之病因學完全不同","(C) 牙科治療時的長時間張口，可能造成顳顎關節的急性傷害","(D) 眾多的個體間差異變數，會導致病人對症狀的感受產生極大的差異"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya5-115-1-78","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第1次第78題","year":115,"session":1,"number":78,"question":"下列何者不是以咬合板治療顳顎障礙症的目的？","options":["(A) 提供上、下顎一個穩定的骨間關係","(B) 保護牙齒不受磨耗","(C) 阻斷過早的咬合接觸","(D) 提升咀嚼肌施力的能力"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-1-79","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第1次第79題","year":115,"session":1,"number":79,"question":"關於使用前置位咬合板（anterior position splint）治療可復性關節盤移位（disc displacement with reduction），下列敘述何者正確？①藉由下顎往前重新建立一個正常的關節盤與髁頭關係 ②臨床上以臉外 型美觀程度決定下顎往前突出的量 ③在改善關節聲響方面，與穩定形咬合板（stabilization splint）相 當 ④減少對關節盤後組織的負荷（loading）","options":["(A) ①②","(B) 僅①④","(C) ②③","(D) ①③④"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya5-115-1-80","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第1次第80題","year":115,"session":1,"number":80,"question":"有關磁共振造影術（magnetic resonance imaging, MRI）的敘述，下列何者正確？","options":["(A) 利用強烈磁場，主要改變氮離子能量而成像","(B) 相較於椎束射線電腦斷層攝影（CBCT），磁共振造影對於骨質的觀察更佳","(C) 不會形成對組織造成損害的放射線","(D) 設備價錢相對便宜，一般牙科診所也可使用"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-1","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"一個中度吸收的下顎無牙嵴，其承載義齒咬力的面積約為12.25 cm 2，為單顎自然齒列牙周膜表面積之多少倍？","options":["(A) 3/4","(B) 1/2","(C) 1/3","(D) 1/4"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-2","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"評估患者正在使用的全口義齒時，牙醫師應獲取那些資訊？①義齒與黏膜間的密合度 ②患者對現有義齒的滿意狀況 ③義齒邊緣長度是否適當 ④咬合面磨損程度 ⑤咬合垂直高度是否適當 ⑥人工牙與殘嵴的相對位置","options":["(A) 僅①③⑤⑥","(B) 僅②④⑥","(C) 僅①②③④⑤","(D) ①②③④⑤⑥"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-3","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"關於上顎粗隆（maxillary tuberosity）的敘述，下列何者錯誤？","options":["(A) 為上顎全口活動義齒主要咬合壓力承載區之一","(B) 內含緻密纖維的結締組織（dense fibrous connective tissue）","(C) 通常不會伴隨喪失對咬牙的上顎牙齒一起向下移動及生長","(D) 此處的頰側產生很大的倒凹時，需視情況評估是否手術移除"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-4","subject":"ya5","topic":"牙科材料學","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"全口義齒製作時，若排牙空間不足，下列何種基底材料最適合？","options":["(A) 硬基底板蠟（hard baseplate wax）","(B) 光聚式樹脂基底","(C) 自聚式樹脂基底","(D) 熱聚式樹脂基底"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-5","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"關於用於全口義齒人工後牙的敘述，下列何者錯誤？","options":["(A) 現今多使用壓克力樹脂作為人工後牙的主要材料","(B) 現今使用人工後牙的頰舌徑較自然牙狹窄","(C) 較窄的人工後牙咬合面（occlusal table），會使咀嚼效率下降","(D) 較窄的人工後牙咬合面（occlusal table），減少義齒的位移"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-6","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"病人配戴新製作的全口義齒，抱怨想發/t /音的時候會發成/d /音，最有可能是下列何種狀況？","options":["(A) 上顎前牙排列太長","(B) 上顎前牙排列太短","(C) 上顎前牙排列太腭側","(D) 上顎前牙排列太唇側"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-7","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"當配戴全口義齒的病人，抱怨唱歌的時候容易有上顎義齒鬆脫的問題，最可能是下列何種狀況？","options":["(A) 上顎義齒的後腭封（posterior palatal seal）後方延伸太長","(B) 垂直咬合高度（vertical dimension of occlusion）太低","(C) 沒有達到雙側平衡咬合（bilateral balanced occlusion）","(D) 後牙義齒排列高於咬合平面（occlusal plane）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-8","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"關於過渡性即裝全口義齒（interim immediate complete dentures）的敘述，下列何者正確？①可利用現有的牙齒或可撤式局部義齒來修改製成 ②印模通常以常備模托（stock tray）與藻膠（alginate）印模便可 ③拔牙後即可裝戴義齒，有助傷口之止血與癒合 ④此義齒無法長期使用，之後仍須依傳統製作流程製作全口義齒","options":["(A) 僅①④","(B) 僅②③","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-9","subject":"ya5","topic":"植牙贋復","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"使用下列何種裝置於植體覆蓋式義齒不具應力緩衝（stress-breaking）之效果？","options":["(A) 單一磁性（magnetic）支柱牙","(B) 蛋型道爾得槓（egg-shaped Dolder bar）","(C) 球狀附連體（ball attachments）","(D) 套疊式鑄造牙冠（cast telescopic copings）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-10","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"下列何者為活動義齒發生斷裂的危險因子？①患者有手容易抖動的疾病 ②採用舌側化咬合（lingualized occlusion） ③採用平衡咬合（balanced occlusion） ④齒槽骨吸收 ⑤繫帶（frenum）範圍過大或太靠近齒槽嵴上方 ⑥大範圍的隆凸（torus）","options":["(A) ①②③④⑤⑥","(B) 僅①④⑤⑥","(C) 僅②④⑤","(D) 僅①③⑥"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-11","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"完成煮聚的全口義齒需技工室重置位（laboratory remounting），最主要是因為下列何種材料的關係？","options":["(A) 蠟","(B) 印模材","(C) 石膏","(D) 樹脂"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-12","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"在決定全口義齒前牙排列時，下列敘述何者最不適當？","options":["(A) 首先要聆聽病人對於美觀的主要訴求，如：牙齒的形狀或大小等","(B) 病人對於義齒的美觀無主觀想法時，牙醫師可適時介入討論","(C) 應以病人意見為主，無須參考病人親屬的意見","(D) 可交給受過專業比色訓練的牙醫師來建議全口義齒的排牙顏色，以滿足病人美觀的需求"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-13","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"下列何者屬於組合症候群（combination syndrome）患者的口內表徵？①上顎粗隆（tuberosity）嚴重萎縮 ②上顎前牙區嚴重萎縮 ③下顎前牙區嚴重萎縮 ④下顎後牙區嚴重萎縮 ⑤垂直距離（vertical dimension）不足 ⑥上顎炎性乳頭狀增生（inflammatory papillary hyperplasia）","options":["(A) ①②④⑤","(B) ②④⑤⑥","(C) ①③⑤⑥","(D) ②③④⑥"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-14","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"關於全口義齒邊緣成形（border molding）的敘述，下列何者錯誤？","options":["(A) 個人牙托的邊緣長度會比最終義齒邊緣長度短2～3mm","(B) 糊劑（paste）和油灰（putty）形式的邊緣材料分別有不同的邊緣成形步驟","(C) 會引導患者進行上、下顎運動","(D) 引導病人閉口同時以手固定下顎，用以記錄咬肌切跡（masseteric notch）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-15","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"上顎全口義齒最終印模（final impression）前，會在客製化模托（custom tray）上打洞（vent holes），下列何者為適當的打洞位置？①粗隆（tuberosity） ②中腭縫（midpalatine suture） ③門齒乳突（incisive papilla） ④皺摺區（rugae area）","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-16","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"全口活動義齒排前牙時，需要有水平覆蓋（overjet）與垂直覆蓋（overbite），下列敘述何者錯誤？","options":["(A) 前牙區在最大咬頭嵌合（maximum intercuspation）時仍需有接觸","(B) 容許義齒基底在彈性黏膜（resilient mucosa）上有限度的位移","(C) 能夠讓微小的前突（protrusion）和側向偏離（lateral excursion）時，減少前方導引（anterior guidance）","(D) 水平覆蓋大於垂直覆蓋可避免前牙齒槽嵴承受過大的咀嚼負荷（chewing load）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-17","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"全口義齒製作時，使用解剖型牙齒（anatomical teeth）排成平衡咬合運動（balanced articulation），下列敘述何者錯誤？","options":["(A) 可將前牙設定為低的門齒導引（low incisal guidance）","(B) 排後牙時，以能建立理想的咬合平面而達到下顎全口活動義齒的穩定性為優先考量","(C) 根據前牙門齒導引（incisal guidance）的設定，有時需要將上、下顎大臼齒與小臼齒間留牙間縫（diastema）以提供準確的空間給上、下顎第一小臼齒排列","(D) 因為義齒煮聚（denture processing）時樹脂會收縮，故煮聚後需再做咬合調整"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-18","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"全口義齒試戴時，發現咬合有早期接觸，垂直高度誤差大約低2 mm，需重置位（remount）且不移動牙齒的情況下，至少須提高多少mm以取得正確咬合記錄？","options":["(A) 1至2 mm","(B) 3至4 mm","(C) 5至6 mm","(D) 不須提高垂直高度"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-19","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"下顎小臼齒缺牙齒槽（mandibular bicuspid residual alveolus）區域在全口義齒排牙上提供重要的線索，下列敘述何者錯誤？","options":["(A) 拔牙後此區域骨頭的吸收主要在垂直方向","(B) 此區域有助於決定下顎顎弓的形態（arch form）","(C) 此區域有助於決定咬合面高低","(D) 此區域有助於決定舌頭的空間"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-20","subject":"ya5","topic":"全口義齒 - 排牙美觀與臨床","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"全口活動義齒使用30度牙排成Angle's class Ⅰ咬合關係時，下列敘述何者最適當？","options":["(A) 下顎向左突出時第一大臼齒有平衡側干擾，應修磨右側下顎第一大臼齒的頰咬頭之舌斜面（lingual incline of buccal cusp）","(B) 下顎向右突出時第一大臼齒有工作側干擾，應先修磨右上犬齒舌側面","(C) 下顎向前突出時第一大臼齒有前突干擾，應修磨上顎第一大臼齒腭咬頭之近心斜面（mesial incline of palatal cusp）","(D) 下顎向右突出時第一大臼齒有平衡側干擾，應修磨右側上顎第一大臼齒的頰咬頭之腭斜面（palatal incline of buccal cusp）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-21","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"製作全口義齒時，決定垂直咬合高度的敘述，下列何者錯誤？","options":["(A) 利用靜止位置（rest position）減去2至4 mm","(B) 讓病人發S音，上、下牙距離約1至1.5 mm","(C) 參考病人拔牙前、仍有對咬牙齒之垂直高度","(D) 上、下犬齒區的前庭垂直距離約22 mm"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-22","subject":"ya5","topic":"全口義齒 - 印模與咬合記錄","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"關於技工室重置（laboratory remount）與臨床重置（clinical remount）的敘述，下列何者錯誤？","options":["(A) 技工室重置主要在修正技工端製作過程中的誤差","(B) 臨床重置主要在修正義齒製作過程中臨床操作的誤差","(C) 要先做技工室重置後再進行臨床重置","(D) 當義齒剛放入患者口中立即出現咬合誤差，須立刻記錄出來進行臨床重置"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-23","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"可撤式局部義齒小連接體（minor connectors）的設計，下列敘述何者正確？","options":["(A) 連接下顎義齒基底（denture bases）與主連接體的小連接體，遠心側延伸（distal extension）長度應為無牙嵴的1/2","(B) 連接牙鈎組（clasp assemblies）與主連接體的小連接體，其近遠心方向（mesiolaterally）要寬，而頰舌側方向（buccolingually）要薄","(C) 當小連接體位於楔隙（embrasure）時，從主連接體開始建議以有錐度（taper）方式往牙齒部分延伸，而尖端的部位是朝向主連接體處","(D) 上顎腭板主連接體與小連接體之間，其終接線（finish line）應落在人工牙舌側面連線往腭中央方向2 mm"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-24","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"可撤式局部義齒咬合面鈎靠座（rest seat）的敘述，下列何者錯誤？","options":["(A) 牙齒鄰接面與鈎靠座底部所形成的角度須小於90度","(B) 外型應該近似三角形，且三角形的基底是位於邊緣嵴（marginal ridge）","(C) 在支柱牙的邊緣嵴之厚度應為1.0～1.5 mm","(D) 近遠心長度約為支柱牙近遠心長度的1/2～2/3"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-25","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"可撤式局部義齒間接固位體（indirect retainer）的設計，需考量下列那些因素？①遠端缺牙區（distal extension edentulous area）的長度 ②可撤式局部義齒運動旋轉軸線位置 ③間接固位體置放點與可撤式局部義齒運動旋轉軸線的距離 ④牙齒的傾斜度 ⑤牙齒的牙周狀況","options":["(A) ①②③④⑤","(B) 僅①③④","(C) 僅②③⑤","(D) 僅②④⑤"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-26","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"關於下顎可撤式局部義齒舌側板（linguoplate）的敘述，下列何者正確？","options":["(A) 覆蓋下顎前牙面積越大越好","(B) 下顎前牙較深之楔隙（embrasure）需平行封凹","(C) 可以取代間接固位體功能","(D) 是下顎可撤式局部義齒中最易牙周清潔的設計"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-27","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"關於遠伸性可撤式局部義齒（distal extension removable partial denture）設計，常將鈎靠（rest）放置於離無牙嵴較遠的位置，下列敘述何者最適當？①目的為使基底下方殘嵴受力時，更接近垂直方向的力量 ②常見於Kennedy class I設計 ③長接觸面引導面（long guiding plane），對支柱牙水平作用力最小 ④配合修正模型印模技術（altered cast impression technique），可降低支柱牙的扭矩負擔","options":["(A) ①③④","(B) ①②④","(C) 僅①②","(D) ②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-28","subject":"ya5","topic":"可撤式局部義齒 - 主副連接體","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"下顎Kennedy class I缺牙，門齒牙周病狀況不佳，將來可能拔除，較適合採用下列何種可撤式局部義齒主連接體？","options":["(A) 舌側槓（lingual bar）","(B) 舌下槓（sublingual bar）","(C) 唇側槓（labial bar）","(D) 舌側板（lingual plate）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-29","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"關於Kennedy class III可撤式局部義齒的敘述，下列何者錯誤？","options":["(A) 其直接固位（direct retention）的作用在於避免義齒的脫落（dislodgment）","(B) 其支持（support）主要是支柱牙與殘嵴","(C) 需考量支柱牙的牙周健康情形與平行度","(D) 缺牙顆數較多時需適當放置間接固位體（indirect retainer）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-30","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"關於可撤式局部義齒RPI設計的敘述，下列何者正確？①其組成包含近心鈎靠 ②其直接固位體的水平穩定性較差，但固位性較佳 ③其鈎靠設計，避免遠伸性局部義齒受力時，支柱牙與鄰接牙分離 ④咬合力施於遠伸性局部義齒時，其牙鈎之固位點（retentive tip）將會移向遠心倒凹區","options":["(A) 僅①③","(B) ②④","(C) ①②③","(D) ①③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-31","subject":"ya5","topic":"可撤式局部義齒 - 鉤環與支托","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"當支柱牙固位性倒凹不存在時，下列處理方式何者最不適當？","options":["(A) 牙釉質表面再造型","(B) 牙冠增長手術","(C) 金屬陶瓷融合牙冠","(D) 陶瓷貼片"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-32","subject":"ya5","topic":"可撤式局部義齒 - Kennedy 設計原則","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"關於可撤式局部義齒引導面（guiding plane）的敘述，下列何者正確？","options":["(A) 指模型的咬合平面","(B) 可引導可撤式局部義齒的吞嚥功能","(C) 會與小連接體（minor connector）連結","(D) 高度通常是2～4釐米"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-33","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"下列何者會影響可撤式局部義齒析量時模型的傾斜位置？①固位倒凹（retentive undercut）位置 ②美觀考量 ③缺牙數目","options":["(A) 僅①","(B) 僅②","(C) 僅①②","(D) ①②③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-34","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"可撤式局部義齒臨床上出現的雪鞋效應（snowshoe effect），下列敘述何者正確？①會發生在Kennedy class II中 ②會發生在Kennedy class I中 ③為可撤式局部義齒基底對口內軟組織覆蓋不足造成 ④會造成齒槽嵴吸收 ⑤通常需對殘嵴進行第二次印模","options":["(A) ①②③④⑤","(B) 僅①③④","(C) 僅②③⑤","(D) 僅①④⑤"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-35","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"關於咀嚼的敘述，下列何者錯誤？","options":["(A) 吞嚥閾值是指將食物減少到可以吞嚥的食團顆粒程度","(B) 咀嚼效率為在一定時間範圍內將食物減少到一定大小的能力","(C) 咀嚼效率與對咬牙齒的數目（occlusal pair）呈現顯著相關性","(D) 咀嚼能力下降反映在吞嚥閾值較小的食團顆粒上"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-36","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"可撤式局部義齒印模時，使用聚乙醚印模材（polyether）的考量，下列何者正確？①屬於彈性印模材 ②親水性（hydrophilic） ③與加成式矽化物印模材（addition reaction silicone）相容 ④具流動減凝性（thixotropic）可提升表面精確度","options":["(A) 僅①②","(B) 僅①③④","(C) 僅①②④","(D) ①②③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-37","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"可撤式局部義齒印模使用水凝膠（hydrocolloids）的敘述，下列何者正確？①具有吸水性（imbibition） ②凝析（syneresis）會造成石膏表面軟化 ③加入如硫化鉀（potassium sulfate）無法抵消石膏被延緩硬化的反應 ④在不可逆水凝膠的凝膠化過程中，模托的任何移動皆會造成內部壓力（internal stress），而使模型變形","options":["(A) 僅①②","(B) 僅①②④","(C) 僅①②③","(D) ①②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-38","subject":"ya5","topic":"臨床基礎與倫理","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"在記錄患者的咬合關係時，為了患者的舒適考量，最合理的治療椅傾斜角度為何？","options":["(A) 20度","(B) 40度","(C) 60度","(D) 80度"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-39","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"關於支架包埋時鑄道（sprue）的成型處理，下列敘述何者錯誤？","options":["(A) 鑄道成型器擺放位置與形狀通常是按照合金材料廠商的建議而定","(B) 高溫的鈷鉻合金的鑄造其鑄道是由蠟型上方配合一些輔助鑄道而成型","(C) 第四類金合金是使用單一鑄道成型器自耐火模型往蠟型接近","(D) 粗大的支架蠟型常須添加一些輔助鑄道，直徑大約為主鑄道1/3至1/4大小"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-40","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"可撤式局部義齒支架自包埋材取出後完成支架修磨操作，下列相關敘述何者正確？","options":["(A) 支架上殘留的包埋材料可以使用較粗顆粒的砂紙磨光，避免傷到牙鈎尖端部位","(B) 支架以粗圓盤與磨石完成修磨後，再使用較細的橡膠修磨拋光組織面與牙鈎尖端內緣","(C) 電解磨光（electropolishing）是一種電解切削的形式，使用含85%磷酸的電解槽內加溫進行","(D) 支架完成電解磨光後，以布輪沾磨光劑將支架所有部位拋光完成後放回主模型做貼合測試"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-41","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"已有上顎全口義齒，需製作新的下顎可撤式局部義齒時，其咬合關係之建立，下列何者錯誤？","options":["(A) 若原有上顎全口義齒之外型、咬合、美觀均尚可接受，則可延用，視同一完整的牙弓（intact arch）","(B) 不需使用面弓轉移，直接取出上顎義齒模型對合在咬合器上，即可進行排牙","(C) 在義齒煮聚完成後，須執行技工室重置位（laboratory remount）之咬合調整","(D) 若上顎全口義齒穩定度好，可以記錄下顎咬合軌跡（occlusal pathway）的方式，取得對咬關係"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-42","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"在可撤式局部義齒製作完成於裝戴的那一天，最優先需要注意的事項為何？","options":["(A) 所有的鈎靠（rest）都和支柱牙上的鈎座（rest seat）密合","(B) 可撤式局部義齒與對咬牙間有正確的咬合","(C) 義齒凸緣（flange）有正確的延伸","(D) 義齒基底與覆蓋的組織密貼"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-43","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"製作可撤式局部義齒塗布壓力顯示膏（pressure indicating paste）時，應使用何種工具最理想？","options":["(A) 毛刷（brush）","(B) 調刀（spatula）","(C) 壓舌板（tongue blade）","(D) 蠟刀（No.7 wax spatula）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-44","subject":"ya5","topic":"可撤式局部義齒 - 印模與製作","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"關於可撤式局部義齒病人的日常維護，下列敘述何者錯誤？","options":["(A) 因會附上牙菌斑（dental plaque），故要常清潔","(B) 清潔時不可用含氯產品","(C) 病人應在晚上將假牙取下，使口腔組織休息","(D) 置入義齒時，應先放單側，再放另一側，以單指壓入"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-45","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"下列何者不是影響全牙冠固位性（retention）的因素？","options":["(A) 黏著劑種類","(B) 黏著劑厚度","(C) 完成線（finish line）類型","(D) 牙冠內面的粗糙度"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-46","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"前牙3/4牙冠之鄰接溝（proximal groove）的走向需平行於何者？","options":["(A) 牙齒的長軸","(B) 唇側切端1/2至2/3的表面","(C) 唇側牙齦端1/3的表面","(D) 舌側面"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-47","subject":"ya5","topic":"牙科材料學","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"印模材料的濕潤能力（wetting ability）常會以接觸角度（contact angle）的大小來代表，下列何種材料有最大的接觸角度？","options":["(A) 聚乙醚（polyether）","(B) 藻膠（alginate）","(C) 瓊膠（agar）","(D) 多硫化橡膠（polysulfide）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-48","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"對於薄牙齦生物型態（thin biotype）特徵的敘述，下列何者錯誤？","options":["(A) 有較寬的角化牙齦區","(B) 牙齦緣位於牙骨質牙釉質交界（CEJ）等高或以下","(C) 三角形的牙齒","(D) 較小的鄰間接觸區"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-49","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"下列何者不是固定義齒診斷牙齒修形（diagnostic tooth preparation）之目的？","options":["(A) 可以先決定將來贋復物的置入途徑（path of placement）","(B) 可以預估支柱牙修磨的齒質量","(C) 可以決定贋復物邊緣的位置","(D) 可以先決定使用黏合劑的種類"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-50","subject":"ya5","topic":"牙科材料學","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"下列何者並非全瓷牙冠常見的主要成分？","options":["(A) 鋁（aluminum）","(B) 鉻（chromium）","(C) 鋰（lithium）","(D) 鋯（zirconium）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-51","subject":"ya5","topic":"牙科材料學","meta":"115年第2次第51題","year":115,"session":2,"number":51,"question":"下列牙科黏合劑何者與牙齒有黏著性？①玻璃離子體黏合劑（glass ionomer cement） ②複合樹脂黏合劑（composite resin cement） ③聚羧酸鋅黏合劑（zinc polycarboxylate cement） ④磷酸鋅黏合劑（zinc phosphate cement）","options":["(A) 僅③④","(B) ①②③","(C) 僅①②","(D) ②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-52","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第2次第52題","year":115,"session":2,"number":52,"question":"與瓷融合金屬（porcelain-fused-to-metal）固定義齒比較，纖維強化式樹脂固定義齒（fiber-reinforced composite fixed prosthesis）不具有下列何種優點？","options":["(A) 美觀且適合與可撤式活動義齒對咬","(B) 減少對咬自然牙的磨秏","(C) 可使用於對義齒金屬過敏的病人","(D) 可使用於缺牙區較長的病人"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-53","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第2次第53題","year":115,"session":2,"number":53,"question":"比色時，眼睛先注視何種顏色，可以增強對黃色系列牙齒之分辨能力？","options":["(A) 淡紫色","(B) 灰白色","(C) 淡灰藍色","(D) 淡灰綠色"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-54","subject":"ya5","topic":"植牙贋復","meta":"115年第2次第54題","year":115,"session":2,"number":54,"question":"有關cement-retained implant crown相較於screw-retained implant crown的敘述，下列何者正確？","options":["(A) 螺絲鬆脫發生的機會較低","(B) 可容許較大的植體植入角度","(C) 製作過程所需要的chair time較少","(D) 對周遭軟組織較少的侵犯性"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-55","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第55題","year":115,"session":2,"number":55,"question":"要為一個下顎運動時有較明顯Bennett side shift的病人製作後牙單牙冠補綴物，則牙冠的咬合面形態應如何？","options":["(A) 有一較寬的中心窩（central fossa）","(B) 有尖銳的牙尖角（cusp angle）","(C) 有三點接觸的咬合面（tripodized occlusal surface）","(D) 有超過1 mm的長中心距離（long centric distance）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-56","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第56題","year":115,"session":2,"number":56,"question":"使用前方程式設計裝置（anterior programming device）取得咬合記錄時，下列敘述何者正確？①避免下顎前牙咬在前方程式設計裝置的斜面上，而造成下顎過度後縮 ②前方程式設計裝置要能限制下顎的側方移動 ③為方便操作，後方上下顎牙齒分開愈遠愈好 ④目的在取得中心咬合記錄時，避免後方牙齒之咬合干擾 ⑤為幫助上下顎模型定位，取得之中心咬合記錄應覆蓋愈多牙齒愈好","options":["(A) 僅①④","(B) ①②","(C) ②⑤","(D) ①③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-57","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第2次第57題","year":115,"session":2,"number":57,"question":"一般而言，單齒模空間劑（die spacer）應塗布的範圍與牙齒修形邊緣的關係為何？","options":["(A) 距離邊緣1 mm","(B) 剛好與邊緣齊平","(C) 距肩台邊緣（shoulder margin）1 mm，距弧形邊緣（chamfer margin）0.5 mm","(D) 隨單齒模空間劑之廠牌不同而異"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-58","subject":"ya5","topic":"固定義齒 - 牙體修形與印模","meta":"115年第2次第58題","year":115,"session":2,"number":58,"question":"根管治療後的牙齒，在製作根柱（post）時，首先需移除根管內部分的根管填充物至根柱所需的長度。此一階段不建議使用下列何種器械？","options":["(A) warmed endodontic plugger","(B) Gates Glidden drill","(C) parapost drill","(D) peeso reamer"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-59","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第2次第59題","year":115,"session":2,"number":59,"question":"從病人口內拆下如下圖所示的金屬瓷牙橋，發現瓷面與金屬脫離。其最可能的原因是什麼？","options":["(A) 無牙嵴空間太小，以致橋體斷裂","(B) 燒瓷前之金屬處理不良","(C) 鑲瓷牙橋的咬合設計不良，改成咬瓷即可","(D) 燒瓷時瓷粉堆積不緻密"],"answer":1,"image":"ya5-115-2-59.jpeg","clinical_level":"一般"},{"id":"ya5-115-2-60","subject":"ya5","topic":"植牙贋復","meta":"115年第2次第60題","year":115,"session":2,"number":60,"question":"下列那些情況會增加人工植體周邊齒槽骨過度吸收？①選擇大小形狀不適當的人工植體 ②支柱體與人工植體之間不密合，有縫隙產生 ③人工植體在骨整合尚未完成前，過早承受不當的咬合力 ④種植長度過長之人工植體","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-61","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第2次第61題","year":115,"session":2,"number":61,"question":"Tjan等人將smile分為high、average及low smile，下列敘述何者正確？","options":["(A) average smile係指微笑時會露出50%上顎正中門齒及牙齦","(B) low smile係指微笑時會露出低於75%上顎正中門齒及牙齦","(C) 研究中指出男性比女性較易擁有high smile","(D) high smile係指微笑時會露出75%～100%上顎正中門齒及牙齦"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-62","subject":"ya5","topic":"固定義齒 - 假牙冠與牙橋設計","meta":"115年第2次第62題","year":115,"session":2,"number":62,"question":"固定義齒治療計畫中，關於biomechanical consideration的敘述，下列何者錯誤？","options":["(A) 根據Ante's Law，病患失去第一大臼齒及第二小臼齒，以牙周健全的第一小臼齒與第二大臼齒為支撐的四單位牙橋，有可接受的預後","(B) 依據牙齒的位置，缺失一顆牙齒，以前、後牙齒支撐的三單位牙橋，擁有良好的預後。但是上顎的犬齒缺失時則是例外","(C) 有二顆橋體（pontic）時，前牙固定式義齒的預後優於後牙固定式義齒","(D) 所有固定式義齒受到咬力時會產生彎曲（flexure），彎曲會隨著徑距長（span length）而增加，兩者之間呈現單純的線性關係"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-63","subject":"ya5","topic":"牙科材料學","meta":"115年第2次第63題","year":115,"session":2,"number":63,"question":"瓷融合金屬冠的瓷與金屬間，應有相配合的熱膨脹係數，試問兩者間的係數差距應保持在多少以內？","options":["(A) 0.5×10 -6/℃","(B) 5×10 -6/℃","(C) 0.5×10 -3/℃","(D) 5×10 -3/℃"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-64","subject":"ya5","topic":"牙科材料學","meta":"115年第2次第64題","year":115,"session":2,"number":64,"question":"下列何者最不可能是金屬牙冠鑄造失誤產鰭狀物（fins）的原因？","options":["(A) 包埋材水／粉比太大","(B) 包埋材加熱太快","(C) 去蠟不全","(D) 鑄造壓過大"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-65","subject":"ya5","topic":"牙科材料學","meta":"115年第2次第65題","year":115,"session":2,"number":65,"question":"關於type II包埋粉的吸水性膨脹（hygroscopic expansion），其範圍為下列何者？","options":["(A) 0.5～0.8%","(B) 1.2～2.2%","(C) 3.0～3.5%","(D) 4.0～4.3%"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-66","subject":"ya5","topic":"植牙贋復","meta":"115年第2次第66題","year":115,"session":2,"number":66,"question":"下列何者會影響鈦金屬支柱（titanium abutment）的表面平滑度？","options":["(A) 聚羧酸黏合劑（polycarboxylate cement）","(B) 臨時黏合劑（temporary cement）","(C) 磷酸鋅黏合劑（zinc phosphate cement）","(D) 樹脂黏合劑（resin cement）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-67","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第2次第67題","year":115,"session":2,"number":67,"question":"關於顳顎關節解剖形態的敘述，下列何者正確？","options":["(A) 關節囊的前側部可能變厚，形成一個帶，有時稱為莖突下顎韌帶（stylomandibular ligament）","(B) 關節窩前面為關節突起（articular eminence），屬於顳骨的一部分","(C) 咀嚼時關節盤不會承擔應力（stress bearing）","(D) 關節面外層包覆著一層上皮組織"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-68","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第68題","year":115,"session":2,"number":68,"question":"關於肌伸張反射（stretch reflex），下列何者錯誤？","options":["(A) 反射動作的脈衝最終會返回骨骼肌","(B) 下顎的肌伸張反射為單突觸反射","(C) 膝跳反射是一個肌伸張反射的例子","(D) 突然向下敲擊下巴會使下顎下降，咬肌舒張，導致嘴巴張開"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-69","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第69題","year":115,"session":2,"number":69,"question":"有關食物進入口腔咀嚼的過程，下列何者錯誤？","options":["(A) 嘴唇可引導、控制食物攝取及密封口腔","(B) 舌頭主要的功能在味覺，並不參與操控口中之食物","(C) 臉頰可以使食物保持在咬合面之間","(D) 液體食物之攝取，嘴唇扮演非常重要的角色"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-70","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第70題","year":115,"session":2,"number":70,"question":"觀察有齒列磨耗者的下顎邊緣運動，從下列那一面觀，其中心咬合接觸位置較易呈現平台狀？","options":["(A) 矢面觀（sagittal view）","(B) 額面觀（frontal view）","(C) 水平面觀（horizontal view）","(D) 無論從何面觀察，中心咬合皆為平台狀"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-71","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第71題","year":115,"session":2,"number":71,"question":"有關選擇性修磨（selective grinding）的先決條件，下列何者錯誤？","options":["(A) 必須要有穩定的顎間關係","(B) 在口內修磨前，必須先在診斷模型上修磨","(C) 修磨時儘量保留珐瑯質","(D) 選擇性修磨後垂直高度的改變不會影響治療的成功機率"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-72","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第72題","year":115,"session":2,"number":72,"question":"下列有關咬合調整的敘述，何者錯誤？","options":["(A) 咬合調整適用於錯誤的牙科復形體所造成的功能障礙","(B) 咬合調整適用於錯誤的牙科復形體的修正","(C) 咬合調整不應於顎肌疼痛時執行","(D) 下顎中心位置的咬合調整適用於顱顎障礙症之初步治療"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-73","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第73題","year":115,"session":2,"number":73,"question":"關於下顎運動時，髁頭（condyle head）移動的敘述，下列何者正確？","options":["(A) 髁頭在開口的過程中，只發生純粹的樞紐運動（hinge movement）","(B) 為了開口時順利下降下顎，必須產生髁頭往前與往下的移動（translation）","(C) 下顎進行側向運動時，工作側髁頭內側端（medial pole）因有顳顎韌帶（TM ligament）附著，使髁頭向外向後旋轉","(D) 下顎進行側向運動時，非工作側髁頭的內側因為外翼肌的牽引，而發生向後向下及向內之側移（side shift）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-74","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第74題","year":115,"session":2,"number":74,"question":"附圖為下顎邊緣運動多面體，圖中那一點最有可能代表髁在關節窩內未移位之最大開口位置？","options":["(A) B","(B) E","(C) N","(D) M"],"answer":2,"image":"ya5-115-2-74.jpeg","clinical_level":"一般"},{"id":"ya5-115-2-75","subject":"ya5","topic":"咬合學基礎","meta":"115年第2次第75題","year":115,"session":2,"number":75,"question":"承上題，從G點移動到H點的路徑不受下列那一項影響？","options":["(A) 顎關節","(B) 咀嚼肌","(C) 前牙","(D) 後牙"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-76","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第2次第76題","year":115,"session":2,"number":76,"question":"下列何者不是顳顎關節障礙症病因學（etiology）的主要相關因素？","options":["(A) 創傷（trauma）","(B) 結構（anatomy）","(C) 生理病理（pathophysiology）","(D) 老化過程（aging process）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-77","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第2次第77題","year":115,"session":2,"number":77,"question":"關於檢查顳顎關節雜音與關節盤移位（disc displacement），下列敘述何者錯誤？","options":["(A) 一般來說，雜音可分為彈響（click）以及輾軋音（crepitus）兩主要類別","(B) 彈響（click）可能為關節盤移位或是關節的重塑（remodeling）甚至也可能為肌源性（muscular type）所致","(C) 彈響（click）若發生在開口末期，表示關節盤移位較輕微且預後也越好","(D) 輾軋音（crepitus）可能是關節炎或關節病變等引起髁頭表面的不平滑（irregularity）所致"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-78","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第2次第78題","year":115,"session":2,"number":78,"question":"下列何者不是不可復位關節盤異位的臨床特徵？","options":["(A) 開口受限","(B) 若開口時偏移中線，可能是對側（contralateral）關節盤異位","(C) 下顎做同側（ipsilateral）離中心運動時不受限","(D) 下顎做對側（contralateral）離中心運動時會受限"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-79","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第2次第79題","year":115,"session":2,"number":79,"question":"下列何種疾病不是以持續鈍痛為特徵，並且會因關節運動而加劇？","options":["(A) 關節盤紊亂症（disc derangement disorders）","(B) 關節炎（arthritis）","(C) 關節盤後炎（retrodiscitis）","(D) 關節囊炎（capsulitis）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya5-115-2-80","subject":"ya5","topic":"顳顎關節疾患","meta":"115年第2次第80題","year":115,"session":2,"number":80,"question":"有關依格氏症候群（Eagle's syndrome）病因的敘述，下列何者正確？","options":["(A) 關節盤異位（disc displacement）造成","(B) 關節盤後炎（retrodiscitis）造成","(C) 莖突（styloid process）過長造成","(D) 關節隆突（articular eminence）角度過大造成"],"answer":2,"image":"","clinical_level":"一般"}];
